INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里那片可怕地树林，我们绕着走了。", "corrected_sentence": "夜里那片可怕的树林，我们绕着走了。", "error_description": "“可怕”修饰名词“树林”时要用“的”，不能用“地”。“地”只用在动词前。错误写法是“可怕地树林”，正确写法是“可怕的树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
