INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "官员是在政府里做事的人。", "primary_collocate": null, "pronunciation": "guān yuán", "ipa": "kwan˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这位官员每天早上八点到政府上班。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府的官员来学校看学生。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲是一位官员，常常很忙。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些官员在会议室里讨论修路的计划。", "target_word": "官员", "complexity_tier": "T3", "furigana": "zhèxiē guānyuán zài huìyìshì lǐ tǎolùn xiūlù de jìhuà.", "sentence_source": "generated"}, {"text": "那个官员对记者说，路下个月就修好。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当官员，所以努力学习法律。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员不能随便收别人的礼物。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位官员坐车去了农村。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国官员昨天来我们城市参观。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员很关心老百姓的生活。", "target_word": "官员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "官員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在政府里工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86837, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "官员", "is_correct": true, "explanation": "正确：官员（guān yuán）指在政府机关中工作的人。"}, {"text": "馆员", "is_correct": false, "explanation": "馆员（guǎn yuán）与官员的第一音节声调不同：guǎn 为第三声，guān 为第一声；馆员指图书馆等场所的工作人员。"}, {"text": "光源", "is_correct": false, "explanation": "光源（guāng yuán）与官员的第一音节韵母不同：guāng 带后鼻音 ng，guān 不带；光源指发光的物体。"}, {"text": "专员", "is_correct": false, "explanation": "专员（zhuān yuán）与官员的第一音节声母不同：zh 与 g 不同；专员指负责某项专门事务的人员。"}], "explanations": {"官员": "正确：官员（guān yuán）指在政府机关中工作的人。", "馆员": "馆员（guǎn yuán）与官员的第一音节声调不同：guǎn 为第三声，guān 为第一声；馆员指图书馆等场所的工作人员。", "光源": "光源（guāng yuán）与官员的第一音节韵母不同：guāng 带后鼻音 ng，guān 不带；光源指发光的物体。", "专员": "专员（zhuān yuán）与官员的第一音节声母不同：zh 与 g 不同；专员指负责某项专门事务的人员。"}, "sentence_index": null, "correct_answer": "官员"}, "level_3": {"options": [{"text": "官员", "is_correct": true, "explanation": "正确：官员指政府机关中的工作人员，与“到政府上班”相合。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师在学校工作，不到政府上班，与句中的“政府”不符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生在医院工作，与“政府上班”的语境不符。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“上班”说的是工作，学生应说“上学”，不说“上班”。"}], "explanations": {"官员": "正确：官员指政府机关中的工作人员，与“到政府上班”相合。", "老师": "语义：老师在学校工作，不到政府上班，与句中的“政府”不符。", "医生": "语义：医生在医院工作，与“政府上班”的语境不符。", "学生": "搭配：“上班”说的是工作，学生应说“上学”，不说“上班”。"}, "sentence_index": 0, "correct_answer": "官员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的官员在会议室里讨论工作计划。", "explanation": "这里应该用〈员工〉。官员指政府机关中的人，公司里的工作人员要用〈员工〉。"}, {"text": "这部电影的官员很有名。", "explanation": "这里应该用〈演员〉。官员指政府工作的人员，与电影无关，电影里表演的人要用〈演员〉。"}, {"text": "这位官员给客人剪头发。", "explanation": "这里应该用〈理发师〉。官员指政府机关中的人，给客人剪头发的要用〈理发师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86837, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "官员", "is_correct": true, "explanation": "正确：官员（guān yuán）指在政府机关中工作的人。"}, {"text": "官运", "is_correct": false, "explanation": "官运（guān yùn）与官员的第二音节不同：yùn 与 yuán 韵母、声调都不同；官运指做官的运气。"}, {"text": "船员", "is_correct": false, "explanation": "船员（chuán yuán）与官员的第一音节声母和声调都不同：ch 与 g 不同，chuán 为第二声；船员指在船上工作的人。"}, {"text": "馆员", "is_correct": false, "explanation": "馆员（guǎn yuán）与官员的第一音节声调不同：guǎn 为第三声，guān 为第一声；馆员指图书馆等场所的工作人员。"}], "explanations": {"官员": "正确：官员（guān yuán）指在政府机关中工作的人。", "官运": "官运（guān yùn）与官员的第二音节不同：yùn 与 yuán 韵母、声调都不同；官运指做官的运气。", "船员": "船员（chuán yuán）与官员的第一音节声母和声调都不同：ch 与 g 不同，chuán 为第二声；船员指在船上工作的人。", "馆员": "馆员（guǎn yuán）与官员的第一音节声调不同：guǎn 为第三声，guān 为第一声；馆员指图书馆等场所的工作人员。"}, "sentence_index": null, "correct_answer": "官员"}, "level_3": {"options": [{"text": "官员", "is_correct": true, "explanation": "正确：官员指政府机关中的人，他们不能随便收礼物，与句意相合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“收礼物”的主语须是能接受礼物的人，石头不能收礼物。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，无法收别人的礼物，句子不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书是物品，不能收别人的礼物，与句子的语义不符。"}], "explanations": {"官员": "正确：官员指政府机关中的人，他们不能随便收礼物，与句意相合。", "石头": "搭配：“收礼物”的主语须是能接受礼物的人，石头不能收礼物。", "空气": "语义：空气不是人，无法收别人的礼物，句子不通。", "书": "语义：书是物品，不能收别人的礼物，与句子的语义不符。"}, "sentence_index": 6, "correct_answer": "官员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院的官员很细心地照顾病人。", "explanation": "这里应该用〈护士〉。官员指政府机关中的人，医院里照顾病人的人员要用〈护士〉。"}, {"text": "这支球队的官员很努力训练。", "explanation": "这里应该用〈球员〉。官员指政府机关中的人，训练比赛的人要用〈球员〉。"}, {"text": "这家饭店的官员很热情。", "explanation": "这里应该用〈服务员〉。官员指政府机关中的人，饭店里接待顾客的人要用〈服务员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只官员每天坐公交车到政府上班。", "corrected_sentence": "这位官员每天坐公交车到政府上班。", "error_description": "量词“只”用于动物，官员应该用“位”。错误在于“这只官员”，正确形式是“这位官员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位官员们坐车去了县城。", "corrected_sentence": "几位官员坐车去了县城。", "error_description": "“几位”是数量词，后面不能再加表示复数的“们”。错误在于“官员们”，正确形式是“几位官员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
