INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地址是你家住在哪里的名称和号码。", "primary_collocate": null, "pronunciation": "dì zhǐ", "ipa": "ti˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请你把家里的地址写在这张纸上。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他家的地址，所以找不到他家。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的新地址是哪里？", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家里的地址告诉了快递员。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地址不对，信寄不到。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把朋友的地址记在手机里了。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她搬家了，没有告诉我新地址。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你家的地址和电话号码。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每年都往老家寄东西，地址从来没变过。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着信封上的地址，找到了那栋楼。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家庭地址", "label": "复合"}], "register": "中性", "sense_fingerprint": "家庭住址：说明住在哪条路、哪个门牌号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86839, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地址", "is_correct": true, "explanation": "地址 dì zhǐ：住在哪里的名称和号码。"}, {"text": "弟子", "is_correct": false, "explanation": "弟子 dì zǐ：z 与 zh 声母不同，意思是跟随老师学习的人，即学生。"}, {"text": "地质", "is_correct": false, "explanation": "地质 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是地球的构造和成分。"}, {"text": "地支", "is_correct": false, "explanation": "地支 dì zhī：zhī（第一声）与 zhǐ（第三声）声调不同，意思是十二地支。"}, {"text": "帝制", "is_correct": false, "explanation": "帝制 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是君主专制的政治制度。"}], "explanations": {"地址": "地址 dì zhǐ：住在哪里的名称和号码。", "弟子": "弟子 dì zǐ：z 与 zh 声母不同，意思是跟随老师学习的人，即学生。", "地质": "地质 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是地球的构造和成分。", "地支": "地支 dì zhī：zhī（第一声）与 zhǐ（第三声）声调不同，意思是十二地支。", "帝制": "帝制 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是君主专制的政治制度。"}, "sentence_index": null, "correct_answer": "地址"}, "level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "搭配：“写”不能用于钥匙，钥匙无法写在纸上。"}, {"text": "地址", "is_correct": true, "explanation": "地址：家里的住址，可以写在纸上，符合句意。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“写”只用于文字，照片不能写在纸上。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是要写在纸上的个人信息，与“把家里的……写在纸上”不符。"}], "explanations": {"钥匙": "搭配：“写”不能用于钥匙，钥匙无法写在纸上。", "地址": "地址：家里的住址，可以写在纸上，符合句意。", "照片": "搭配：“写”只用于文字，照片不能写在纸上。", "天气": "语义：“天气”不是要写在纸上的个人信息，与“把家里的……写在纸上”不符。"}, "sentence_index": 0, "correct_answer": "地址"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司的地址很高。", "explanation": "这里应该用〈地位〉。地址指所在地点或住址，形容人在公司里的身份高低要用“地位”。"}, {"text": "事情已经到了这种地址。", "explanation": "这里应该用〈地步〉。地址指住在哪里的名称和号码，表示事情发展到的程度要用“地步”。"}, {"text": "昨天发生了一场大地址。", "explanation": "这里应该用〈地震〉。地址不能指自然灾害，应说“大地震”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”是食物或气味的属性，不是搬家后应告知的信息，句意不通。"}, {"text": "地址", "is_correct": true, "explanation": "地址：搬家后的新住址，是应当告诉对方的信息，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是搬家后需要告知的内容，与“没有告诉我新……”的语境不符。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“告诉”后不能接“饭菜”来表示搬家的信息。"}], "explanations": {"味道": "语义：“味道”是食物或气味的属性，不是搬家后应告知的信息，句意不通。", "地址": "地址：搬家后的新住址，是应当告诉对方的信息，符合句意。", "颜色": "语义：“颜色”不是搬家后需要告知的内容，与“没有告诉我新……”的语境不符。", "饭菜": "搭配：“告诉”后不能接“饭菜”来表示搬家的信息。"}, "sentence_index": 6, "correct_answer": "地址"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地址绕着太阳转。", "explanation": "这里应该用〈地球〉。地址指所在地点或住址，不是星球；绕着太阳转的是地球，不能说“地址”。"}, {"text": "我坐地址去学校。", "explanation": "这里应该用〈地铁〉。地址指住在哪里的名称和号码，不是交通工具；去学校可以坐“地铁”。"}, {"text": "房间里铺着一块地址。", "explanation": "这里应该用〈地毯〉。地址不是铺在地上的东西，房间里铺的应是“地毯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "信封上写着一本地址。", "corrected_sentence": "信封上写着一个地址。", "error_description": "量词错误：“地址”的量词应是“个”，不能用“本”。正确的说法是“信封上写着一个地址”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的地址北京。", "corrected_sentence": "他的地址在北京。", "error_description": "介词漏写：表示所在地点的句子需要“在”，漏掉“在”不成句。正确的说法是“他的地址在北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
