INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "单位或机构所在的地点，如公司、学校、医院的位置。", "primary_collocate": null, "pronunciation": "dì zhǐ", "ipa": "ti˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司的地址在市中心。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在申请表上填写单位的地址。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的地址你知道吗？", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的地址写在通知的最上面。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上有商店的地址和营业时间。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请核对一下这家工厂的地址。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的新地址离地铁站很近。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司搬家了，请记一下新地址。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上找不到这家餐厅的地址。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员打电话问我公司的地址。", "target_word": "地址", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "单位地址", "label": "复合"}], "register": "中性", "sense_fingerprint": "单位或机构所在的地点，如公司、学校、医院的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86840, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地址", "is_correct": true, "explanation": "地址 dì zhǐ：单位或机构所在的地点。"}, {"text": "弟子", "is_correct": false, "explanation": "弟子 dì zǐ：z 与 zh 声母不同，意思是跟随老师学习的人，即学生。"}, {"text": "地质", "is_correct": false, "explanation": "地质 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是地球的构造和成分。"}, {"text": "地支", "is_correct": false, "explanation": "地支 dì zhī：zhī（第一声）与 zhǐ（第三声）声调不同，意思是十二地支。"}, {"text": "帝制", "is_correct": false, "explanation": "帝制 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是君主专制的政治制度。"}], "explanations": {"地址": "地址 dì zhǐ：单位或机构所在的地点。", "弟子": "弟子 dì zǐ：z 与 zh 声母不同，意思是跟随老师学习的人，即学生。", "地质": "地质 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是地球的构造和成分。", "地支": "地支 dì zhī：zhī（第一声）与 zhǐ（第三声）声调不同，意思是十二地支。", "帝制": "帝制 dì zhì：zhì（第四声）与 zhǐ（第三声）声调不同，意思是君主专制的政治制度。"}, "sentence_index": null, "correct_answer": "地址"}, "level_3": {"options": [{"text": "电话", "is_correct": false, "explanation": "语义：“电话”不是地点，不能说它“在市中心”。"}, {"text": "地址", "is_correct": true, "explanation": "地址：公司所在的地点，说“在市中心”符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是地点，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“在市中心”搭配来表示位置。"}], "explanations": {"电话": "语义：“电话”不是地点，不能说它“在市中心”。", "地址": "地址：公司所在的地点，说“在市中心”符合句意。", "价格": "语义：“价格”不是地点，句意不通。", "颜色": "搭配：“颜色”不能与“在市中心”搭配来表示位置。"}, "sentence_index": 0, "correct_answer": "地址"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司经历了一场大地址。", "explanation": "这里应该用〈地震〉。地址指所在地点或住址，不能指自然灾害；比喻公司遭遇巨大变动要说“大地震”。"}, {"text": "我在家里的地址很高。", "explanation": "这里应该用〈地位〉。地址指所在地点或住址，形容在家里的身份高低要用“地位”。"}, {"text": "公司的问题已经到了这种地址。", "explanation": "这里应该用〈地步〉。地址指所在地点，表示事情发展到的程度要用“地步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名称", "is_correct": false, "explanation": "语义：“名称”是指称，不是位置，不能说离地铁站近。"}, {"text": "地址", "is_correct": true, "explanation": "地址：医院所在的地点，可以说离地铁站很近，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能有远近，“离地铁站很近”只能描述地点。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能与“离……很近”搭配，句意荒谬。"}], "explanations": {"名称": "语义：“名称”是指称，不是位置，不能说离地铁站近。", "地址": "地址：医院所在的地点，可以说离地铁站很近，符合句意。", "时间": "语义：“时间”不能有远近，“离地铁站很近”只能描述地点。", "体重": "搭配：“体重”不能与“离……很近”搭配，句意荒谬。"}, "sentence_index": 6, "correct_answer": "地址"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天坐地址去公司。", "explanation": "这里应该用〈地铁〉。地址指所在地点，不是交通工具；去公司可以坐“地铁”。"}, {"text": "公司大厅里铺着一块地址。", "explanation": "这里应该用〈地毯〉。地址不是铺在地上的东西，铺在地上的应是“地毯”。"}, {"text": "快递员打电话问我，我公司的地址绕着太阳转。", "explanation": "这里应该用〈地球〉。地址指所在地点或住址，不是星球；绕着太阳转的应是“地球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司的地址东门附近。", "corrected_sentence": "我们公司的地址在东门附近。", "error_description": "介词漏写：表示所在位置的句子需要“在”，漏掉“在”不成句。正确的说法是“我们公司的地址在东门附近”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司有一本新地址。", "corrected_sentence": "这家公司有一个新地址。", "error_description": "量词错误：“地址”的量词应是“个”，不能用“本”。正确的说法是“这家公司有一个新地址”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
