INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拍是用手掌轻轻打一下。", "primary_collocate": null, "pronunciation": "pāi", "ipa": "pʰaɪ˥", "syllable_count": 1, "sentences": [{"text": "他拍了一下我的手。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家高兴地拍着手唱歌。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻轻拍着宝宝的背。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师拍了拍黑板，让大家安静。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶轻轻拍了拍我的手，什么也没说。", "target_word": "拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忽然想起什么，轻轻拍了一下自己的额头。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把衣服上的灰拍掉。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友拍我的肩，让我别担心。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗很乖，我拍它的头，它就摇尾巴。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吓了一跳，拍着胸口。", "target_word": "拍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍了", "label": "完成体"}, {"form": "拍着", "label": "持续体"}, {"form": "拍过", "label": "经历体"}, {"form": "拍拍", "label": "重叠"}, {"form": "拍打", "label": "复合词"}, {"form": "拍手", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用手掌轻轻打一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 小狗 (Zipf 3.89), 乖 (Zipf 3.76), 摇 (Zipf 3.93)']::text[], '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86841, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拍", "is_correct": true, "explanation": "拍（pāi，第一声）指用手掌轻轻打一下，是本题的正确答案。"}, {"text": "排", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是排列。"}, {"text": "派", "is_correct": false, "explanation": "pài（第四声）与 pāi（第一声）声调不同，意思是派遣或派别。"}, {"text": "掰", "is_correct": false, "explanation": "bāi 与 pāi 只差送气（b 与 p），声调相同，意思是用手把东西分开。"}], "explanations": {"拍": "拍（pāi，第一声）指用手掌轻轻打一下，是本题的正确答案。", "排": "pái（第二声）与 pāi（第一声）声调不同，意思是排列。", "派": "pài（第四声）与 pāi（第一声）声调不同，意思是派遣或派别。", "掰": "bāi 与 pāi 只差送气（b 与 p），声调相同，意思是用手把东西分开。"}, "sentence_index": null, "correct_answer": "拍"}, "level_3": {"options": [{"text": "拍", "is_correct": true, "explanation": "拍：用手掌轻打。“拍了一下”指轻轻打一下，是本句正确的词。"}, {"text": "锁", "is_correct": false, "explanation": "搭配：“锁”不能用于“手”这种动作，说“锁了一下我的手”不通。"}, {"text": "挂", "is_correct": false, "explanation": "语义：挂是悬挂或挂断，与“打手”的动作无关，句子不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是用水加热食物，不能用来描述手打的动作，句子不通。"}], "explanations": {"拍": "拍：用手掌轻打。“拍了一下”指轻轻打一下，是本句正确的词。", "锁": "搭配：“锁”不能用于“手”这种动作，说“锁了一下我的手”不通。", "挂": "语义：挂是悬挂或挂断，与“打手”的动作无关，句子不通。", "煮": "语义：煮是用水加热食物，不能用来描述手打的动作，句子不通。"}, "sentence_index": 0, "correct_answer": "拍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直拍哈欠，看起来很困。", "explanation": "这里应该用〈打〉。“打哈欠”是固定说法，“拍”不能与“哈欠”搭配。"}, {"text": "他会拍吉他，经常在晚会上表演。", "explanation": "这里应该用〈弹〉。“弹吉他”指按弦演奏，“拍”只表示用手掌轻打，不能表示弹奏。"}, {"text": "他感冒了，一直拍鼻涕。", "explanation": "这里应该用〈擤〉。“擤鼻涕”是固定说法，“拍”不能用于擤去鼻涕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86841, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拍", "is_correct": true, "explanation": "拍（pāi，第一声）指用手掌轻轻打一下，是本题的正确答案。"}, {"text": "牌", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是牌子或纸牌。"}, {"text": "抛", "is_correct": false, "explanation": "pāo 与 pāi 韵母不同（ao 与 ai），意思是抛掷。"}, {"text": "攀", "is_correct": false, "explanation": "pān 与 pāi 韵母不同（an 与 ai），意思是攀爬。"}, {"text": "掰", "is_correct": false, "explanation": "bāi 与 pāi 声母不同（b 与 p），意思是把东西分开。"}], "explanations": {"拍": "拍（pāi，第一声）指用手掌轻轻打一下，是本题的正确答案。", "牌": "pái（第二声）与 pāi（第一声）声调不同，意思是牌子或纸牌。", "抛": "pāo 与 pāi 韵母不同（ao 与 ai），意思是抛掷。", "攀": "pān 与 pāi 韵母不同（an 与 ai），意思是攀爬。", "掰": "bāi 与 pāi 声母不同（b 与 p），意思是把东西分开。"}, "sentence_index": null, "correct_answer": "拍"}, "level_3": {"options": [{"text": "拍", "is_correct": true, "explanation": "拍：用手掌轻打，“拍掉”指把灰轻打下来，是本句正确的词。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“灰”不能被吃掉，“吃”与“灰”不搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，不能用来说去掉衣服上的灰。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝是咽下液体，与衣服上的灰无关，句子不通。"}], "explanations": {"拍": "拍：用手掌轻打，“拍掉”指把灰轻打下来，是本句正确的词。", "吃": "搭配：“灰”不能被吃掉，“吃”与“灰”不搭配。", "咬": "语义：咬是用牙齿夹住，不能用来说去掉衣服上的灰。", "喝": "语义：喝是咽下液体，与衣服上的灰无关，句子不通。"}, "sentence_index": 6, "correct_answer": "拍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在教室里拍盹，老师很生气。", "explanation": "这里应该用〈打〉。“打盹”是固定说法，“拍”不能与“盹”搭配。"}, {"text": "妈妈在厨房拍饭，过一会儿就能吃了。", "explanation": "这里应该用〈煮〉。“煮饭”指加热做饭，“拍”不能表示烹煮。"}, {"text": "奶奶在厨房拍粥，香味飘满了屋子。", "explanation": "这里应该用〈熬〉。“熬粥”是固定说法，“拍”不能表示熬煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他轻轻拍了一个我的背。", "corrected_sentence": "他轻轻拍了一下我的背。", "error_description": "动量词应用“下”，不说“个”。“拍了一个我的背”不通，应说“拍了一下我的背”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她小心地拍了过我的肩膀。", "corrected_sentence": "她小心地拍过我的肩膀。", "error_description": "“拍过”表示曾经发生的经历，不能与“了”连用成“拍了过”。应说“拍过”，不说“拍了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
