INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86843, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大学生是在大学里读书的人。", "primary_collocate": null, "pronunciation": "dà xué shēng", "ipa": "ta˥˩ ɕɥɛ˧˥ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "我哥哥是大学生，现在住在学校里。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多大学生。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生每天都要去图书馆学习。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还是大学生的时候去过北京。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜便宜，大学生常来吃。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年十九岁，是一名大学生。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生们正在教室里上课。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多大学生周末会去做兼职。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹想当大学生。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大学生能说三种语言。", "target_word": "大学生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女大学生", "label": "复合"}], "register": "中性", "sense_fingerprint": "指正在大学里读书的人，强调身份是在读大学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大学生", "is_correct": true, "explanation": "正确。“我哥哥是大学生，现在住在学校里”语义通顺。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿与“哥哥”的身份相矛盾，句子不成立。"}, {"text": "老奶奶", "is_correct": false, "explanation": "语义：“老奶奶”与“哥哥”的性别和身份相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“哥哥”是人，不能说“我哥哥是桌子”。"}], "explanations": {"大学生": "正确。“我哥哥是大学生，现在住在学校里”语义通顺。", "婴儿": "语义：婴儿与“哥哥”的身份相矛盾，句子不成立。", "老奶奶": "语义：“老奶奶”与“哥哥”的性别和身份相矛盾。", "桌子": "语义：“哥哥”是人，不能说“我哥哥是桌子”。"}, "sentence_index": 0, "correct_answer": "大学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我考上了大学生。", "explanation": "这里应该用〈大学〉。“考上”后接的是学校，“大学生”指人，不能说“考上大学生”。"}, {"text": "驾校的大学生都很认真。", "explanation": "这里应该用〈学员〉。“学员”指在驾校或培训班学习的人，“大学生”指在大学读书的人，不能用于驾校。"}, {"text": "这座大学生有很多商店和餐厅。", "explanation": "这里应该用〈大学城〉。“大学城”指聚集了多所大学的地方，“大学生”指人，不能用来形容地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大学生", "is_correct": true, "explanation": "正确。“大学生们正在教室里上课”语义通顺。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不在教室里上课，与句意相矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人一般不会在教室里上课，与句意不符。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“上课”的主语一般是学生或老师，“游客”与“上课”搭配不当。"}], "explanations": {"大学生": "正确。“大学生们正在教室里上课”语义通顺。", "乘客": "语义：乘客不在教室里上课，与句意相矛盾。", "病人": "语义：病人一般不会在教室里上课，与句意不符。", "游客": "搭配：“上课”的主语一般是学生或老师，“游客”与“上课”搭配不当。"}, "sentence_index": 6, "correct_answer": "大学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在读大学生。", "explanation": "这里应该用〈大学〉。“读”后面接学校，“大学生”指人，应说“读大学”。"}, {"text": "小学里有很多大学生。", "explanation": "这里应该用〈小学生〉。小学里的学生是小学生，“大学生”指在大学读书的人。"}, {"text": "这所中学有一千名大学生。", "explanation": "这里应该用〈中学生〉。中学的学生是中学生，“大学生”不能用来指中学的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥是一只大学生，在北京读书。", "corrected_sentence": "我表哥是一名大学生，在北京读书。", "error_description": "量词错误：指人的“大学生”要用“名”或“个”，“只”多用于动物。正确的是“一名大学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表姐是大学生们，在南京读书。", "corrected_sentence": "表姐是大学生，在南京读书。", "error_description": "复数标记错误：“们”表示复数，而“表姐”指一个人，不能加“们”。正确的是“表姐是大学生，在南京读书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
