INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86850, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86850, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "像下面所说的。", "primary_collocate": null, "pronunciation": "rú xià", "ipa": "ɻu˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "请注意如下几点。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如下问题，请大家想一想。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有如下规定：不能迟到。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看如下例子。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说了如下的话。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请完成如下三个任务。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想提出如下建议。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家要遵守如下要求。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提了如下的问题，我答不出来。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通知里有如下内容：明天不上课。", "target_word": "如下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作定语，指下面所说的：如下几点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如下", "is_correct": true, "explanation": "“如下”作定语，指下面所说的，“请注意如下几点”语义通顺，是正确答案。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“注意”要求关注事物，“忘记几点”与“请注意”的语义相反。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”的对象是任务或工作，不能与“几点”组成“完成几点”。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“注意”无法搭配，“请注意睡觉几点”不通。"}], "explanations": {"如下": "“如下”作定语，指下面所说的，“请注意如下几点”语义通顺，是正确答案。", "忘记": "语义：“注意”要求关注事物，“忘记几点”与“请注意”的语义相反。", "完成": "搭配：“完成”的对象是任务或工作，不能与“几点”组成“完成几点”。", "睡觉": "语义：“睡觉”与“注意”无法搭配，“请注意睡觉几点”不通。"}, "sentence_index": 0, "correct_answer": "如下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如下有问题，就来找我。", "explanation": "这里应该用〈如果〉。引出假设的连词是“如果”，“如下”表示下面所说，不能引出假设。"}, {"text": "如下简单的问题，大家都会做。", "explanation": "这里应该用〈如此〉。“如下”指下面所说，不能修饰“简单”，表示程度应用“如此”。"}, {"text": "他终于如下了心愿。", "explanation": "这里应该用〈如愿〉。“如愿”表示实现心愿，“如下”表示下面所说，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如下", "is_correct": true, "explanation": "“如下”作定语，指下面所说的，“我想提出如下建议”语义通顺，是正确答案。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“提出建议”无关，“提出唱建议”不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”是动作，不能修饰“建议”作定语，与“提出”也搭配不当。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“建议”搭配不当，“提出吃建议”不通。"}], "explanations": {"如下": "“如下”作定语，指下面所说的，“我想提出如下建议”语义通顺，是正确答案。", "唱": "语义：“唱”与“提出建议”无关，“提出唱建议”不通。", "拒绝": "搭配：“拒绝”是动作，不能修饰“建议”作定语，与“提出”也搭配不当。", "吃": "语义：“吃”与“建议”搭配不当，“提出吃建议”不通。"}, "sentence_index": 6, "correct_answer": "如下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如下有需要，请随时告诉我。", "explanation": "这里应该用〈如果〉。引出假设的连词是“如果”，“如下”表示下面所说，不能引出假设。"}, {"text": "他说话的声音如下，像个孩子。", "explanation": "这里应该用〈如同〉。表示像什么用“如同”，“如下”表示下面所说，不能表示比喻。"}, {"text": "这次考试如下难，很多人没及格。", "explanation": "这里应该用〈如此〉。表示程度“这样”用“如此”，“如下”指下面所说的，不能修饰形容词“难”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请遵守如下了规定。", "corrected_sentence": "请遵守如下规定。", "error_description": "体标错误：定语“如下”后不能接“了”，应去掉“了”，说“请遵守如下规定。”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请记住如下了三点。", "corrected_sentence": "请记住如下三点。", "error_description": "体标错误：定语“如下”不能接“了”，应去掉“了”，说“请记住如下三点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
