INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86851, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "确实是说真的是这样，没有错。", "primary_collocate": null, "pronunciation": "què shí", "ipa": "tɕʰɥɛ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这家饭馆的菜确实很好吃。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天确实比昨天冷。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说得确实没错。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法确实很有用。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我确实不知道他在哪儿。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你确实应该多休息。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书确实很有意思。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他确实来过我们家。", "target_word": "确实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的秋天确实很美。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事确实是我的错。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "確實", "label": "繁体"}, {"form": "确确实实", "label": "重叠"}], "register": "中性", "sense_fingerprint": "确实：副词，表示情况真的是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81d15118-0c81-46f0-82ea-032f2bef765b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86851, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "确实", "is_correct": true, "explanation": "正确答案：确实（què shí），副词，表示情况真的是这样。"}, {"text": "却是", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，“却是”表示转折，意思是“不过”，不是“真的”。"}, {"text": "缺失", "is_correct": false, "explanation": "quē shī 与 què shí 两个字的声调都不同，缺失指缺少，与“真的”无关。"}, {"text": "绝食", "is_correct": false, "explanation": "jué 与 què 声母不同（j 与 q），绝食指不吃饭，与“真的”无关。"}], "explanations": {"确实": "正确答案：确实（què shí），副词，表示情况真的是这样。", "却是": "shì（第四声）与 shí（第二声）声调不同，“却是”表示转折，意思是“不过”，不是“真的”。", "缺失": "quē shī 与 què shí 两个字的声调都不同，缺失指缺少，与“真的”无关。", "绝食": "jué 与 què 声母不同（j 与 q），绝食指不吃饭，与“真的”无关。"}, "sentence_index": null, "correct_answer": "确实"}, "level_3": {"options": [{"text": "确实", "is_correct": true, "explanation": "正确：确实表示肯定，与“很好吃”搭配，句子通顺。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，不能说明菜的味道是“突然很好吃”。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同，不能修饰“很好吃”这样的状态。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示时间很快，与“好吃”的性质无关，句子意思不通。"}], "explanations": {"确实": "正确：确实表示肯定，与“很好吃”搭配，句子通顺。", "突然": "语义：“突然”表示事情忽然发生，不能说明菜的味道是“突然很好吃”。", "一起": "搭配：“一起”表示共同，不能修饰“很好吃”这样的状态。", "马上": "语义：“马上”表示时间很快，与“好吃”的性质无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "确实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个办法确实可能有用。", "explanation": "这里应该用〈可能〉。确实表示肯定，与“可能”的推测相矛盾；没有把握时只说“这个办法可能有用”。"}, {"text": "这个办法确实也许有用。", "explanation": "这里应该用〈大概〉。确实表示肯定，不能与表示推测的说法同用；对效果没有把握时要说“大概”。"}, {"text": "这个办法确实有没有用？", "explanation": "这里应该用〈到底〉。确实表示肯定，不能用于正反问句；追问要说“这个办法到底有没有用？”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确实", "is_correct": true, "explanation": "正确：确实表示肯定，与“很有意思”搭配，句子通顺。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示时间很快，不能说明书“立刻很有意思”，句子意思不通。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示事情突然出现，与“有意思”的性质无关。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要修饰人的动作，不能修饰“这本书很有意思”这样的状态。"}], "explanations": {"确实": "正确：确实表示肯定，与“很有意思”搭配，句子通顺。", "立刻": "语义：“立刻”表示时间很快，不能说明书“立刻很有意思”，句子意思不通。", "忽然": "语义：“忽然”表示事情突然出现，与“有意思”的性质无关。", "亲自": "搭配：“亲自”要修饰人的动作，不能修饰“这本书很有意思”这样的状态。"}, "sentence_index": 6, "correct_answer": "确实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你确实早点来。", "explanation": "这里应该用〈一定〉。确实表示已经成立的事实，不能用于请求别人做事；请人做事要说“一定”。"}, {"text": "我确实可能错了。", "explanation": "这里应该用〈也许〉。确实表示肯定，不能与表示不确定的说法同用；对可能的错误要说“也许”。"}, {"text": "你确实别担心。", "explanation": "这里应该用〈一定〉。确实用于肯定已经成立的事，不能直接用于劝说或命令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天天气确实得很热。", "corrected_sentence": "今天天气确实很热。", "error_description": "“确实”是副词，后面不能直接加“得”，应说成“今天天气确实很热”。“确实得很热”中的“得”是多余的，错在“确实”的补语形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他确实了很努力。", "corrected_sentence": "他确实很努力。", "error_description": "“确实”是副词，后面不能直接加体标“了”。应去掉“了”，说成“他确实很努力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
