INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同父母（或同父、同母）而年纪比自己小的女子。", "primary_collocate": null, "pronunciation": "mèi mei", "ipa": "meɪ˥˩ meɪ", "syllable_count": 2, "sentences": [{"text": "妹妹和我长得很像。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的妹妹在上大学。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹的生日是下个月。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是我的哥哥，她是我的妹妹。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妹妹和我是同一个妈妈生的。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只有一个妹妹，没有哥哥。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹出生的时候，我已经五岁了。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妹妹常常给远方的父母打电话。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家有三个孩子，我最大，妹妹最小。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的妹妹刚工作，她每个月都会寄钱给爸爸妈妈。", "target_word": "妹妹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "亲妹妹", "label": "复合"}], "register": "中性", "sense_fingerprint": "妹妹：同父母（或同父、同母）而年纪比自己小的女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfa9012-682f-47cd-812e-5fb770f93c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妹妹", "is_correct": true, "explanation": "正确：「妹妹」是人，可以和「我」长得很像。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」是家具，不会和人长得很像。"}, {"text": "声音", "is_correct": false, "explanation": "体貌：「长得像」说的是外貌，「声音」不能说长得像。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」是物件，不能和「我」比较长相。"}], "explanations": {"妹妹": "正确：「妹妹」是人，可以和「我」长得很像。", "桌子": "语义：「桌子」是家具，不会和人长得很像。", "声音": "体貌：「长得像」说的是外貌，「声音」不能说长得像。", "窗户": "语义：「窗户」是物件，不能和「我」比较长相。"}, "sentence_index": 0, "correct_answer": "妹妹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的妹妹比我大两岁。", "explanation": "这里应该用〈姐姐〉。妹妹指比自己小的同胞女性，比自己大的要说姐姐。"}, {"text": "他是我的妹妹。", "explanation": "这里应该用〈弟弟〉。妹妹指女性，男性的同胞晚辈要说弟弟。"}, {"text": "我妈妈的妹妹是我的妹妹。", "explanation": "这里应该用〈阿姨〉。妈妈的妹妹是我的阿姨，不是同父母的妹妹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妹妹", "is_correct": true, "explanation": "正确：「妹妹」是人，可以在「___出生的时候」中作主语。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：「汽车」是机器，不会「出生」，句子不成立。"}, {"text": "数学", "is_correct": false, "explanation": "语义：「数学」是学科，不能「出生」。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：「公司」说「成立」，不说「出生」。"}], "explanations": {"妹妹": "正确：「妹妹」是人，可以在「___出生的时候」中作主语。", "汽车": "语义：「汽车」是机器，不会「出生」，句子不成立。", "数学": "语义：「数学」是学科，不能「出生」。", "公司": "搭配：「公司」说「成立」，不说「出生」。"}, "sentence_index": 6, "correct_answer": "妹妹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一只妹妹。", "explanation": "这里应该用〈个〉。「只」多用于动物，指人要用「个」。"}, {"text": "我家有一张妹妹。", "explanation": "这里应该用〈个〉。「张」用于平面的东西，指人要用「个」。"}, {"text": "我家有一台妹妹。", "explanation": "这里应该用〈个〉。「台」用于机器等物件，指人要用「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
