INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86857, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说到是说起一件事，或者谈到某个人。", "primary_collocate": null, "pronunciation": "shuō dào", "ipa": "ʂwo˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "说到中国菜，我最喜欢四川菜。", "target_word": "说到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说到我的朋友小李，他是个很热情的人。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到学汉语，我觉得听力最难。", "target_word": "说到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们聊天时说到了下个月的旅行。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到足球，他可以说一个小时。", "target_word": "说到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一说到家乡，爷爷的眼睛就亮了。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到这家饭馆，我去过三次了。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家说到明天的比赛，都很紧张。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到音乐，她比我懂得多。", "target_word": "说到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭的时候，我们说到了小学老师。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说到了", "label": "体标"}, {"form": "说到过", "label": "体标"}, {"form": "说到做到", "label": "复合"}], "register": "口语", "sense_fingerprint": "以某个话题或某人为话头说起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "说到", "is_correct": true, "explanation": "正确答案：说到（shuō dào），意思是说起某个话题或某人。"}, {"text": "刷到", "is_correct": false, "explanation": "shuā（第一声）与 shuō（第一声）韵母不同（a/o）。刷到意思是刷手机时看到。"}, {"text": "戳到", "is_correct": false, "explanation": "chuō（第一声）与 shuō（第一声）声母不同（ch/sh）。戳到意思是用尖的东西碰到。"}, {"text": "水稻", "is_correct": false, "explanation": "shuǐ（第三声）与 shuō（第一声）韵母和声调都不同，意思是水稻。"}, {"text": "睡到", "is_correct": false, "explanation": "shuì（第四声）与 shuō（第一声）韵母和声调都不同，意思是睡到某个时间。"}], "explanations": {"说到": "正确答案：说到（shuō dào），意思是说起某个话题或某人。", "刷到": "shuā（第一声）与 shuō（第一声）韵母不同（a/o）。刷到意思是刷手机时看到。", "戳到": "chuō（第一声）与 shuō（第一声）声母不同（ch/sh）。戳到意思是用尖的东西碰到。", "水稻": "shuǐ（第三声）与 shuō（第一声）韵母和声调都不同，意思是水稻。", "睡到": "shuì（第四声）与 shuō（第一声）韵母和声调都不同，意思是睡到某个时间。"}, "sentence_index": null, "correct_answer": "说到"}, "level_3": {"options": [{"text": "说到", "is_correct": true, "explanation": "正确：“说到”在这里引出话题，表示说起中国菜。"}, {"text": "去", "is_correct": false, "explanation": "配价：“去”后要接处所，不能直接接“中国菜”。"}, {"text": "逛", "is_correct": false, "explanation": "搭配：“逛”接地点，如“逛超市”，不接菜品。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”是移动动作，不能接“中国菜”，也不能引出话题。"}], "explanations": {"说到": "正确：“说到”在这里引出话题，表示说起中国菜。", "去": "配价：“去”后要接处所，不能直接接“中国菜”。", "逛": "搭配：“逛”接地点，如“逛超市”，不接菜品。", "跑": "搭配：“跑”是移动动作，不能接“中国菜”，也不能引出话题。"}, "sentence_index": 0, "correct_answer": "说到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温说到了三十度。", "explanation": "这里应该用〈达到〉。说到表示谈及话题，不能用于温度或数量，温度要用“达到”。"}, {"text": "她听完后说到了一声叹息。", "explanation": "这里应该用〈发出〉。说到表示谈及话题，不能用于发出声音或叹息，应说“发出了一声叹息”。"}, {"text": "我伸手在黑暗中说到了开关。", "explanation": "这里应该用〈摸到〉。说到表示谈及话题，不能表示用手碰到东西，摸到开关要用“摸到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "说到", "is_correct": true, "explanation": "正确答案：说到（shuō dào），意思是说起某个话题或某人。"}, {"text": "烧到", "is_correct": false, "explanation": "shāo（第一声）与 shuō（第一声）韵母不同（ao/uo）。烧到意思是温度等达到某个程度。"}, {"text": "摔到", "is_correct": false, "explanation": "shuāi（第一声）与 shuō（第一声）韵母不同（uai/uo）。摔到意思是跌落到某处。"}, {"text": "数到", "is_correct": false, "explanation": "数到（shǔ dào，第三声）与 shuō（第一声）韵母和声调都不同，意思是数到某个数字。"}, {"text": "刷到", "is_correct": false, "explanation": "shuā（第一声）与 shuō（第一声）只差韵母（a/o），意思是刷手机时看到。"}], "explanations": {"说到": "正确答案：说到（shuō dào），意思是说起某个话题或某人。", "烧到": "shāo（第一声）与 shuō（第一声）韵母不同（ao/uo）。烧到意思是温度等达到某个程度。", "摔到": "shuāi（第一声）与 shuō（第一声）韵母不同（uai/uo）。摔到意思是跌落到某处。", "数到": "数到（shǔ dào，第三声）与 shuō（第一声）韵母和声调都不同，意思是数到某个数字。", "刷到": "shuā（第一声）与 shuō（第一声）只差韵母（a/o），意思是刷手机时看到。"}, "sentence_index": null, "correct_answer": "说到"}, "level_3": {"options": [{"text": "说到", "is_correct": true, "explanation": "正确：“说到”在这里引出话题，表示说起这家饭馆。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”接住处，如“住宾馆”，不能直接接“饭馆”。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆除，不能用来引出话题，“拆这家饭馆”说不通。"}, {"text": "躲", "is_correct": false, "explanation": "配价：“躲”要接躲避的对象，或用“躲进”，不能直接接“饭馆”。"}], "explanations": {"说到": "正确：“说到”在这里引出话题，表示说起这家饭馆。", "住": "搭配：“住”接住处，如“住宾馆”，不能直接接“饭馆”。", "拆": "语义：“拆”是拆除，不能用来引出话题，“拆这家饭馆”说不通。", "躲": "配价：“躲”要接躲避的对象，或用“躲进”，不能直接接“饭馆”。"}, "sentence_index": 6, "correct_answer": "说到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们爬了一上午，终于说到了山顶。", "explanation": "这里应该用〈到达〉。说到表示谈及话题，不表示走到某个地方，到了山顶要用“到达”。"}, {"text": "我在楼下说到了哭声。", "explanation": "这里应该用〈听到〉。说到表示谈及话题，不能用于听见声音，应说“听到了哭声”。"}, {"text": "厨房里说到了香味。", "explanation": "这里应该用〈闻到〉。说到表示谈及话题，不能用于闻到气味，应说“闻到了香味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开会的时候，大家说到着新产品的价格。", "corrected_sentence": "开会的时候，大家说到了新产品的价格。", "error_description": "错误：“说到着”。正确：“说到了”。“着”表示动作持续，这里说的是已经发生的事，应使用体标“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没说到了自己的家人。", "corrected_sentence": "他从来没说到过自己的家人。", "error_description": "错误：“没说到了”。正确：“没说到过”。“没”否定过去的经历时不能和“了”一起用，应使用体标“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
