INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谈到；提到某人或某事。", "primary_collocate": null, "pronunciation": "shuō dào", "ipa": "ʂwo˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "说到这个问题，老师有不同的看法。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上说到了我们的新计划。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到小王，大家都夸他工作认真。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说到小时候的事，笑了起来。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天说到了考试的时间。", "target_word": "说到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说到旅行，我最想去云南。", "target_word": "说到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说到钱的问题，大家都不说话了。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才你说到的那本书，我也想看。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到工作，他总是很高兴。", "target_word": "说到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在信里说到了家里的新房子。", "target_word": "说到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说到了", "label": "体标"}, {"form": "说到过", "label": "体标"}], "register": "口语", "sense_fingerprint": "谈话中提到某人或某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说到", "is_correct": true, "explanation": "正确。说到表示谈到这个问题，符合句意。"}, {"text": "吃到", "is_correct": false, "explanation": "搭配：“吃到”接的应是食物，不能接“问题”。"}, {"text": "买到", "is_correct": false, "explanation": "搭配：“买到”接的是商品，问题不能被买到。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：问题不是气味，“闻到这个问题”说不通。"}], "explanations": {"说到": "正确。说到表示谈到这个问题，符合句意。", "吃到": "搭配：“吃到”接的应是食物，不能接“问题”。", "买到": "搭配：“买到”接的是商品，问题不能被买到。", "闻到": "语义：问题不是气味，“闻到这个问题”说不通。"}, "sentence_index": 0, "correct_answer": "说到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对我说到了一句谢谢。", "explanation": "这里应该用〈说〉。说到表示谈到某件事或某人，引出一句话要用“说”。"}, {"text": "他跑了一上午，终于说到了火车站。", "explanation": "这里应该用〈到达〉。说到表示谈到某件事或某人，表示走到某地要用“到达”。"}, {"text": "他把“妈”说到了第三声。", "explanation": "这里应该用〈读〉。说到表示谈到话题，说出字音要用“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说到", "is_correct": true, "explanation": "正确。说到表示谈到钱的问题，符合句意。"}, {"text": "尝到", "is_correct": false, "explanation": "语义：“尝到”的对象是味道，钱的问题不能尝。"}, {"text": "喝到", "is_correct": false, "explanation": "搭配：“喝”接饮品，不能接“钱的问题”，句子说不通。"}, {"text": "咬到", "is_correct": false, "explanation": "搭配：“咬到”搭配的是可以咬的东西，不能接“问题”。"}], "explanations": {"说到": "正确。说到表示谈到钱的问题，符合句意。", "尝到": "语义：“尝到”的对象是味道，钱的问题不能尝。", "喝到": "搭配：“喝”接饮品，不能接“钱的问题”，句子说不通。", "咬到": "搭配：“咬到”搭配的是可以咬的东西，不能接“问题”。"}, "sentence_index": 6, "correct_answer": "说到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她伸手说到了桌上的杯子。", "explanation": "这里应该用〈碰到〉。说到表示谈及话题，用手碰到东西要用“碰到”。"}, {"text": "他把书说到了书架上。", "explanation": "这里应该用〈放〉。说到表示谈到话题，把东西放到某处要用“放”。"}, {"text": "我们走了一个小时，终于说到了城外。", "explanation": "这里应该用〈到达〉。说到表示谈及话题，走到某地要用“到达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们说到着新计划。", "corrected_sentence": "我们说到了新计划。", "error_description": "错误：“说到着”。正确：“说到了”。“着”表示动作持续，这里说的是已经发生的事，应使用体标“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "说到的这里，大家都笑了。", "corrected_sentence": "说到这里，大家都笑了。", "error_description": "助词错误：“这里”是指示代词，前面不能加“说到的”来修饰，多余的“的”应删去，应说“说到这里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
