INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工资是做事情以后得到的钱。", "primary_collocate": null, "pronunciation": "gōng zī", "ipa": "kʊŋ˥ tsɿ˥", "syllable_count": 2, "sentences": [{"text": "我这个月的工资已经花完了。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个月的工资是五千块。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用第一笔工资给妈妈买了礼物。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作十天，老板就给了我工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作工资不高，但是很轻松。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资一发，我就去交房租。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天打工，就是为了拿工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥拿到工资后请我们吃饭。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一份工资高一点的工作。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完这个月的工作，你就可以拿到工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "工资单", "label": "复合"}, {"form": "工資", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做工作之后拿到的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86859, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工资", "is_correct": true, "explanation": "正确。工资：做事以后得到的钱。"}, {"text": "公司", "is_correct": false, "explanation": "gōngsī 与 gōngzī 的第二个音节声母不同（s 与 z），意思是公司。"}, {"text": "公子", "is_correct": false, "explanation": "gōngzǐ（第三声）与 gōngzī（第一声）声调不同，意思是公子，指富贵人家的儿子。"}, {"text": "攻击", "is_correct": false, "explanation": "gōngjī 与 gōngzī 的第二个音节声母不同（j 与 z），意思是攻击。"}], "explanations": {"工资": "正确。工资：做事以后得到的钱。", "公司": "gōngsī 与 gōngzī 的第二个音节声母不同（s 与 z），意思是公司。", "公子": "gōngzǐ（第三声）与 gōngzī（第一声）声调不同，意思是公子，指富贵人家的儿子。", "攻击": "gōngjī 与 gōngzī 的第二个音节声母不同（j 与 z），意思是攻击。"}, "sentence_index": null, "correct_answer": "工资"}, "level_3": {"options": [{"text": "工资", "is_correct": true, "explanation": "正确。工资可以花完，符合句中的“花完了”。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“花完”说的是钱，礼物不能被花完。"}, {"text": "工作", "is_correct": false, "explanation": "语义：工作是做的事，不是可以花掉的东西，句子说不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“花”要接钱，不能接饭菜，说“饭菜花完了”不通。"}], "explanations": {"工资": "正确。工资可以花完，符合句中的“花完了”。", "礼物": "搭配：“花完”说的是钱，礼物不能被花完。", "工作": "语义：工作是做的事，不是可以花掉的东西，句子说不通。", "饭菜": "搭配：“花”要接钱，不能接饭菜，说“饭菜花完了”不通。"}, "sentence_index": 0, "correct_answer": "工资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上捡到了一百块，高兴地说这是他的工资。", "explanation": "这里应该用〈钱〉。工资是做事情以后得到的钱，捡到的钱不是工资。"}, {"text": "我把钱存进银行，每年银行还会给我一点工资。", "explanation": "这里应该用〈利息〉。工资是做事情得到的报酬，存款的收益要用利息。"}, {"text": "他整天在家睡觉，亲戚每个月却给他一笔工资。", "explanation": "这里应该用〈生活费〉。工资以做事为前提，不工作却拿到的钱不叫工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": true, "explanation": "正确。拿工资与“打工”的目的相符。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“拿”的是可以得到的东西，故事不能拿来作为打工的目的，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“拿”不能和“空气”搭配，空气不是能拿到手的东西。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是打工的报酬，为了石头去打工说不通。"}], "explanations": {"工资": "正确。拿工资与“打工”的目的相符。", "故事": "语义：“拿”的是可以得到的东西，故事不能拿来作为打工的目的，句子说不通。", "空气": "搭配：“拿”不能和“空气”搭配，空气不是能拿到手的东西。", "石头": "语义：石头不是打工的报酬，为了石头去打工说不通。"}, "sentence_index": 6, "correct_answer": "工资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他上个月辞去了工资。", "explanation": "这里应该用〈工作〉。辞去的是工作，工资是拿到的钱，不能辞去。"}, {"text": "政府每个月给失业的人工资。", "explanation": "这里应该用〈补助〉。工资是给有工作的人的报酬，给失业者的生活费要用补助。"}, {"text": "我在家里喝茶，邻居每个月却给我一笔工资。", "explanation": "这里应该用〈接济〉。工资以做事为前提，不工作拿到的钱不叫工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上个月领到了一块工资。", "corrected_sentence": "他上个月领到了一份工资。", "error_description": "量词错误：“工资”应该用量词“份”或“笔”，说成“块”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天终于领了到工资。", "corrected_sentence": "他今天终于领到了工资。", "error_description": "补语位置错误：结果补语“到”应紧跟动词，“了”应放在补语之后，应说“领到了工资”，不能说“领了到工资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
