INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "雇主定期付给劳动者的报酬。", "primary_collocate": null, "pronunciation": "gōng zī", "ipa": "kʊŋ˥ tsɿ˥", "syllable_count": 2, "sentences": [{"text": "公司每个月十号发工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂没有按时给工人发工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板每月给工人的工资都不一样。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工的工资是按月付的。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工资每个月会打到银行卡里。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年公司提高了大家的工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板拖了三个月，还没付工人的工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工资每周发一次。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月发工资以前，会计要先算好钱。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府规定，老板不能少给工人工资。", "target_word": "工资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "工资单", "label": "复合"}, {"form": "工資", "label": "繁体"}], "register": "中性", "sense_fingerprint": "雇主按期付给劳动者的报酬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工资", "is_correct": true, "explanation": "正确。工资：雇主定期付给劳动者的报酬。"}, {"text": "公司", "is_correct": false, "explanation": "gōngsī 与 gōngzī 的第二个音节声母不同（s 与 z），意思是公司。"}, {"text": "公子", "is_correct": false, "explanation": "gōngzǐ（第三声）与 gōngzī（第一声）声调不同，意思是公子，指富贵人家的儿子。"}, {"text": "攻击", "is_correct": false, "explanation": "gōngjī 与 gōngzī 的第二个音节声母不同（j 与 z），意思是攻击。"}], "explanations": {"工资": "正确。工资：雇主定期付给劳动者的报酬。", "公司": "gōngsī 与 gōngzī 的第二个音节声母不同（s 与 z），意思是公司。", "公子": "gōngzǐ（第三声）与 gōngzī（第一声）声调不同，意思是公子，指富贵人家的儿子。", "攻击": "gōngjī 与 gōngzī 的第二个音节声母不同（j 与 z），意思是攻击。"}, "sentence_index": null, "correct_answer": "工资"}, "level_3": {"options": [{"text": "工资", "is_correct": true, "explanation": "正确。公司定期发放工资，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：公司不会发作业，作业是老师布置、学生完成的东西。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“发”后面接“脾气”是人的动作，公司不会发脾气。"}, {"text": "香味", "is_correct": false, "explanation": "语义：“发”的是香味，但公司每月十号发香味说不通，与句中的薪酬发放不符。"}], "explanations": {"工资": "正确。公司定期发放工资，符合句意。", "作业": "语义：公司不会发作业，作业是老师布置、学生完成的东西。", "脾气": "搭配：“发”后面接“脾气”是人的动作，公司不会发脾气。", "香味": "语义：“发”的是香味，但公司每月十号发香味说不通，与句中的薪酬发放不符。"}, "sentence_index": 0, "correct_answer": "工资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他帮我修好了电脑，我给了他一笔工资。", "explanation": "这里应该用〈报酬〉。工资是雇主定期付给员工的钱，一次帮忙的谢礼要用报酬。"}, {"text": "他买彩票中了一百万，这笔工资让他很高兴。", "explanation": "这里应该用〈奖金〉。工资是雇主定期付给劳动者的报酬，中彩票得到的钱不是工资。"}, {"text": "我把房子租给别人，每个月收他的工资。", "explanation": "这里应该用〈房租〉。工资是雇主付给劳动者的报酬，租房子收的钱是房租。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": true, "explanation": "正确。“付工资”指付给工人的报酬，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“付”后面要接钱或账款，不能接“时间”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以付的报酬，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能拿来还给工人，这里说不通。"}], "explanations": {"工资": "正确。“付工资”指付给工人的报酬，符合句意。", "时间": "搭配：“付”后面要接钱或账款，不能接“时间”。", "石头": "语义：石头不是可以付的报酬，句子说不通。", "空气": "语义：空气不能拿来还给工人，这里说不通。"}, "sentence_index": 6, "correct_answer": "工资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他决定离开公司，就辞去了一笔工资。", "explanation": "这里应该用〈工作〉。辞去的是工作，工资是拿到的钱，不能辞去。"}, {"text": "政府每月给失业的老人工资。", "explanation": "这里应该用〈补助〉。工资是给有工作的人的报酬，给老人的生活费要用补助。"}, {"text": "他每月去超市买东西，超市却每月给他一笔工资。", "explanation": "这里应该用〈优惠〉。他与超市没有雇佣关系，所得不是工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们月底才拿了到工资。", "corrected_sentence": "工人们月底才拿到工资。", "error_description": "语序错误：“了”不能放在动词“拿”和结果补语“到”之间，应说“拿到工资”，“到”紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板每个月都按时给工人发一只工资。", "corrected_sentence": "老板每个月都按时给工人发一笔工资。", "error_description": "量词错误：“工资”可用量词“笔”或“份”，“只”多用于动物，不能用于工资，应改为“一笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
