INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "府是很大很气派的房子，有钱的人家住。", "primary_collocate": null, "pronunciation": "fǔ", "ipa": "fu˨˩˦", "syllable_count": 1, "sentences": [{"text": "回府的路上，他看见门口站着两个守卫。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老爷每天早上从府里出来，去衙门办事。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王大人回府以后，先喝了一杯热茶。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "府里的院子很大，种了很多花。", "target_word": "府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "府里的大门前有两头石狮子。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "府里的摆设很气派，大家都称赞不已。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是府里的厨师，每天要做几十个人的饭。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧里的老爷一直住在府里。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，府里的灯都亮了。", "target_word": "府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下人们把府里打扫得干干净净。", "target_word": "府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "王府", "label": "复合"}, {"form": "府邸", "label": "复合"}], "register": "书面", "sense_fingerprint": "旧时有钱人家住的大宅院", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "府", "is_correct": true, "explanation": "正确。府：很大很气派的大宅院，有钱人家住。"}, {"text": "富", "is_correct": false, "explanation": "fù（第四声）与 fǔ（第三声）声调不同，意思是富裕。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ 与 fǔ 声母不同（h 与 f），意思是老虎。"}, {"text": "福", "is_correct": false, "explanation": "fú（第二声）与 fǔ（第三声）声调不同，意思是幸福。"}], "explanations": {"府": "正确。府：很大很气派的大宅院，有钱人家住。", "富": "fù（第四声）与 fǔ（第三声）声调不同，意思是富裕。", "虎": "hǔ 与 fǔ 声母不同（h 与 f），意思是老虎。", "福": "fú（第二声）与 fǔ（第三声）声调不同，意思是幸福。"}, "sentence_index": null, "correct_answer": "府"}, "level_3": {"options": [{"text": "府", "is_correct": true, "explanation": "正确。回府指回到大宅，与句中的守卫相符。"}, {"text": "鸡窝", "is_correct": false, "explanation": "语义：守卫不会站在鸡窝门口，鸡窝不是有守卫的大宅。"}, {"text": "鸟笼", "is_correct": false, "explanation": "语义：鸟笼不是可以“回”去的地方，门口也不会站守卫。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“回”不能接“冰箱”，说“回冰箱”不通。"}], "explanations": {"府": "正确。回府指回到大宅，与句中的守卫相符。", "鸡窝": "语义：守卫不会站在鸡窝门口，鸡窝不是有守卫的大宅。", "鸟笼": "语义：鸟笼不是可以“回”去的地方，门口也不会站守卫。", "冰箱": "搭配：“回”不能接“冰箱”，说“回冰箱”不通。"}, "sentence_index": 0, "correct_answer": "府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在城东开了一个府，专门卖早点。", "explanation": "这里应该用〈店〉。府指很大很气派的住宅，卖东西的地方要用店。"}, {"text": "小鸟在树上搭了一个府。", "explanation": "这里应该用〈窝〉。府指有钱人家住的大宅院，鸟住的地方要用窝。"}, {"text": "我每天坐地铁去府里上班，在电脑前写报告。", "explanation": "这里应该用〈公司〉。府指有钱人家住的大宅院，现代上班的地方要用公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86863, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "府", "is_correct": true, "explanation": "正确。府：很大很气派的大宅院，有钱人家住。"}, {"text": "父", "is_correct": false, "explanation": "fù（第四声）与 fǔ（第三声）声调不同，意思是父亲。"}, {"text": "扶", "is_correct": false, "explanation": "fú（第二声）与 fǔ（第三声）声调不同，意思是扶助、搀扶。"}, {"text": "付", "is_correct": false, "explanation": "fù（第四声）与 fǔ（第三声）声调不同，意思是付钱。"}], "explanations": {"府": "正确。府：很大很气派的大宅院，有钱人家住。", "父": "fù（第四声）与 fǔ（第三声）声调不同，意思是父亲。", "扶": "fú（第二声）与 fǔ（第三声）声调不同，意思是扶助、搀扶。", "付": "fù（第四声）与 fǔ（第三声）声调不同，意思是付钱。"}, "sentence_index": null, "correct_answer": "府"}, "level_3": {"options": [{"text": "府", "is_correct": true, "explanation": "正确。府里指有钱人家的大宅，厨师在府里工作。"}, {"text": "教室", "is_correct": false, "explanation": "语义：厨师不在教室里工作，教室与“做几十个人的饭”的场景不符。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“里”前的地点要能作为厨师工作的场所，书包不能这样用。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是厨师工作的地方，句子说不通。"}], "explanations": {"府": "正确。府里指有钱人家的大宅，厨师在府里工作。", "教室": "语义：厨师不在教室里工作，教室与“做几十个人的饭”的场景不符。", "书包": "搭配：“里”前的地点要能作为厨师工作的场所，书包不能这样用。", "冰箱": "语义：冰箱不是厨师工作的地方，句子说不通。"}, "sentence_index": 6, "correct_answer": "府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我放学回府，妈妈已经做好了饭。", "explanation": "这里应该用〈家〉。府多指有钱人的大宅，普通人的住处要用家。"}, {"text": "这间小府只有两个房间。", "explanation": "府指很大很气派的大宅院，形容“小”的房子不能用府。"}, {"text": "这座府是一户人家住的小平房。", "explanation": "府指很气派的大宅，一户人家住的小平房不能叫府。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条府里住着一位老爷。", "corrected_sentence": "那座府里住着一位老爷。", "error_description": "量词错误：府是建筑，量词应用“座”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下人们在里府忙碌。", "corrected_sentence": "下人们在府里忙碌。", "error_description": "方位词位置错误：“府里”是“府”加方位词“里”，应说“在府里”，不能说“在里府”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
