INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物或器物的出入口；也指安在出入口可开关的装置。", "primary_collocate": null, "pronunciation": "mén", "ipa": "mən˧˥", "syllable_count": 1, "sentences": [{"text": "请把门关上。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人在敲门。", "target_word": "门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他拉开门，看见外面下雪了。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门没有锁，你直接进来吧。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门是红色的。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风一吹，门就开了。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出去的时候，别忘了锁门。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的门坏了，打不开。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱的门没关好，里面的菜坏了。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推开门，走进了房间。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扇", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "門", "label": "繁体"}, {"form": "大门", "label": "复合词"}, {"form": "门口", "label": "复合词"}, {"form": "前门", "label": "复合词"}], "register": "中性", "sense_fingerprint": "建筑物或器物的出入口及可开关的门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "门", "is_correct": true, "explanation": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。"}, {"text": "闷", "is_correct": false, "explanation": "mèn（第四声）与 mén（第二声）声调不同，意思是烦闷。"}, {"text": "盟", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是结盟。"}, {"text": "民", "is_correct": false, "explanation": "mín 与 mén 韵母不同（in 与 en），意思是人民。"}], "explanations": {"门": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。", "闷": "mèn（第四声）与 mén（第二声）声调不同，意思是烦闷。", "盟": "méng 与 mén 韵母不同（eng 与 en），意思是结盟。", "民": "mín 与 mén 韵母不同（in 与 en），意思是人民。"}, "sentence_index": null, "correct_answer": "门"}, "level_3": {"options": [{"text": "门", "is_correct": true, "explanation": "门：出入口，“关上”可用于门，是本句正确的词。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“关上”不能用于饭，“请把饭关上”不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能被“关上”，与句意不符。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能被“关上”，与句意不符。"}], "explanations": {"门": "门：出入口，“关上”可用于门，是本句正确的词。", "饭": "搭配：“关上”不能用于饭，“请把饭关上”不通。", "树": "语义：树不能被“关上”，与句意不符。", "河": "语义：河不能被“关上”，与句意不符。"}, "sentence_index": 0, "correct_answer": "门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块门是红色的。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“块”用于块状的东西，不用于门。"}, {"text": "这条门很高，要用力才能推开。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“条”用于细长的东西，不用于门。"}, {"text": "这辆门很结实，是木头做的。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“辆”用于车辆，不用于门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "门", "is_correct": true, "explanation": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。"}, {"text": "蒙", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是遮盖或蒙骗。"}, {"text": "闻", "is_correct": false, "explanation": "wén 与 mén 声母不同（w 与 m），意思是听闻或闻嗅。"}, {"text": "们", "is_correct": false, "explanation": "men（轻声）与 mén（第二声）声调不同，意思是表示复数。"}], "explanations": {"门": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。", "蒙": "méng 与 mén 韵母不同（eng 与 en），意思是遮盖或蒙骗。", "闻": "wén 与 mén 声母不同（w 与 m），意思是听闻或闻嗅。", "们": "men（轻声）与 mén（第二声）声调不同，意思是表示复数。"}, "sentence_index": null, "correct_answer": "门"}, "level_3": {"options": [{"text": "门", "is_correct": true, "explanation": "门：出入口，“锁门”指锁上门，是本句正确的词。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“锁”的对象不能是钥匙，说“锁钥匙”不通。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不能被锁，与句意不符。"}, {"text": "灯", "is_correct": false, "explanation": "搭配：“锁”不用于灯，应说“关灯”，说“锁灯”不通。"}], "explanations": {"门": "门：出入口，“锁门”指锁上门，是本句正确的词。", "钥匙": "搭配：“锁”的对象不能是钥匙，说“锁钥匙”不通。", "饭": "语义：饭不能被锁，与句意不符。", "灯": "搭配：“锁”不用于灯，应说“关灯”，说“锁灯”不通。"}, "sentence_index": 6, "correct_answer": "门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家新买了一张门，今天刚装好。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“张”用于桌子、纸等平面的东西，不用于门。"}, {"text": "这根门太窄，大家都进不去。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“根”用于细长的东西，不用于门。"}, {"text": "这顶门很旧了，该换新的了。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“顶”用于帽子、帐篷等，不用于门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一只门打开了。", "corrected_sentence": "他把一扇门打开了。", "error_description": "门的量词应用“扇”。“只”多用于动物等，不用于门。应说“一扇门”，不说“一只门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一直开门着等客人。", "corrected_sentence": "他们一直开着门等客人。", "error_description": "“着”应紧跟动词“开”，说“开着门”，不说“开门着”。错在“着”的位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
