INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86867, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "弄是做一做，搞一搞。", "primary_collocate": null, "pronunciation": "nòng", "ipa": "nʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我来弄点吃的吧。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，我弄不明白。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你帮我弄一下电脑好吗？", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水洒了，快去弄干净。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想弄一张演唱会的票。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在院子里弄花草。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别弄出声音，宝宝在睡觉。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弄了半天，门还是打不开。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题你是怎么弄出来的？", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房间弄得很整齐。", "target_word": "弄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弄了", "label": "体标"}, {"form": "弄弄", "label": "重叠"}], "register": "口语", "sense_fingerprint": "口语里表示动手做、处理、设法得到某事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86867, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弄", "is_correct": true, "explanation": "正确：弄（nòng）是本词，口语中指做、搞一搞。"}, {"text": "农", "is_correct": false, "explanation": "nóng（第二声）与 nòng（第四声）声调不同，意思是农业。"}, {"text": "浓", "is_correct": false, "explanation": "nóng（第二声）与 nòng（第四声）声调不同，意思是浓稠。"}, {"text": "脓", "is_correct": false, "explanation": "nóng（第二声）与 nòng（第四声）声调不同，意思是脓液。"}], "explanations": {"弄": "正确：弄（nòng）是本词，口语中指做、搞一搞。", "农": "nóng（第二声）与 nòng（第四声）声调不同，意思是农业。", "浓": "nóng（第二声）与 nòng（第四声）声调不同，意思是浓稠。", "脓": "nóng（第二声）与 nòng（第四声）声调不同，意思是脓液。"}, "sentence_index": null, "correct_answer": "弄"}, "level_3": {"options": [{"text": "弄", "is_correct": true, "explanation": "正确：“我来弄点吃的”指动手做点吃的，与语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏点吃的”不成立，“欣赏”的对象不是食物。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观点吃的”不通，“参观”指到某处看一看，不能用于食物。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是走路休闲，与“做点吃的”无关。"}], "explanations": {"弄": "正确：“我来弄点吃的”指动手做点吃的，与语境相符。", "欣赏": "搭配：“欣赏点吃的”不成立，“欣赏”的对象不是食物。", "参观": "搭配：“参观点吃的”不通，“参观”指到某处看一看，不能用于食物。", "散步": "语义：“散步”是走路休闲，与“做点吃的”无关。"}, "sentence_index": 0, "correct_answer": "弄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭前一定要先弄手。", "explanation": "这里应该用〈洗〉。弄泛指做、搞，不表示清洗身体部位，应说“洗手”。"}, {"text": "他们昨天弄了一架，今天又和好了。", "explanation": "这里应该用〈吵〉。弄是做、搞的意思，不能表示争吵；说“吵了一架”才对。"}, {"text": "他见到老师，主动弄招呼。", "explanation": "这里应该用〈打〉。弄不能和“招呼”搭配，应说“打招呼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86867, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弄", "is_correct": true, "explanation": "正确：弄（nòng）是本词，口语中指做、搞一搞。"}, {"text": "侬", "is_correct": false, "explanation": "nóng（第二声）与 nòng（第四声）声调不同，意思是吴语中的“你”。"}, {"text": "哝", "is_correct": false, "explanation": "nóng（第二声）与 nòng（第四声）声调不同，意思是低声说话。"}, {"text": "笼", "is_correct": false, "explanation": "lóng 与 nòng 声母、声调都不同，听起来相近，意思是笼子。"}], "explanations": {"弄": "正确：弄（nòng）是本词，口语中指做、搞一搞。", "侬": "nóng（第二声）与 nòng（第四声）声调不同，意思是吴语中的“你”。", "哝": "nóng（第二声）与 nòng（第四声）声调不同，意思是低声说话。", "笼": "lóng 与 nòng 声母、声调都不同，听起来相近，意思是笼子。"}, "sentence_index": null, "correct_answer": "弄"}, "level_3": {"options": [{"text": "弄", "is_correct": true, "explanation": "正确：“别弄出声音”指动手让东西发出声响，与语境相符。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看出声音”不成立，“看出”指看得出，不能与“声音”搭配。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻出声音”不通，“闻”的对象是气味，不能与“声音”搭配。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿出声音”不成立，“穿”的对象是衣服鞋子，不能与“声音”搭配。"}], "explanations": {"弄": "正确：“别弄出声音”指动手让东西发出声响，与语境相符。", "看": "搭配：“看出声音”不成立，“看出”指看得出，不能与“声音”搭配。", "闻": "搭配：“闻出声音”不通，“闻”的对象是气味，不能与“声音”搭配。", "穿": "搭配：“穿出声音”不成立，“穿”的对象是衣服鞋子，不能与“声音”搭配。"}, "sentence_index": 6, "correct_answer": "弄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天弄生病的奶奶。", "explanation": "这里应该用〈照顾〉。弄不表示护理、照料别人。"}, {"text": "昨天晚上我弄了一个很奇怪的梦。", "explanation": "这里应该用〈做〉。“梦”固定搭配“做梦”，不能说“弄梦”。"}, {"text": "明天早上六点请你弄我起床。", "explanation": "这里应该用〈叫〉。弄不表示呼唤、叫醒别人，应说“叫我起床”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把饭好弄了。", "corrected_sentence": "我把饭弄好了。", "error_description": "错误形式：“我把饭好弄了”，结果补语“好”应放在动词“弄”之后；正确形式：“我把饭弄好了”，“弄好”是动补结构，表示做完。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弄得半天，终于把灯修好了。", "corrected_sentence": "我弄了半天，终于把灯修好了。", "error_description": "错误形式：“弄得半天”，“得”不能接时量短语；正确形式：“弄了半天”，“了”表示动作持续后完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
