INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不可以是说这样做不行，大人不让做。", "primary_collocate": null, "pronunciation": "bù kě yǐ", "ipa": "pu˥˩ kʰɤ˨˩ i˨˩", "syllable_count": 3, "sentences": [{"text": "妈妈说，晚上不可以一个人出去玩。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸告诉我，不可以在家里踢球。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，上课的时候不可以吃东西。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说小孩子不可以喝太多可乐。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈对弟弟说，你不可以玩我的手机。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人说过，小孩不可以靠近河边。", "target_word": "不可以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不让我吃糖，说不可以吃太多。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，没写完作业不可以看电视。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，不可以随便拿别人的东西。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，我不可以一个人去游泳。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "大人对小孩说不许做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示大人不允许晚上一个人出去，与“妈妈说”的禁止语气一致。"}, {"text": "不会", "is_correct": false, "explanation": "语义：「不会」表示预测或能力，不能表示妈妈的禁止。"}, {"text": "不敢", "is_correct": false, "explanation": "语义：「不敢」说的是人心里害怕，句子里没有这种意思，也不表示被禁止外出。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示许可，说“晚上能一个人出去玩”与妈妈的禁止意思相反。"}], "explanations": {"不可以": "正确：表示大人不允许晚上一个人出去，与“妈妈说”的禁止语气一致。", "不会": "语义：「不会」表示预测或能力，不能表示妈妈的禁止。", "不敢": "语义：「不敢」说的是人心里害怕，句子里没有这种意思，也不表示被禁止外出。", "能": "语义：「能」表示许可，说“晚上能一个人出去玩”与妈妈的禁止意思相反。"}, "sentence_index": 0, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书太厚了，我一天不可以看完。", "explanation": "这里应该用〈看不完〉。〈不可以〉表示不被允许，书太厚一天读不完是能力或条件问题，要用可能补语〈看不完〉。"}, {"text": "这块冰太滑了，我不可以站稳。", "explanation": "这里应该用〈站不稳〉。〈不可以〉表示许可，冰面太滑使身体无法保持平衡是条件所致，要用〈站不稳〉。"}, {"text": "这个字太小了，我不可以看清。", "explanation": "这里应该用〈看不清〉。〈不可以〉不能表示视力或距离造成的看不见结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示不允许吃太多，与“爷爷不让我吃糖”的语境一致。"}, {"text": "应该", "is_correct": false, "explanation": "语义：「应该」表示应当，说“应该吃太多”与“不让我吃糖”的意思相反。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示许可或能力，说“能吃太多”与爷爷不让吃的语境冲突。"}, {"text": "得", "is_correct": false, "explanation": "语义：「得」作能愿动词表示必要，“说得吃太多”是“必须多吃”，与爷爷不让吃的语境相反。"}], "explanations": {"不可以": "正确：表示不允许吃太多，与“爷爷不让我吃糖”的语境一致。", "应该": "语义：「应该」表示应当，说“应该吃太多”与“不让我吃糖”的意思相反。", "能": "语义：「能」表示许可或能力，说“能吃太多”与爷爷不让吃的语境冲突。", "得": "语义：「得」作能愿动词表示必要，“说得吃太多”是“必须多吃”，与爷爷不让吃的语境相反。"}, "sentence_index": 6, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌太难了，我不可以唱完。", "explanation": "这里应该用〈唱不完〉。〈不可以〉表示不被允许，唱不完是难度或能力的问题。"}, {"text": "他耳朵聋了，所以不可以听见声音。", "explanation": "这里应该用〈听不见〉。〈不可以〉不能表示感官无法接收声音的结果。"}, {"text": "窗户太高了，我不可以够到。", "explanation": "这里应该用〈够不到〉。〈不可以〉表示许可，身高或距离造成的够不到要用〈够不到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈说，你不可以了喝酒。", "corrected_sentence": "妈妈说，你不可以喝酒。", "error_description": "错误形式：「不可以」后面直接加了「了」。正确形式：「不可以喝酒」。「不可以」后面应直接接动词，不能插入「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校规定，学生很不可以带手机进教室。", "corrected_sentence": "学校规定，学生不可以带手机进教室。", "error_description": "错误形式：「很不可以」，在「不可以」前加了程度副词「很」。正确形式：「不可以带手机」。「不可以」表示禁止，不能再用「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
