INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示不被允许、不行。", "primary_collocate": null, "pronunciation": "bù kě yǐ", "ipa": "pu˥˩ kʰɤ˨˩ i˨˩", "syllable_count": 3, "sentences": [{"text": "这里不可以停车。", "target_word": "不可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "图书馆里不可以大声说话。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里不可以抽烟。", "target_word": "不可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试的时候不可以看手机。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有票的人不可以进去。", "target_word": "不可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机起飞前，手机不可以开机。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家酒店规定，宠物不可以进房间。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游泳池里不可以带食物进来。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这家店里，不可以拍照。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "规定说，开车时不可以打电话。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "规定或场合不允许做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示这个场所规定不允许停车。"}, {"text": "不会", "is_correct": false, "explanation": "语义：「不会」表示预测，不能表示场所的禁止规定。"}, {"text": "不敢", "is_correct": false, "explanation": "搭配：「不敢」要求人主动胆怯，「这里」作为地点不能作「不敢」的主语。"}, {"text": "不了", "is_correct": false, "explanation": "语法：「不了」是可能补语，要放在动词后面（如「停不了」），不能放在「停车」前面。"}], "explanations": {"不可以": "正确：表示这个场所规定不允许停车。", "不会": "语义：「不会」表示预测，不能表示场所的禁止规定。", "不敢": "搭配：「不敢」要求人主动胆怯，「这里」作为地点不能作「不敢」的主语。", "不了": "语法：「不了」是可能补语，要放在动词后面（如「停不了」），不能放在「停车」前面。"}, "sentence_index": 0, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题太难了，我不可以做出来。", "explanation": "这里应该用〈做不出来〉。〈不可以〉表示不被允许，做不出来是能力不足，不能用它。"}, {"text": "我的手机没电了，所以不可以打电话。", "explanation": "这里应该用〈打不了〉。〈不可以〉表示许可，没电是客观条件，不能用它来说明。"}, {"text": "这件衣服太大了，我不可以穿。", "explanation": "这里应该用〈穿不了〉。〈不可以〉不能表示尺码不合适造成的无法穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示酒店规定不允许宠物进房间。"}, {"text": "不了", "is_correct": false, "explanation": "语法：「不了」要放在动词后面（如「进不了」），不能放在「进房间」前面。"}, {"text": "不对", "is_correct": false, "explanation": "语法：「不对」是形容词性说法，不能直接放在动词「进」前表示禁止。"}, {"text": "别的", "is_correct": false, "explanation": "语法：「别的」修饰名词，不能放在动词「进」前面。"}], "explanations": {"不可以": "正确：表示酒店规定不允许宠物进房间。", "不了": "语法：「不了」要放在动词后面（如「进不了」），不能放在「进房间」前面。", "不对": "语法：「不对」是形容词性说法，不能直接放在动词「进」前表示禁止。", "别的": "语法：「别的」修饰名词，不能放在动词「进」前面。"}, "sentence_index": 6, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电脑坏了，不可以上网。", "explanation": "这里应该用〈上不了网〉。〈不可以〉表示许可，电脑坏了是客观条件，不能用它表达。"}, {"text": "我没有钥匙，所以不可以开门。", "explanation": "这里应该用〈开不了门〉。〈不可以〉不能说明没有钥匙造成的无法开门。"}, {"text": "我的嗓子太哑了，我不可以唱到高音。", "explanation": "这里应该用〈唱不上去〉。〈不可以〉表示许可，嗓音条件造成的唱不到高音要用〈唱不上去〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
