INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下达是上面的人把话传给下面的人。他们要下面的人照着做。", "primary_collocate": null, "pronunciation": "xià dá", "ipa": "ɕja˥˩ ta˧˥", "syllable_count": 2, "sentences": [{"text": "经理下达了一个新任务。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板今天下达了新的规定。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师下达命令，大家马上去做。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长向我们下达了出发的命令。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上面下达的指示，我们要照着做。", "target_word": "下达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长下达通知，明天不上课。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理把工作计划下达给了每个人。", "target_word": "下达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁下达了这个奇怪的要求？", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板昨天下达的任务很重。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "命令下达以后，大家都行动了。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下达了", "label": "体标"}, {"form": "下达过", "label": "体标"}], "register": "通用", "sense_fingerprint": "上面的人把话或要求传给下面的人，让他们照着做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下达", "is_correct": true, "explanation": "下达：上级把任务传给下级，与“经理”“新任务”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能吃“任务”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦桌子、玻璃等，不说擦任务。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”用于养宠物、孩子、习惯，不说养任务。"}], "explanations": {"下达": "下达：上级把任务传给下级，与“经理”“新任务”搭配。", "吃": "语义：“吃”的对象是食物，不能吃“任务”。", "擦": "搭配：“擦”用于擦桌子、玻璃等，不说擦任务。", "养": "搭配：“养”用于养宠物、孩子、习惯，不说养任务。"}, "sentence_index": 0, "correct_answer": "下达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向老师下达了一个请求。", "explanation": "这里应该用〈提出〉。下达是上级把命令传给下级，我是下级，不能向老师下达请求。"}, {"text": "他下达了一声惨叫。", "explanation": "这里应该用〈发出〉。下达的对象是命令、指示、任务，不能用于声音。"}, {"text": "学校下达了考试成绩。", "explanation": "这里应该用〈公布〉。下达只用于命令、指示，考试成绩要公布，不能下达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下达", "is_correct": true, "explanation": "下达：把工作计划传达给每个人，与“工作计划”“给”搭配。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“工作计划”作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能煮“工作计划”。"}, {"text": "浇", "is_correct": false, "explanation": "语义：“浇”用于浇水、浇花等液体或植物，不能浇工作计划。"}], "explanations": {"下达": "下达：把工作计划传达给每个人，与“工作计划”“给”搭配。", "哭": "配价：“哭”是不及物动词，不能带“工作计划”作宾语。", "煮": "语义：“煮”的对象是食物，不能煮“工作计划”。", "浇": "语义：“浇”用于浇水、浇花等液体或植物，不能浇工作计划。"}, "sentence_index": 6, "correct_answer": "下达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下达了老师的话。", "explanation": "这里应该用〈转达〉。下达是上级发出命令，我不是上级，不能把别人的话说成下达。"}, {"text": "他下达了一封邮件。", "explanation": "这里应该用〈发送〉。下达的内容是命令、指示，邮件要用发送。"}, {"text": "她下达了自己的看法。", "explanation": "这里应该用〈表达〉。下达的内容是命令、指示，看法要用表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "总经理把我们下达了紧急命令。", "corrected_sentence": "总经理向我们下达了紧急命令。", "error_description": "错误：“把我们下达”；正确：“向我们下达”。下达的接收方要用介词“向”引出，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "局长把新任务下达每个部门。", "corrected_sentence": "局长把新任务下达给每个部门。", "error_description": "错误：缺少“给”；正确：“下达给每个部门”。下达后面引出接收方时要加“给”（或“到”），不能直接接“每个部门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
