INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86876, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上级把命令、指示、任务等传达给下级。", "primary_collocate": null, "pronunciation": "xià dá", "ipa": "ɕja˥˩ ta˧˥", "syllable_count": 2, "sentences": [{"text": "上级向各部门下达了工作任务。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总部下达指示，要求马上停工。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府下达命令，要求学校停课。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把这项任务下达给了销售部。", "target_word": "下达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "命令一旦下达，所有人必须执行。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂长下达的指示，工人都认真执行。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上级已经下达了今年的生产任务。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "局长昨天下达了检查工作的通知。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理向各地分公司下达销售指标。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里下达紧急通知，各学校今天放假。", "target_word": "下达", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下达了", "label": "体标"}, {"form": "下达过", "label": "体标"}], "register": "书面", "sense_fingerprint": "上级向下级传达命令、指示、任务，用于机关和单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下达", "is_correct": true, "explanation": "下达：上级向各部门传达任务，与“上级”“工作任务”搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是食物等，不能咬任务。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于衣物、餐具等，不说洗任务。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于水果、花等，不说摘任务。"}], "explanations": {"下达": "下达：上级向各部门传达任务，与“上级”“工作任务”搭配。", "咬": "语义：“咬”的对象是食物等，不能咬任务。", "洗": "搭配：“洗”用于衣物、餐具等，不说洗任务。", "摘": "搭配：“摘”用于水果、花等，不说摘任务。"}, "sentence_index": 0, "correct_answer": "下达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向经理下达了辞职报告。", "explanation": "这里应该用〈递交〉。下达是上级向下级发出命令，下级向上级提交材料要用递交。"}, {"text": "校长下达了一首新歌。", "explanation": "这里应该用〈唱〉。下达的对象是命令、指示、任务，不能是歌曲。"}, {"text": "他下达了一篇读后感。", "explanation": "这里应该用〈写〉。下达只用于命令、指示、任务，读后感要写，不能下达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下达", "is_correct": true, "explanation": "下达：上级传达今年的生产任务，与“上级”“生产任务”搭配。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“生产任务”作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能煮生产任务。"}, {"text": "浇", "is_correct": false, "explanation": "语义：“浇”用于浇水、浇花，不能浇生产任务。"}], "explanations": {"下达": "下达：上级传达今年的生产任务，与“上级”“生产任务”搭配。", "睡": "配价：“睡”是不及物动词，不能带“生产任务”作宾语。", "煮": "语义：“煮”的对象是食物，不能煮生产任务。", "浇": "语义：“浇”用于浇水、浇花，不能浇生产任务。"}, "sentence_index": 6, "correct_answer": "下达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生下达了一份紧急通知。", "explanation": "这里应该用〈转达〉。下达由上级发出，学生不是上级，不能下达通知。"}, {"text": "他向朋友下达了一句祝福。", "explanation": "这里应该用〈送上〉。下达的内容是命令、指示、任务，祝福是善意的话，要用送上。"}, {"text": "他下达了一句道歉。", "explanation": "这里应该用〈说〉。下达的内容是命令、指示、任务，道歉要用说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上级把各个单位下达了新的规定。", "corrected_sentence": "上级向各个单位下达了新的规定。", "error_description": "错误：“把各个单位下达”；正确：“向各个单位下达”。“把”之后引出的是被处置的对象，下达的接收方要用“向”或“给”引出，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导给全体员工下达着安全规定。", "corrected_sentence": "领导给全体员工下达了安全规定。", "error_description": "错误：“下达着”；正确：“下达了”。“下达”是一次完成的动作，不能用表示持续的“着”，说明已经下达要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
