INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作或学习中取得的成绩。", "primary_collocate": null, "pronunciation": "chéng guǒ", "ipa": "tʂʰɤŋ˧˥ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的研究成果很重要。", "target_word": "成果", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司今年的工作成果不错。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家有很多研究成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请学生们展示学习成果。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的第一项科研成果是去年发表的。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在工作中取得了不少成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师看了我们的学习成果，很满意。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项成果会帮助很多病人。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把三年的研究成果写成了一本书。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听听你们这个月的工作成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "科研成果", "label": "复合"}], "register": "中性", "sense_fingerprint": "成果·工作或学习中取得的成绩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d39edd-56d4-44c7-b5fd-93bb63a43a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "正确：“研究成果”指研究中取得的成绩，与“他的”搭配自然。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能是研究取得的成果。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“研究”修饰的一般是抽象的成果或报告，不能修饰鞋子。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，与“研究”的意思不符。"}], "explanations": {"成果": "正确：“研究成果”指研究中取得的成绩，与“他的”搭配自然。", "椅子": "语义：椅子是家具，不能是研究取得的成果。", "鞋子": "搭配：“研究”修饰的一般是抽象的成果或报告，不能修饰鞋子。", "鸡蛋": "语义：鸡蛋是食物，与“研究”的意思不符。"}, "sentence_index": 0, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次失败让我得到了很多成果。", "explanation": "这里应该用〈收获〉。收获指从经历中得到的东西，可以是教训；成果指工作或学习中取得的成绩，不能用于失败的经历。"}, {"text": "这种护肤品的成果很好。", "explanation": "这里应该用〈效果〉。护肤品的作用要用效果，成果指工作或学习中取得的成绩，不能用来形容护肤品。"}, {"text": "这座山的成果很高。", "explanation": "这里应该用〈高度〉。山有多高要用高度，成果指工作或学习中取得的成绩，不能用来说山的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "正确：“学习成果”指学习中取得的成绩，老师可以看，也可以满意。"}, {"text": "水壶", "is_correct": false, "explanation": "语义：水壶是用具，不是学习取得的成绩。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“学习”不修饰沙发，“学习沙发”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为学习的成果被老师看。"}], "explanations": {"成果": "正确：“学习成果”指学习中取得的成绩，老师可以看，也可以满意。", "水壶": "语义：水壶是用具，不是学习取得的成绩。", "沙发": "搭配：“学习”不修饰沙发，“学习沙发”说不通。", "冰箱": "语义：冰箱是家电，不能作为学习的成果被老师看。"}, "sentence_index": 6, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成果增加了三公斤。", "explanation": "这里应该用〈体重〉。体重是人的重量，成果指工作或学习中取得的成绩，不能用来说重量增加。"}, {"text": "这块布的成果很软。", "explanation": "这里应该用〈质地〉。布料的软硬要用质地，成果指工作或学习中取得的成绩，不能用来形容布料。"}, {"text": "这种药的成果很好。", "explanation": "这里应该用〈效果〉。药物的作用要用效果，成果指工作或学习中取得的成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把研究成果很重要。", "corrected_sentence": "这项研究成果很重要。", "error_description": "量词错误：“研究成果”应用量词“项”。“把”用于有柄的器具，不能用于成果，应改为“这项研究成果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们取得了一座不错的成果。", "corrected_sentence": "他们取得了一项不错的成果。", "error_description": "量词错误：“成果”应用量词“项”。“座”用于山、楼房等大型建筑，不能用于成果，应改为“一项成果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86881, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86881, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86881, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "交易会是很多人聚在一起买东西、卖东西的大会。", "primary_collocate": null, "pronunciation": "jiāo yì huì", "ipa": "tɕjɑʊ˥ i˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "周末城里有个交易会，我想去看看。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易会上有很多人在买东西。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在交易会买了一件新衣服。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易会里卖水果的人很多。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友一起去逛交易会。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易会门口排着长队。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店的东西在交易会上卖得很快。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在交易会卖了很多茶叶。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天学校旁边有一个交易会。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易会里的东西又多又便宜。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交易會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人聚在一起买卖东西的大会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e7f192b-be0b-4077-9581-3be7d265068c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交易会", "is_correct": true, "explanation": "正确。“城里有个交易会”指集中买卖东西的大会，符合“我想去看看”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”一般不用“个”计量，“有个雨”不自然。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是可以去看的活动。"}, {"text": "手指", "is_correct": false, "explanation": "语义：“手指”是身体部位，不是可以去看的地方或活动。"}], "explanations": {"交易会": "正确。“城里有个交易会”指集中买卖东西的大会，符合“我想去看看”。", "雨": "搭配：“雨”一般不用“个”计量，“有个雨”不自然。", "感冒": "语义：“感冒”是疾病，不是可以去看的活动。", "手指": "语义：“手指”是身体部位，不是可以去看的地方或活动。"}, "sentence_index": 0, "correct_answer": "交易会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都去交易会学开车。", "explanation": "搭配错误：这里应该用〈驾校〉。交易会是很多人买卖东西的大会，不是学车的地方，不能说“去交易会学开车”。"}, {"text": "我晚上躺在交易会上睡觉。", "explanation": "搭配错误：这里应该用〈床〉。交易会是很多人买卖东西的大会，不是睡觉用的家具，不能躺在上面睡觉。"}, {"text": "我们在这辆交易会里买了很多水果。", "explanation": "量词错误：这里应该用〈个〉。“辆”用于车辆，不能用来计量交易会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交易会", "is_correct": true, "explanation": "正确。“在交易会上卖得很快”指东西在很多人买卖东西的大会上卖得快，符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，不是商品销售的场所，“在厨房上卖”不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是物品，不是可以摆放商品销售的场所。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“上”一般不与时间词搭配，“在周末上卖”不自然。"}], "explanations": {"交易会": "正确。“在交易会上卖得很快”指东西在很多人买卖东西的大会上卖得快，符合语境。", "厨房": "语义：“厨房”是做饭的地方，不是商品销售的场所，“在厨房上卖”不通。", "眼镜": "语义：“眼镜”是物品，不是可以摆放商品销售的场所。", "周末": "搭配：“上”一般不与时间词搭配，“在周末上卖”不自然。"}, "sentence_index": 6, "correct_answer": "交易会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场交易会的歌很好听，大家都在唱。", "explanation": "近义误用：这里应用〈音乐会〉。交易会是买卖的集会，不演出，不能用来说唱歌。"}, {"text": "这张桌子是交易会，花了我一百块。", "explanation": "意思错误：交易会指很多人聚在一起买卖的大会，不能指一件物品，这张桌子不能叫交易会。"}, {"text": "交易会累得直打哈欠。", "explanation": "用法错误：交易会是活动，不是人，不会累，也不会打哈欠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小区门口有辆交易会，很多人在卖旧书。", "corrected_sentence": "小区门口有个交易会，很多人在卖旧书。", "error_description": "错误在量词。交易会应该用“个”或“届”，说“有个交易会”；“辆”用于车辆，不能说“有辆交易会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在上交易会买了一台二手电脑。", "corrected_sentence": "我在交易会买了一台二手电脑。", "error_description": "错误在“上”的位置。“上”不能放在“交易会”前面，“在上交易会”不通；应说“在交易会买”或“在交易会上买”，“上”要放在处所词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
