INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86882, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "定期举行、供各地商人集中展示商品并洽谈买卖的大型集会。", "primary_collocate": null, "pronunciation": "jiāo yì huì", "ipa": "tɕjɑʊ˥ i˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "每年春天，广州都会举办交易会。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多外国商人来参加这次交易会。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个交易会每年举行两次。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在交易会上认识了新客户。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司准备了很多样品，要带去交易会。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交易会的第一天，人特别多。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的展位在交易会的二号馆。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这届交易会吸引了上千家公司。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理下周要去上海参加交易会。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气不好，交易会晚了一天开幕。", "target_word": "交易会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "届", "label": "量词"}, {"form": "交易會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "定期举办、商人展示商品洽谈生意的大型集会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e7f192b-be0b-4077-9581-3be7d265068c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交易会", "is_correct": true, "explanation": "正确。“举办交易会”指组织定期的商品洽谈大会，搭配自然。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“举办”接的是活动，“手机”不是可以举办的事物。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是可以举办的活动。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然状况，不能被举办。"}], "explanations": {"交易会": "正确。“举办交易会”指组织定期的商品洽谈大会，搭配自然。", "手机": "搭配：“举办”接的是活动，“手机”不是可以举办的事物。", "厨房": "语义：厨房是做饭的地方，不是可以举办的活动。", "天气": "语义：天气是自然状况，不能被举办。"}, "sentence_index": 0, "correct_answer": "交易会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都在交易会里刷牙洗脸。", "explanation": "用法错误：这里应该用〈卫生间〉。交易会是定期举办的商品洽谈集会，不是日常洗漱的地方。"}, {"text": "我每周都去交易会打篮球。", "explanation": "搭配错误：这里应该用〈篮球场〉。交易会是商品买卖的大会，不是打球的地方，不能说“去交易会打篮球”。"}, {"text": "我们今年参加了一辆交易会。", "explanation": "量词错误：这里应该用〈届〉。“辆”用于车辆，不能用来计量交易会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交易会", "is_correct": true, "explanation": "正确。“交易会的二号馆”指交易会的场馆，符合语境。"}, {"text": "奶茶", "is_correct": false, "explanation": "语义：“奶茶”是饮品，不是场馆，不能说“奶茶的二号馆”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不是可以设立场馆的场所。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“二号馆”是场馆名称，不能用“雨伞的二号馆”来指位置。"}], "explanations": {"交易会": "正确。“交易会的二号馆”指交易会的场馆，符合语境。", "奶茶": "语义：“奶茶”是饮品，不是场馆，不能说“奶茶的二号馆”。", "老师": "语义：“老师”是人，不是可以设立场馆的场所。", "雨伞": "搭配：“二号馆”是场馆名称，不能用“雨伞的二号馆”来指位置。"}, "sentence_index": 6, "correct_answer": "交易会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场交易会的歌唱得很好听。", "explanation": "近义误用：这里应用〈音乐会〉。交易会是商品洽谈的集会，不演出，不能用来说唱歌。"}, {"text": "他花五百块买了一个交易会。", "explanation": "意思错误：交易会是定期举办的大型集会，是活动而不是可以买卖的物品，不能说“买了一个交易会”。"}, {"text": "交易会生病了，所以今天没有开。", "explanation": "主语错误：交易会是活动，不是人，不能说“生病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今年参加了这只交易会。", "corrected_sentence": "他今年参加了这届交易会。", "error_description": "错误在量词。交易会应该用“届”，说“这届交易会”；“只”用于动物等，不能说“这只交易会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司今年在交易会这届上展出了新产品。", "corrected_sentence": "我们公司今年在交易会上展出了新产品。", "error_description": "错误在“这届”的位置。“这届”是修饰名词的限定词，要放在“交易会”前面，“交易会这届上”不能说；去掉放错位置的“这届”，应说“在交易会上”（或“在这届交易会上”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
