INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86883, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "死亡是生命没有了，不再活着。", "primary_collocate": null, "pronunciation": "sǐ wáng", "ipa": "sɿ˨˩˦ waŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的爷爷去年在医院死亡了。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故中，有三个人死亡。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人已经死亡了。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多动物在大雪中死亡。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人是因病死亡的。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在冬天的夜里死亡了。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他时，他已经死亡。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花离开水就会死亡。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的妻子在地震中死亡了。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次战争中，很多士兵死亡。", "target_word": "死亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "死亡了", "label": "体标"}, {"form": "死亡率", "label": "复合"}], "register": "书面", "sense_fingerprint": "生命没有了，不再活着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "死亡", "is_correct": true, "explanation": "死亡指生命终止，与“去年在医院”的叙述相合，句子成立。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指新生命降临，与爷爷去年在医院的情境相反。"}, {"text": "升学", "is_correct": false, "explanation": "语义：“升学”指升入更高年级，与爷爷在医院的情境不符，句子不成立。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，不能用于爷爷。"}], "explanations": {"死亡": "死亡指生命终止，与“去年在医院”的叙述相合，句子成立。", "出生": "语义：“出生”指新生命降临，与爷爷去年在医院的情境相反。", "升学": "语义：“升学”指升入更高年级，与爷爷在医院的情境不符，句子不成立。", "毕业": "语义：“毕业”指完成学业，不能用于爷爷。"}, "sentence_index": 0, "correct_answer": "死亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机死亡了，得去买新的。", "explanation": "这里应该用〈没电〉。死亡只用于生物，手机等物品不能说死亡。"}, {"text": "这个笑话太好笑了，我笑得快要死亡了。", "explanation": "这里应该用〈笑死〉。死亡语体庄重，只表示真实的生命终止，不能用来夸张地形容笑的程度。"}, {"text": "这把火死亡了，屋子里很冷。", "explanation": "这里应该用〈熄灭〉。死亡只用于生物，火要说〈熄灭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死亡", "is_correct": true, "explanation": "死亡指生命终止，与“警察发现他时，他已经”搭配，句子成立。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指下落不明，与警察已经找到他的情境矛盾。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：警察发现他时他还在场，不能说他已经逃跑了。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，与警察发现他时的情境毫不相干，句子不成立。"}], "explanations": {"死亡": "死亡指生命终止，与“警察发现他时，他已经”搭配，句子成立。", "失踪": "语义：“失踪”指下落不明，与警察已经找到他的情境矛盾。", "逃跑": "语义：警察发现他时他还在场，不能说他已经逃跑了。", "毕业": "语义：“毕业”指完成学业，与警察发现他时的情境毫不相干，句子不成立。"}, "sentence_index": 6, "correct_answer": "死亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心跳死亡了。", "explanation": "这里应该用〈停止〉。死亡指生命终止，心跳只是生命的一个功能，心跳停止要说〈停止〉，不能说死亡。"}, {"text": "坚持住，你千万别死亡！", "explanation": "这里应该用〈别死〉。死亡语体庄重，口语中劝人坚持时不用。"}, {"text": "这台电脑昨天死亡了，打不开了。", "explanation": "这里应该用〈坏了〉。死亡只用于生物，电脑等机器不能说死亡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨晚在睡梦中被死亡了。", "corrected_sentence": "他昨晚在睡梦中死亡了。", "error_description": "“被死亡”是错误的：死亡是不及物动词，不能用“被”字句。应改为“死亡了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位诗人在三十岁时死亡得很早。", "corrected_sentence": "那位诗人在三十岁时死亡了。", "error_description": "“死亡得很早”是错误的：死亡不带“得”字补语，而且“三十岁时”已说明时间，“很早”多余。应改为“死亡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
