INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86887, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "亦称的意思是也可以叫做这个名字。", "primary_collocate": null, "pronunciation": "yì chēng", "ipa": "i˥˩ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "西红柿亦称番茄。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆亦称马铃薯。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米亦称苞谷。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节亦称过年。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋节亦称团圆节。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京亦称燕京。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菠萝亦称凤梨。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马铃薯亦称洋芋。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元宵节亦称灯节。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花生亦称落花生。", "target_word": "亦称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亦稱", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "同一事物也可以叫这个名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a82c9e-092e-40ce-a3d1-76b4efb5b7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议程", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是会议的程序。"}, {"text": "亦称", "is_correct": true, "explanation": "正确答案。亦称（yì chēng）表示同一事物也可以叫这个名字。"}, {"text": "一成", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，chéng（第二声）与 chēng（第一声）声调也不同，意思是十分之一。"}, {"text": "一程", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，chéng 与 chēng 声调也不同，意思是一段路程。"}], "explanations": {"议程": "chéng（第二声）与 chēng（第一声）声调不同，意思是会议的程序。", "亦称": "正确答案。亦称（yì chēng）表示同一事物也可以叫这个名字。", "一成": "yī（第一声）与 yì（第四声）声调不同，chéng（第二声）与 chēng（第一声）声调也不同，意思是十分之一。", "一程": "yī（第一声）与 yì（第四声）声调不同，chéng 与 chēng 声调也不同，意思是一段路程。"}, "sentence_index": null, "correct_answer": "亦称"}, "level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "语义：“切”指用刀分开，“西红柿”和“番茄”是同一种东西的两个名字，不能切。"}, {"text": "亦称", "is_correct": true, "explanation": "正确答案。亦称表示同一事物也可以叫这个名字，与“西红柿”“番茄”的关系相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是可以吃的东西，“西红柿吃番茄”不成立。"}, {"text": "产于", "is_correct": false, "explanation": "配价：“产于”后要接产地，“番茄”不是产地，句子不成立。"}], "explanations": {"切": "语义：“切”指用刀分开，“西红柿”和“番茄”是同一种东西的两个名字，不能切。", "亦称": "正确答案。亦称表示同一事物也可以叫这个名字，与“西红柿”“番茄”的关系相符。", "吃": "搭配：“吃”的宾语应是可以吃的东西，“西红柿吃番茄”不成立。", "产于": "配价：“产于”后要接产地，“番茄”不是产地，句子不成立。"}, "sentence_index": 0, "correct_answer": "亦称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们亦称明天去公园。", "explanation": "这里应该用〈打算〉。亦称表示同一事物的另一个名称，不能表示计划要做的事。"}, {"text": "这个方法我亦称很有效。", "explanation": "这里应该用〈认为〉。亦称表示同一事物的另一名称，不能用来表达对事物的看法。"}, {"text": "老师亦称他的作文写得很好。", "explanation": "这里应该用〈赞扬〉。亦称表示事物的另一个名称，不用来称赞别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "削", "is_correct": false, "explanation": "语义：“削”指去掉外皮，这句说的是两个名字，不是动作，句子不通。"}, {"text": "亦称", "is_correct": true, "explanation": "正确答案。亦称表示同一事物也可以叫这个名字，与“菠萝”“凤梨”的关系相符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用力切断，与“菠萝”和“凤梨”是同一事物的两个名字不符。"}, {"text": "来自", "is_correct": false, "explanation": "配价：“来自”后要接来源，“凤梨”不是菠萝的来源，句子不成立。"}], "explanations": {"削": "语义：“削”指去掉外皮，这句说的是两个名字，不是动作，句子不通。", "亦称": "正确答案。亦称表示同一事物也可以叫这个名字，与“菠萝”“凤梨”的关系相符。", "砍": "语义：“砍”指用力切断，与“菠萝”和“凤梨”是同一事物的两个名字不符。", "来自": "配价：“来自”后要接来源，“凤梨”不是菠萝的来源，句子不成立。"}, "sentence_index": 6, "correct_answer": "亦称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈亦称我的名字，让我回家吃饭。", "explanation": "这里是“大声叫人”的意思。亦称表示同一事物的另一个名称，不表示叫人。"}, {"text": "我亦称明天会下雨。", "explanation": "这里应该用〈觉得〉。亦称表示同一事物的另一个名称，不能表达自己的判断。"}, {"text": "这道菜亦称很好吃。", "explanation": "这里应该用〈据说〉。亦称后面要接另一个名称，不能接对事物的评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "黄豆亦称于大豆。", "corrected_sentence": "黄豆亦称大豆。", "error_description": "错误在于多加了介词「于」：「亦称」后直接接另一个名称，不能加「于」，应说「亦称大豆」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
