INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议程", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是会议的程序。"}, {"text": "亦称", "is_correct": true, "explanation": "正确答案。亦称（yì chēng）表示同一事物也可以叫这个名字。"}, {"text": "一成", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，chéng（第二声）与 chēng（第一声）声调也不同，意思是十分之一。"}, {"text": "一程", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，chéng 与 chēng 声调也不同，意思是一段路程。"}], "explanations": {"议程": "chéng（第二声）与 chēng（第一声）声调不同，意思是会议的程序。", "亦称": "正确答案。亦称（yì chēng）表示同一事物也可以叫这个名字。", "一成": "yī（第一声）与 yì（第四声）声调不同，chéng（第二声）与 chēng（第一声）声调也不同，意思是十分之一。", "一程": "yī（第一声）与 yì（第四声）声调不同，chéng 与 chēng 声调也不同，意思是一段路程。"}, "sentence_index": null, "correct_answer": "亦称"}, "level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "语义：“切”指用刀分开，“地瓜”和“红薯”是同一种东西的两个名字，不能切。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”针对的是要煮的食物，这里说的是两个名称的关系，“煮红薯”与语境不符。"}, {"text": "亦称", "is_correct": true, "explanation": "正确答案。亦称表示同一事物也可以叫这个名字，与“地瓜”“红薯”的关系相符。"}, {"text": "产于", "is_correct": false, "explanation": "配价：“产于”后要接产地，“红薯”不是产地，句子不成立。"}], "explanations": {"切": "语义：“切”指用刀分开，“地瓜”和“红薯”是同一种东西的两个名字，不能切。", "煮": "搭配：“煮”针对的是要煮的食物，这里说的是两个名称的关系，“煮红薯”与语境不符。", "亦称": "正确答案。亦称表示同一事物也可以叫这个名字，与“地瓜”“红薯”的关系相符。", "产于": "配价：“产于”后要接产地，“红薯”不是产地，句子不成立。"}, "sentence_index": 0, "correct_answer": "亦称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们亦称周末去爬山。", "explanation": "这里应该用〈打算〉。亦称表示同一事物的另一个名称，不能表示计划。"}, {"text": "我亦称这次旅行很有意思。", "explanation": "这里应该用〈认为〉。亦称表示同一事物的另一名称，不能用来表达对事物的看法。"}, {"text": "班长亦称他的字写得很漂亮。", "explanation": "这里应该用〈夸赞〉。亦称表示事物的另一名称，不用来夸奖别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "削", "is_correct": false, "explanation": "语义：“削”指去掉外皮，这句说的是两个名字，不是动作，句子不通。"}, {"text": "亦称", "is_correct": true, "explanation": "正确答案。亦称表示同一事物也可以叫这个名字，与“洛阳”“洛邑”的关系相符。"}, {"text": "来自", "is_correct": false, "explanation": "配价：“来自”后要接来源，“洛邑”不是洛阳的来源，句子不成立。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用力切断，与“洛阳”和“洛邑”是同一地方的两个名字不符。"}], "explanations": {"削": "语义：“削”指去掉外皮，这句说的是两个名字，不是动作，句子不通。", "亦称": "正确答案。亦称表示同一事物也可以叫这个名字，与“洛阳”“洛邑”的关系相符。", "来自": "配价：“来自”后要接来源，“洛邑”不是洛阳的来源，句子不成立。", "砍": "语义：“砍”指用力切断，与“洛阳”和“洛邑”是同一地方的两个名字不符。"}, "sentence_index": 6, "correct_answer": "亦称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亦称他会来。", "explanation": "这里应该用〈觉得〉。亦称表示同一事物的另一个名称，不能表达判断。"}, {"text": "这本书亦称很有意思。", "explanation": "这里应该用〈据说〉。亦称后接另一个名称，不能接评价。"}, {"text": "老师亦称我们早点回家。", "explanation": "这里应该用〈要求〉。亦称表示另一名称，不表示让别人做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "芝麻亦称了脂麻。", "corrected_sentence": "芝麻亦称脂麻。", "error_description": "“亦称”表示同一事物的另一个名称，其后不加“了”，应说“芝麻亦称脂麻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "番薯亦称于地瓜。", "corrected_sentence": "番薯亦称地瓜。", "error_description": "错误在于多加了介词「于」：「亦称」后直接接另一个名称，不能加「于」，应说「亦称地瓜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
