INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86889, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抢是很快把别人的东西拿走，或者和别人争着拿。", "primary_collocate": null, "pronunciation": "qiǎng", "ipa": "tɕʰjɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "坏人抢了银行的钱。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从我手里抢走了电话。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别抢我的东西！", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和妹妹在抢最后一块蛋糕。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抢着拿桌上的糖。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路上抢了一位老人的钱。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人抢了商店的钱就跑了。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员在场上抢球。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟抢我的玩具，我很生气。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抢到了最后一张票。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抢了", "label": "体标"}, {"form": "抢着", "label": "体标"}, {"form": "抢走", "label": "复合"}, {"form": "抢到", "label": "复合"}], "register": "口语", "sense_fingerprint": "很快拿走别人的东西，或和别人争着拿东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抢", "is_correct": true, "explanation": "抢：qiǎng，指很快把别人的东西拿走，或和别人争着拿。"}, {"text": "墙", "is_correct": false, "explanation": "qiáng（第二声）与 qiǎng（第三声）声调不同，墙的意思是房屋四周的墙壁。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng（第一声）与 qiǎng（第三声）声调不同，枪的意思是枪械。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn 与 qiǎng 的韵尾不同（-n 与 -ng），浅的意思是浅。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng（第四声）与 qiǎng（第三声）声调不同，呛的意思是被烟或水刺激喉咙而咳嗽。"}], "explanations": {"抢": "抢：qiǎng，指很快把别人的东西拿走，或和别人争着拿。", "墙": "qiáng（第二声）与 qiǎng（第三声）声调不同，墙的意思是房屋四周的墙壁。", "枪": "qiāng（第一声）与 qiǎng（第三声）声调不同，枪的意思是枪械。", "浅": "qiǎn 与 qiǎng 的韵尾不同（-n 与 -ng），浅的意思是浅。", "呛": "qiàng（第四声）与 qiǎng（第三声）声调不同，呛的意思是被烟或水刺激喉咙而咳嗽。"}, "sentence_index": null, "correct_answer": "抢"}, "level_3": {"options": [{"text": "抢", "is_correct": true, "explanation": "正确：“抢了银行的钱”指坏人用力夺取钱财，与句子的语境相符。"}, {"text": "存", "is_correct": false, "explanation": "语义：“存”是把钱存入银行，与“坏人”的行为不符。"}, {"text": "送", "is_correct": false, "explanation": "语义：坏人不会把银行的钱送出去，“坏人送了银行的钱”与句意不符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”不能与“钱”搭配，不能说“戴了银行的钱”。"}], "explanations": {"抢": "正确：“抢了银行的钱”指坏人用力夺取钱财，与句子的语境相符。", "存": "语义：“存”是把钱存入银行，与“坏人”的行为不符。", "送": "语义：坏人不会把银行的钱送出去，“坏人送了银行的钱”与句意不符。", "戴": "搭配：“戴”不能与“钱”搭配，不能说“戴了银行的钱”。"}, "sentence_index": 0, "correct_answer": "抢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把被子抢到了阳台上。", "explanation": "这里应该用〈晒〉。抢表示用力夺取，把被子放在阳台上晾干要用“晒”。"}, {"text": "他抢开了那个盒子。", "explanation": "这里应该用〈打〉。抢表示夺取，打开盒子要说“打开”。"}, {"text": "她用胶水抢好了杯子。", "explanation": "这里应该用〈粘〉。抢表示用力夺取，用胶水把东西粘在一起要用“粘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抢", "is_correct": true, "explanation": "正确：“抢了商店的钱就跑了”指用力夺取钱财，与句子的语境相符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打的动作，不能踢钱，“踢了商店的钱就跑了”与句意不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是唱歌的动作，“唱了商店的钱”与句意不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理的动作，不能修钱，“修了商店的钱就跑了”与句意不符。"}], "explanations": {"抢": "正确：“抢了商店的钱就跑了”指用力夺取钱财，与句子的语境相符。", "踢": "语义：“踢”是用脚击打的动作，不能踢钱，“踢了商店的钱就跑了”与句意不符。", "唱": "语义：“唱”是唱歌的动作，“唱了商店的钱”与句意不符。", "修": "语义：“修”是修理的动作，不能修钱，“修了商店的钱就跑了”与句意不符。"}, "sentence_index": 6, "correct_answer": "抢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他擦干净了窗户，然后抢干净了窗台。", "explanation": "这里应该用〈擦〉。抢表示用力夺取，清洁窗台要用“擦”。"}, {"text": "厨师抢好了一锅汤。", "explanation": "这里应该用〈煮〉。抢表示用力夺取，把汤煮熟要用“煮”。"}, {"text": "他抢上了插头。", "explanation": "这里应该用〈插〉。抢表示用力夺取，连接电源要用“插”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们抢在糖。", "corrected_sentence": "孩子们在抢糖。", "error_description": "“在”的位置错误：表示正在进行的“在”应放在动词“抢”之前，不能放在“抢”之后。正确说法是“孩子们在抢糖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快走抢了钱。", "corrected_sentence": "他很快抢走了钱。", "error_description": "补语位置错误：结果补语“走”要放在动词“抢”之后，应说“抢走”，不能说“走抢”。正确的是“他很快抢走了钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
