INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86890, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力夺取；争着做。", "primary_collocate": null, "pronunciation": "qiǎng", "ipa": "tɕʰjɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "小偷想抢她手里的包。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都抢着回答老师的问题。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在路上抢了他的手机。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子在抢同一个玩具。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家抢着去帮助那位老人。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抢过我的书就跑了。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗抢走了小孩手里的面包。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们抢着付钱，谁也不让谁。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，有人会抢你的钱包。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟总是跟我抢遥控器。", "target_word": "抢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抢了", "label": "体标"}, {"form": "抢着", "label": "体标"}, {"form": "抢过", "label": "体标"}, {"form": "抢走", "label": "复合"}], "register": "口语", "sense_fingerprint": "用力夺取别人的东西，或争着去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抢", "is_correct": true, "explanation": "抢：qiǎng，指用力夺取，或争着去做。"}, {"text": "强", "is_correct": false, "explanation": "qiáng（第二声）与 qiǎng（第三声）声调不同，强的意思是强大、强壮。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng（第一声）与 qiǎng（第三声）声调不同，枪的意思是枪械。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn 与 qiǎng 的韵尾不同（-n 与 -ng），浅的意思是浅。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng（第四声）与 qiǎng（第三声）声调不同，呛的意思是被烟或水刺激喉咙而咳嗽。"}], "explanations": {"抢": "抢：qiǎng，指用力夺取，或争着去做。", "强": "qiáng（第二声）与 qiǎng（第三声）声调不同，强的意思是强大、强壮。", "枪": "qiāng（第一声）与 qiǎng（第三声）声调不同，枪的意思是枪械。", "浅": "qiǎn 与 qiǎng 的韵尾不同（-n 与 -ng），浅的意思是浅。", "呛": "qiàng（第四声）与 qiǎng（第三声）声调不同，呛的意思是被烟或水刺激喉咙而咳嗽。"}, "sentence_index": null, "correct_answer": "抢"}, "level_3": {"options": [{"text": "抢", "is_correct": true, "explanation": "正确：“抢”表示用力夺取，与“小偷”和“她手里的包”的语境相符。"}, {"text": "送", "is_correct": false, "explanation": "语义：小偷不会把东西送给别人，“小偷想送她手里的包”与句意不符。"}, {"text": "借", "is_correct": false, "explanation": "语义：小偷不会向人借东西，“小偷想借她手里的包”与句意不符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等物品，不能说“戴她手里的包”。"}], "explanations": {"抢": "正确：“抢”表示用力夺取，与“小偷”和“她手里的包”的语境相符。", "送": "语义：小偷不会把东西送给别人，“小偷想送她手里的包”与句意不符。", "借": "语义：小偷不会向人借东西，“小偷想借她手里的包”与句意不符。", "戴": "搭配：“戴”用于帽子、眼镜等物品，不能说“戴她手里的包”。"}, "sentence_index": 0, "correct_answer": "抢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用水抢干净了杯子。", "explanation": "这里应该用〈洗〉。抢表示用力夺取，清洗杯子要用“洗”。"}, {"text": "他抢开了那扇门。", "explanation": "这里应该用〈推〉。抢表示夺取，不表示推动，推门要用“推”。"}, {"text": "他用书包抢住了阳光。", "explanation": "这里应该用〈挡〉。抢表示夺取，用书包遮挡阳光要用“挡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抢", "is_correct": true, "explanation": "正确：“抢走”表示用力拿走别人的东西，与“那只狗”和“小孩手里的面包”的语境相符。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹走”指用气流把东西吹开，狗不能把小孩手里的面包吹走，“那只狗吹走了小孩手里的面包”与句意不符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是摩擦的动作，不能擦走面包，与句意不符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗的动作，不能把面包洗走，“那只狗洗走了小孩手里的面包”与句意不符。"}], "explanations": {"抢": "正确：“抢走”表示用力拿走别人的东西，与“那只狗”和“小孩手里的面包”的语境相符。", "吹": "语义：“吹走”指用气流把东西吹开，狗不能把小孩手里的面包吹走，“那只狗吹走了小孩手里的面包”与句意不符。", "擦": "语义：“擦”是摩擦的动作，不能擦走面包，与句意不符。", "洗": "语义：“洗”是清洗的动作，不能把面包洗走，“那只狗洗走了小孩手里的面包”与句意不符。"}, "sentence_index": 6, "correct_answer": "抢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抢好了自行车。", "explanation": "这里应该用〈修〉。抢表示用力夺取，修理自行车要用“修”。"}, {"text": "理发师抢了她的头发。", "explanation": "这里应该用〈剪〉。抢表示用力夺取，修剪头发要用“剪”。"}, {"text": "她抢了地，然后去吃饭。", "explanation": "这里应该用〈扫〉。抢表示用力夺取，清扫地面要用“扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他抢了到一个好位置。", "corrected_sentence": "他抢到了一个好位置。", "error_description": "“了”的位置错误：“抢到”是复合动词，“了”应放在“到”之后，不能插在“抢”和“到”之间。正确说法是“抢到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小偷走抢了她的包。", "corrected_sentence": "小偷抢走了她的包。", "error_description": "补语语序错误：“抢走”是动补结构，补语“走”应紧跟在“抢”之后，不能说“走抢”。正确说法是“抢走了她的包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
