INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人的儿子；在《圣经》中是耶稣对自己的称呼。", "primary_collocate": null, "pronunciation": "rén zǐ", "ipa": "ɻən˧˥ tsɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "在《圣经》里，耶稣常常称自己为人子。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人子是耶稣对自己的称呼。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教会的老师给我们讲人子的故事。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "《圣经》里说，人子要来到世上。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一页写着人子和朋友们吃饭。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师说，人子的爱很大。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在书里读到人子的话，很感动。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道人子为什么这样说。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多画都画着人子。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人子在山上对大家说话。", "target_word": "人子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "《圣经》中耶稣的自称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86892, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人子", "is_correct": true, "explanation": "正确答案。人子（rén zǐ）指人的儿子，在《圣经》中是耶稣对自己的称呼。"}, {"text": "人字", "is_correct": false, "explanation": "zì（第四声）与 zǐ（第三声）声调不同，“人字”指字形像“人”的形状，与“人子”意思不同。"}, {"text": "人质", "is_correct": false, "explanation": "zhì（第四声）与 zǐ（第三声）声母与声调都不同（zh 与 z），“人质”指被扣押的人，与“人子”意思不同。"}, {"text": "人次", "is_correct": false, "explanation": "cì（第四声）与 zǐ（第三声）声母与声调不同（c 与 z），“人次”是人数乘以次数的统计单位，与“人子”意思不同。"}, {"text": "林子", "is_correct": false, "explanation": "lín（第二声）与 rén（第二声）声调相同，但声母不同（l 与 r），“林子”指树林，与“人子”意思不同。"}], "explanations": {"人子": "正确答案。人子（rén zǐ）指人的儿子，在《圣经》中是耶稣对自己的称呼。", "人字": "zì（第四声）与 zǐ（第三声）声调不同，“人字”指字形像“人”的形状，与“人子”意思不同。", "人质": "zhì（第四声）与 zǐ（第三声）声母与声调都不同（zh 与 z），“人质”指被扣押的人，与“人子”意思不同。", "人次": "cì（第四声）与 zǐ（第三声）声母与声调不同（c 与 z），“人次”是人数乘以次数的统计单位，与“人子”意思不同。", "林子": "lín（第二声）与 rén（第二声）声调相同，但声母不同（l 与 r），“林子”指树林，与“人子”意思不同。"}, "sentence_index": null, "correct_answer": "人子"}, "level_3": {"options": [{"text": "人子", "is_correct": true, "explanation": "正确。“耶稣常常称自己为”后接的是耶稣的自称，“人子”符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不是耶稣用来称呼自己的名号，句意不通。"}, {"text": "爹", "is_correct": false, "explanation": "语域：“爹”是口语的亲属称呼，与《圣经》的庄重语体不符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是空间场所，不能用来称呼自己，与句意矛盾。"}], "explanations": {"人子": "正确。“耶稣常常称自己为”后接的是耶稣的自称，“人子”符合句意。", "桌子": "语义：“桌子”是家具，不是耶稣用来称呼自己的名号，句意不通。", "爹": "语域：“爹”是口语的亲属称呼，与《圣经》的庄重语体不符。", "房间": "语义：“房间”是空间场所，不能用来称呼自己，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "人子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "《圣经》里说，人子是一只小狗。", "explanation": "“人子”指人或耶稣的自称，不能用来指动物，这里误用为指动物。"}, {"text": "我把人子放进了书包里。", "explanation": "“人子”指人的儿子或耶稣的自称，不是可以放进书包的物品，这里误用了它的意思。"}, {"text": "释迦牟尼在佛经里常常称自己为人子。", "explanation": "“人子”是《圣经》中耶稣的自称，释迦牟尼不用此称，这里误用了它的专称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人子", "is_correct": true, "explanation": "正确。“读到……的话”需要说话的人，“人子”指像耶稣这样的说话者，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不会说话，不能作为“话”的来源，与“读到……的话”不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能说话，句中“话”无从读到。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不是能说话的对象，与句意矛盾。"}], "explanations": {"人子": "正确。“读到……的话”需要说话的人，“人子”指像耶稣这样的说话者，符合句意。", "天气": "搭配：“天气”不会说话，不能作为“话”的来源，与“读到……的话”不合。", "冰箱": "语义：“冰箱”是家电，不能说话，句中“话”无从读到。", "窗户": "语义：“窗户”是建筑部件，不是能说话的对象，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "人子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的人子都很努力。", "explanation": "“人子”指人的儿子或耶稣的自称，不用来泛指同学；此处应说“同学”。"}, {"text": "我们周末去人子玩。", "explanation": "“人子”指人的儿子或耶稣的自称，不能指地方，这里误用了它的意思。"}, {"text": "他去超市买了一个人子。", "explanation": "“人子”指人的儿子或耶稣的自称，不能当作商品买卖，这里误用了它的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "星期天，老师给我们讲了一张人子的故事，大家都听得很认真。", "corrected_sentence": "星期天，老师给我们讲了人子的故事，大家都听得很认真。", "error_description": "错误：“一张人子”。“人子”指人，不能用量词“张”修饰；应直接说“人子的故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在教会读到一本人子的话，心里很温暖。", "corrected_sentence": "我们在教会读到人子的话，心里很温暖。", "error_description": "错误：“一本人子”。“人子”指人，不能用书本的量词“本”修饰；应为“读到人子的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86893, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "哭", "is_correct": true, "explanation": "“哭”与“笑”是反义词，指悲伤时流泪出声。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“笑”没有反义关系，不能与之对应。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”与“笑”没有反义关系，不能与之对应。"}, {"text": "说", "is_correct": false, "explanation": "“说”与“笑”没有反义关系，不能与之对应。"}], "correct_answer": "哭", "explanations": {"哭": "“哭”与“笑”是反义词，指悲伤时流泪出声。", "跑": "“跑”与“笑”没有反义关系，不能与之对应。", "吃": "“吃”与“笑”没有反义关系，不能与之对应。", "说": "“说”与“笑”没有反义关系，不能与之对应。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86893, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "哭", "is_correct": true, "explanation": "“哭”与“笑”是反义词，指悲伤时流泪出声。"}, {"text": "走", "is_correct": false, "explanation": "“走”与“笑”没有反义关系，不能与之对应。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“笑”没有反义关系，不能与之对应。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”与“笑”没有反义关系，不能与之对应。"}], "correct_answer": "哭", "explanations": {"哭": "“哭”与“笑”是反义词，指悲伤时流泪出声。", "走": "“走”与“笑”没有反义关系，不能与之对应。", "唱": "“唱”与“笑”没有反义关系，不能与之对应。", "坐": "“坐”与“笑”没有反义关系，不能与之对应。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86893, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "笑是高兴的时候，嘴巴张开，发出声音。", "primary_collocate": null, "pronunciation": "xiào", "ipa": "ɕi̯ɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "他听了这个故事，大声地笑了。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在院子里又跑又笑。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一听就笑出了声。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太有意思，我们笑了一晚上。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别笑，我说的是真的。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑得肚子都疼了。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一说话，全班同学都笑了。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了个故事，我们笑个不停。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐在桌子旁边又说又笑。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在图书馆里大声笑，会吵到别人。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笑了", "label": "体标"}, {"form": "笑着", "label": "体标"}, {"form": "笑过", "label": "体标"}, {"form": "笑笑", "label": "重叠"}], "register": "中性", "sense_fingerprint": "笑：高兴时张嘴出声地笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86893, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "笑", "is_correct": true, "explanation": "笑 xiào，意思是高兴时张嘴发出声音地笑。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小。"}, {"text": "叫", "is_correct": false, "explanation": "jiào 与 xiào 声母不同（j 与 x），意思是叫。"}, {"text": "消", "is_correct": false, "explanation": "xiāo（第一声）与 xiào（第四声）声调不同，意思是消失。"}], "explanations": {"笑": "笑 xiào，意思是高兴时张嘴发出声音地笑。", "小": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小。", "叫": "jiào 与 xiào 声母不同（j 与 x），意思是叫。", "消": "xiāo（第一声）与 xiào（第四声）声调不同，意思是消失。"}, "sentence_index": null, "correct_answer": "笑"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：“写”是书写，不能大声进行，“大声地写了”与“听了这个故事”的情境不符，句意不通。"}, {"text": "笑", "is_correct": true, "explanation": "“笑”指高兴时张嘴出声地笑，与“大声地”搭配，符合句意。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“睡”不能和“大声地”搭配，表达不自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“听了这个故事”的情境无关，句子不合逻辑。"}], "explanations": {"写": "语义：“写”是书写，不能大声进行，“大声地写了”与“听了这个故事”的情境不符，句意不通。", "笑": "“笑”指高兴时张嘴出声地笑，与“大声地”搭配，符合句意。", "睡": "搭配：“睡”不能和“大声地”搭配，表达不自然。", "吃": "语义：“吃”与“听了这个故事”的情境无关，句子不合逻辑。"}, "sentence_index": 0, "correct_answer": "笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看着窗外的雨，轻轻地笑了一口气。", "explanation": "这里应该用〈叹〉。“笑”指高兴时发出笑声，不能与“一口气”搭配；表示无奈应说“叹了一口气”。"}, {"text": "他高兴地笑了一首新歌。", "explanation": "这里应该用〈唱〉。“笑”表示发出笑声或面露喜色，不能用来表示唱歌，应说“唱了一首新歌”。"}, {"text": "她把行李笑上了车，准备出发。", "explanation": "这里应该用〈搬〉。“笑”不能表示搬运，应说“把行李搬上了车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86893, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "笑", "is_correct": true, "explanation": "笑 xiào，意思是高兴时张嘴发出声音地笑。"}, {"text": "翘", "is_correct": false, "explanation": "qiào 与 xiào 声母不同（q 与 x），意思是翘起。"}, {"text": "销", "is_correct": false, "explanation": "xiāo（第一声）与 xiào（第四声）声调不同，意思是销售。"}, {"text": "轿", "is_correct": false, "explanation": "jiào 与 xiào 声母不同（j 与 x），意思是轿子。"}], "explanations": {"笑": "笑 xiào，意思是高兴时张嘴发出声音地笑。", "翘": "qiào 与 xiào 声母不同（q 与 x），意思是翘起。", "销": "xiāo（第一声）与 xiào（第四声）声调不同，意思是销售。", "轿": "jiào 与 xiào 声母不同（j 与 x），意思是轿子。"}, "sentence_index": null, "correct_answer": "笑"}, "level_3": {"options": [{"text": "咳", "is_correct": false, "explanation": "语义：“咳嗽”与“他一说话”之间没有合理的因果关系，句子不通。"}, {"text": "笑", "is_correct": true, "explanation": "“笑”指全班同学因为他的话而笑，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要宾语，“全班同学都扔了”说不完整。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“全班同学都摔了”的说法不自然，句意不通。"}], "explanations": {"咳": "语义：“咳嗽”与“他一说话”之间没有合理的因果关系，句子不通。", "笑": "“笑”指全班同学因为他的话而笑，符合句意。", "扔": "配价：“扔”需要宾语，“全班同学都扔了”说不完整。", "摔": "搭配：“全班同学都摔了”的说法不自然，句意不通。"}, "sentence_index": 6, "correct_answer": "笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈看着菜谱，笑了一锅汤。", "explanation": "这里应该用〈煮〉。“笑”不能表示烹饪，应说“煮了一锅汤”。"}, {"text": "她把杯子笑在桌子上，没有说话。", "explanation": "这里应该用〈放〉。“笑”不能表示放置东西，应说“把杯子放在桌子上”。"}, {"text": "他把窗户笑开了，让风吹进来。", "explanation": "这里应该用〈推〉。“笑开”表示笑出声，不能表示打开窗户，应说“推开了窗户”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一看到我，就大声笑起了来。", "corrected_sentence": "他一看到我，就大声笑了起来。", "error_description": "助词位置错误：“笑了起来”中的“了”紧跟动词“笑”，“起来”作补语在后；“笑起了来”的语序不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家听完笑话，都笑前仰后合。", "corrected_sentence": "大家听完笑话，都笑得前仰后合。", "error_description": "补语错误：“笑得前仰后合”中的“得”不能省略，省略后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86894, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "哭", "is_correct": true, "explanation": "“哭”与“笑”是反义词，指悲伤时流泪出声。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“笑”没有反义关系，不能与之对应。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”与“笑”没有反义关系，不能与之对应。"}, {"text": "说", "is_correct": false, "explanation": "“说”与“笑”没有反义关系，不能与之对应。"}], "correct_answer": "哭", "explanations": {"哭": "“哭”与“笑”是反义词，指悲伤时流泪出声。", "跑": "“跑”与“笑”没有反义关系，不能与之对应。", "吃": "“吃”与“笑”没有反义关系，不能与之对应。", "说": "“说”与“笑”没有反义关系，不能与之对应。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86894, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "哭", "is_correct": true, "explanation": "“哭”与“笑”是反义词，指悲伤时流泪出声。"}, {"text": "走", "is_correct": false, "explanation": "“走”与“笑”没有反义关系，不能与之对应。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“笑”没有反义关系，不能与之对应。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”与“笑”没有反义关系，不能与之对应。"}], "correct_answer": "哭", "explanations": {"哭": "“哭”与“笑”是反义词，指悲伤时流泪出声。", "走": "“走”与“笑”没有反义关系，不能与之对应。", "唱": "“唱”与“笑”没有反义关系，不能与之对应。", "坐": "“坐”与“笑”没有反义关系，不能与之对应。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86894, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因高兴或觉得有趣而面露喜色，不一定发出声音。", "primary_collocate": null, "pronunciation": "xiào", "ipa": "ɕi̯ɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "她看着我，轻轻地笑了笑。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见到老朋友，高兴地笑了。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，请大家笑一笑。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看着孩子，笑着点了点头。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不说话，只是看着我笑。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑起来很好看。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩对我甜甜地笑了一下。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在门口，一直笑着。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天心情很好，总是笑。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了我的话，她只笑了笑，没有说什么。", "target_word": "笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笑了", "label": "体标"}, {"form": "笑着", "label": "体标"}, {"form": "笑过", "label": "体标"}, {"form": "笑笑", "label": "重叠"}], "register": "中性", "sense_fingerprint": "笑：因高兴或觉得有趣而脸上露出笑容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86894, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "笑", "is_correct": true, "explanation": "笑 xiào，意思是因高兴或觉得有趣而脸上露出笑容。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小。"}, {"text": "较", "is_correct": false, "explanation": "jiào 与 xiào 声母不同（j 与 x），意思是比较。"}, {"text": "销", "is_correct": false, "explanation": "xiāo（第一声）与 xiào（第四声）声调不同，意思是销售。"}], "explanations": {"笑": "笑 xiào，意思是因高兴或觉得有趣而脸上露出笑容。", "小": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小。", "较": "jiào 与 xiào 声母不同（j 与 x），意思是比较。", "销": "xiāo（第一声）与 xiào（第四声）声调不同，意思是销售。"}, "sentence_index": null, "correct_answer": "笑"}, "level_3": {"options": [{"text": "吼了吼", "is_correct": false, "explanation": "语义：“吼”是大声叫喊，与“轻轻地”的语气相反，句意矛盾。"}, {"text": "笑了笑", "is_correct": true, "explanation": "“笑了笑”是“笑”的重叠形式，表示轻轻地笑一下，与“轻轻地”搭配，符合句意。"}, {"text": "砸了砸", "is_correct": false, "explanation": "语义：“砸”是重击，与“轻轻地”矛盾，句意不通。"}, {"text": "炸了炸", "is_correct": false, "explanation": "语义：“炸”表示爆裂，与“轻轻地”和“看着我”的情境完全不符。"}], "explanations": {"吼了吼": "语义：“吼”是大声叫喊，与“轻轻地”的语气相反，句意矛盾。", "笑了笑": "“笑了笑”是“笑”的重叠形式，表示轻轻地笑一下，与“轻轻地”搭配，符合句意。", "砸了砸": "语义：“砸”是重击，与“轻轻地”矛盾，句意不通。", "炸了炸": "语义：“炸”表示爆裂，与“轻轻地”和“看着我”的情境完全不符。"}, "sentence_index": 0, "correct_answer": "笑了笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她听完消息，默默地笑了一口气。", "explanation": "这里应该用〈叹〉。“笑”不能与“一口气”搭配，表示无奈或悲伤应说“叹了一口气”。"}, {"text": "孩子们放学后笑了一支歌。", "explanation": "这里应该用〈唱〉。“笑”表示面露喜色或发出笑声，不能用来表示唱歌，应说“唱了一支歌”。"}, {"text": "她把花笑进了花瓶。", "explanation": "这里应该用〈插〉。“笑”不能表示把花放入容器，应说“把花插进花瓶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86894, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "笑", "is_correct": true, "explanation": "笑 xiào，意思是因高兴或觉得有趣而脸上露出笑容。"}, {"text": "翘", "is_correct": false, "explanation": "qiào 与 xiào 声母不同（q 与 x），意思是翘起。"}, {"text": "轿", "is_correct": false, "explanation": "jiào 与 xiào 声母不同（j 与 x），意思是轿子。"}, {"text": "消", "is_correct": false, "explanation": "xiāo（第一声）与 xiào（第四声）声调不同，意思是消失。"}], "explanations": {"笑": "笑 xiào，意思是因高兴或觉得有趣而脸上露出笑容。", "翘": "qiào 与 xiào 声母不同（q 与 x），意思是翘起。", "轿": "jiào 与 xiào 声母不同（j 与 x），意思是轿子。", "消": "xiāo（第一声）与 xiào（第四声）声调不同，意思是消失。"}, "sentence_index": null, "correct_answer": "笑"}, "level_3": {"options": [{"text": "摔", "is_correct": false, "explanation": "搭配：“摔”不能用“甜甜地”修饰，搭配不当。"}, {"text": "笑", "is_correct": true, "explanation": "“笑”指因高兴而露出笑容，与“甜甜地”搭配，符合句意。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”与“甜甜地”的温和语气相反，句意矛盾。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳嗽”与“对我”的亲切情境不符，句子不通。"}], "explanations": {"摔": "搭配：“摔”不能用“甜甜地”修饰，搭配不当。", "笑": "“笑”指因高兴而露出笑容，与“甜甜地”搭配，符合句意。", "骂": "语义：“骂”与“甜甜地”的温和语气相反，句意矛盾。", "咳": "语义：“咳嗽”与“对我”的亲切情境不符，句子不通。"}, "sentence_index": 6, "correct_answer": "笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿坏了，笑了一大碗面。", "explanation": "这里应该用〈吃〉。“笑”表示面露喜色或发出笑声，不能表示吃东西，应说“吃了一大碗面”。"}, {"text": "他把球笑进了门里。", "explanation": "这里应该用〈踢〉。“笑”不能表示把球弄进去，应说“把球踢进了门里”。"}, {"text": "他站在灵前，笑了三个躬。", "explanation": "这里应该用〈鞠〉。“笑”不能与“躬”搭配，应说“鞠了三个躬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对我了笑笑，什么也没说。", "corrected_sentence": "她对我笑了笑，什么也没说。", "error_description": "助词位置错误：“笑了笑”中的“了”应放在两个“笑”之间，不能放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐在窗边，静静地着笑。", "corrected_sentence": "他坐在窗边，静静地笑着。", "error_description": "助词位置错误：“笑着”的“着”应放在动词之后，不能放在动词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
