INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "暴力是用很大的力气打人或伤害别人。", "primary_collocate": null, "pronunciation": "bào lì", "ipa": "pɑʊ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "老师说，打人是暴力，不能这样做。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不应该看有暴力的电影。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友使用暴力，大家都很生气。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里不允许有暴力。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴力不能解决问题。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候看到过暴力，现在还很害怕。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有太多暴力，不适合小孩。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用暴力打了同学，老师很生气。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸常教我，遇到问题不要用暴力。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的暴力让孩子很害怕。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家庭暴力", "label": "复合"}, {"form": "暴力行为", "label": "复合"}], "register": "中性", "sense_fingerprint": "用力气打人、伤害别人的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86895, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暴力", "is_correct": true, "explanation": "暴力：bào lì，指用很大的力气伤害别人的行为。"}, {"text": "薄利", "is_correct": false, "explanation": "bó lì 与 bào lì 第一个音节韵母不同（o 与 ao），薄利意思是微薄的利润。"}, {"text": "保理", "is_correct": false, "explanation": "bǎo lǐ 与 bào lì 两个音节声调都不同，保理是金融术语，指应收账款的管理与融资。"}, {"text": "包里", "is_correct": false, "explanation": "bāo lǐ 与 bào lì 两个音节声调都不同，包里意思是包的里面。"}], "explanations": {"暴力": "暴力：bào lì，指用很大的力气伤害别人的行为。", "薄利": "bó lì 与 bào lì 第一个音节韵母不同（o 与 ao），薄利意思是微薄的利润。", "保理": "bǎo lǐ 与 bào lì 两个音节声调都不同，保理是金融术语，指应收账款的管理与融资。", "包里": "bāo lǐ 与 bào lì 两个音节声调都不同，包里意思是包的里面。"}, "sentence_index": null, "correct_answer": "暴力"}, "level_3": {"options": [{"text": "暴力", "is_correct": true, "explanation": "正确：暴力指用力伤害别人的行为，与“打人”和“不能这样做”的语境相符。"}, {"text": "和平", "is_correct": false, "explanation": "语义：和平指和睦安宁，与打人的行为相反，不能说打人是和平。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：打人不是游戏，“打人是游戏”与句子的语境不符。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：礼貌是待人有礼的品质，不能用“是礼貌”来描述打人这种行为。"}], "explanations": {"暴力": "正确：暴力指用力伤害别人的行为，与“打人”和“不能这样做”的语境相符。", "和平": "语义：和平指和睦安宁，与打人的行为相反，不能说打人是和平。", "游戏": "语义：打人不是游戏，“打人是游戏”与句子的语境不符。", "礼貌": "搭配：礼貌是待人有礼的品质，不能用“是礼貌”来描述打人这种行为。"}, "sentence_index": 0, "correct_answer": "暴力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有很强的暴力，每天坚持跑步。", "explanation": "这里应该用〈毅力〉。暴力指伤害他人的行为，坚持不懈的意志要用“毅力”。"}, {"text": "他感到很大的暴力，每天都睡不好。", "explanation": "这里应该用〈压力〉。暴力指伤害他人的行为，心理上的负担要用“压力”。"}, {"text": "他很有暴力，每次考试都得第一。", "explanation": "这里应该用〈能力〉。暴力指伤害他人的行为，学习的本领要用“能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴力", "is_correct": true, "explanation": "正确：“太多暴力”说明游戏的内容问题，与“不适合小孩”的语境相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：游戏的内容不是作业，“游戏有太多作业”与句子的意思不符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是友善的表情，“太多微笑”与“不适合小孩”的意思无法连贯。"}, {"text": "香水", "is_correct": false, "explanation": "搭配：游戏与香水不搭配，“游戏有太多香水”无法构成合理的说明。"}], "explanations": {"暴力": "正确：“太多暴力”说明游戏的内容问题，与“不适合小孩”的语境相符。", "作业": "语义：游戏的内容不是作业，“游戏有太多作业”与句子的意思不符。", "微笑": "语义：微笑是友善的表情，“太多微笑”与“不适合小孩”的意思无法连贯。", "香水": "搭配：游戏与香水不搭配，“游戏有太多香水”无法构成合理的说明。"}, "sentence_index": 6, "correct_answer": "暴力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的暴力很旺盛，每天都运动。", "explanation": "这里应该用〈精力〉。暴力指伤害他人的行为，形容精力充沛要用“精力”。"}, {"text": "他的暴力很好，一眼就看出了真假。", "explanation": "这里应该用〈眼力〉。暴力用于伤害他人，观察和判断的能力要用“眼力”。"}, {"text": "这辆汽车的暴力很强，爬坡很快。", "explanation": "这里应该用〈动力〉。暴力指伤害他人的行为，机器推动车辆的能力要用“动力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把暴力让人很害怕。", "corrected_sentence": "这种暴力让人很害怕。", "error_description": "量词错误：“暴力”是抽象名词，应该用量词“种”，不能用“把”。正确说法是“这种暴力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部暴力地电影让孩子很害怕。", "corrected_sentence": "这部暴力的电影让孩子很害怕。", "error_description": "结构助词错误：修饰名词“电影”要用“的”，不能用“地”。正确说法是“暴力的电影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
