INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "强制的、伤害他人的力量或行为。", "primary_collocate": null, "pronunciation": "bào lì", "ipa": "pɑʊ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "法律禁止对儿童使用暴力。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些人用暴力占领了工厂。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里有暴力，孩子不能看。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反对用暴力解决问题。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会上的暴力越来越少了。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要用法律对抗暴力。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用暴力威胁商店的老板。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴力会给受害的人带来很大的伤害。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定严厉打击暴力。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和平的方法比暴力更有用。", "target_word": "暴力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暴力行为", "label": "复合"}, {"form": "暴力犯罪", "label": "复合"}], "register": "中性", "sense_fingerprint": "强制他人、造成伤害的力量或手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暴力", "is_correct": true, "explanation": "暴力：bào lì，指强制他人、造成伤害的力量或手段。"}, {"text": "薄利", "is_correct": false, "explanation": "bó lì 与 bào lì 第一个音节韵母不同（o 与 ao），薄利意思是微薄的利润。"}, {"text": "保理", "is_correct": false, "explanation": "bǎo lǐ 与 bào lì 两个音节声调都不同，保理是金融术语，指应收账款的管理与融资。"}, {"text": "包里", "is_correct": false, "explanation": "bāo lǐ 与 bào lì 两个音节声调都不同，包里意思是包的里面。"}], "explanations": {"暴力": "暴力：bào lì，指强制他人、造成伤害的力量或手段。", "薄利": "bó lì 与 bào lì 第一个音节韵母不同（o 与 ao），薄利意思是微薄的利润。", "保理": "bǎo lǐ 与 bào lì 两个音节声调都不同，保理是金融术语，指应收账款的管理与融资。", "包里": "bāo lǐ 与 bào lì 两个音节声调都不同，包里意思是包的里面。"}, "sentence_index": null, "correct_answer": "暴力"}, "level_3": {"options": [{"text": "暴力", "is_correct": true, "explanation": "正确：“使用暴力”指对儿童施加伤害，与“法律禁止”的语境相符。"}, {"text": "和平", "is_correct": false, "explanation": "搭配：“使用”不跟“和平”搭配，不能说“使用和平”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不会伤害儿童，“法律禁止对儿童使用音乐”的意思不成立。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“友谊”是人与人之间的关系，不能说“使用友谊”。"}], "explanations": {"暴力": "正确：“使用暴力”指对儿童施加伤害，与“法律禁止”的语境相符。", "和平": "搭配：“使用”不跟“和平”搭配，不能说“使用和平”。", "音乐": "语义：音乐不会伤害儿童，“法律禁止对儿童使用音乐”的意思不成立。", "友谊": "搭配：“友谊”是人与人之间的关系，不能说“使用友谊”。"}, "sentence_index": 0, "correct_answer": "暴力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很有暴力，一道题可以想一个小时。", "explanation": "这里应该用〈耐心〉。暴力指伤害他人的行为，做事有耐心要用“耐心”。"}, {"text": "这位同学很有暴力，敢在全班面前发言。", "explanation": "这里应该用〈勇气〉。暴力指伤害他人的行为，敢于面对困难的胆量要用“勇气”。"}, {"text": "她有很强的暴力，一直坚持练习。", "explanation": "这里应该用〈毅力〉。暴力指伤害他人的行为，坚持不懈的意志要用“毅力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴力", "is_correct": true, "explanation": "正确：“用暴力威胁”说明威胁的手段，与句子的语境相符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑不是威胁的手段，“用微笑威胁”与句子的意思不符。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：“礼貌”不能作为威胁的手段，“用礼貌威胁”搭配不当。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不能用来威胁人，“用花朵威胁”与句子的意思不符。"}], "explanations": {"暴力": "正确：“用暴力威胁”说明威胁的手段，与句子的语境相符。", "微笑": "语义：微笑不是威胁的手段，“用微笑威胁”与句子的意思不符。", "礼貌": "搭配：“礼貌”不能作为威胁的手段，“用礼貌威胁”搭配不当。", "花朵": "语义：花朵不能用来威胁人，“用花朵威胁”与句子的意思不符。"}, "sentence_index": 6, "correct_answer": "暴力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的暴力很强，数学考了第一名。", "explanation": "这里应该用〈能力〉。暴力指伤害他人的行为，形容人的学习能力要用“能力”。"}, {"text": "这个孩子的暴力很足，每天都跑跑跳跳。", "explanation": "这里应该用〈活力〉。暴力指伤害他人的行为，形容精力充沛要用“活力”。"}, {"text": "她的暴力很好，能连续跑三个小时。", "explanation": "这里应该用〈体力〉。暴力指伤害他人的行为，身体的力量与耐力要用“体力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用暴力地抢走了别人的钱包。", "corrected_sentence": "他们用暴力抢走了别人的钱包。", "error_description": "助词错误：“暴力”在这里是名词，作“用”的宾语，后面不能加“地”。正确说法是“用暴力抢走了别人的钱包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们对店主使用这把暴力，店主报了警。", "corrected_sentence": "他们对店主使用这种暴力，店主报了警。", "error_description": "量词错误：“暴力”是抽象名词，应该用量词“种”，不能用“把”。正确说法是“这种暴力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
