INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "代表人物是一群人里最有名、最有力量的那个人。大家一想到这类人，就先想到他。", "primary_collocate": null, "pronunciation": "dài biǎo rén wù", "ipa": "tai˥˩ piau˨˩˦ ʐən˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "说起中国功夫，李小龙是代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐队里，主唱是代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们学校，他是篮球队的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一提到网球，就想起这位代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到中国足球，很多人先想到这位代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周杰伦是流行音乐的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的代表人物是王大爷。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说起中国相声，谁是最有名的代表人物？", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直是这个团队的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提到京剧，她是大家心里的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "一群人里最有名、最有力量、最先被想到的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代表人物", "is_correct": true, "explanation": "“代表人物”指在某个群体中最有名、最有力量、最先被想到的人，与“李小龙”相符。"}, {"text": "作品", "is_correct": false, "explanation": "语义：“作品”指成果，不是人，“李小龙是中国功夫的作品”说不通。"}, {"text": "门派", "is_correct": false, "explanation": "语义：“门派”指武术的派别，不指某个人，与“李小龙”不符。"}, {"text": "招式", "is_correct": false, "explanation": "语义：“招式”指武术的动作套路，不指人，“李小龙是招式”说不通。"}], "explanations": {"代表人物": "“代表人物”指在某个群体中最有名、最有力量、最先被想到的人，与“李小龙”相符。", "作品": "语义：“作品”指成果，不是人，“李小龙是中国功夫的作品”说不通。", "门派": "语义：“门派”指武术的派别，不指某个人，与“李小龙”不符。", "招式": "语义：“招式”指武术的动作套路，不指人，“李小龙是招式”说不通。"}, "sentence_index": 0, "correct_answer": "代表人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌是流行音乐的代表人物。", "explanation": "这里应该用〈代表作〉。“代表人物”指人，说一首歌是某类音乐的代表，应该用“代表作”。"}, {"text": "他拿到了全国代表人物。", "explanation": "这里应该用〈冠军〉。“代表人物”指有代表性的人，不是比赛名次，不能说“拿到代表人物”。"}, {"text": "他在比赛中取得了好代表人物。", "explanation": "这里应该用〈成绩〉。“代表人物”指人，取得的是成绩，不能说“取得好代表人物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代表人物", "is_correct": true, "explanation": "“代表人物”指在这个村子里最有名、最有影响的人，与“王大爷”相符。"}, {"text": "特产", "is_correct": false, "explanation": "语义：“特产”指本地出产的东西，不是人，“王大爷”不能是特产。"}, {"text": "名胜", "is_correct": false, "explanation": "语义：“名胜”指有名的风景点，不指人，与“王大爷”不符。"}, {"text": "名称", "is_correct": false, "explanation": "语义：“名称”指事物的叫法，不指人，“这个村子的名称是王大爷”说不通。"}], "explanations": {"代表人物": "“代表人物”指在这个村子里最有名、最有影响的人，与“王大爷”相符。", "特产": "语义：“特产”指本地出产的东西，不是人，“王大爷”不能是特产。", "名胜": "语义：“名胜”指有名的风景点，不指人，与“王大爷”不符。", "名称": "语义：“名称”指事物的叫法，不指人，“这个村子的名称是王大爷”说不通。"}, "sentence_index": 6, "correct_answer": "代表人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛在室内代表人物举行。", "explanation": "这里应该用〈场地〉。“代表人物”指人，不能用来指比赛的地点。"}, {"text": "他主持的代表人物很精彩。", "explanation": "这里应该用〈节目〉。“代表人物”指人，不能用来形容节目的好坏。"}, {"text": "他做事的代表人物很正派。", "explanation": "这里应该用〈作风〉。“代表人物”指人，说做事的方式要用“作风”，不能说“做事的代表人物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是这个乐队里代表人物。", "corrected_sentence": "他是这个乐队里的代表人物。", "error_description": "“这个乐队里”修饰“代表人物”时要用“的”，应说“这个乐队里的代表人物”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有一只代表人物，叫小林。", "corrected_sentence": "我们班有一位代表人物，叫小林。", "error_description": "“代表人物”指一群人里最有名的那一个人，量词应用“位”。“只”多用于动物和物品，不能用来数人，应说“一位代表人物”，不说“一只代表人物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
