INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在某个时代、领域或群体中最具代表性、影响最大的人。", "primary_collocate": null, "pronunciation": "dài biǎo rén wù", "ipa": "tai˥˩ piau˨˩˦ ʐən˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "李白是唐代诗歌的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个行业的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "齐白石是中国画的代表人物之一。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师是现代教育的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅是新文化运动的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马云是中国电商的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梅兰芳是京剧的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成了这个时代的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是中国女子篮球的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱因斯坦是现代物理学的代表人物。", "target_word": "代表人物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "某时代或领域中最有代表性、影响最大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代表人物", "is_correct": true, "explanation": "“代表人物”指某时代或领域中最有代表性的人，与“李白”和“唐代诗歌”相符。"}, {"text": "作品", "is_correct": false, "explanation": "语义：“作品”指写出或做出来的东西，不是人，“李白是唐代诗歌的作品”说不通。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”指一段历史时期，不指人，与“李白”不能画等号。"}, {"text": "体裁", "is_correct": false, "explanation": "语义：“体裁”指文学作品的类型，不指人，“李白是唐代诗歌的体裁”说不通。"}], "explanations": {"代表人物": "“代表人物”指某时代或领域中最有代表性的人，与“李白”和“唐代诗歌”相符。", "作品": "语义：“作品”指写出或做出来的东西，不是人，“李白是唐代诗歌的作品”说不通。", "时代": "语义：“时代”指一段历史时期，不指人，与“李白”不能画等号。", "体裁": "语义：“体裁”指文学作品的类型，不指人，“李白是唐代诗歌的体裁”说不通。"}, "sentence_index": 0, "correct_answer": "代表人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座古塔是北京的代表人物。", "explanation": "这里应该用〈象征〉。“代表人物”指人，说古塔这类事物的代表应该用“象征”。"}, {"text": "各班推选出来的代表人物都来参加了会议。", "explanation": "这里应该用〈代表〉。被推选出来参加会议的人叫“代表”；“代表人物”指在某领域最有影响的人，不指会议代表。"}, {"text": "这本书是他的代表人物。", "explanation": "这里应该用〈代表作〉。“代表人物”指人，说一本书是他的“代表人物”不成立，应说“代表作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代表人物", "is_correct": true, "explanation": "“代表人物”指在京剧领域最有代表性的人，与“梅兰芳”相符。"}, {"text": "剧目", "is_correct": false, "explanation": "语义：“剧目”指演出的戏，不是人，“梅兰芳是京剧的剧目”说不通。"}, {"text": "流派", "is_correct": false, "explanation": "语义：“流派”指艺术上的派别，不指某一个人，与“梅兰芳”这个人不符。"}, {"text": "剧院", "is_correct": false, "explanation": "语义：“剧院”指演出的场所，不指人，“梅兰芳是京剧的剧院”说不通。"}], "explanations": {"代表人物": "“代表人物”指在京剧领域最有代表性的人，与“梅兰芳”相符。", "剧目": "语义：“剧目”指演出的戏，不是人，“梅兰芳是京剧的剧目”说不通。", "流派": "语义：“流派”指艺术上的派别，不指某一个人，与“梅兰芳”这个人不符。", "剧院": "语义：“剧院”指演出的场所，不指人，“梅兰芳是京剧的剧院”说不通。"}, "sentence_index": 6, "correct_answer": "代表人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "五四运动是中国近代史上的代表人物。", "explanation": "这里应该用〈事件〉。“代表人物”指人，五四运动是一场事件，不能说它是“代表人物”。"}, {"text": "这项研究取得了重要的代表人物。", "explanation": "这里应该用〈成果〉。“代表人物”指人，“取得”的应是成果，不能取得一个人。"}, {"text": "他提出了重要的代表人物。", "explanation": "这里应该用〈思想〉。“代表人物”指人，提出的是思想或理论，不能说“提出代表人物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是这一带代表人物。", "corrected_sentence": "她是这一带的代表人物。", "error_description": "“这一带”修饰“代表人物”时要用结构助词“的”，应说“这一带的代表人物”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几只都是团队里的代表人物。", "corrected_sentence": "这几位都是团队里的代表人物。", "error_description": "“只”用于动物和物品，不能用来数人。这里应说“这几位”，不说“这几只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
