INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86901, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示每一次都这样，没有例外。", "primary_collocate": null, "pronunciation": "zǒng shì", "ipa": "tsʊŋ˨˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "每次考试，他总是很紧张。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给她打电话，她总是不接。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一下雨，路上总是堵车。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问他问题，他总是认真回答。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生日，我总是送一本书。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次回家，妈妈总是做鱼。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃饭的时候总是看手机。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁的时候，我总是听音乐。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到春天，他总是打喷嚏。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子见到我总是害羞地笑。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，每一次都这样，没有例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总是", "is_correct": true, "explanation": "正确答案：总是（zǒng shì）。"}, {"text": "中式", "is_correct": false, "explanation": "zhōng（第一声）与 zǒng（第三声）声母与声调都不同（z 与 zh），意思是中式。"}, {"text": "总数", "is_correct": false, "explanation": "shì 与 shù 韵母不同（i 与 u），意思是总数。"}, {"text": "走势", "is_correct": false, "explanation": "zǒu（第三声）与 zǒng 韵母不同（u 与 ng），意思是走势。"}, {"text": "懂事", "is_correct": false, "explanation": "dǒng 与 zǒng 声母不同（d 与 z），意思是懂事。"}], "explanations": {"总是": "正确答案：总是（zǒng shì）。", "中式": "zhōng（第一声）与 zǒng（第三声）声母与声调都不同（z 与 zh），意思是中式。", "总数": "shì 与 shù 韵母不同（i 与 u），意思是总数。", "走势": "zǒu（第三声）与 zǒng 韵母不同（u 与 ng），意思是走势。", "懂事": "dǒng 与 zǒng 声母不同（d 与 z），意思是懂事。"}, "sentence_index": null, "correct_answer": "总是"}, "level_3": {"options": [{"text": "总是", "is_correct": true, "explanation": "正确：“总是”表示每一次都这样，与“每次考试”的前提相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“每次”正好矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作此刻进行，不能说“正在很紧张”这种状态。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，用于让步语境，放在这句口语叙述中不自然。"}], "explanations": {"总是": "正确：“总是”表示每一次都这样，与“每次考试”的前提相符。", "偶尔": "语义：“偶尔”表示不常发生，与“每次”正好矛盾。", "正在": "体貌：“正在”表示动作此刻进行，不能说“正在很紧张”这种状态。", "诚然": "语域：“诚然”是书面语，用于让步语境，放在这句口语叙述中不自然。"}, "sentence_index": 0, "correct_answer": "总是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上个月总是去了一次北京。", "explanation": "这里应该用〈只〉。“总是”表示每次都这样、反复发生，不能和“一次”这种一次性的事件连用。"}, {"text": "他昨天总是迟到了一次。", "explanation": "这里应该用〈偶尔〉。“总是”不能和“一次”这种只发生一次的数量连用。"}, {"text": "这次比赛他总是拿了冠军。", "explanation": "这里应该用〈终于〉。“总是”表示反复发生，这次比赛的结果是一次性的，要用“终于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总是", "is_correct": true, "explanation": "正确：“总是”表示每次都这样，与“吃饭的时候”每次看手机的习惯相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙行动，与吃饭时看手机这种日常习惯不符。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示马上行动，不能用来描述日常习惯。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要共同的对象或多人，“他”一个人看手机不能用“一起”。"}], "explanations": {"总是": "正确：“总是”表示每次都这样，与“吃饭的时候”每次看手机的习惯相符。", "赶紧": "语义：“赶紧”表示急忙行动，与吃饭时看手机这种日常习惯不符。", "连忙": "语义：“连忙”表示马上行动，不能用来描述日常习惯。", "一起": "搭配：“一起”需要共同的对象或多人，“他”一个人看手机不能用“一起”。"}, "sentence_index": 6, "correct_answer": "总是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次见面，这个孩子总是笑了一下。", "explanation": "这里应该用〈只〉。“总是”表示每次都这样的反复，这次见面中笑了一下是一次性的事。"}, {"text": "明天这个孩子总是见到我。", "explanation": "这里应该用〈会〉。“总是”表示每次都这样，明天这样的一次见面是将来的一次性事件，要用表示将来的“会”。"}, {"text": "我第一次见到这个孩子，她总是害羞地笑。", "explanation": "这里应该用〈一直〉。“总是”表示每次都反复出现，第一次见面中的持续状态要用表示持续的“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每次开会，她总是很认真了。", "corrected_sentence": "每次开会，她总是很认真。", "error_description": "“总是”描述每次都这样的惯常情况，句末不能再加表示变化的“了”。应删去“了”，说“每次开会，她总是很认真。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子见到我没总是害羞地笑。", "corrected_sentence": "这个孩子见到我不总是害羞地笑。", "error_description": "否定“总是”要用“不”，应说“不总是”。“没”不能用来否定“总是”，“没总是”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
