INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86902, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示一直如此，每次都这样。", "primary_collocate": null, "pronunciation": "zǒng shì", "ipa": "tsʊŋ˨˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他总是第一个到教室。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是早上六点起床。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟总是忘带钥匙。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的人总是很多。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷总是坐在窗边看报纸。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是笑着跟大家打招呼。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这里总是下雪。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是迟到，老师很生气。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王总是帮我拿东西。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们总是去公园跑步。", "target_word": "总是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，一直如此，习惯性地总这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86902, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总是", "is_correct": true, "explanation": "正确答案：总是（zǒng shì）。"}, {"text": "中式", "is_correct": false, "explanation": "zhōng（第一声）与 zǒng（第三声）声母与声调都不同（z 与 zh），意思是中式。"}, {"text": "总数", "is_correct": false, "explanation": "shì 与 shù 韵母不同（i 与 u），意思是总数。"}, {"text": "走势", "is_correct": false, "explanation": "zǒu 与 zǒng 韵母不同（ou 与 ong），意思是走势。"}, {"text": "懂事", "is_correct": false, "explanation": "dǒng 与 zǒng 声母不同（d 与 z），意思是懂事。"}], "explanations": {"总是": "正确答案：总是（zǒng shì）。", "中式": "zhōng（第一声）与 zǒng（第三声）声母与声调都不同（z 与 zh），意思是中式。", "总数": "shì 与 shù 韵母不同（i 与 u），意思是总数。", "走势": "zǒu 与 zǒng 韵母不同（ou 与 ong），意思是走势。", "懂事": "dǒng 与 zǒng 声母不同（d 与 z），意思是懂事。"}, "sentence_index": null, "correct_answer": "总是"}, "level_3": {"options": [{"text": "总是", "is_correct": true, "explanation": "正确：“总是”表示习惯性地一直如此，与“第一个到教室”的日常习惯相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，“到教室”是一次完成的动作，不能用于习惯性的句子。"}, {"text": "很", "is_correct": false, "explanation": "语法：程度副词“很”不能修饰“第一个到教室”这样的动词短语。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，用于让步语境，放在这句普通叙述中不自然。"}], "explanations": {"总是": "正确：“总是”表示习惯性地一直如此，与“第一个到教室”的日常习惯相符。", "正在": "体貌：“正在”表示动作正在进行，“到教室”是一次完成的动作，不能用于习惯性的句子。", "很": "语法：程度副词“很”不能修饰“第一个到教室”这样的动词短语。", "诚然": "语域：“诚然”是书面语，用于让步语境，放在这句普通叙述中不自然。"}, "sentence_index": 0, "correct_answer": "总是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们等了很久，他总是到了。", "explanation": "这里应该用〈总算〉。“总是”表示反复出现的习惯，等待之后的一次到达要用“总算”。"}, {"text": "那场比赛他总是赢了，大家都很高兴。", "explanation": "这里应该用〈终于〉。“总是”表示反复发生，比赛中的一次胜利要用“终于”。"}, {"text": "他昨晚十二点总是回家。", "explanation": "这里应该用〈才〉。“总是”表示每次都这样，昨晚的一次晚归要用“才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总是", "is_correct": true, "explanation": "正确：“总是”表示一直如此，与“冬天这里”每年都下雪的情况相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做某事，需要有意志的主语，下雪不能“赶紧”。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要性，不能用来描述天气的自然变化。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要多个主体或共同的对象，这句话只说地点和天气，不能用“一起”。"}], "explanations": {"总是": "正确：“总是”表示一直如此，与“冬天这里”每年都下雪的情况相符。", "赶紧": "语义：“赶紧”表示急忙去做某事，需要有意志的主语，下雪不能“赶紧”。", "必须": "语义：“必须”表示必要性，不能用来描述天气的自然变化。", "一起": "搭配：“一起”需要多个主体或共同的对象，这句话只说地点和天气，不能用“一起”。"}, "sentence_index": 6, "correct_answer": "总是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天总是下雪了，所以路很滑。", "explanation": "这里应该用〈突然〉。“总是”表示反复发生的习惯，昨天的这场雪是一次性事件，要用“突然”。"}, {"text": "他总是读完了那本书，只用了一个晚上。", "explanation": "这里应该用〈一口气〉。“总是”表示反复，一个晚上读完一本书是一次性的，要用“一口气”。"}, {"text": "下周我们总是去北京。", "explanation": "这里应该用〈将要〉。“总是”表示每次都反复，下周的北京之行是一次性安排，要用“将要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶很总是早上五点起床。", "corrected_sentence": "奶奶总是早上五点起床。", "error_description": "错误：“很”后面接了副词“总是”。“很”只修饰形容词或心理动词，不能修饰“总是”。应去掉“很”，说“奶奶总是早上五点起床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天这里没总是下雪。", "corrected_sentence": "冬天这里不总是下雪。", "error_description": "否定“总是”要用“不”，说“不总是”。“没”不能用来否定“总是”，“没总是”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
