INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86903, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "任从是不管，让别人想怎么样就怎么样。", "primary_collocate": null, "pronunciation": "rèn cóng", "ipa": "ɻən˥˩ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "任从别人怎么说，他都不生气。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从你去哪里，我都不管。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从孩子们在院子里玩。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从他怎么解释，大家都不相信。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从她选，哪件都可以。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从你怎么想，我都支持你。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师任从学生自己决定。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从风吹雨打，小树还是站着。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从同学们怎么问，他一句话也不说。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从他们吵，她只管看书。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任從", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "不管别人怎样，由着别人想怎么样就怎么样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a82c9e-092e-40ce-a3d1-76b4efb5b7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "语义：“切”指用刀分开，“别人怎么说”不是可以切的东西，句子不通。"}, {"text": "任从", "is_correct": true, "explanation": "正确答案。任从表示不管别人怎样说，由着别人去说，与后句“他都不生气”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是可以吃的东西，“别人怎么说”不能吃，句子不通。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”需要接收对象和通知内容，此处结构不完整，句子不成立。"}], "explanations": {"切": "语义：“切”指用刀分开，“别人怎么说”不是可以切的东西，句子不通。", "任从": "正确答案。任从表示不管别人怎样说，由着别人去说，与后句“他都不生气”相符。", "吃": "搭配：“吃”的宾语应是可以吃的东西，“别人怎么说”不能吃，句子不通。", "通知": "配价：“通知”需要接收对象和通知内容，此处结构不完整，句子不成立。"}, "sentence_index": 0, "correct_answer": "任从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们任从老师的安排，按时完成了作业。", "explanation": "这里应该用〈听从〉。任从表示不加干涉、由着别人去做，不表示顺从别人的指示。"}, {"text": "士兵任从上级的命令，立刻出发。", "explanation": "这里应该用〈服从〉。任从强调放手不管，不表示接受命令。"}, {"text": "大家任从医生的建议，按时吃药。", "explanation": "这里应该用〈遵从〉。任从强调不加干涉，不表示依照建议行事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替别人，与“学生自己决定”相矛盾，句子不通。"}, {"text": "管", "is_correct": false, "explanation": "语义：“管”表示管理或干预，“管学生自己决定”的意思与语境相反。"}, {"text": "任从", "is_correct": true, "explanation": "正确答案。任从表示由着别人去做，不加干涉，与“学生自己决定”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“学生自己决定”不能吃，句子不通。"}], "explanations": {"替": "语义：“替”表示代替别人，与“学生自己决定”相矛盾，句子不通。", "管": "语义：“管”表示管理或干预，“管学生自己决定”的意思与语境相反。", "任从": "正确答案。任从表示由着别人去做，不加干涉，与“学生自己决定”相符。", "吃": "搭配：“吃”的宾语应是食物，“学生自己决定”不能吃，句子不通。"}, "sentence_index": 6, "correct_answer": "任从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗任从主人，一步也不离开。", "explanation": "这里应该用〈跟随〉。任从表示不管别人怎样、由着别人，不表示紧跟着走。"}, {"text": "他任从老师，学了很多年的画。", "explanation": "这里应该用〈追随〉。任从不表示跟着某人学习。"}, {"text": "老师任从我们的建议，改了计划。", "explanation": "这里应该用〈采纳〉。任从表示放手不管，不表示接受建议并付诸实施。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "任从了他自己决定吧。", "corrected_sentence": "任从他自己决定吧。", "error_description": "“任从”后不能直接加“了”，应说“任从他自己决定吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "任从着他去吧。", "corrected_sentence": "任从他去吧。", "error_description": "“任从”后不接“着”，应说“任从他去吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
