INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86904, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听凭；任凭（别人怎样做）。", "primary_collocate": null, "pronunciation": "rèn cóng", "ipa": "ɻən˥˩ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "任从你们安排，我没有意见。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母任从孩子自己选择专业。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他任从别人批评，不回答一句。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从大家讨论，老师不说话。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把钥匙交给我，任从我处理。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从客人挑选，价格都一样。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理任从大家提意见，从不干预。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从别人笑他，他还是坚持着。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任从你们怎么玩，别吵到邻居。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他任从事情发展，什么也不做。", "target_word": "任从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任從", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "听凭别人去做，不加干涉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a82c9e-092e-40ce-a3d1-76b4efb5b7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与后句“我没有意见”相矛盾。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”表示不遵守，与“我没有意见”的态度不符，句子不通。"}, {"text": "任从", "is_correct": true, "explanation": "正确答案。任从表示听凭别人去做，与后句“我没有意见”相符。"}, {"text": "指责", "is_correct": false, "explanation": "搭配：“指责”针对的是人或行为，且与“我没有意见”的语境不合。"}], "explanations": {"反对": "语义：“反对”表示不同意，与后句“我没有意见”相矛盾。", "违背": "语义：“违背”表示不遵守，与“我没有意见”的态度不符，句子不通。", "任从": "正确答案。任从表示听凭别人去做，与后句“我没有意见”相符。", "指责": "搭配：“指责”针对的是人或行为，且与“我没有意见”的语境不合。"}, "sentence_index": 0, "correct_answer": "任从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子任从父母的安排，马上照办，一句也不多说。", "explanation": "这里应该用〈顺从〉。任从强调由着别人去做、不加干涉，不表示顺着对方的意愿服从。"}, {"text": "他任从朋友的请求，帮了忙。", "explanation": "这里应该用〈答应〉。任从表示放手不管，不表示同意对方的请求。"}, {"text": "校长任从同学们的意见，取消了考试。", "explanation": "这里应该用〈采纳〉。任从表示不加干涉，不表示接受意见并付诸实施。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”表示不让别人做，与“任从”的放任态度相反，不符合经理的态度。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是可以吃的东西，“大家提意见”不能吃，句子不通。"}, {"text": "任从", "is_correct": true, "explanation": "正确答案。任从表示由着别人去做，不加干涉，与“大家提意见”相符。"}, {"text": "逼", "is_correct": false, "explanation": "语义：“逼”表示强迫，与“任从”的放手态度相反，句子不符合语境。"}], "explanations": {"阻止": "语义：“阻止”表示不让别人做，与“任从”的放任态度相反，不符合经理的态度。", "吃": "搭配：“吃”的宾语应是可以吃的东西，“大家提意见”不能吃，句子不通。", "任从": "正确答案。任从表示由着别人去做，不加干涉，与“大家提意见”相符。", "逼": "语义：“逼”表示强迫，与“任从”的放手态度相反，句子不符合语境。"}, "sentence_index": 6, "correct_answer": "任从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们任从老师的提问，纷纷举手回答。", "explanation": "这里是“回应、作答”的意思。任从表示由着别人去做、不加干涉，不表示对别人的提问作出回应。"}, {"text": "学校任从这名新同学，让他入了学。", "explanation": "这里应该用〈接纳〉。任从表示不加干涉，不表示同意让对方加入。"}, {"text": "他任从老师的话，马上去做作业。", "explanation": "这里应该用〈听从〉。任从表示由着别人、不加干涉，不表示按别人的话去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "任从着孩子们自己选择吧。", "corrected_sentence": "任从孩子们自己选择吧。", "error_description": "“任从”后不接“着”，应说“任从孩子们自己选择吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
