INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86905, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "决议是大家开会商量以后，决定好的事。", "primary_collocate": null, "pronunciation": "jué yì", "ipa": "tɕɥɛ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "开会以后，大家有了一个决议。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上的决议是下周去公园。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班会上定下的决议，每个人都要记住。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组的决议写在黑板上了。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把会议的决议告诉了老师。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决议是大家一起商量出来的。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，家庭会议的决议不能改。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不同意今天会上的决议。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按照决议开始打扫教室。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新决议已贴在门口，请大家前往查阅。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "決議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "大家开会商量后定下的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "决计", "is_correct": false, "explanation": "jì（第四声）与 yì（第四声）声母不同（j 与 y），意思是决计（一定、务必）。"}, {"text": "学艺", "is_correct": false, "explanation": "xué（第二声）与 jué（第二声）声母不同（x 与 j），yì 相同，意思是学艺。"}, {"text": "决议", "is_correct": true, "explanation": "正确。决议 jué yì，指大家开会商量后定下的事。"}, {"text": "绝地", "is_correct": false, "explanation": "dì（第四声）与 yì（第四声）声母不同（d 与 y），意思是绝地。"}, {"text": "决疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声母韵母相同、只差声调，意思是决断疑惑。"}], "explanations": {"决计": "jì（第四声）与 yì（第四声）声母不同（j 与 y），意思是决计（一定、务必）。", "学艺": "xué（第二声）与 jué（第二声）声母不同（x 与 j），yì 相同，意思是学艺。", "决议": "正确。决议 jué yì，指大家开会商量后定下的事。", "绝地": "dì（第四声）与 yì（第四声）声母不同（d 与 y），意思是绝地。", "决疑": "yí（第二声）与 yì（第四声）声母韵母相同、只差声调，意思是决断疑惑。"}, "sentence_index": null, "correct_answer": "决议"}, "level_3": {"options": [{"text": "大海", "is_correct": false, "explanation": "语义：“大海”不能被“有了”，与“开会以后”形成的结果不相容，句意不通。"}, {"text": "决议", "is_correct": true, "explanation": "正确。“开会以后，大家有了一个决议”符合语境，“决议”指会议后定下的事。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“开会以后”不能“有了”一个季节，与会议的结果语义不符。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：开会不会产生一个孩子，与“开会以后”形成的结果不相容。"}], "explanations": {"大海": "语义：“大海”不能被“有了”，与“开会以后”形成的结果不相容，句意不通。", "决议": "正确。“开会以后，大家有了一个决议”符合语境，“决议”指会议后定下的事。", "夏天": "语义：“开会以后”不能“有了”一个季节，与会议的结果语义不符。", "孩子": "语义：开会不会产生一个孩子，与“开会以后”形成的结果不相容。"}, "sentence_index": 0, "correct_answer": "决议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的决议是去看电影。", "explanation": "这里应该用〈决定〉。决议要经会议讨论通过，个人的选择要用〈决定〉。"}, {"text": "我对这件事有不同决议。", "explanation": "这里应该用〈意见〉。决议是集体讨论后通过的决定，个人的看法要用〈意见〉。"}, {"text": "这道数学题的决议是三十六。", "explanation": "这里应该用〈答案〉。决议是大家商量后定下的事，数学题的结果要用〈答案〉，不能说「决议是……」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：“改”的对象应是决议、计划之类的规定，“天空”与家庭会议无关。"}, {"text": "决议", "is_correct": true, "explanation": "正确。“家庭会议的决议不能改”符合语境，“决议”指会议通过的决定。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“改”可以搭配“主意、计划”，不能说“改脚步”。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”指闲话、传闻，不是家庭会议定下、不能改的事。"}], "explanations": {"天空": "语义：“改”的对象应是决议、计划之类的规定，“天空”与家庭会议无关。", "决议": "正确。“家庭会议的决议不能改”符合语境，“决议”指会议通过的决定。", "脚步": "搭配：“改”可以搭配“主意、计划”，不能说“改脚步”。", "八卦": "语义：“八卦”指闲话、传闻，不是家庭会议定下、不能改的事。"}, "sentence_index": 6, "correct_answer": "决议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的决议是下课后去打篮球。", "explanation": "这里应该用〈建议〉。决议要经会议讨论通过，个人的提议要用〈建议〉。"}, {"text": "老师的决议是每天读书。", "explanation": "这里应该用〈指示〉。决议要经大家开会讨论通过，老师一个人的安排要用〈指示〉。"}, {"text": "这次调查的决议是大家都很满意。", "explanation": "这里应该用〈结论〉。决议是会议通过的决定，调查得出的判断要用〈结论〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班会上定下了一只新决议。", "corrected_sentence": "班会上定下了一项新决议。", "error_description": "量词错误：“决议”应该用量词“项”，不能用“只”（“只”用于动物、成对器官等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨晚一个人想了想，作出了一项决议：早点睡觉。", "corrected_sentence": "我昨晚一个人想了想，作出了一个决定：早点睡觉。", "error_description": "用词错误：“决议”要经会议讨论通过，一个人自己定下的事应该用“决定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
