INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经会议讨论通过的决定。", "primary_collocate": null, "pronunciation": "jué yì", "ipa": "tɕɥɛ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "大会通过了一项关于环保的决议。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事会的决议明天会公布。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项决议得到了大多数人的支持。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经开始执行股东会的决议。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议最后作出了新的决议。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对这份决议没有意见。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上宣读了那项决议。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项决议要求每个部门提交报告。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校委会的决议让学生们很高兴。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员们一致同意这个决议。", "target_word": "决议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "決議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "会议讨论后正式通过的决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绝技", "is_correct": false, "explanation": "jì（第四声）与 yì（第四声）声母不同（j 与 y），意思是绝技。"}, {"text": "决议", "is_correct": true, "explanation": "正确。决议 jué yì，指经会议讨论通过的决定。"}, {"text": "决疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声母韵母相同、只差声调，意思是决断疑惑。"}, {"text": "学艺", "is_correct": false, "explanation": "xué（第二声）与 jué（第二声）声母不同（x 与 j），yì 相同，意思是学艺。"}, {"text": "绝地", "is_correct": false, "explanation": "dì（第四声）与 yì（第四声）声母不同（d 与 y），意思是绝地。"}], "explanations": {"绝技": "jì（第四声）与 yì（第四声）声母不同（j 与 y），意思是绝技。", "决议": "正确。决议 jué yì，指经会议讨论通过的决定。", "决疑": "yí（第二声）与 yì（第四声）声母韵母相同、只差声调，意思是决断疑惑。", "学艺": "xué（第二声）与 jué（第二声）声母不同（x 与 j），yì 相同，意思是学艺。", "绝地": "dì（第四声）与 yì（第四声）声母不同（d 与 y），意思是绝地。"}, "sentence_index": null, "correct_answer": "决议"}, "level_3": {"options": [{"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不能被“通过”，句中“通过”的对象应是提案、决议之类的事项。"}, {"text": "决议", "is_correct": true, "explanation": "正确。“通过”的对象是决议、提案之类的事项，“一项关于环保的决议”符合语境。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与“大会通过”“关于环保”的书面语体不协调。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是会议可以通过的事项，与“通过了一项……”的语义不符。"}], "explanations": {"咖啡": "语义：咖啡不能被“通过”，句中“通过”的对象应是提案、决议之类的事项。", "决议": "正确。“通过”的对象是决议、提案之类的事项，“一项关于环保的决议”符合语境。", "玩意儿": "语域：“玩意儿”是口语说法，与“大会通过”“关于环保”的书面语体不协调。", "天气": "语义：天气不是会议可以通过的事项，与“通过了一项……”的语义不符。"}, "sentence_index": 0, "correct_answer": "决议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人在家想了很久，最后作出了一个决议：周末不出门。", "explanation": "这里应该用〈决定〉。决议必须经会议讨论通过，一个人独自做的选择不能叫决议。"}, {"text": "这次会议的决议是三个方案，大家可以选一个。", "explanation": "这里应该用〈方案〉。决议是讨论通过后定下的结果，还没定的几个备选办法要用〈方案〉。"}, {"text": "他随口定了一项关于环保的决议。", "explanation": "这里应该用〈决定〉。决议要经会议讨论通过，随口说的个人决定不能叫决议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“宣读”搭配的是文件、声明之类的文字，不搭配“作业”。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓不是可以被宣读的文字内容，与“宣读”的对象不符。"}, {"text": "决议", "is_correct": true, "explanation": "正确。“宣读”的对象是决议、声明等文件，“那项决议”符合语境。"}, {"text": "哥哥", "is_correct": false, "explanation": "配价：“宣读”的宾语必须是文字内容，“哥哥”是人，不能作宾语。"}], "explanations": {"作业": "搭配：“宣读”搭配的是文件、声明之类的文字，不搭配“作业”。", "草莓": "语义：草莓不是可以被宣读的文字内容，与“宣读”的对象不符。", "决议": "正确。“宣读”的对象是决议、声明等文件，“那项决议”符合语境。", "哥哥": "配价：“宣读”的宾语必须是文字内容，“哥哥”是人，不能作宾语。"}, "sentence_index": 6, "correct_answer": "决议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的决议是大家周末一起去爬山。", "explanation": "这里应该用〈建议〉。决议要经会议讨论通过，个人的提议要用〈建议〉。"}, {"text": "我一个人在屋里定下决议，要戒烟。", "explanation": "这里应该用〈决心〉。决议要经会议讨论通过，一个人在屋里下的决心不能叫决议。"}, {"text": "这次实验的决议是水会变成蒸气。", "explanation": "这里应该用〈结论〉。决议是会议通过的决定，实验得出的判断要用〈结论〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大会刚刚通过了一只新决议。", "corrected_sentence": "大会刚刚通过了一项新决议。", "error_description": "量词错误：“决议”应该用量词“项”，不能用“只”（“只”用于动物、成对器官等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人想了很久，作出了一项决议：明天早起。", "corrected_sentence": "他一个人想了很久，作出了一个决定：明天早起。", "error_description": "用词错误：“决议”是会议讨论通过的决定，个人独自定下的事应该用“决定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86907, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86907, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86907, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "偏见是还没看清楚，就觉得某个人不好。这样想是不对的。", "primary_collocate": null, "pronunciation": "piān jiàn", "ipa": "pʰjɛn˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他没见过我，就对我有偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不应该对学生有偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你还不认识他，别对他有偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以前对他有偏见，现在觉得他很好。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为偏见，他不想和新同学说话。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别带着偏见看人，先和他聊聊。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对我有偏见，所以不愿帮我。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了朋友的话，我对他有了偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "认识以后，我才知道自己的偏见是错的。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，不要因为偏见就不相信别人。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "种族偏见", "label": "复合"}, {"form": "偏見", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对某个人还不了解，就认为他不好的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d9b7acb-06c4-4953-b400-63e6e8a36ece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86907, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香味", "is_correct": false, "explanation": "语义：香味说的是气味，不能用来表示对人的看法，“对我有香味”说不通。"}, {"text": "偏见", "is_correct": true, "explanation": "正确：偏见是还没了解就有的不好看法，与“没见过我”的语境相合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有”后面不接体重，人的体重不说“对谁有”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“对我有颜色”不成话，颜色不用于对人的看法。"}], "explanations": {"香味": "语义：香味说的是气味，不能用来表示对人的看法，“对我有香味”说不通。", "偏见": "正确：偏见是还没了解就有的不好看法，与“没见过我”的语境相合。", "体重": "搭配：“有”后面不接体重，人的体重不说“对谁有”。", "颜色": "搭配：“对我有颜色”不成话，颜色不用于对人的看法。"}, "sentence_index": 0, "correct_answer": "偏见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪器的测量结果有偏见。", "explanation": "这里应该用〈偏差〉。偏见指对人的片面看法，仪器的测量误差要说偏差。"}, {"text": "他有早睡的偏见。", "explanation": "这里应该用〈习惯〉。偏见是对人或事的看法，不用来指“早睡”这类生活习惯。"}, {"text": "他用偏见解决了这个问题。", "explanation": "这里应该用〈办法〉。偏见是片面的看法，不能用来解决问题；解决问题要靠“办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86907, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好感", "is_correct": false, "explanation": "语义：好感是喜欢的心情，与“所以不愿帮我”的语气相反。"}, {"text": "偏见", "is_correct": true, "explanation": "正确：偏见是对她的不好看法，与“不愿帮我”相合。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“对……有”后面不接礼物，句子说不通。"}, {"text": "信心", "is_correct": false, "explanation": "语义：信心是肯定的态度，和“不愿帮我”矛盾。"}], "explanations": {"好感": "语义：好感是喜欢的心情，与“所以不愿帮我”的语气相反。", "偏见": "正确：偏见是对她的不好看法，与“不愿帮我”相合。", "礼物": "搭配：“对……有”后面不接礼物，句子说不通。", "信心": "语义：信心是肯定的态度，和“不愿帮我”矛盾。"}, "sentence_index": 6, "correct_answer": "偏见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的偏见很漂亮，大家都喜欢她。", "explanation": "这里应该用〈长相〉。偏见是对人的片面看法，不能形容外貌；说“漂亮”要用于长相。"}, {"text": "他的偏见修好了电脑。", "explanation": "这里应该用〈技术人员〉。偏见是片面的看法，不能动手修电脑；修电脑的应是“技术人员”。"}, {"text": "我在博物馆里看到一幅偏见的画。", "explanation": "这里应该用〈风格〉。偏见指对人或事的片面看法，描述画的特点要说“风格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我偏见，我要改正它。", "corrected_sentence": "这是我的偏见，我要改正它。", "error_description": "错误：「我偏见」漏掉了结构助词「的」。正确应为「我的偏见」，名词性定语和中心词之间要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向新来的同事有偏见，所以很少说话。", "corrected_sentence": "他对新来的同事有偏见，所以很少说话。", "error_description": "错误：「向」不能与「有偏见」搭配，对人的看法要用「对」。正确应为「对新来的同事有偏见」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
