INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对人或事物所持的片面、不公正而又不易改变的看法。", "primary_collocate": null, "pronunciation": "piān jiàn", "ipa": "pʰjɛn˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "社会上有人对女性有偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种偏见很难一下子改变。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个行业一直有偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人对外国人有偏见，这不公平。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看问题总是带着偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体的报道有时会加深人们的偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要努力消除对老年人的偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用实际行动打破了大家的偏见。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偏见让人只看到事情的一面。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的偏见太深，谁劝也没用。", "target_word": "偏见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "种族偏见", "label": "复合"}, {"form": "偏見", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事物片面、不公正且难以改变的看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d9b7acb-06c4-4953-b400-63e6e8a36ece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼物", "is_correct": false, "explanation": "搭配：“对……有”后面不接礼物，“对女性有礼物”说不通。"}, {"text": "偏见", "is_correct": true, "explanation": "正确：偏见指对某类人片面、不公正的看法，与“社会上有人”的语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不用于对群体的看法，“有颜色”不能接“对女性”。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味是气味，不是对女性的看法，句意不通。"}], "explanations": {"礼物": "搭配：“对……有”后面不接礼物，“对女性有礼物”说不通。", "偏见": "正确：偏见指对某类人片面、不公正的看法，与“社会上有人”的语境相合。", "颜色": "搭配：颜色不用于对群体的看法，“有颜色”不能接“对女性”。", "香味": "语义：香味是气味，不是对女性的看法，句意不通。"}, "sentence_index": 0, "correct_answer": "偏见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验的结果有偏见。", "explanation": "这里应该用〈误差〉。偏见指对人或事的片面看法，实验的数据偏差要说误差。"}, {"text": "他有晨练的偏见。", "explanation": "这里应该用〈习惯〉。偏见不指“晨练”这类生活习惯，习惯要说“习惯”。"}, {"text": "他的偏见很能干，把工作都做完了。", "explanation": "这里应该用〈能力〉。偏见是片面的看法，不能用来形容人能干；形容人的本事要说“能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊重", "is_correct": false, "explanation": "语义：“消除”的对象是不好的看法，尊重是好的态度，不能被消除。"}, {"text": "偏见", "is_correct": true, "explanation": "正确：偏见是对老年人的不好看法，与“消除”搭配，句意通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是可以消除的看法，“消除椅子”句意不通。"}, {"text": "礼貌", "is_correct": false, "explanation": "语义：礼貌是正面的待人态度，不是需要消除的东西。"}], "explanations": {"尊重": "语义：“消除”的对象是不好的看法，尊重是好的态度，不能被消除。", "偏见": "正确：偏见是对老年人的不好看法，与“消除”搭配，句意通顺。", "椅子": "语义：椅子是家具，不是可以消除的看法，“消除椅子”句意不通。", "礼貌": "语义：礼貌是正面的待人态度，不是需要消除的东西。"}, "sentence_index": 6, "correct_answer": "偏见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用偏见拟定了这个计划。", "explanation": "这里应该用〈思路〉。偏见是片面的看法，不能用来拟定计划；拟定计划要靠“思路”。"}, {"text": "我把这首歌的偏见唱给朋友听。", "explanation": "这里应该用〈歌词〉。偏见是片面的看法，不能拿来唱；唱的是“歌词”或“旋律”。"}, {"text": "我的偏见在厨房里做了一顿晚饭。", "explanation": "这里应该用〈厨师〉。偏见是看法，不能动手做饭；做饭的应是“厨师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只偏见一旦形成，就很难改变。", "corrected_sentence": "一种偏见一旦形成，就很难改变。", "error_description": "错误：「一只」用于动物或成对的东西，偏见要用量词「种」。正确应为「一种偏见」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向这个行业有偏见，所以一直不去了解。", "corrected_sentence": "他对这个行业有偏见，所以一直不去了解。", "error_description": "错误：「向」不能与「有偏见」搭配，对事物的偏见要用「对」。正确应为「对这个行业有偏见」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
