INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86909, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86909, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留是让人或东西待在这里，不走。", "primary_collocate": null, "pronunciation": "liú", "ipa": "ljou˧˥", "syllable_count": 1, "sentences": [{"text": "朋友要走，我留他吃饭。", "target_word": "留", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天晚了，妈妈留我在家住。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想留他，可是他还是走了。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把我留在教室里，让我写作业。", "target_word": "留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，主人留客人多坐一会儿。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们热情地留我们住了一晚。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别走，我想留你再坐一会儿。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想留这位好老师，给他涨了工资。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她哭着留他，可他没有回头。", "target_word": "留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说有事要走，我们留不住他。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "留着", "label": "体标"}, {"form": "留了", "label": "体标"}, {"form": "留过", "label": "体标"}, {"form": "留下", "label": "复合"}], "register": "中性", "sense_fingerprint": "留：挽留，让人待在原地不走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86909, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "留", "is_correct": true, "explanation": "留（liú）：让人待在这里不走，是本题的目标词。"}, {"text": "牛", "is_correct": false, "explanation": "niú 与 liú 声母不同（n 与 l），意思是牛。"}, {"text": "柳", "is_correct": false, "explanation": "liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。"}, {"text": "六", "is_correct": false, "explanation": "liù（第四声）与 liú（第二声）声调不同，意思是数字六。"}], "explanations": {"留": "留（liú）：让人待在这里不走，是本题的目标词。", "牛": "niú 与 liú 声母不同（n 与 l），意思是牛。", "柳": "liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。", "六": "liù（第四声）与 liú（第二声）声调不同，意思是数字六。"}, "sentence_index": null, "correct_answer": "留"}, "level_3": {"options": [{"text": "留", "is_correct": true, "explanation": "留：挽留，让朋友待下来吃饭，符合“要走”的语境。"}, {"text": "赶", "is_correct": false, "explanation": "语义：“赶”是驱赶，与“我留他吃饭”的挽留意思相反。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不能带“吃饭”作补充，“扔他吃饭”不成立。"}, {"text": "拦", "is_correct": false, "explanation": "配价：“拦”是阻挡，只能拦住人或东西，不能与“吃饭”搭配表示挽留。"}], "explanations": {"留": "留：挽留，让朋友待下来吃饭，符合“要走”的语境。", "赶": "语义：“赶”是驱赶，与“我留他吃饭”的挽留意思相反。", "扔": "搭配：“扔”不能带“吃饭”作补充，“扔他吃饭”不成立。", "拦": "配价：“拦”是阻挡，只能拦住人或东西，不能与“吃饭”搭配表示挽留。"}, "sentence_index": 0, "correct_answer": "留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想去美国留学，所以很努力。", "explanation": "这里的“留”是“留学”义，指去国外读书，与“让人待着不走”无关，不能用于挽留人。"}, {"text": "朋友要走，我留他到门口。", "explanation": "这里应该用〈送〉。留表示让人待着不走，送人到门口要用“送”，“留他到门口”不通。"}, {"text": "这次旅行给我留下了深刻的印象。", "explanation": "这里的“留下”是“留下印象”义，指给人留下感受，不表示挽留人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86909, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "留", "is_correct": true, "explanation": "留（liú）：让人待在这里不走，是本题的目标词。"}, {"text": "楼", "is_correct": false, "explanation": "lóu 比 liú 少了介音 i，意思是楼房。"}, {"text": "溜", "is_correct": false, "explanation": "liū（第一声）与 liú（第二声）声调不同，意思是滑走、溜走。"}, {"text": "遛", "is_correct": false, "explanation": "liù（第四声）与 liú（第二声）声调不同，意思是遛狗、散步。"}], "explanations": {"留": "留（liú）：让人待在这里不走，是本题的目标词。", "楼": "lóu 比 liú 少了介音 i，意思是楼房。", "溜": "liū（第一声）与 liú（第二声）声调不同，意思是滑走、溜走。", "遛": "liù（第四声）与 liú（第二声）声调不同，意思是遛狗、散步。"}, "sentence_index": null, "correct_answer": "留"}, "level_3": {"options": [{"text": "留", "is_correct": true, "explanation": "留：挽留，让人再坐一会儿，符合“别走”的语境。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是送行，与“别走”“再坐一会儿”的语境矛盾。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不能接“再坐一会儿”这种劝留说法，“打你再坐一会儿”不通。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是丢弃，与挽留相反，不能表示让人留下。"}], "explanations": {"留": "留：挽留，让人再坐一会儿，符合“别走”的语境。", "送": "语义：“送”是送行，与“别走”“再坐一会儿”的语境矛盾。", "打": "搭配：“打”不能接“再坐一会儿”这种劝留说法，“打你再坐一会儿”不通。", "丢": "语义：“丢”是丢弃，与挽留相反，不能表示让人留下。"}, "sentence_index": 6, "correct_answer": "留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我留言说今天不来了。", "explanation": "这里的“留”是“留言”义，指写下话让别人知道，与挽留人无关。"}, {"text": "妈妈留我去医院。", "explanation": "这里应该用〈陪〉。留表示让人待着不走，陪人去某地要用“陪”，“留我去医院”不通。"}, {"text": "他因为成绩不好留级了。", "explanation": "这里的“留”是“留级”义，指学生因成绩不够而不升级，与挽留人不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家怎么劝，他也留不住下。", "corrected_sentence": "大家怎么劝，他也留不住。", "error_description": "“留不住下”错误：“住”与“下”不能同时作结果补语，应为“留不住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天晚了，你就留来吃饭吧。", "corrected_sentence": "天晚了，你就留下来吃饭吧。", "error_description": "“留来”错误，应为“留下来”。挽留人留下时，“留”后要接趋向补语“下来”，不能只接“来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
