INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86910, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留是把东西保存下来，不用掉，留给以后或别人。", "primary_collocate": null, "pronunciation": "liú", "ipa": "ljou˧˥", "syllable_count": 1, "sentences": [{"text": "这个苹果你吃，那个留给妹妹。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想留一张照片做纪念。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好吃的菜，奶奶总是留着给孩子。", "target_word": "留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书我留着，以后还要看。", "target_word": "留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的饭我给你留了一份，在锅里。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把爷爷写的信都留了很多年。", "target_word": "留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我留一个靠窗的座位。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把第一次赚的钱留作纪念。", "target_word": "留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃剩的菜别扔，留到晚上再吃。", "target_word": "留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服太小了，但我还是留着。", "target_word": "留", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "留着", "label": "体标"}, {"form": "留了", "label": "体标"}, {"form": "留下", "label": "复合"}, {"form": "留给", "label": "复合"}], "register": "中性", "sense_fingerprint": "留：把东西保存下来，不用掉，留给以后或别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86910, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "留", "is_correct": true, "explanation": "留（liú）：保存下来，不用掉，是本题的目标词。"}, {"text": "牛", "is_correct": false, "explanation": "niú 与 liú 声母不同（n 与 l），意思是牛。"}, {"text": "柳", "is_correct": false, "explanation": "liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。"}, {"text": "六", "is_correct": false, "explanation": "liù（第四声）与 liú（第二声）声调不同，意思是数字六。"}], "explanations": {"留": "留（liú）：保存下来，不用掉，是本题的目标词。", "牛": "niú 与 liú 声母不同（n 与 l），意思是牛。", "柳": "liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。", "六": "liù（第四声）与 liú（第二声）声调不同，意思是数字六。"}, "sentence_index": null, "correct_answer": "留"}, "level_3": {"options": [{"text": "留", "is_correct": true, "explanation": "留：保存下来，留给别人，与句中“留给妹妹”一致。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“给妹妹”，“吃给妹妹”不成立。"}, {"text": "哭", "is_correct": false, "explanation": "语义：苹果不会哭，“那个哭给妹妹”与句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：苹果不能“唱”，与句中的“那个”（苹果）搭配不通。"}], "explanations": {"留": "留：保存下来，留给别人，与句中“留给妹妹”一致。", "吃": "搭配：“吃”不能带“给妹妹”，“吃给妹妹”不成立。", "哭": "语义：苹果不会哭，“那个哭给妹妹”与句意不通。", "唱": "语义：苹果不能“唱”，与句中的“那个”（苹果）搭配不通。"}, "sentence_index": 0, "correct_answer": "留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他留了一撇胡子。", "explanation": "这里的“留”是“留胡子”义，指让胡须长起来，与“使停留、保存”无关。"}, {"text": "他去美国留学了。", "explanation": "这里的“留”是“留学”义，指去国外读书，与保存东西无关。"}, {"text": "他给我留言说今天不来了。", "explanation": "这里的“留”是“留言”义，指写下话让别人知道，与保存东西无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86910, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "留", "is_correct": true, "explanation": "留（liú）：保存下来，不用掉，是本题的目标词。"}, {"text": "楼", "is_correct": false, "explanation": "lóu 比 liú 少了介音 i，意思是楼房。"}, {"text": "溜", "is_correct": false, "explanation": "liū（第一声）与 liú（第二声）声调不同，意思是滑走、溜走。"}, {"text": "遛", "is_correct": false, "explanation": "liù（第四声）与 liú（第二声）声调不同，意思是遛狗、散步。"}], "explanations": {"留": "留（liú）：保存下来，不用掉，是本题的目标词。", "楼": "lóu 比 liú 少了介音 i，意思是楼房。", "溜": "liū（第一声）与 liú（第二声）声调不同，意思是滑走、溜走。", "遛": "liù（第四声）与 liú（第二声）声调不同，意思是遛狗、散步。"}, "sentence_index": null, "correct_answer": "留"}, "level_3": {"options": [{"text": "留", "is_correct": true, "explanation": "留：保留，为我预留一个座位。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打一个座位”不通，“打”不能表示预留座位。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是擦拭，不表示预留座位。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚踢，与“座位”搭配不通，也不表示预留。"}], "explanations": {"留": "留：保留，为我预留一个座位。", "打": "搭配：“打一个座位”不通，“打”不能表示预留座位。", "擦": "语义：“擦”是擦拭，不表示预留座位。", "踢": "语义：“踢”是用脚踢，与“座位”搭配不通，也不表示预留。"}, "sentence_index": 6, "correct_answer": "留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈留我去医院。", "explanation": "这里应该用〈陪〉。这里的“留”表示把东西保存下来，不能用来表示陪人去某地，“留我去医院”不通。"}, {"text": "这次旅行给我留下了深刻的印象。", "explanation": "这里的“留下”是“留下印象”义，指给人留下感受，与保存东西无关。"}, {"text": "他因为成绩不好留级了。", "explanation": "这里的“留”是“留级”义，指学生因成绩不够而不升级，与保存东西无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这个苹果留妹妹。", "corrected_sentence": "我把这个苹果留给妹妹。", "error_description": "“留妹妹”错误，应为“留给妹妹”。为某人保存东西时，“留”后要接“给”，不能直接接人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张旧地图我还留了着，那是我小时候的东西。", "corrected_sentence": "这张旧地图我还留着，那是我小时候的东西。", "error_description": "“留了着”错误，应为“留着”。“了”和“着”不能同时用在“留”后，表示持续保存要用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
