INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86912, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结合在一起；使几方面共同行动。", "primary_collocate": null, "pronunciation": "lián hé", "ipa": "ljɛn˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个办法可以把大家联合起来。", "target_word": "联合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家联合举行了军事训练。", "target_word": "联合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三所大学联合培养研究生。", "target_word": "联合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人和农民联合起来，力量就大了。", "target_word": "联合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师想把各班的同学联合起来办活动。", "target_word": "联合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几家公司联合发表了一份声明。", "target_word": "联合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们联合起来反对这个决定。", "target_word": "联合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小国联合起来，才能保护自己。", "target_word": "联合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你联合其他部门解决这个问题。", "target_word": "联合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个政党联合组成了新政府。", "target_word": "联合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "联合起来", "label": "复合"}, {"form": "联合了", "label": "体标"}, {"form": "聯合", "label": "繁体"}], "register": "中性", "sense_fingerprint": "联合：使几个方面结合起来共同行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "联合", "is_correct": true, "explanation": "联合：使大家结合起来，共同行动，符合句意。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开，与“把大家结合起来”的意思相反。"}, {"text": "散", "is_correct": false, "explanation": "语义：“散”是分散，与结合义相反，也不能说“散起来”。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”用于撕纸之类的具体物体，不能接“把大家……起来”。"}], "explanations": {"联合": "联合：使大家结合起来，共同行动，符合句意。", "拆": "语义：“拆”是拆开，与“把大家结合起来”的意思相反。", "散": "语义：“散”是分散，与结合义相反，也不能说“散起来”。", "撕": "搭配：“撕”用于撕纸之类的具体物体，不能接“把大家……起来”。"}, "sentence_index": 0, "correct_answer": "联合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乐队联合了一首新曲子。", "explanation": "这里应该用〈合奏〉。联合表示使几方结合共同行动，不能用于演奏曲子。"}, {"text": "农民买了一台联合收割机。", "explanation": "这里的“联合”是名词修饰语，指一种收割机，不表示使几方结合共同行动。"}, {"text": "他在联合国工作。", "explanation": "这里的“联合”是“联合国”的一部分，是专有名词，不表示使几方面共同行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联合", "is_correct": true, "explanation": "联合：他们共同行动，符合句中“反对这个决定”的一致行动语境。"}, {"text": "赞成", "is_correct": false, "explanation": "语义：“赞成”与“反对这个决定”意思相反，句子会矛盾。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”与“反对这个决定”相反，句子会矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃起来”不成说法，“放弃反对”也与“联合起来”的语境不协调。"}], "explanations": {"联合": "联合：他们共同行动，符合句中“反对这个决定”的一致行动语境。", "赞成": "语义：“赞成”与“反对这个决定”意思相反，句子会矛盾。", "支持": "语义：“支持”与“反对这个决定”相反，句子会矛盾。", "放弃": "搭配：“放弃起来”不成说法，“放弃反对”也与“联合起来”的语境不协调。"}, "sentence_index": 6, "correct_answer": "联合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树要三个人才能联合。", "explanation": "这里应该用〈合抱〉。联合表示使几方结合共同行动，不能用来形容几个人合围一棵树。"}, {"text": "他是联合王国的留学生。", "explanation": "这里的“联合”是“联合王国”的一部分，是国名，不是动词，不表示使几方结合共同行动。"}, {"text": "同学们在晚会上联合了一首歌。", "explanation": "这里应该用〈合唱〉。联合表示使几方结合共同行动，不能用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各国要联合下来应对危机。", "corrected_sentence": "各国要联合起来应对危机。", "error_description": "补语错误：“联合”后应接趋向补语“起来”，说“联合下来”不通，应为“联合起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个方面要联合了在一起。", "corrected_sentence": "这两个方面要联合在一起。", "error_description": "“联合了在一起”错误，应为“联合在一起”。“了”是完成标记，不能插在“联合”和“在一起”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
