INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86913, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86913, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做梦是睡着的时候，脑子里出现了好像真的人和事。", "primary_collocate": null, "pronunciation": "zuò mèng", "ipa": "tsuɔ˥˩ mɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "妹妹睡得很香，好像在做梦。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡着以后常常做梦。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很少做梦，睡得很好。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在床上做梦，还笑了起来。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨晚做梦，梦到自己会飞。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨晚是不是做梦了？一直在说话。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡觉时做梦，嘴里还在说话。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天做梦，吓得半夜醒了。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做梦的时候，我常常看到已经去世的爷爷。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边睡一边笑，大概在做梦吧。", "target_word": "做梦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做过梦", "label": "体标"}, {"form": "做着梦", "label": "体标"}, {"form": "做了梦", "label": "体标"}, {"form": "白日做梦", "label": "复合"}, {"form": "做夢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "睡着时脑子里出现像真的人和事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d9b7acb-06c4-4953-b400-63e6e8a36ece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：散步是醒着时的活动，与“睡得很香”矛盾。"}, {"text": "做梦", "is_correct": true, "explanation": "正确：睡着时脑中出现情景，与“睡得很香”相合。"}, {"text": "写字", "is_correct": false, "explanation": "语义：写字要醒着进行，与“睡得很香”矛盾。"}, {"text": "观察", "is_correct": false, "explanation": "语义：观察是醒着时有意的注意活动，睡得很香的人不会在观察，句意不通。"}], "explanations": {"散步": "语义：散步是醒着时的活动，与“睡得很香”矛盾。", "做梦": "正确：睡着时脑中出现情景，与“睡得很香”相合。", "写字": "语义：写字要醒着进行，与“睡得很香”矛盾。", "观察": "语义：观察是醒着时有意的注意活动，睡得很香的人不会在观察，句意不通。"}, "sentence_index": 0, "correct_answer": "做梦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用做梦来解决问题，结果没有成功。", "explanation": "这里应该用〈想办法〉。做梦指睡时的情景或幻想，解决问题要说“想办法”。"}, {"text": "妈妈正在厨房做梦，饭马上就好了。", "explanation": "这里应该用〈做饭〉。做梦是睡着时脑子里出现的情景，在厨房准备饭菜要说“做饭”。"}, {"text": "孩子把床做梦了，还笑了起来。", "explanation": "这里应该用〈躺〉。“做梦”不能用“把”带“床”作宾语，应说“孩子躺在床上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上班", "is_correct": false, "explanation": "语义：上班是醒着时的工作，睡觉时不能上班。"}, {"text": "做梦", "is_correct": true, "explanation": "正确：睡觉时脑中出现人和事，与“他睡觉时”相合。"}, {"text": "观察", "is_correct": false, "explanation": "语义：观察是醒着时有意的注意活动，睡觉时不会观察，“睡觉时观察”句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试要醒着作答，与“睡觉时”冲突。"}], "explanations": {"上班": "语义：上班是醒着时的工作，睡觉时不能上班。", "做梦": "正确：睡觉时脑中出现人和事，与“他睡觉时”相合。", "观察": "语义：观察是醒着时有意的注意活动，睡觉时不会观察，“睡觉时观察”句意不通。", "考试": "语义：考试要醒着作答，与“睡觉时”冲突。"}, "sentence_index": 6, "correct_answer": "做梦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把做梦存进了银行，每个月都有利息。", "explanation": "这里应该用〈存款〉。做梦不是钱，不能存进银行；存进银行的应是“存款”。"}, {"text": "这辆自行车做梦很快。", "explanation": "这里应该用〈速度〉。做梦指睡时的情景，形容自行车的快慢要说“速度快”。"}, {"text": "老师在黑板上做梦了一个字。", "explanation": "这里应该用〈写〉。做梦是睡着时的事情，不能带“一个字”作宾语；在黑板上要说“写了一个字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹昨晚做梦着，早上一直说个不停。", "corrected_sentence": "妹妹昨晚做梦了，早上一直说个不停。", "error_description": "错误：「做梦着」中「着」用错，表示已经做完的梦应用「了」，正确为「做梦了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨晚做梦过，梦见了老家。", "corrected_sentence": "他昨晚做梦了，梦见了老家。", "error_description": "错误：「做梦过」中「过」不能这样接在「做梦」后，表示已完成的梦应说「做梦了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
