INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86915, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "当上是成为了某个身份。", "primary_collocate": null, "pronunciation": "dāng shàng", "ipa": "tɑŋ˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他长大后当上了老师。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当上了妈妈，特别高兴。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王当上了爸爸。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当上了冠军，大家都为他鼓掌。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟当上了警察。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小想当上演员，现在做到了。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说他当上了爷爷，笑得很开心。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他终于当上了外公，全家都很高兴。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就盼望着将来能当上父亲。", "target_word": "当上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当上了新娘，穿着白色的长裙。", "target_word": "当上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当上了", "label": "体标"}, {"form": "当上过", "label": "体标"}, {"form": "當上", "label": "繁体"}], "register": "口语", "sense_fingerprint": "当上：成为某种身份的人（妈妈、冠军、警察等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86915, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：当上（dāng shàng），意思是成为某种身份的人。"}, {"text": "搭上", "is_correct": false, "explanation": "搭上（dā shàng）与 dāng shàng 韵母不同（a 与 ang），意思是搭乘，如搭上车。"}, {"text": "刚上", "is_correct": false, "explanation": "刚上（gāng shàng）与 dāng shàng 声母不同（g 与 d），意思是刚开始去，如刚上小学。"}, {"text": "帮上", "is_correct": false, "explanation": "帮上（bāng shàng）与 dāng shàng 声母不同（b 与 d），意思是对别人起到帮助作用。"}, {"text": "蹬上", "is_correct": false, "explanation": "蹬上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是用脚踩着往上登。"}], "explanations": {"当上": "正确答案：当上（dāng shàng），意思是成为某种身份的人。", "搭上": "搭上（dā shàng）与 dāng shàng 韵母不同（a 与 ang），意思是搭乘，如搭上车。", "刚上": "刚上（gāng shàng）与 dāng shàng 声母不同（g 与 d），意思是刚开始去，如刚上小学。", "帮上": "帮上（bāng shàng）与 dāng shàng 声母不同（b 与 d），意思是对别人起到帮助作用。", "蹬上": "蹬上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是用脚踩着往上登。"}, "sentence_index": null, "correct_answer": "当上"}, "level_3": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：「当上」表示成为某种身份，与「长大后」和「老师」相合。"}, {"text": "嫁", "is_correct": false, "explanation": "搭配：「嫁」多指女子出嫁，句中主语是「他」，不能说「嫁了老师」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」是吞咽食物，句中要表达的是身份，不能吃老师。"}, {"text": "生", "is_correct": false, "explanation": "配价：「生」要求「孩子」一类的宾语，「老师」不能被生。"}], "explanations": {"当上": "正确答案：「当上」表示成为某种身份，与「长大后」和「老师」相合。", "嫁": "搭配：「嫁」多指女子出嫁，句中主语是「他」，不能说「嫁了老师」。", "吃": "语义：「吃」是吞咽食物，句中要表达的是身份，不能吃老师。", "生": "配价：「生」要求「孩子」一类的宾语，「老师」不能被生。"}, "sentence_index": 0, "correct_answer": "当上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰化了以后当上了水。", "explanation": "这里应该用〈变成〉。当上表示人担任职务或成为身份，冰变成水是物质的变化，不能说「当上」。"}, {"text": "她当上了一个奖杯。", "explanation": "这里应该用〈得到〉。奖杯是物品，不是职务或身份，当上只用于人获得职务或身份。"}, {"text": "熬夜当上了他的习惯。", "explanation": "这里应该用〈成为〉。当上指人担任职务或获得身份，抽象的习惯不能「当上」，应说「成为他的习惯」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86915, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：当上（dāng shàng），意思是成为某种身份的人。"}, {"text": "盯上", "is_correct": false, "explanation": "盯上（dīng shàng）与 dāng shàng 主要元音不同（i 与 a），意思是把目光锁定在某人或某物上。"}, {"text": "登上", "is_correct": false, "explanation": "登上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是爬到高处。"}, {"text": "担上", "is_correct": false, "explanation": "担上（dān shàng）与 dāng shàng 韵尾不同（an 与 ang），意思是用肩膀挑起。"}, {"text": "挡上", "is_correct": false, "explanation": "挡上（dǎng shàng）与 dāng shàng 声调不同（第三声与第一声），意思是遮挡、拦住。"}], "explanations": {"当上": "正确答案：当上（dāng shàng），意思是成为某种身份的人。", "盯上": "盯上（dīng shàng）与 dāng shàng 主要元音不同（i 与 a），意思是把目光锁定在某人或某物上。", "登上": "登上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是爬到高处。", "担上": "担上（dān shàng）与 dāng shàng 韵尾不同（an 与 ang），意思是用肩膀挑起。", "挡上": "挡上（dǎng shàng）与 dāng shàng 声调不同（第三声与第一声），意思是遮挡、拦住。"}, "sentence_index": null, "correct_answer": "当上"}, "level_3": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：「当上」表示成为某种身份，与「爷爷」相合。"}, {"text": "失去", "is_correct": false, "explanation": "语义：「失去爷爷」与后面的「笑得很开心」情绪相冲，句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」要求衣物作宾语，不能用来搭配「爷爷」。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」表示丢弃，「扔了爷爷」与句子表达的喜悦不合。"}], "explanations": {"当上": "正确答案：「当上」表示成为某种身份，与「爷爷」相合。", "失去": "语义：「失去爷爷」与后面的「笑得很开心」情绪相冲，句意不通。", "穿": "搭配：「穿」要求衣物作宾语，不能用来搭配「爷爷」。", "扔": "语义：「扔」表示丢弃，「扔了爷爷」与句子表达的喜悦不合。"}, "sentence_index": 6, "correct_answer": "当上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张纸当上了书签。", "explanation": "这里应该用〈充当〉。当上指人担任职务或获得身份，纸张不能「当上」书签，器物做某种用途要用〈充当〉。"}, {"text": "她当上了婚礼。", "explanation": "这里应该用〈参加〉。当上表示担任职务，婚礼是活动，不能「当上」，应说「参加婚礼」。"}, {"text": "她当上了一顶帽子。", "explanation": "这里应该用〈戴〉。当上用于人的身份或职务，帽子是衣物，应说「戴上一顶帽子」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学毕业后当上过了医生。", "corrected_sentence": "他大学毕业后当上了医生。", "error_description": "错误：「当上过了」不对。说毕业后成为了医生，是一次完成的变化，只用「了」：「大学毕业后当上了医生」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表哥今年当上是飞行员。", "corrected_sentence": "我表哥今年当上了飞行员。", "error_description": "错误：「当上」后的「了」误写成「是」。「当上」表示成为某种身份，「了」表示动作完成，应说「当上了飞行员」，不能用「是」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
