INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担任；成为。", "primary_collocate": null, "pronunciation": "dāng shàng", "ipa": "tɑŋ˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他当上了我们班的班长。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她三十岁就当上了经理。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师当上了学校的校长。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李当上了公司的部门主任。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他努力工作，终于当上了队长。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当上了小组组长，大家都很高兴。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想当上医院里的科室主任。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥去年当上了市长的秘书。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当上主任以后，工作更忙了。", "target_word": "当上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想当上队长吗？", "target_word": "当上", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "当上了", "label": "体标"}, {"form": "当上过", "label": "体标"}, {"form": "當上", "label": "繁体"}], "register": "口语", "sense_fingerprint": "当上：担任某个职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：当上（dāng shàng），意思是担任某个职务。"}, {"text": "搭上", "is_correct": false, "explanation": "搭上（dā shàng）与 dāng shàng 韵母不同（a 与 ang），意思是搭乘，如搭上车。"}, {"text": "登上", "is_correct": false, "explanation": "登上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是爬到高处。"}, {"text": "刚上", "is_correct": false, "explanation": "刚上（gāng shàng）与 dāng shàng 声母不同（g 与 d），意思是刚开始去，如刚上大学。"}, {"text": "帮上", "is_correct": false, "explanation": "帮上（bāng shàng）与 dāng shàng 声母不同（b 与 d），意思是对别人起到帮助作用。"}], "explanations": {"当上": "正确答案：当上（dāng shàng），意思是担任某个职务。", "搭上": "搭上（dā shàng）与 dāng shàng 韵母不同（a 与 ang），意思是搭乘，如搭上车。", "登上": "登上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是爬到高处。", "刚上": "刚上（gāng shàng）与 dāng shàng 声母不同（g 与 d），意思是刚开始去，如刚上大学。", "帮上": "帮上（bāng shàng）与 dāng shàng 声母不同（b 与 d），意思是对别人起到帮助作用。"}, "sentence_index": null, "correct_answer": "当上"}, "level_3": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：「当上」表示担任职务，与「班长」相合。"}, {"text": "关", "is_correct": false, "explanation": "语义：「关」是关闭，与「班长」这种职务的意思不合。"}, {"text": "吃", "is_correct": false, "explanation": "配价：「吃」要求食物作宾语，「班长」不能被吃。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」多与食物搭配，不能用来煮班长。"}], "explanations": {"当上": "正确答案：「当上」表示担任职务，与「班长」相合。", "关": "语义：「关」是关闭，与「班长」这种职务的意思不合。", "吃": "配价：「吃」要求食物作宾语，「班长」不能被吃。", "煮": "搭配：「煮」多与食物搭配，不能用来煮班长。"}, "sentence_index": 0, "correct_answer": "当上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一觉醒来，他当上了一只猫。", "explanation": "这里应该用〈变成〉。当上指担任职务或取得某种身份，外形的改变要用〈变成〉，猫不是可以「当上」的身份。"}, {"text": "这件事当上了大家的话题。", "explanation": "这里应该用〈成为〉。当上的对象是人的职务或身份，「话题」不是身份，应说「成为大家的话题」。"}, {"text": "这块木板当上了桌子。", "explanation": "这里应该用〈充当〉。当上要求有身份的人，木板不能「当上」桌子；器物承担某种用途要用〈充当〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：当上（dāng shàng），意思是担任某个职务。"}, {"text": "盯上", "is_correct": false, "explanation": "盯上（dīng shàng）与 dāng shàng 主要元音不同（i 与 a），意思是把目光锁定在某人或某物上。"}, {"text": "蹬上", "is_correct": false, "explanation": "蹬上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是用脚踩着往上登。"}, {"text": "担上", "is_correct": false, "explanation": "担上（dān shàng）与 dāng shàng 韵尾不同（an 与 ang），意思是用肩膀挑起。"}, {"text": "挡上", "is_correct": false, "explanation": "挡上（dǎng shàng）与 dāng shàng 声调不同（第三声与第一声），意思是遮挡、拦住。"}], "explanations": {"当上": "正确答案：当上（dāng shàng），意思是担任某个职务。", "盯上": "盯上（dīng shàng）与 dāng shàng 主要元音不同（i 与 a），意思是把目光锁定在某人或某物上。", "蹬上": "蹬上（dēng shàng）与 dāng shàng 主要元音不同（e 与 a），意思是用脚踩着往上登。", "担上": "担上（dān shàng）与 dāng shàng 韵尾不同（an 与 ang），意思是用肩膀挑起。", "挡上": "挡上（dǎng shàng）与 dāng shàng 声调不同（第三声与第一声），意思是遮挡、拦住。"}, "sentence_index": null, "correct_answer": "当上"}, "level_3": {"options": [{"text": "当上", "is_correct": true, "explanation": "正确答案：「当上」表示担任职务，与「想」和「主任」相合。"}, {"text": "修", "is_correct": false, "explanation": "语义：「修」的对象是器物或房屋，不能用于人担任的职务。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：「烧」多与柴火、食物等搭配，不能用于职务。"}, {"text": "拆", "is_correct": false, "explanation": "配价：「拆」要求可拆解的物件作宾语，「主任」不能被拆。"}], "explanations": {"当上": "正确答案：「当上」表示担任职务，与「想」和「主任」相合。", "修": "语义：「修」的对象是器物或房屋，不能用于人担任的职务。", "烧": "搭配：「烧」多与柴火、食物等搭配，不能用于职务。", "拆": "配价：「拆」要求可拆解的物件作宾语，「主任」不能被拆。"}, "sentence_index": 6, "correct_answer": "当上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他当上了那场比赛。", "explanation": "这里应该用〈参加〉。当上是担任职务，比赛是活动，不能「当上」；应说「参加那场比赛」。"}, {"text": "他当上了所有的责任。", "explanation": "这里应该用〈承担〉。当上接的是职务或身份，责任不能被「当上」，应说「承担所有的责任」。"}, {"text": "她当上了一件礼物。", "explanation": "这里应该用〈得到〉。当上表示担任或成为某种身份，礼物不是身份，应说「得到一件礼物」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他要当上了班长，大家都很高兴。", "corrected_sentence": "他当上了班长，大家都很高兴。", "error_description": "错误：「要」与「了」同用。「要」表示将来，「了」表示已经完成，二者不能同用；应说「他当上了班长」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她了当上了医院的护士长。", "corrected_sentence": "她当上了医院的护士长。", "error_description": "错误：「了」的位置。「了」不能放在「当上」之前，应放在「当上」之后，应说「当上了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86918, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
