INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人在社会中所从事的、作为主要生活来源的工作。", "primary_collocate": null, "pronunciation": "zhí yè", "ipa": "ʈʂɨ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "你父亲的职业是什么？", "target_word": "职业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的职业是医生，每天都很忙。", "target_word": "职业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "填表的时候，要写姓名和职业。", "target_word": "职业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师是一个很受人尊敬的职业。", "target_word": "职业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她选择了护士这个职业。", "target_word": "职业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个职业需要很多耐心。", "target_word": "职业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了职业，现在做销售。", "target_word": "职业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同职业的人，生活习惯也不一样。", "target_word": "职业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从小就想选一个自己喜欢的职业。", "target_word": "职业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个职业的收入不高，但是很稳定。", "target_word": "职业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "職業", "label": "繁体"}, {"form": "职业病", "label": "复合"}, {"form": "职业道德", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人谋生所从事的固定工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86918, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职业", "is_correct": true, "explanation": "正确答案：职业（zhí yè），意思是个人谋生所从事的固定工作。"}, {"text": "实业", "is_correct": false, "explanation": "实业（shí yè）与 zhí yè 声母不同（sh 与 zh），意思是工商、制造等实体行业。"}, {"text": "纸业", "is_correct": false, "explanation": "纸业（zhǐ yè）与 zhí yè 声调不同（第三声与第二声），意思是造纸行业。"}, {"text": "执意", "is_correct": false, "explanation": "执意（zhí yì）与 zhí yè 韵母不同（i 与 e），意思是坚持己见。"}], "explanations": {"职业": "正确答案：职业（zhí yè），意思是个人谋生所从事的固定工作。", "实业": "实业（shí yè）与 zhí yè 声母不同（sh 与 zh），意思是工商、制造等实体行业。", "纸业": "纸业（zhǐ yè）与 zhí yè 声调不同（第三声与第二声），意思是造纸行业。", "执意": "执意（zhí yì）与 zhí yè 韵母不同（i 与 e），意思是坚持己见。"}, "sentence_index": null, "correct_answer": "职业"}, "level_3": {"options": [{"text": "职业", "is_correct": true, "explanation": "正确答案：「职业」指个人的谋生工作，问父亲的工作是合适的。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「价格」多用于商品，不能用来问人的工作。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」指天象，与人的身份或工作无关。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」是动作，不能作「你父亲的」的中心语，「你父亲的吃」不成词。"}], "explanations": {"职业": "正确答案：「职业」指个人的谋生工作，问父亲的工作是合适的。", "价格": "搭配：「价格」多用于商品，不能用来问人的工作。", "天气": "语义：「天气」指天象，与人的身份或工作无关。", "吃": "搭配：「吃」是动作，不能作「你父亲的」的中心语，「你父亲的吃」不成词。"}, "sentence_index": 0, "correct_answer": "职业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年升了职业，现在是部门经理。", "explanation": "这里应该用〈职位〉。职业指个人从事的工作类别，职务的晋升要用〈职位〉，应说「升了职位」。"}, {"text": "我大学的职业是历史。", "explanation": "这里应该用〈专业〉。职业指毕业后谋生的工作，学校里学的科目要用〈专业〉。"}, {"text": "他一辈子都在为慈善职业而奋斗。", "explanation": "这里应该用〈事业〉。职业指作为主要生活来源的工作，为公益这样的远大目标奋斗要用〈事业〉，应说「为慈善事业而奋斗」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86918, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "职业", "is_correct": true, "explanation": "正确答案：职业（zhí yè），意思是个人谋生所从事的固定工作。"}, {"text": "置业", "is_correct": false, "explanation": "置业（zhì yè）与 zhí yè 声调不同（第四声与第二声），意思是购置房产。"}, {"text": "纸业", "is_correct": false, "explanation": "纸业（zhǐ yè）与 zhí yè 声调不同（第三声与第二声），意思是造纸行业。"}, {"text": "直译", "is_correct": false, "explanation": "直译（zhí yì）与 zhí yè 韵母不同（i 与 e），意思是按字面意思翻译。"}], "explanations": {"职业": "正确答案：职业（zhí yè），意思是个人谋生所从事的固定工作。", "置业": "置业（zhì yè）与 zhí yè 声调不同（第四声与第二声），意思是购置房产。", "纸业": "纸业（zhǐ yè）与 zhí yè 声调不同（第三声与第二声），意思是造纸行业。", "直译": "直译（zhí yì）与 zhí yè 韵母不同（i 与 e），意思是按字面意思翻译。"}, "sentence_index": null, "correct_answer": "职业"}, "level_3": {"options": [{"text": "职业", "is_correct": true, "explanation": "正确答案：「职业」与「换了」和「做销售」相合，表示换了工作。"}, {"text": "星座", "is_correct": false, "explanation": "语义：「星座」不能被更换，与句中的换工作不合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「换」用于工作、地点等，不能用于年龄。"}, {"text": "血型", "is_correct": false, "explanation": "语义：「血型」是天生的特征，无法更换，与句意不合。"}], "explanations": {"职业": "正确答案：「职业」与「换了」和「做销售」相合，表示换了工作。", "星座": "语义：「星座」不能被更换，与句中的换工作不合。", "年龄": "搭配：「换」用于工作、地点等，不能用于年龄。", "血型": "语义：「血型」是天生的特征，无法更换，与句意不合。"}, "sentence_index": 6, "correct_answer": "职业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他利用周末做职业，赚点零花钱。", "explanation": "这里应该用〈兼职〉。职业指长期固定的谋生工作，周末的临时工作要用〈兼职〉。"}, {"text": "他的职业是硕士，英语很好。", "explanation": "这里应该用〈学历〉。职业指谋生的工作，所受教育的程度要用〈学历〉，应说「他的学历是硕士」。"}, {"text": "他按时完成了职业。", "explanation": "这里应该用〈任务〉。职业是长期从事的工作，不能「完成」，一项具体工作要用〈任务〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她选择了一只好职业。", "corrected_sentence": "她选择了一个好职业。", "error_description": "错误：量词「只」。「职业」应搭配「个」或「份」，「只」多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的职业病是程序员。", "corrected_sentence": "他的职业是程序员。", "error_description": "错误：「职业病」。「职业病」指因工作环境引起的疾病，与「职业」（工作）意思不同；这里应说「他的职业是程序员」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
