INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "西是太阳落下去的那一边。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "太阳从东边出来，要往西落下去。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你面向北，右手是东，左手是西。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东、西、南、北，你分得清吗？", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园的大门朝西，早上不太亮。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑车往西去了，我往东走。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这列火车从东往西开。", "target_word": "西", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "向东走是学校，向西走是医院。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风从东吹到西，树叶都动了。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一直往西，你会看到一座大桥。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上我看着太阳向西慢慢落下。", "target_word": "西", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "西边", "label": "复合词"}, {"form": "西方", "label": "复合词"}, {"form": "西部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "太阳落下去的那一边，用来指路辨方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：表示太阳落下的方向，与“从东边出来”相对。"}, {"text": "东", "is_correct": false, "explanation": "语义：「往东落下去」与“从东边出来”冲突，太阳不会向东落下。"}, {"text": "西餐", "is_correct": false, "explanation": "搭配：「西餐」是食物，不能表示太阳落下的方向。"}, {"text": "西服", "is_correct": false, "explanation": "搭配：「西服」是衣服，不能表示太阳落下的方向。"}], "explanations": {"西": "正确：表示太阳落下的方向，与“从东边出来”相对。", "东": "语义：「往东落下去」与“从东边出来”冲突，太阳不会向东落下。", "西餐": "搭配：「西餐」是食物，不能表示太阳落下的方向。", "西服": "搭配：「西服」是衣服，不能表示太阳落下的方向。"}, "sentence_index": 0, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家书店的装修很西，我常去。", "explanation": "这里应该用〈西式〉。〈西〉不能直接修饰装修表示西式风格，要说〈西式〉。"}, {"text": "这家饭店很西，我最爱吃。", "explanation": "这里应该用〈西式〉。〈西〉作形容词修饰饭店不规范，表示西式风格要说〈西式〉。"}, {"text": "我晚饭想吃西。", "explanation": "这里应该用〈西餐〉。〈西〉是方向词，不能单独指西餐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：与“向东走”形成对照，表示另一个方向。"}, {"text": "东西", "is_correct": false, "explanation": "搭配：「东西」在此指“物品”或不具体的方向，「向东西走」不能指一个具体方向，句子不成立。"}, {"text": "西服", "is_correct": false, "explanation": "搭配：「西服」是衣服，不能表示方向。"}, {"text": "西洋", "is_correct": false, "explanation": "语义：「西洋」指西方的国家或地区，句中需要的是具体方向。"}], "explanations": {"西": "正确：与“向东走”形成对照，表示另一个方向。", "东西": "搭配：「东西」在此指“物品”或不具体的方向，「向东西走」不能指一个具体方向，句子不成立。", "西服": "搭配：「西服」是衣服，不能表示方向。", "西洋": "语义：「西洋」指西方的国家或地区，句中需要的是具体方向。"}, "sentence_index": 6, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一套西，很便宜。", "explanation": "这里应该用〈西服〉。〈西〉单独作名词指衣服不规范，要说〈西服〉。"}, {"text": "她穿的衣服很西，大家都喜欢。", "explanation": "这里应该用〈西式〉。〈西〉作形容词修饰衣服不规范，描述风格要说〈西式〉。"}, {"text": "这条路很西，我们每天走。", "explanation": "这里应该用〈西式〉。〈西〉作形容词不能直接修饰路，描述西式街道要说〈西式〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上太阳西往落下去，天就黑了。", "corrected_sentence": "晚上太阳往西落下去，天就黑了。", "error_description": "错误形式：「西往」，语序颠倒。正确形式：「往西」。介词「往」要放在方向词「西」前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沿着这条路一直在西走，就到了火车站。", "corrected_sentence": "沿着这条路一直往西走，就到了火车站。", "error_description": "错误形式：「在西走」，用了「在」。正确形式：「往西走」。「在」表示位置，不能引出动作的方向；表示方向要用「往」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
