INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "方向名，太阳落下的一边，与“东”相对。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "从这里往西走，就能看到地铁站。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳每天从东边升起，向西落下。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河由东向西流，穿过整个城市。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间屋子的窗户朝西，下午很热。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路从东到西，一共有五公里。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车到路口以后，请向西拐。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的房子坐西朝东。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机往西飞了五个小时。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上，上北下南，左西右东。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟儿向西飞去，天慢慢黑了。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "西边", "label": "复合词"}, {"form": "西方", "label": "复合词"}, {"form": "西部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "方向名，与东相对，太阳落下的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 东边 (Zipf 3.76), 升起 (Zipf 3.91), 落下 (Zipf 3.98)']::text[], '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：表示方向，与“往……走”搭配。"}, {"text": "西服", "is_correct": false, "explanation": "搭配：「西服」是衣服，不能与“往……走”搭配表示方向。"}, {"text": "东西", "is_correct": false, "explanation": "搭配：「东西」指“物品”，「往东西走」不能指一个具体方向。"}, {"text": "西餐", "is_correct": false, "explanation": "搭配：「西餐」是食物，不能与“往……走”搭配。"}], "explanations": {"西": "正确：表示方向，与“往……走”搭配。", "西服": "搭配：「西服」是衣服，不能与“往……走”搭配表示方向。", "东西": "搭配：「东西」指“物品”，「往东西走」不能指一个具体方向。", "西餐": "搭配：「西餐」是食物，不能与“往……走”搭配。"}, "sentence_index": 0, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很喜欢西的音乐，经常听。", "explanation": "这里应该用〈西方〉或〈西洋〉。〈西〉不能直接修饰音乐表示“西方的”，要说〈西方音乐〉。"}, {"text": "这个饭店的菜很西，我很喜欢。", "explanation": "这里应该用〈西式〉。〈西〉作形容词表示“西式”不规范，描述菜式要说〈西式〉。"}, {"text": "我们今天吃西吧。", "explanation": "这里应该用〈西餐〉。〈西〉不能单独指西餐，要说〈西餐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：「坐西朝东」是固定的方位说法，「西」表示房屋背靠的方向。"}, {"text": "东", "is_correct": false, "explanation": "语义：「坐东朝东」两个方向重复，与句中的「朝东」冲突。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：「西瓜」是水果，不能用来表示房屋的朝向。"}, {"text": "西药", "is_correct": false, "explanation": "搭配：「西药」是药品，不能与“坐……”搭配表示朝向。"}], "explanations": {"西": "正确：「坐西朝东」是固定的方位说法，「西」表示房屋背靠的方向。", "东": "语义：「坐东朝东」两个方向重复，与句中的「朝东」冲突。", "西瓜": "搭配：「西瓜」是水果，不能用来表示房屋的朝向。", "西药": "搭配：「西药」是药品，不能与“坐……”搭配表示朝向。"}, "sentence_index": 6, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家的装修很西，门口有一棵大树。", "explanation": "这里应该用〈西式〉。〈西〉表示“西式”时不能直接修饰装修，要说〈西式〉。"}, {"text": "这本书的封面很西，我很喜欢。", "explanation": "这里应该用〈西式〉。〈西〉作形容词表示“西式”不规范，描述封面要说〈西式〉。"}, {"text": "这家饭店的西很好吃。", "explanation": "这里应该用〈西餐〉。〈西〉不能单独作名词指西餐，要说〈西餐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子一直西开，过了河就是老城区。", "corrected_sentence": "车子一直往西开，过了河就是老城区。", "error_description": "错误形式：「西开」，漏掉了介词「往」。正确形式：「往西开」。表示沿着某个方向行驶，要用「往」引出方向。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们往西的走，就到了湖边。", "corrected_sentence": "我们往西走，就到了湖边。", "error_description": "错误形式：「往西的走」，在「西」和「走」之间多加了「的」。正确形式：「往西走」。「往西」是状语，后面直接接动词，不能加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86925, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外在", "is_correct": true, "explanation": "外在与内在构成反义，指外部、看得见的一面，与句中的外表相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外貌好看，与内在没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与内在没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂的反义词是简单，与内在没有反义关系。"}], "correct_answer": "外在", "explanations": {"外在": "外在与内在构成反义，指外部、看得见的一面，与句中的外表相对。", "漂亮": "漂亮形容外貌好看，与内在没有反义关系。", "清楚": "清楚指明白、不模糊，与内在没有反义关系。", "复杂": "复杂的反义词是简单，与内在没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86925, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外在", "is_correct": true, "explanation": "外在与内在构成反义，指外部、看得见的一面，与句中的「外表」相对。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴表示心情愉快，与内在没有反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "灵活形容动作或思路敏捷，与内在没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情形容待人友好、情绪高，与内在没有反义关系。"}], "correct_answer": "外在", "explanations": {"外在": "外在与内在构成反义，指外部、看得见的一面，与句中的「外表」相对。", "高兴": "高兴表示心情愉快，与内在没有反义关系。", "灵活": "灵活形容动作或思路敏捷，与内在没有反义关系。", "热情": "热情形容待人友好、情绪高，与内在没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86925, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "内在是在里面的，不是在外面看得见的。", "primary_collocate": null, "pronunciation": "nèi zài", "ipa": "nei̯˥˩ t͡sai̯˥˩", "syllable_count": 2, "sentences": [{"text": "她外表普通，但内在美让人难忘。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，内在的美比外表更重要。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一种内在的安静，让人很放心。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的衣服只能改变外表，不能改变内在气质。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的内在力量很强，从不怕困难。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内在的自信，比漂亮的衣服更重要。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子外表安静，内在的想象力却很丰富。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，让自己的内在气质更好。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说我的内在气质比外表更吸引人。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外表很冷，内在的善良却让人感动。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "内在美", "label": "复合词"}, {"form": "内在气质", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "内在：在里面、看不见的（人的品质、气质等），与外表相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86925, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内在", "is_correct": true, "explanation": "内在美指人内在的品质之美，与前半句「外表普通」形成对比，是正确选项。"}, {"text": "外向", "is_correct": false, "explanation": "搭配：「外向」形容性格开朗、爱交际，不能修饰「美」。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」描写身材，与前半句的外表描写重复，且不指内在品质，说不通。"}, {"text": "狭隘", "is_correct": false, "explanation": "语义：「狭隘」指心胸、见识窄，与「美」的意思不相容。"}], "explanations": {"内在": "内在美指人内在的品质之美，与前半句「外表普通」形成对比，是正确选项。", "外向": "搭配：「外向」形容性格开朗、爱交际，不能修饰「美」。", "高大": "体貌：「高大」描写身材，与前半句的外表描写重复，且不指内在品质，说不通。", "狭隘": "语义：「狭隘」指心胸、见识窄，与「美」的意思不相容。"}, "sentence_index": 0, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的内在很干净，地板也很亮。", "explanation": "这里应该用〈内部〉。内在指人的品质或事物本身的特性，不用来说房屋等有形空间的里面。"}, {"text": "他说话内在很慢，大家都在等他。", "explanation": "这里应该用〈慢〉。内在表示人的品质或事物固有的特点，不能用来形容说话的快慢，应直接说「说话很慢」。"}, {"text": "这首诗的内在很长，我读了好几遍。", "explanation": "这里应该用〈篇幅〉。篇幅指作品的长短，说诗有多长要用篇幅；内在指人或事物里面看不见的特点，不用来说长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内在", "is_correct": true, "explanation": "内在的想象力指藏在心里、外面看不见的想象力，与前半句「外表安静」形成对比，是正确选项。"}, {"text": "细长", "is_correct": false, "explanation": "体貌：「细长」描写形状，不能修饰「想象力」。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：「粗糙」形容质地不光滑，不能修饰「想象力」。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：「干燥」形容缺少水分，不能修饰「想象力」。"}], "explanations": {"内在": "内在的想象力指藏在心里、外面看不见的想象力，与前半句「外表安静」形成对比，是正确选项。", "细长": "体貌：「细长」描写形状，不能修饰「想象力」。", "粗糙": "搭配：「粗糙」形容质地不光滑，不能修饰「想象力」。", "干燥": "搭配：「干燥」形容缺少水分，不能修饰「想象力」。"}, "sentence_index": 6, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到噩耗，她的内在一直很难过。", "explanation": "这里应该用〈内心〉。内在指人的品质或事物固有的特点，说心里的感受和情绪要用内心。"}, {"text": "他有内在的好嗓子，唱歌很好听。", "explanation": "这里应该用〈天生〉。内在用于人的品质或事物的本质，不用来说先天的身体条件，如嗓子好。"}, {"text": "这个箱子的内在放满了旧衣服。", "explanation": "这里应该用〈里面〉。内在指人的品质或气质等看不见的方面，不指箱子等物体里面的空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老爷爷的很内在美很动人。", "corrected_sentence": "这位老爷爷的内在美很动人。", "error_description": "错误在于「很内在美」。「内在」作定语修饰「美」时，前面不能加程度副词「很」，应说「内在美」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的很内在气质很特别，大家都注意到了。", "corrected_sentence": "她的内在气质很特别，大家都注意到了。", "error_description": "错误在于「很内在气质」。「内在」修饰「气质」时，前面不能加程度副词「很」，应说「她的内在气质」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86926, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外在", "is_correct": true, "explanation": "外在与内在构成反义，指事物外部、非本质的方面，与句中的内在规律相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外貌好看，与内在没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与内在没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "善良形容品行好，与内在没有反义关系。"}], "correct_answer": "外在", "explanations": {"外在": "外在与内在构成反义，指事物外部、非本质的方面，与句中的内在规律相对。", "漂亮": "漂亮形容外貌好看，与内在没有反义关系。", "清楚": "清楚指明白、不模糊，与内在没有反义关系。", "善良": "善良形容品行好，与内在没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86926, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外在", "is_correct": true, "explanation": "外在与内在构成反义，指事物外部、非本质的方面，与句中的「内在的联系」相对。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴表示心情愉快，与内在没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂的反义词是简单，与内在没有反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "灵活形容动作或思路敏捷，与内在没有反义关系。"}], "correct_answer": "外在", "explanations": {"外在": "外在与内在构成反义，指事物外部、非本质的方面，与句中的「内在的联系」相对。", "高兴": "高兴表示心情愉快，与内在没有反义关系。", "复杂": "复杂的反义词是简单，与内在没有反义关系。", "灵活": "灵活形容动作或思路敏捷，与内在没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86926, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事物本身所固有的、存在于内部的。", "primary_collocate": null, "pronunciation": "nèi zài", "ipa": "nei̯˥˩ t͡sai̯˥˩", "syllable_count": 2, "sentences": [{"text": "这两件事之间有内在的联系。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习要有内在的动力，不能只靠父母。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的内在价值很高。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们找出这个故事的内在规律。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题的内在原因比外在原因更难发现。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法有内在的问题，用不久。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展有它自己的内在规律。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子爱读书的内在原因是好奇。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的内在矛盾越来越多。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字背后有一种内在的联系。", "target_word": "内在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "内在联系", "label": "复合词"}, {"form": "内在规律", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "内在：事物本身固有的、内部的（联系、规律、原因、动力等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内在", "is_correct": true, "explanation": "内在的联系指事物本身固有的联系，与「两件事之间」相配，是正确选项。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：「漂亮」形容外貌好看，不能修饰「联系」。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：「高大」描写身材或体积，不能修饰「联系」。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：「年轻」指年龄不大，与「联系」的意思不相容。"}], "explanations": {"内在": "内在的联系指事物本身固有的联系，与「两件事之间」相配，是正确选项。", "漂亮": "体貌：「漂亮」形容外貌好看，不能修饰「联系」。", "高大": "搭配：「高大」描写身材或体积，不能修饰「联系」。", "年轻": "语义：「年轻」指年龄不大，与「联系」的意思不相容。"}, "sentence_index": 0, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书包的内在放着两本书和一支笔。", "explanation": "这里应该用〈内部〉。内在表示事物本身固有的、看不见的特点，不用来指物体里面的位置。"}, {"text": "他想起小时候的事，内在很难过。", "explanation": "这里应该用〈内心〉。内在指事物本身固有的特点，不用来说心里的感受；表达心里难过要用内心。"}, {"text": "问题的内在现象很明显，大家都看得出来。", "explanation": "这里应该用〈表面〉。内在指事物固有的、本质的方面，说明显可见的现象要用表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内在", "is_correct": true, "explanation": "内在规律指事物本身固有的规律，与「经济发展有它自己的」相配，是正确选项。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：「温柔」形容性情或态度，不能修饰「规律」。"}, {"text": "低矮", "is_correct": false, "explanation": "体貌：「低矮」描写高度，不能修饰「规律」。"}, {"text": "鲜红", "is_correct": false, "explanation": "语义：「鲜红」指颜色，与「规律」的意思不相容。"}], "explanations": {"内在": "内在规律指事物本身固有的规律，与「经济发展有它自己的」相配，是正确选项。", "温柔": "搭配：「温柔」形容性情或态度，不能修饰「规律」。", "低矮": "体貌：「低矮」描写高度，不能修饰「规律」。", "鲜红": "语义：「鲜红」指颜色，与「规律」的意思不相容。"}, "sentence_index": 6, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他性格内在，喜欢一个人待着。", "explanation": "这里应该用〈内向〉。内在用于事物固有的特点，不用来描述性格偏于安静、不爱与人交往。"}, {"text": "这件衣服的内在很漂亮，颜色也好看。", "explanation": "这里应该用〈外观〉。内在指事物本身固有、看不见的特点，说看得见的样子要用外观。"}, {"text": "冰箱的内在放着很多水果。", "explanation": "这里应该用〈里面〉。内在指事物本身固有的特点，不指物体里面的空间位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇小说的很内在规律很难发现。", "corrected_sentence": "这篇小说的内在规律很难发现。", "error_description": "错误在于「很内在规律」。「内在」修饰「规律」时，前面不能加程度副词「很」，应说「内在规律」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的很内在动力很强。", "corrected_sentence": "他的内在动力很强。", "error_description": "错误在于「很内在动力」。「内在」修饰「动力」时，前面不能加程度副词「很」，应说「内在动力」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
