INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86927, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "罪是做了坏事，要受到惩罚。", "primary_collocate": null, "pronunciation": "zuì", "ipa": "tswei˥˩", "syllable_count": 1, "sentences": [{"text": "他犯了罪，被警察带走了。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官说他有罪，要坐三年牢。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人没有罪，法官让他回家。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他知道自己有罪，一直不敢说话。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官问他：“你承认自己有罪吗？”", "target_word": "罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做了坏事的人，一定要为自己的罪负责。", "target_word": "罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说：“他的罪太大了，不能原谅。”", "target_word": "罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能证明他有罪。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他因为这个罪，在监狱里住了五年。", "target_word": "罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个罪很重，他要坐很长时间的牢。", "target_word": "罪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯罪", "label": "复合"}, {"form": "罪行", "label": "复合"}, {"form": "罪犯", "label": "复合"}], "register": "中性", "sense_fingerprint": "做坏事而应受惩罚的过错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86927, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪 zuì，意思是做了坏事、应受惩罚的过错。"}, {"text": "嘴", "is_correct": false, "explanation": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴。"}, {"text": "脆", "is_correct": false, "explanation": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是食物松脆。"}, {"text": "岁", "is_correct": false, "explanation": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是年龄。"}, {"text": "做", "is_correct": false, "explanation": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是做事。"}, {"text": "坠", "is_correct": false, "explanation": "zhuì 与 zuì 声母不同（zh 与 z），声调相同，意思是落下。"}], "explanations": {"罪": "罪 zuì，意思是做了坏事、应受惩罚的过错。", "嘴": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴。", "脆": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是食物松脆。", "岁": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是年龄。", "做": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是做事。", "坠": "zhuì 与 zuì 声母不同（zh 与 z），声调相同，意思是落下。"}, "sentence_index": null, "correct_answer": "罪"}, "level_3": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪：做了坏事、应受惩罚的过错，与“犯了”搭配，“被警察带走”说明是犯罪，句意通顺。"}, {"text": "钱", "is_correct": false, "explanation": "搭配：“犯”可以接罪行、错误这类词，不能说“犯钱”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不是违法或过错，与“被警察带走”的情境矛盾。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子不是行为，不能被“犯”，句子不通。"}], "explanations": {"罪": "罪：做了坏事、应受惩罚的过错，与“犯了”搭配，“被警察带走”说明是犯罪，句意通顺。", "钱": "搭配：“犯”可以接罪行、错误这类词，不能说“犯钱”。", "礼物": "语义：礼物不是违法或过错，与“被警察带走”的情境矛盾。", "盒子": "语义：盒子不是行为，不能被“犯”，句子不通。"}, "sentence_index": 0, "correct_answer": "罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在作业里犯了一个罪，把3写成了8。", "explanation": "这里应该用〈错误〉。罪指触犯法律或严重道德的行为，把数字写错只是失误，应说“犯了一个错误”。"}, {"text": "他忘了带钥匙，进不了门，这次是他的罪。", "explanation": "这里应该用〈过错〉。罪指触犯法律或严重恶行，忘带钥匙只是小过错，应说“这次是他的过错”。"}, {"text": "他上课迟到了五分钟，老师说这是他的罪。", "explanation": "这里应该用〈错〉。罪指触犯法律、应受惩罚的过错，迟到只是小错，应说“这是他的错”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86927, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪 zuì，意思是做了坏事、应受惩罚的过错。"}, {"text": "翠", "is_correct": false, "explanation": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是翠绿色。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是破碎。"}, {"text": "座", "is_correct": false, "explanation": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是座位。"}, {"text": "穗", "is_correct": false, "explanation": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是谷物的穗。"}], "explanations": {"罪": "罪 zuì，意思是做了坏事、应受惩罚的过错。", "翠": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是翠绿色。", "碎": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是破碎。", "座": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是座位。", "穗": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是谷物的穗。"}, "sentence_index": null, "correct_answer": "罪"}, "level_3": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪：做了坏事的过错，“原谅”“太大”都能搭配，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“原谅”针对过错，房子不是过错，不能被原谅。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“原谅”的对象应是过错，花园不能被原谅。"}, {"text": "精力", "is_correct": false, "explanation": "搭配：“太大”不修饰“精力”，精力一般说充沛或旺盛，不说太大。"}], "explanations": {"罪": "罪：做了坏事的过错，“原谅”“太大”都能搭配，符合句意。", "房子": "语义：“原谅”针对过错，房子不是过错，不能被原谅。", "花园": "语义：“原谅”的对象应是过错，花园不能被原谅。", "精力": "搭配：“太大”不修饰“精力”，精力一般说充沛或旺盛，不说太大。"}, "sentence_index": 6, "correct_answer": "罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忘了还朋友的钱，这是他的一个罪。", "explanation": "这里应该用〈过错〉。罪指触犯法律或严重道德的行为，忘记还钱只是一般过错，不能说成罪。"}, {"text": "他在考试里算错了一道题，他说这是自己的罪。", "explanation": "这里应该用〈失误〉。罪指触犯法律或严重恶行，算错一道题只是失误，应说“这是自己的失误”。"}, {"text": "下雨了，他忘了收衣服，这是他的罪。", "explanation": "这里应该用〈疏忽〉。罪指犯法、应受惩罚的过错，忘了收衣服只是疏忽，不能说成罪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院认定他罪有。", "corrected_sentence": "法院认定他有罪。", "error_description": "错误形式“罪有”，正确形式“有罪”。“有罪”是动宾结构，“有”在前、“罪”在后，表示被认定犯了罪；“罪有”不能单独成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坚持说自己没干罪，是无辜的。", "corrected_sentence": "他坚持说自己没犯罪，是无辜的。", "error_description": "错误形式“干罪”，正确形式“犯罪”。表示做了犯法的事，“罪”要和动词“犯”搭配，不说“干罪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
