INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "犯法或做坏事的行为。", "primary_collocate": null, "pronunciation": "zuì", "ipa": "tswei˥˩", "syllable_count": 1, "sentences": [{"text": "偷东西是一种罪。", "target_word": "罪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他犯了很重的罪。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杀人是最大的罪。", "target_word": "罪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个国家对这种罪的处罚很严。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一生没有犯过罪。", "target_word": "罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了犯下大罪的人。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子不懂什么是罪。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说谎不是法律上的罪，却是不好的行为。", "target_word": "罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为过去的罪感到后悔。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他犯的罪被写进了报纸。", "target_word": "罪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯罪", "label": "复合"}, {"form": "罪行", "label": "复合"}, {"form": "罪犯", "label": "复合"}], "register": "中性", "sense_fingerprint": "犯法或做坏事的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪 zuì，意思是触犯法律或做坏事的行为。"}, {"text": "坐", "is_correct": false, "explanation": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是坐下。"}, {"text": "穗", "is_correct": false, "explanation": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是谷物的穗。"}, {"text": "脆", "is_correct": false, "explanation": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是松脆。"}, {"text": "作", "is_correct": false, "explanation": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是写作或作品。"}, {"text": "翠", "is_correct": false, "explanation": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是翠绿色。"}], "explanations": {"罪": "罪 zuì，意思是触犯法律或做坏事的行为。", "坐": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是坐下。", "穗": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是谷物的穗。", "脆": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是松脆。", "作": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是写作或作品。", "翠": "cuì 与 zuì 声母不同（c 与 z），声调相同，意思是翠绿色。"}, "sentence_index": null, "correct_answer": "罪"}, "level_3": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪：触犯法律或做坏事的行为，“一种”后接这类词，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是行为，偷东西不能归为一种颜色。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来指偷东西这类行为。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是发声的器具，偷东西不是乐器。"}], "explanations": {"罪": "罪：触犯法律或做坏事的行为，“一种”后接这类词，句意通顺。", "颜色": "语义：颜色不是行为，偷东西不能归为一种颜色。", "身材": "体貌：身材指人的体形，不能用来指偷东西这类行为。", "乐器": "语义：乐器是发声的器具，偷东西不是乐器。"}, "sentence_index": 0, "correct_answer": "罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他忘记关灯，犯了一个小罪。", "explanation": "这里应该用〈过失〉。罪指触犯法律或严重恶行，忘记关灯只是疏忽，应说“犯了一个小过失”。"}, {"text": "他洗碗时不小心打碎了一个盘子，他觉得这是一桩罪。", "explanation": "这里应该用〈意外〉。罪指犯法或严重的恶行，打碎盘子是无意造成的意外，应说“这是一次意外”，不能称为罪。"}, {"text": "他把自己的书借给了同学，这是一种罪。", "explanation": "这里应该用〈好事〉。罪指犯法或做坏事的行为，借书给同学是帮助别人，应说“这是一件好事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86928, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪 zuì，意思是触犯法律或做坏事的行为。"}, {"text": "座", "is_correct": false, "explanation": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是座位。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是破碎。"}, {"text": "嘴", "is_correct": false, "explanation": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴。"}, {"text": "坠", "is_correct": false, "explanation": "zhuì 与 zuì 声母不同（zh 与 z），声调相同，意思是坠落。"}], "explanations": {"罪": "罪 zuì，意思是触犯法律或做坏事的行为。", "座": "zuò 与 zuì 韵母不同（o 与 i），声调相同，意思是座位。", "碎": "suì 与 zuì 声母不同（s 与 z），声调相同，意思是破碎。", "嘴": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴。", "坠": "zhuì 与 zuì 声母不同（zh 与 z），声调相同，意思是坠落。"}, "sentence_index": null, "correct_answer": "罪"}, "level_3": {"options": [{"text": "罪", "is_correct": true, "explanation": "罪：做了坏事的行为，“不懂什么是”后接这类抽象概念，句意通顺。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：孩子从小就认识眼睛，不会说“不懂什么是眼睛”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是孩子天天看到的东西，不能说“不懂”。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“不懂什么是”后面多接抽象概念，“早饭”是日常食物，不能这样说。"}], "explanations": {"罪": "罪：做了坏事的行为，“不懂什么是”后接这类抽象概念，句意通顺。", "眼睛": "语义：孩子从小就认识眼睛，不会说“不懂什么是眼睛”。", "窗户": "语义：窗户是孩子天天看到的东西，不能说“不懂”。", "早饭": "搭配：“不懂什么是”后面多接抽象概念，“早饭”是日常食物，不能这样说。"}, "sentence_index": 6, "correct_answer": "罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在作文里写错了一个字，犯了一个罪。", "explanation": "这里应该用〈错误〉。罪指触犯法律或严重恶行，写错一个字只是失误，应说“犯了一个错误”。"}, {"text": "这次投篮的罪让我们输了比赛。", "explanation": "这里应该用〈失误〉。罪指违法或恶行，投篮没进只是失误，应说“投篮的失误”。"}, {"text": "他每天早上帮妈妈做饭，这是他的罪。", "explanation": "这里应该用〈好习惯〉。罪指犯法或做坏事的行为，帮妈妈做饭是好的行为，应说“这是他的好习惯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时做过一次罪，后来改过自新了。", "corrected_sentence": "他年轻时犯过一次罪，后来改过自新了。", "error_description": "错误形式“做过一次罪”，正确形式“犯过一次罪”。“罪”与动词“犯”搭配，表示触犯法律或做坏事，“做罪”不能这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他承认了自己罪，愿意接受处罚。", "corrected_sentence": "他承认了自己的罪，愿意接受处罚。", "error_description": "错误形式“自己罪”，正确形式“自己的罪”。“罪”前有“自己”作定语，中间要加“的”，“自己罪”不成词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
