INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "金是黄黄亮亮、很贵重的东西。", "primary_collocate": null, "pronunciation": "jīn", "ipa": "tɕin˥", "syllable_count": 1, "sentences": [{"text": "这个杯子是金的，亮亮的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金很亮，也很贵。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的手表是金的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个戒指是用金做的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光下，金闪闪发光。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金比铁贵多了。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金是黄色的，大家都喜欢。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金放很多年也不会生锈。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁不喜欢又黄又亮的金呢？", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条金的项链看起来很贵。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄金", "label": "复合"}, {"form": "金子", "label": "复合"}, {"form": "金色", "label": "复合"}], "register": "通用", "sense_fingerprint": "黄黄亮亮、很贵重的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6db36e4c-cdd6-4cfb-9f57-3ab5220c3d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄黄亮亮、很贵重的东西，本题的正确答案。"}, {"text": "近", "is_correct": false, "explanation": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。"}, {"text": "精", "is_correct": false, "explanation": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。"}, {"text": "君", "is_correct": false, "explanation": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固。"}, {"text": "亲", "is_correct": false, "explanation": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}], "explanations": {"金": "金：黄黄亮亮、很贵重的东西，本题的正确答案。", "近": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。", "精": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。", "君": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。", "紧": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固。", "亲": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "“金的”指用黄金做的，正好说明杯子的材质。"}, {"text": "布", "is_correct": false, "explanation": "体貌：布做的杯子柔软、不会亮亮的，与“亮亮的”矛盾。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸做的杯子不反光，不会是“亮亮的”。"}, {"text": "土", "is_correct": false, "explanation": "体貌：土做的杯子灰暗，与“亮亮的”的外观不符。"}], "explanations": {"金": "“金的”指用黄金做的，正好说明杯子的材质。", "布": "体貌：布做的杯子柔软、不会亮亮的，与“亮亮的”矛盾。", "纸": "语义：纸做的杯子不反光，不会是“亮亮的”。", "土": "体貌：土做的杯子灰暗，与“亮亮的”的外观不符。"}, "sentence_index": 0, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个玩具是金的，一块钱就能买到一个。", "explanation": "这里与〈金〉的意思不符：〈金〉指很贵重的东西，不能指一块钱就能买到的玩具。"}, {"text": "这把旧伞上的金很便宜，一块钱就能买到。", "explanation": "这里与〈金〉的意思不符：〈金〉指很贵重的东西，这里描述的价格却很低。"}, {"text": "这件衣服是金的，穿着又软又舒服。", "explanation": "这里与〈金〉的意思不符：〈金〉是又硬又贵重的东西，不能做又软又舒服的衣服，应该用〈棉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄黄亮亮、很贵重的东西，本题的正确答案。"}, {"text": "惊", "is_correct": false, "explanation": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。"}, {"text": "经", "is_correct": false, "explanation": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过。"}, {"text": "心", "is_correct": false, "explanation": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。"}, {"text": "进", "is_correct": false, "explanation": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。"}, {"text": "京", "is_correct": false, "explanation": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}], "explanations": {"金": "金：黄黄亮亮、很贵重的东西，本题的正确答案。", "惊": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。", "经": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过。", "心": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。", "进": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。", "京": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "金是黄色的，这里说的正是金的颜色，句子通顺。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪是白色的，不是黄色的。"}, {"text": "血", "is_correct": false, "explanation": "语义：血是红色的，不能说“血是黄色的”。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：说冰的颜色通常用“白色”“透明”，与“黄色的”搭配不通。"}], "explanations": {"金": "金是黄色的，这里说的正是金的颜色，句子通顺。", "雪": "语义：雪是白色的，不是黄色的。", "血": "语义：血是红色的，不能说“血是黄色的”。", "冰": "搭配：说冰的颜色通常用“白色”“透明”，与“黄色的”搭配不通。"}, "sentence_index": 6, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的金快用完了，爸爸很着急。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“家里的钱快用完了”要用〈钱〉。"}, {"text": "这个金很便宜，一块钱就能买到。", "explanation": "这里与〈金〉的意思不符：〈金〉很贵重，不能说一块钱就能买到。"}, {"text": "这张纸是金的，可以在上面写字。", "explanation": "这里与〈金〉的意思不符：写字的纸不是用金做的，应该用〈白〉描述纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块手表是用金做。", "corrected_sentence": "这块手表是用金做的。", "error_description": "错误形式“是用金做”，正确形式“是用金做的”。说明东西的材料用“是……的”句，句末不能少“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个戒指是金做了的。", "corrected_sentence": "这个戒指是金做的。", "error_description": "错误形式“金做了的”，正确形式“金做的”。说明材料的“是……的”句里，动词后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
