INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种黄色的贵重金属；也泛指金属。", "primary_collocate": null, "pronunciation": "jīn", "ipa": "tɕin˥", "syllable_count": 1, "sentences": [{"text": "金、银、铜、铁都是金属。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个戒指是金的，不是银的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金比银贵。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一条金做的项链。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金很软，可以做成各种样子。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的耳环是金还是银？", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块奖牌是金的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金不会生锈。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶买了一个金的手镯。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金在火里会变软。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄金", "label": "复合"}, {"form": "金子", "label": "复合"}, {"form": "金属", "label": "复合"}], "register": "通用", "sense_fingerprint": "黄金这种贵重金属，也泛指金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6db36e4c-cdd6-4cfb-9f57-3ab5220c3d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄色的贵重金属，本题的正确答案。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固，不是金属。"}, {"text": "进", "is_correct": false, "explanation": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。"}, {"text": "精", "is_correct": false, "explanation": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。"}, {"text": "君", "is_correct": false, "explanation": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。"}, {"text": "京", "is_correct": false, "explanation": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}], "explanations": {"金": "金：黄色的贵重金属，本题的正确答案。", "紧": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固，不是金属。", "进": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。", "精": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。", "君": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。", "京": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "金是金属，与银、铜、铁并列，正好放在空格里。"}, {"text": "木", "is_correct": false, "explanation": "语义：木是木材，不属于金属，与银、铜、铁并列不成立。"}, {"text": "石", "is_correct": false, "explanation": "语义：石是岩石，不是金属，句子说的是四种金属。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“都是金属”要求并列成分都是金属类名词，“水”与“金属”搭配不通。"}], "explanations": {"金": "金是金属，与银、铜、铁并列，正好放在空格里。", "木": "语义：木是木材，不属于金属，与银、铜、铁并列不成立。", "石": "语义：石是岩石，不是金属，句子说的是四种金属。", "水": "搭配：“都是金属”要求并列成分都是金属类名词，“水”与“金属”搭配不通。"}, "sentence_index": 0, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我身上没有金了，只能坐公交车。", "explanation": "这里应该用〈钱〉。〈金〉指黄色贵重金属，不能表示钱；说“没有钱”要用〈钱〉。"}, {"text": "爸爸每个月的金都给了妈妈。", "explanation": "这里应该用〈钱〉（工资）。〈金〉不表示钱。"}, {"text": "这个月的金不够交房租了。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“不够交房租”要用〈钱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄色的贵重金属，本题的正确答案。"}, {"text": "近", "is_correct": false, "explanation": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。"}, {"text": "惊", "is_correct": false, "explanation": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。"}, {"text": "经", "is_correct": false, "explanation": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过、经历。"}, {"text": "心", "is_correct": false, "explanation": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。"}, {"text": "亲", "is_correct": false, "explanation": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}], "explanations": {"金": "金：黄色的贵重金属，本题的正确答案。", "近": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。", "惊": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。", "经": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过、经历。", "心": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。", "亲": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "奖牌常用金、银、铜等金属制作，“金的”正好指材质。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以用来制作奖牌的材料。"}, {"text": "火", "is_correct": false, "explanation": "语义：火不能用来制作奖牌，句子说的是奖牌的材质。"}, {"text": "云", "is_correct": false, "explanation": "搭配：“奖牌”的材质通常说金、银、铜，“云”不能作为奖牌的材料。"}], "explanations": {"金": "奖牌常用金、银、铜等金属制作，“金的”正好指材质。", "雨": "语义：雨不是可以用来制作奖牌的材料。", "火": "语义：火不能用来制作奖牌，句子说的是奖牌的材质。", "云": "搭配：“奖牌”的材质通常说金、银、铜，“云”不能作为奖牌的材料。"}, "sentence_index": 6, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的金越来越少，妈妈很着急。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“家里的钱越来越少”要用〈钱〉。"}, {"text": "我想用金买一杯咖啡。", "explanation": "这里应该用〈钱〉。〈金〉指黄色贵重金属，日常买东西付的是钱。"}, {"text": "他攒的金都花完了，只好去借钱。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“花完了钱”要用〈钱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块手表是金地。", "corrected_sentence": "这块手表是金的。", "error_description": "助词错误：表示材质应说“是金的”，用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
