INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86931, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "共话是大家在一起说话、聊天。", "primary_collocate": null, "pronunciation": "gòng huà", "ipa": "kʊŋ˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "晚饭后，一家人坐在院子里共话家常。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学多年没见，今晚围坐一起共话往事。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末朋友们来我家，喝着茶共话生活。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节时亲戚们聚在一起，共话新年的打算。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜深了，大家还坐在火边共话往事。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在咖啡馆里共话旅行的快乐。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好明年再见面，共话各自的变化。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的夜晚很安静，几个人围着火共话到天亮。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业二十年后，同学们终于有机会共话青春。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们常在树下共话家常，从早聊到晚。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共话了", "label": "体标"}, {"form": "共话过", "label": "体标"}], "register": "书面", "sense_fingerprint": "多人聚在一起闲谈、聊天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共话", "is_correct": true, "explanation": "共话：一起交谈，与“家常”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能吃“家常”这种谈话内容。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂物品，不能挂家常。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦桌子、玻璃等，不说擦家常。"}], "explanations": {"共话": "共话：一起交谈，与“家常”搭配。", "吃": "语义：“吃”的对象是食物，不能吃“家常”这种谈话内容。", "挂": "语义：“挂”指悬挂物品，不能挂家常。", "擦": "搭配：“擦”用于擦桌子、玻璃等，不说擦家常。"}, "sentence_index": 0, "correct_answer": "共话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人坐在窗边，共话了很久。", "explanation": "这里应该用〈自言自语〉。共话指大家一起交谈，一个人不能共话。"}, {"text": "老师共话了那个调皮的学生。", "explanation": "这里应该用〈教育〉。共话是交谈，不能把人当作宾语。"}, {"text": "妈妈共话了一顿早饭。", "explanation": "这里应该用〈做〉。共话的对象是话题，不能是早饭这类饮食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共话", "is_correct": true, "explanation": "共话：一起谈论，与“各自的变化”搭配。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指搬运物品，不能搬变化。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“各自的变化”作宾语。"}, {"text": "浇", "is_correct": false, "explanation": "语义：“浇”用于浇水、浇花，不能浇变化。"}], "explanations": {"共话": "共话：一起谈论，与“各自的变化”搭配。", "搬": "语义：“搬”指搬运物品，不能搬变化。", "哭": "配价：“哭”是不及物动词，不能带“各自的变化”作宾语。", "浇": "语义：“浇”用于浇水、浇花，不能浇变化。"}, "sentence_index": 6, "correct_answer": "共话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把饼干共话给孩子了。", "explanation": "这里应该用〈分给〉。共话是交谈，不能用来指把食物分给别人。"}, {"text": "他在日记本上共话了一整夜。", "explanation": "这里应该用〈写〉。共话是口头交谈，不能在纸上进行。"}, {"text": "小狗在院子里共话了一下午。", "explanation": "这里应该用〈玩〉。共话指人与人之间交谈，小狗不能共话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老朋友们坐在茶馆里我共话旧事。", "corrected_sentence": "老朋友们坐在茶馆里和我共话旧事。", "error_description": "错误：缺少“和”；正确：“和我共话”。共话引出交谈对象时要用“和”或“跟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们约定下周末一起共话了往事。", "corrected_sentence": "我们约定下周末一起共话往事。", "error_description": "错误：“共话了往事”；正确：“共话往事”。下周末是将来的时间，不能用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
