INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86932, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一起交谈；共同谈论。", "primary_collocate": null, "pronunciation": "gòng huà", "ipa": "kʊŋ˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "两国代表坐下来，共话经济合作。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们在会上共话环境保护的问题。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长共话孩子的成长。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的节目请三位作家共话读书的乐趣。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在网上共话新年的计划。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动让青年人共话未来的工作。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们开了个小会，共话小区的安全。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在会议室里共话学校的发展。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想共话学习方法，请你也来。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生和病人共话治病的办法。", "target_word": "共话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共话了", "label": "体标"}, {"form": "共话过", "label": "体标"}], "register": "书面", "sense_fingerprint": "围绕某个话题共同谈论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共话", "is_correct": true, "explanation": "共话：围绕话题一起谈论，与“经济合作”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能吃经济合作。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂物品，不能挂经济合作。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“经济合作”作宾语。"}], "explanations": {"共话": "共话：围绕话题一起谈论，与“经济合作”搭配。", "吃": "语义：“吃”的对象是食物，不能吃经济合作。", "挂": "语义：“挂”指悬挂物品，不能挂经济合作。", "哭": "配价：“哭”是不及物动词，不能带“经济合作”作宾语。"}, "sentence_index": 0, "correct_answer": "共话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这本书共话给朋友了。", "explanation": "这里应该用〈借〉。共话是共同谈论，不能带“书”这类物品，也不能表示借出。"}, {"text": "班长共话了那个新来的同学。", "explanation": "这里应该用〈欢迎〉。共话是交谈，不能把人当作宾语。"}, {"text": "他一个人共话了整场辩论。", "explanation": "这里应该用〈主持〉。共话需要两人或多人一起谈论，一个人不能共话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共话", "is_correct": true, "explanation": "共话：围绕话题一起谈论，与“小区的安全”搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是食物等，不能咬小区的安全。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦桌子、玻璃等，不说擦安全。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能煮小区的安全。"}], "explanations": {"共话": "共话：围绕话题一起谈论，与“小区的安全”搭配。", "咬": "语义：“咬”的对象是食物等，不能咬小区的安全。", "擦": "搭配：“擦”用于擦桌子、玻璃等，不说擦安全。", "煮": "语义：“煮”的对象是食物，不能煮小区的安全。"}, "sentence_index": 6, "correct_answer": "共话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在厨房里共话了一锅汤。", "explanation": "这里应该用〈煮〉。共话指交谈，汤是饮食，不能作共话的对象。"}, {"text": "他在信纸上共话了很久。", "explanation": "这里应该用〈写〉。共话是口头交谈，不能在纸上进行。"}, {"text": "小猫在窗台上共话了一下午。", "explanation": "这里应该用〈晒太阳〉。共话指人与人之间交谈，小猫不能共话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位学者在会上记者共话气候变化。", "corrected_sentence": "两位学者在会上和记者共话气候变化。", "error_description": "错误：缺少“和”；正确：“和记者共话”。共话引出交谈对象时要用“和”或“跟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师们明天在办公室里共话过教学方法。", "corrected_sentence": "老师们明天在办公室里共话教学方法。", "error_description": "错误：多出“过”；正确：“共话教学方法”。“明天”是将来的时间，不能用“过”表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下月", "is_correct": true, "explanation": "下月：指本月之后的一个月，与「上月」相对，是反义关系。"}, {"text": "今年", "is_correct": false, "explanation": "「今年」指这一整年，与「上月」不构成反义关系。"}, {"text": "去年", "is_correct": false, "explanation": "「去年」指前一整年，与「上月」不构成反义关系。"}, {"text": "明天", "is_correct": false, "explanation": "「明天」指次日，与「上月」不构成反义关系。"}], "correct_answer": "下月", "explanations": {"下月": "下月：指本月之后的一个月，与「上月」相对，是反义关系。", "今年": "「今年」指这一整年，与「上月」不构成反义关系。", "去年": "「去年」指前一整年，与「上月」不构成反义关系。", "明天": "「明天」指次日，与「上月」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下月", "is_correct": true, "explanation": "下月：指本月之后的一个月，与「上月」相对，是反义关系。"}, {"text": "昨天", "is_correct": false, "explanation": "「昨天」指前一天，与「上月」不构成反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "「周末」指一周的末尾两天，与「上月」不构成反义关系。"}, {"text": "前年", "is_correct": false, "explanation": "「前年」指两年之前，与「上月」不构成反义关系。"}], "correct_answer": "下月", "explanations": {"下月": "下月：指本月之后的一个月，与「上月」相对，是反义关系。", "昨天": "「昨天」指前一天，与「上月」不构成反义关系。", "周末": "「周末」指一周的末尾两天，与「上月」不构成反义关系。", "前年": "「前年」指两年之前，与「上月」不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上月是这个月前面的那一个月。", "primary_collocate": null, "pronunciation": "shàng yuè", "ipa": "ʂɑŋ˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "现在是五月，上月是四月。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月我去了上海，这个月在家。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是十月三号，上月的工作已经做完了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上月买的手机，这个月就坏了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月天气很冷，这个月暖和多了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上月搬了家，现在住在学校旁边。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月比上月忙，我每天都加班。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月的电费已经交了，下个月再交。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月二十号我们见过面，今天又见了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说上月的考试，大家做得很好。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上月底", "label": "复合词"}], "register": "中性", "sense_fingerprint": "上月：本月之前的那个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上月", "is_correct": true, "explanation": "上月：指本月的前一个月，与「现在是五月」相符，可以填入。"}, {"text": "本月", "is_correct": false, "explanation": "语义：「本月」就是现在的五月，不能再说它是四月。"}, {"text": "下月", "is_correct": false, "explanation": "语义：「下月」指这个月之后的一个月，是六月，与「是四月」不符。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：「去年」指一整年之前，不能用来与同一年的月份作前后对应。"}], "explanations": {"上月": "上月：指本月的前一个月，与「现在是五月」相符，可以填入。", "本月": "语义：「本月」就是现在的五月，不能再说它是四月。", "下月": "语义：「下月」指这个月之后的一个月，是六月，与「是四月」不符。", "去年": "搭配：「去年」指一整年之前，不能用来与同一年的月份作前后对应。"}, "sentence_index": 0, "correct_answer": "上月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上月是星期三。", "explanation": "这里应该用〈昨天〉。上月指一整个月，不能说它是星期几。"}, {"text": "上月的会议明天举行。", "explanation": "这里应该用〈下月〉。上月指过去的月份，不能用来说明将来举行的会议。"}, {"text": "我今天上月去了超市。", "explanation": "这里应该用〈昨天〉。上月指整个上一个月，不能用来说明某一天的外出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上月", "is_correct": true, "explanation": "上月：指本月的前一个月，与「这个月」相对比较，可以填入。"}, {"text": "这个月", "is_correct": false, "explanation": "语义：「这个月」本身就是比较的对象，「这个月比这个月忙」没有意义。"}, {"text": "今年", "is_correct": false, "explanation": "语义：「今年」指整年，与「这个月」不能作为同类时间进行比较。"}, {"text": "早上", "is_correct": false, "explanation": "语义：「早上」是一天中的一段时间，不能和「这个月」比较。"}], "explanations": {"上月": "上月：指本月的前一个月，与「这个月」相对比较，可以填入。", "这个月": "语义：「这个月」本身就是比较的对象，「这个月比这个月忙」没有意义。", "今年": "语义：「今年」指整年，与「这个月」不能作为同类时间进行比较。", "早上": "语义：「早上」是一天中的一段时间，不能和「这个月」比较。"}, "sentence_index": 6, "correct_answer": "上月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在是上月。", "explanation": "这里应该用〈这个月〉。「现在」指当前的月份，上月是过去的月份，不能说「现在是上月」。"}, {"text": "这次考试上月就要开始了。", "explanation": "这里应该用〈下个月〉。上月指已经过去的月份，不能用来说明将要开始的考试。"}, {"text": "上月的假期是下个星期。", "explanation": "这里应该用〈这个月〉。上月指已经过去的月份，不能用来指当前安排的假期时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上月了我去了北京。", "corrected_sentence": "上月我去了北京。", "error_description": "错误：「了」放在了「上月」后面，写成「上月了」。「上月」是时间词，「了」应紧跟在动词「去」后面，正确写法是「上月我去了北京」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这上月我们去了一次北京。", "corrected_sentence": "上月我们去了一次北京。", "error_description": "错误：「这」放在了「上月」前面，写成「这上月」。「上月」是表示时间的词，不能用「这」来修饰。正确写法是「上月我们去了一次北京」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
