INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用制冷装置使内部保持低温、用来储存食物和饮料的家用电器。", "primary_collocate": null, "pronunciation": "bīng xiāng", "ipa": "piŋ˥ ɕjaŋ˥", "syllable_count": 2, "sentences": [{"text": "牛奶要放进冰箱里，不然会坏。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的冰箱是去年买的。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有三个苹果。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把西瓜放在冰箱里冰了一下午。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱门没关好，里面的菜都不冷了。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台冰箱很安静，晚上听不到声音。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我最爱喝冰箱里的冰水。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用磁铁把便条贴在冰箱上。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱坏了，我们请人来修。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩菜可以放冰箱，明天再吃。", "target_word": "冰箱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "电冰箱", "label": "复合词"}, {"form": "小冰箱", "label": "复合词"}], "register": "中性", "sense_fingerprint": "家用制冷电器，储存食物和饮料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d9b7acb-06c4-4953-b400-63e6e8a36ece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": true, "explanation": "冰箱能让牛奶保持低温，与“不然会坏”的保存需要相符。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是用来扔废弃物的，放进去的牛奶无法保存，与句中“不然会坏”的保存之意矛盾。"}, {"text": "烤箱", "is_correct": false, "explanation": "语义：烤箱用来加热，把牛奶放进去只会加速变质，与“不然会坏”要表达的低温保存相反。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机用来洗衣服，不能让牛奶保持低温，与“不然会坏”的保存之意不符。"}], "explanations": {"冰箱": "冰箱能让牛奶保持低温，与“不然会坏”的保存需要相符。", "垃圾桶": "语义：垃圾桶是用来扔废弃物的，放进去的牛奶无法保存，与句中“不然会坏”的保存之意矛盾。", "烤箱": "语义：烤箱用来加热，把牛奶放进去只会加速变质，与“不然会坏”要表达的低温保存相反。", "洗衣机": "语义：洗衣机用来洗衣服，不能让牛奶保持低温，与“不然会坏”的保存之意不符。"}, "sentence_index": 0, "correct_answer": "冰箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只冰箱。", "explanation": "这里应该用〈台〉。冰箱是家电，量词用“台”；“只”多用于动物或成对的小物件，不用于冰箱。"}, {"text": "我家有一张冰箱。", "explanation": "这里应该用〈台〉。“张”用于桌子、床等平面的东西，冰箱应该用“台”。"}, {"text": "我买了一把冰箱。", "explanation": "这里应该用〈台〉。“把”用于有柄或可握的东西，冰箱应该用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": true, "explanation": "冰箱能冷藏食物和饮料，冰水从冰箱里取出，与“最爱喝……里的冰水”相符。"}, {"text": "炉子", "is_correct": false, "explanation": "语义：炉子用来烧火加热，里面不可能存放冰水，与“冰水”矛盾。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：书架用来放书，不说“喝书架里的……”，与“喝”搭配不当。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的地方，不会储存冰水，与“冰水”及“喝”的语境不符。"}], "explanations": {"冰箱": "冰箱能冷藏食物和饮料，冰水从冰箱里取出，与“最爱喝……里的冰水”相符。", "炉子": "语义：炉子用来烧火加热，里面不可能存放冰水，与“冰水”矛盾。", "书架": "搭配：书架用来放书，不说“喝书架里的……”，与“喝”搭配不当。", "花园": "语义：花园是种植花草的地方，不会储存冰水，与“冰水”及“喝”的语境不符。"}, "sentence_index": 6, "correct_answer": "冰箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一辆冰箱。", "explanation": "这里应该用〈台〉。“辆”用于车辆，冰箱是家电，应该用“台”。"}, {"text": "我家有一顶冰箱。", "explanation": "这里应该用〈台〉。“顶”用于帽子、帐篷等，冰箱应该用“台”。"}, {"text": "我家有一间冰箱。", "explanation": "这里应该用〈台〉。“间”用于房屋、房间，冰箱应该用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家昨天买了一条冰箱。", "corrected_sentence": "我家昨天买了一台冰箱。", "error_description": "“一条冰箱”错误。“条”用于细长的东西，如鱼、裤子；冰箱是家电，量词应用“台”，应写作“一台冰箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把西瓜放进冰箱上。", "corrected_sentence": "妈妈把西瓜放进冰箱里。", "error_description": "“放进……上”搭配错误。“放进”表示进入容器内部，应与“里”搭配，应写作“放进冰箱里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86937, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "正确。“相同”与“不等”意思相对，指几样东西彼此一致、没有差别。"}, {"text": "清楚", "is_correct": false, "explanation": "与“不等”没有反义关系：“清楚”指明白、不模糊，与几样东西是否一样无关。"}, {"text": "光滑", "is_correct": false, "explanation": "与“不等”没有反义关系：“光滑”指表面平整，与几样东西是否一致无关。"}, {"text": "宽大", "is_correct": false, "explanation": "与“不等”没有反义关系：“宽大”形容空间或范围大，与是否一致无关。"}], "correct_answer": "相同", "explanations": {"相同": "正确。“相同”与“不等”意思相对，指几样东西彼此一致、没有差别。", "清楚": "与“不等”没有反义关系：“清楚”指明白、不模糊，与几样东西是否一样无关。", "光滑": "与“不等”没有反义关系：“光滑”指表面平整，与几样东西是否一致无关。", "宽大": "与“不等”没有反义关系：“宽大”形容空间或范围大，与是否一致无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86937, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "正确。“相同”与“不等”意思相对，指几样东西彼此一致、没有差别。"}, {"text": "平坦", "is_correct": false, "explanation": "与“不等”没有反义关系：“平坦”指表面没有起伏，与是否一致无关。"}, {"text": "温暖", "is_correct": false, "explanation": "与“不等”没有反义关系：“温暖”形容温度或感觉，与是否一致无关。"}, {"text": "安静", "is_correct": false, "explanation": "与“不等”没有反义关系：“安静”与“吵闹”相对，与是否一致无关。"}], "correct_answer": "相同", "explanations": {"相同": "正确。“相同”与“不等”意思相对，指几样东西彼此一致、没有差别。", "平坦": "与“不等”没有反义关系：“平坦”指表面没有起伏，与是否一致无关。", "温暖": "与“不等”没有反义关系：“温暖”形容温度或感觉，与是否一致无关。", "安静": "与“不等”没有反义关系：“安静”与“吵闹”相对，与是否一致无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86937, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不等是说这些东西不是一样的。", "primary_collocate": null, "pronunciation": "bù děng", "ipa": "pu˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些杯子高矮不等，放不整齐。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩的身高不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮子里的鸡蛋大小不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个班的人数不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的树粗细不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几条鱼的重量不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的老师年龄不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人分到的钱多少不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河两边的宽度不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的几件衣服价格不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "几样东西彼此不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丰富", "is_correct": false, "explanation": "语义：“丰富”指内容或数量多，不能用来形容杯子的高矮。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”形容人的情绪，不能用于杯子的高矮。"}, {"text": "不等", "is_correct": true, "explanation": "正确。“这些杯子高矮不等，放不整齐”说明杯子的高矮彼此不同，符合语境。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”搭配水、眼神等，不搭配“高矮”。"}], "explanations": {"丰富": "语义：“丰富”指内容或数量多，不能用来形容杯子的高矮。", "冷静": "语义：“冷静”形容人的情绪，不能用于杯子的高矮。", "不等": "正确。“这些杯子高矮不等，放不整齐”说明杯子的高矮彼此不同，符合语境。", "清澈": "搭配：“清澈”搭配水、眼神等，不搭配“高矮”。"}, "sentence_index": 0, "correct_answer": "不等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石碑的年代不等。", "explanation": "这里不能用〈不等〉。「不等」指多个可比较的东西互不相同，一块石碑只有一个年代，不能说不等。"}, {"text": "我的生日不等。", "explanation": "这里不能用〈不等〉。「不等」指多个东西互不相同，我的生日只有一个，不能说不等。"}, {"text": "这座城市的名字不等。", "explanation": "这里不能用〈不等〉。「不等」需要多个东西相互比较，一座城市只有一个名字，不能说不等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”是味道，年龄不能是辛辣的。"}, {"text": "甜美", "is_correct": false, "explanation": "体貌：“甜美”形容容貌、声音，不用来形容年龄。"}, {"text": "不等", "is_correct": true, "explanation": "正确。“学校里的老师年龄不等”说明老师们的年龄彼此不同，符合语境。"}, {"text": "轻盈", "is_correct": false, "explanation": "搭配：“年龄”可以说大、小、相近，不能说“轻盈”。"}], "explanations": {"辛辣": "语义：“辛辣”是味道，年龄不能是辛辣的。", "甜美": "体貌：“甜美”形容容貌、声音，不用来形容年龄。", "不等": "正确。“学校里的老师年龄不等”说明老师们的年龄彼此不同，符合语境。", "轻盈": "搭配：“年龄”可以说大、小、相近，不能说“轻盈”。"}, "sentence_index": 6, "correct_answer": "不等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两只一模一样的盒子，大小不等。", "explanation": "这里不能用〈不等〉。「一模一样」表示完全相同，与「不等」矛盾，应说〈相同〉。"}, {"text": "他和我考了同样的分数，但我们的分数不等。", "explanation": "这里不能用〈不等〉。「同样的分数」已经说明相同，与「不等」矛盾，应说〈一致〉。"}, {"text": "两地的文化不等。", "explanation": "这里应该用〈迥异〉。“不等”用于大小、多少等可比较的量，文化的差别要用〈迥异〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几只碗的高矮不等着。", "corrected_sentence": "这几只碗的高矮不等。", "error_description": "“不等”是形容词，这里表示状态，接“着”不自然，应说“这几只碗的高矮不等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个鸡蛋大小不等。", "corrected_sentence": "这些鸡蛋大小不等。", "error_description": "数量错误：“不等”指多个事物彼此不同，“这个”只指一个，应说“这些鸡蛋大小不等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86938, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相等", "is_correct": true, "explanation": "正确。“相等”与“不等”意思相反，指数量、大小、长短彼此相同。"}, {"text": "清楚", "is_correct": false, "explanation": "与“不等”没有反义关系：“清楚”指明白、不模糊，与大小、长短是否相等无关。"}, {"text": "宽大", "is_correct": false, "explanation": "与“不等”没有反义关系：“宽大”形容空间或范围大，与大小是否相等无关。"}, {"text": "光滑", "is_correct": false, "explanation": "与“不等”没有反义关系：“光滑”指表面平整，与长短、大小无关。"}], "correct_answer": "相等", "explanations": {"相等": "正确。“相等”与“不等”意思相反，指数量、大小、长短彼此相同。", "清楚": "与“不等”没有反义关系：“清楚”指明白、不模糊，与大小、长短是否相等无关。", "宽大": "与“不等”没有反义关系：“宽大”形容空间或范围大，与大小是否相等无关。", "光滑": "与“不等”没有反义关系：“光滑”指表面平整，与长短、大小无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86938, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相等", "is_correct": true, "explanation": "正确。“相等”与“不等”意思相反，指数量、大小、长短彼此相同。"}, {"text": "平坦", "is_correct": false, "explanation": "与“不等”没有反义关系：“平坦”指表面没有起伏，与数量比较无关。"}, {"text": "温暖", "is_correct": false, "explanation": "与“不等”没有反义关系：“温暖”形容温度或感觉，与大小、多少无关。"}, {"text": "安静", "is_correct": false, "explanation": "与“不等”没有反义关系：“安静”与“吵闹”相对，与是否相等无关。"}], "correct_answer": "相等", "explanations": {"相等": "正确。“相等”与“不等”意思相反，指数量、大小、长短彼此相同。", "平坦": "与“不等”没有反义关系：“平坦”指表面没有起伏，与数量比较无关。", "温暖": "与“不等”没有反义关系：“温暖”形容温度或感觉，与大小、多少无关。", "安静": "与“不等”没有反义关系：“安静”与“吵闹”相对，与是否相等无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86938, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不相等；不一致。", "primary_collocate": null, "pronunciation": "bù děng", "ipa": "pu˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这两个盒子的大小不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个孩子的年龄不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书，厚薄不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几根绳子长短不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每家商店的价格高低不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左右两边的高度不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的成绩好坏不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果大小不等，但都很甜。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的四条腿长短不等，坐着不稳。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每个月的收入多少不等。", "target_word": "不等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量、大小等不相等、不一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 几根 (Zipf 3.29), 绳子 (Zipf 3.86), 长短 (Zipf 3.65)']::text[], '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻松", "is_correct": false, "explanation": "语义：“大小”是可以比较的量，“轻松”形容心情或状态，不能说盒子的大小轻松。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多形容光线、颜色，不搭配“大小”。"}, {"text": "不等", "is_correct": true, "explanation": "正确。“这两个盒子的大小不等”说明两个盒子大小不一样，符合语境。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的才智，不能用来说盒子的大小。"}], "explanations": {"轻松": "语义：“大小”是可以比较的量，“轻松”形容心情或状态，不能说盒子的大小轻松。", "明亮": "搭配：“明亮”多形容光线、颜色，不搭配“大小”。", "不等": "正确。“这两个盒子的大小不等”说明两个盒子大小不一样，符合语境。", "聪明": "语义：“聪明”形容人的才智，不能用来说盒子的大小。"}, "sentence_index": 0, "correct_answer": "不等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种颜色不等。", "explanation": "这里应该用〈不同〉。“不等”多用于大小、长短、多少等可以比较的量，颜色的差异要用〈不同〉。"}, {"text": "我们的兴趣不等。", "explanation": "这里应该用〈不相同〉。“不等”用于可比较的量，兴趣、爱好的差异要用〈不相同〉。"}, {"text": "两个人的性格不等。", "explanation": "这里应该用〈不一样〉。“不等”用于大小、高低、多少，性格的差异要用〈不一样〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水、眼神等透明干净的东西，不能用来评价成绩。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，与“成绩好坏”无关。"}, {"text": "不等", "is_correct": true, "explanation": "正确。“同学们的成绩好坏不等”表示成绩高低不一，符合语境。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，与成绩的好坏没有关系。"}], "explanations": {"清澈": "搭配：“清澈”形容水、眼神等透明干净的东西，不能用来评价成绩。", "高大": "体貌：“高大”形容人或物的体形，与“成绩好坏”无关。", "不等": "正确。“同学们的成绩好坏不等”表示成绩高低不一，符合语境。", "柔软": "语义：“柔软”形容质地，与成绩的好坏没有关系。"}, "sentence_index": 6, "correct_answer": "不等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两件外套的品牌不等。", "explanation": "这里应该用〈有别〉。「不等」只用于大小、多少等可比较的量，品牌的差别不能说不等。"}, {"text": "他和弟弟的名字不等。", "explanation": "这里应该用〈相异〉。「不等」只用于可比较的量，名字的差别不能用「不等」来说。"}, {"text": "两种文化不等。", "explanation": "这里应该用〈迥异〉。“不等”用于大小、多少等可比较的量，文化之间的差别要用〈迥异〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三根木棍的长短不等着。", "corrected_sentence": "这三根木棍的长短不等。", "error_description": "体标错误：“不等”是形容词，表示状态，一般不加“着”，应说“这三根木棍的长短不等”，不能说“不等着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个大小不等的盒子很漂亮。", "corrected_sentence": "这些大小不等的盒子很漂亮。", "error_description": "数量错误：“不等”指多个事物彼此不同，“这个”只指一个，应说“这些大小不等的盒子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
