INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担任（某种职务）。", "primary_collocate": null, "pronunciation": "chū rèn", "ipa": "tʂʰu˥ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "她出任市场部经理，负责销售工作。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王退休后，小李出任厂长。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请他出任董事长。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出任过两次市长。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授出任大学校长。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新总统请她出任外交部长。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出任大使期间，常去各国访问。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁将出任下一任主席？", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出任董事后，公司变化很大。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出任了这家医院的院长。", "target_word": "出任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出任了", "label": "体标（了）"}, {"form": "出任过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "出任：正式地担任某种职务或官职", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出任", "is_correct": true, "explanation": "出任：正式担任职务，与“市场部经理”搭配，符合句意。"}, {"text": "离任", "is_correct": false, "explanation": "配价：“离任”不带宾语，不能说“离任市场部经理”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展品，不能用于指人的职务。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“市场部经理”作宾语。"}], "explanations": {"出任": "出任：正式担任职务，与“市场部经理”搭配，符合句意。", "离任": "配价：“离任”不带宾语，不能说“离任市场部经理”。", "参观": "搭配：“参观”的对象是场所或展品，不能用于指人的职务。", "散步": "配价：“散步”是不及物动词，不能带“市场部经理”作宾语。"}, "sentence_index": 0, "correct_answer": "出任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出任这次活动的安排。", "explanation": "这里应该用〈负责〉。出任指担任职务，“安排”不是职务，不能用“出任”。"}, {"text": "他出任我多年的老朋友。", "explanation": "这里应该用〈是〉。出任的宾语必须是职务，“老朋友”是人际关系，不是职务。"}, {"text": "他出任了这次比赛的冠军。", "explanation": "这里应该用〈获得〉。出任指担任职务，“冠军”是称号，不能用“出任”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出任", "is_correct": true, "explanation": "出任：正式担任职务，与“大使”搭配，符合句意。"}, {"text": "辞职", "is_correct": false, "explanation": "配价：“辞职”不带宾语，不能说“辞职大使期间”。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”的对象是商品，“大使”不能被购买。"}, {"text": "退休", "is_correct": false, "explanation": "配价：“退休”不带宾语，不能说“退休大使”。"}], "explanations": {"出任": "出任：正式担任职务，与“大使”搭配，符合句意。", "辞职": "配价：“辞职”不带宾语，不能说“辞职大使期间”。", "购买": "语义：“购买”的对象是商品，“大使”不能被购买。", "退休": "配价：“退休”不带宾语，不能说“退休大使”。"}, "sentence_index": 6, "correct_answer": "出任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出任这个部门已经五年了。", "explanation": "这里应该用〈领导〉。出任后面要接职务名称，“这个部门”是机构，不能直接作宾语。"}, {"text": "他出任了这次会议。", "explanation": "这里应该用〈参加〉。出任的宾语必须是职务，“会议”不是职务，不能用“出任”。"}, {"text": "他出任了这次考试的第一名。", "explanation": "这里应该用〈考了〉。出任的宾语必须是职务，“第一名”是名次，不是职务，不能用“出任”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她被出任了部门的主管。", "corrected_sentence": "她出任了部门的主管。", "error_description": "错误形式：“被出任”；正确形式：“出任”。“出任”是主动担任职务的动词，不能加“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把他出任了厂长。", "corrected_sentence": "他出任了厂长。", "error_description": "错误形式：“把他出任了厂长”；正确形式：“他出任了厂长”。“出任”是直接带职务作宾语的动词，不能组成“把”字句，前面不能加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86941, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
