INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86941, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "好在是说有一件好事，所以没有出大问题。", "primary_collocate": null, "pronunciation": "hǎo zài", "ipa": "xɑʊ˨˩˦ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "下雨了，好在我有一把伞。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好在他住得近，很快就到了。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了带钱，好在朋友帮了我。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好在这次考试不难，大家都过了。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车晚点了，好在会还没开始。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钥匙丢了，好在妈妈在家。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好在今天是周末，不用早起。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走错了路，好在及时发现了。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子坏了，好在离家不远。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好在大家都没事，我才放心。", "target_word": "好在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "有一件好事，所以没出大问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好在", "is_correct": true, "explanation": "正确答案：好在（hǎo zài）。"}, {"text": "好带", "is_correct": false, "explanation": "dài 与 zài 声母不同（d 与 z），意思是“容易管教”。"}, {"text": "好赖", "is_correct": false, "explanation": "lài 与 zài 声母不同（l 与 z），意思是“好坏、好歹”。"}, {"text": "早在", "is_correct": false, "explanation": "zǎo 与 hǎo 声母不同（z 与 h），意思是“很早就”，与“好在”不同。"}], "explanations": {"好在": "正确答案：好在（hǎo zài）。", "好带": "dài 与 zài 声母不同（d 与 z），意思是“容易管教”。", "好赖": "lài 与 zài 声母不同（l 与 z），意思是“好坏、好歹”。", "早在": "zǎo 与 hǎo 声母不同（z 与 h），意思是“很早就”，与“好在”不同。"}, "sentence_index": null, "correct_answer": "好在"}, "level_3": {"options": [{"text": "居然", "is_correct": false, "explanation": "语义：“居然”表示出乎意料，但带伞并不是意外，用在这里不合。"}, {"text": "好在", "is_correct": true, "explanation": "正确：“好在”说明有一件好事（有伞），所以下雨没有造成大问题。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行，不能与状态动词“有”搭配。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，前文并没有相反的预期。"}], "explanations": {"居然": "语义：“居然”表示出乎意料，但带伞并不是意外，用在这里不合。", "好在": "正确：“好在”说明有一件好事（有伞），所以下雨没有造成大问题。", "正在": "体貌：“正在”表示动作进行，不能与状态动词“有”搭配。", "反而": "语义：“反而”表示与预期相反，前文并没有相反的预期。"}, "sentence_index": 0, "correct_answer": "好在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的成绩很差，好在被开除了。", "explanation": "这里应该用〈结果〉。好在表示有一件好事，所以没出大问题；“被开除”是成绩差导致的坏结果，应该用“结果”。"}, {"text": "比赛输了，好在他摔伤了。", "explanation": "这里应该用〈可惜〉。“摔伤”是已经发生的坏事，好在不能用来表示庆幸，只能用“可惜”表示遗憾。"}, {"text": "我们努力工作，好在被辞退了。", "explanation": "这里应该用〈竟然〉。好在表示有一件好事，“被辞退”是坏事，表示出乎意料一般用“竟然”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好在", "is_correct": true, "explanation": "正确答案：好在（hǎo zài）。"}, {"text": "早在", "is_correct": false, "explanation": "zǎo 与 hǎo 声母不同（z 与 h），意思是“很早就”，与“好在”不同。"}, {"text": "好菜", "is_correct": false, "explanation": "cài 与 zài 声母不同（c 与 z），意思是“好吃的菜”。"}, {"text": "好卖", "is_correct": false, "explanation": "mài 与 zài 声母不同（m 与 z），意思是“容易卖出去”。"}], "explanations": {"好在": "正确答案：好在（hǎo zài）。", "早在": "zǎo 与 hǎo 声母不同（z 与 h），意思是“很早就”，与“好在”不同。", "好菜": "cài 与 zài 声母不同（c 与 z），意思是“好吃的菜”。", "好卖": "mài 与 zài 声母不同（m 与 z），意思是“容易卖出去”。"}, "sentence_index": null, "correct_answer": "好在"}, "level_3": {"options": [{"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生却未发生，与“今天是周末”这一事实不符。"}, {"text": "好在", "is_correct": true, "explanation": "正确：“好在”引出有利条件，今天是周末，所以不用早起。"}, {"text": "偏偏", "is_correct": false, "explanation": "搭配：“偏偏”多与不如意的事搭配，与“不用早起”这一好事不搭。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何只得如此，与“不用早起”这种轻松情况不合。"}], "explanations": {"差点": "语义：“差点”表示几乎发生却未发生，与“今天是周末”这一事实不符。", "好在": "正确：“好在”引出有利条件，今天是周末，所以不用早起。", "偏偏": "搭配：“偏偏”多与不如意的事搭配，与“不用早起”这一好事不搭。", "只好": "语义：“只好”表示无可奈何只得如此，与“不用早起”这种轻松情况不合。"}, "sentence_index": 6, "correct_answer": "好在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直练习，好在摔断了腿。", "explanation": "这里应该用〈结果〉。好在表示避免了坏结果，“摔断了腿”本身是坏事，不能用“好在”来说。"}, {"text": "他工作很忙，好在没有钱。", "explanation": "这里应该用〈却〉。好在表示有一件好事，“没有钱”不是好事，句中转折应用“却”。"}, {"text": "我没有锻炼，好在病了。", "explanation": "这里应该用〈结果〉。好在表示有一件好事，所以避免了坏事；“病了”是不锻炼导致的坏结果，应该用“结果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "好在的我带了地图，没有迷路。", "corrected_sentence": "好在我带了地图，没有迷路。", "error_description": "错误：副词“好在”后多加了“的”。“好在”引出分句，后面不能加“的”，应说“好在我带了地图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "好在了今天不堵车，我们准时到了。", "corrected_sentence": "好在今天不堵车，我们准时到了。", "error_description": "错误：副词“好在”后多加了“了”。“好在”表示有利条件，本身不带“了”，应说“好在今天不堵车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
