INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86943, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刀、锯子等工具把东西截成两段。", "primary_collocate": null, "pronunciation": "qiē duàn", "ipa": "tɕʰie˥ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈用刀把绳子切断了。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把长面条切断，放进碗里。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用锯子把这根竹子切断。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根钢丝很硬，他用力才把它切断。", "target_word": "切断", "complexity_tier": "T3", "furigana": "zhè gēn gāngsī hěn yìng, tā yònglì cái bǎ tā qiēduàn.", "sentence_source": "generated"}, {"text": "工人用机器切断了粗铁管。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把香肠切断，分给孩子们。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀很快，能切断厚厚的肉。", "target_word": "切断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一刀就切断了那根树枝。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师把长长的胡萝卜切断，再放进锅里。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼太长，你先把它切断吧。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "切断了", "label": "了体标"}, {"form": "切断过", "label": "过体标"}], "register": "通用", "sense_fingerprint": "用刀把东西截成两段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8381a54f-c1d7-4b10-9819-04a640eace4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "切断", "is_correct": true, "explanation": "切断：用刀等把东西截成两段，是正确答案。"}, {"text": "切短", "is_correct": false, "explanation": "声调不同：duǎn（第三声）与 duàn（第四声）不同，意思是把东西切得短。"}, {"text": "前段", "is_correct": false, "explanation": "韵母和声调不同：qián（第二声）与 qiē（第一声）不同，意思是前面的一段。"}, {"text": "桥段", "is_correct": false, "explanation": "韵母和声调不同：qiáo（第二声）与 qiē（第一声）不同，意思是桥的一段或情节段落。"}], "explanations": {"切断": "切断：用刀等把东西截成两段，是正确答案。", "切短": "声调不同：duǎn（第三声）与 duàn（第四声）不同，意思是把东西切得短。", "前段": "韵母和声调不同：qián（第二声）与 qiē（第一声）不同，意思是前面的一段。", "桥段": "韵母和声调不同：qiáo（第二声）与 qiē（第一声）不同，意思是桥的一段或情节段落。"}, "sentence_index": null, "correct_answer": "切断"}, "level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "切断：用刀把绳子截成两段，与「用刀」和「了」相符。"}, {"text": "缝好", "is_correct": false, "explanation": "语义：「缝好」是用针线连缀，不能用刀完成，与「用刀」冲突。"}, {"text": "系紧", "is_correct": false, "explanation": "搭配：「系紧」靠打结收紧，不说用刀把绳子系紧。"}, {"text": "捆好", "is_correct": false, "explanation": "语义：「捆好」是用绳子扎起来，与用刀截断的动作不符。"}], "explanations": {"切断": "切断：用刀把绳子截成两段，与「用刀」和「了」相符。", "缝好": "语义：「缝好」是用针线连缀，不能用刀完成，与「用刀」冲突。", "系紧": "搭配：「系紧」靠打结收紧，不说用刀把绳子系紧。", "捆好": "语义：「捆好」是用绳子扎起来，与用刀截断的动作不符。"}, "sentence_index": 0, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一杯水切断了，倒进两个碗里。", "explanation": "这里应该用〈分〉。切断指用刀等把东西截成两段，水是液体，不能切断，分到两个碗里要用分。"}, {"text": "他用梳子把头发切断了。", "explanation": "这里应该用〈梳顺〉。切断要用刀、锯子等工具把东西截成两段，梳子只能梳头发。"}, {"text": "那堵高墙把风切断了。", "explanation": "这里应该用〈挡住〉。切断指截开或中断联系，墙挡住风要用挡住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "切断：刀很快，能把厚肉截成两段，与句意相符。"}, {"text": "烤熟", "is_correct": false, "explanation": "语义：刀不能把肉烤熟，「烤熟」与「刀很快」的用途冲突。"}, {"text": "碾碎", "is_correct": false, "explanation": "语义：碾碎需要重压，不是靠刀的锋利。"}, {"text": "擦干净", "is_correct": false, "explanation": "搭配：「擦干净」不说用快刀擦肉，与「很快」的刀不相配。"}], "explanations": {"切断": "切断：刀很快，能把厚肉截成两段，与句意相符。", "烤熟": "语义：刀不能把肉烤熟，「烤熟」与「刀很快」的用途冲突。", "碾碎": "语义：碾碎需要重压，不是靠刀的锋利。", "擦干净": "搭配：「擦干净」不说用快刀擦肉，与「很快」的刀不相配。"}, "sentence_index": 6, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用勺子把米饭切断，盛进了碗里。", "explanation": "这里应该用〈舀〉。切断指截成两段或中断，米饭是松散的颗粒，盛取要用舀。"}, {"text": "妈妈把蛋糕切断成了小块。", "explanation": "这里应该用〈切成〉。切断表示截成两段或中断，把蛋糕切成小块要用切成。"}, {"text": "他的牙疼得厉害，只好把它切断。", "explanation": "这里应该用〈拔掉〉。切断用于截开物体或中断联系，坏牙要用拔掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用刀把那条绳子切断着。", "corrected_sentence": "他用刀把那条绳子切断了。", "error_description": "错误：「切断着」。动作已完成并有结果，应用「了」表示完成，「着」表示持续的状态，不能用于此处，应改为「切断了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把那根竹竿切断的。", "corrected_sentence": "工人把那根竹竿切断了。", "error_description": "错误：「切断的」。动作已经完成，句末应用「了」，「的」用于名词性结构，不能单独作句末的谓语，应改为「切断了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
