INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86944, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使联系、供应或通路中断。", "primary_collocate": null, "pronunciation": "qiē duàn", "ipa": "tɕʰie˥ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "工人不小心切断了电线。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪切断了山里的路。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水切断了这个村子的交通。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想切断和过去的一切联系。", "target_word": "切断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家工厂突然切断了对我们的供货。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先切断电源，再修电视。", "target_word": "切断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察切断了坏人的逃跑路线。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震切断了城市的水和电。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不要切断朋友之间的联系。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们切断了网络，孩子们只好出去玩。", "target_word": "切断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "切断了", "label": "了体标"}, {"form": "切断过", "label": "过体标"}], "register": "通用", "sense_fingerprint": "使联系、供应、通路中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8381a54f-c1d7-4b10-9819-04a640eace4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "切断", "is_correct": true, "explanation": "切断：使联系、供应或通路中断，是正确答案。"}, {"text": "切短", "is_correct": false, "explanation": "声调不同：duǎn（第三声）与 duàn（第四声）不同，意思是切得短。"}, {"text": "前段", "is_correct": false, "explanation": "韵母和声调不同：qián（第二声）与 qiē（第一声）不同，意思是前面的一段。"}, {"text": "桥段", "is_correct": false, "explanation": "韵母和声调不同：qiáo（第二声）与 qiē（第一声）不同，意思是桥的一段或情节段落。"}], "explanations": {"切断": "切断：使联系、供应或通路中断，是正确答案。", "切短": "声调不同：duǎn（第三声）与 duàn（第四声）不同，意思是切得短。", "前段": "韵母和声调不同：qián（第二声）与 qiē（第一声）不同，意思是前面的一段。", "桥段": "韵母和声调不同：qiáo（第二声）与 qiē（第一声）不同，意思是桥的一段或情节段落。"}, "sentence_index": null, "correct_answer": "切断"}, "level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "切断：工人截断了电线，与「不小心」相符。"}, {"text": "修好", "is_correct": false, "explanation": "语义：「不小心」与「修好」这种有意的行为冲突。"}, {"text": "检查", "is_correct": false, "explanation": "语义：检查是有意的动作，不能说不小心检查了电线。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：电线不能用来煮，「煮了电线」不是正常说法。"}], "explanations": {"切断": "切断：工人截断了电线，与「不小心」相符。", "修好": "语义：「不小心」与「修好」这种有意的行为冲突。", "检查": "语义：检查是有意的动作，不能说不小心检查了电线。", "煮": "搭配：电线不能用来煮，「煮了电线」不是正常说法。"}, "sentence_index": 0, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他决定切断工作，回家休息。", "explanation": "这里应该用〈辞去〉。切断指截断供应、联系或中断通路，离开工作要用辞去。"}, {"text": "他正在写字，突然把墨水切断了。", "explanation": "这里应该用〈洒〉。切断指截断或中断联系，墨水泼洒要用洒。"}, {"text": "这场比赛顺利进行到最后，裁判宣布比赛被切断。", "explanation": "这里应该用〈结束〉。切断指截断或中断，比赛顺利完成时要用结束。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "切断：警察截断了坏人的逃跑路线，符合句意。"}, {"text": "支持", "is_correct": false, "explanation": "语义：警察支持坏人的逃跑路线，与警察的立场矛盾。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：「欢迎」的对象是人，不能带「路线」作宾语。"}, {"text": "同意", "is_correct": false, "explanation": "语义：警察同意坏人逃跑，与句意相反。"}], "explanations": {"切断": "切断：警察截断了坏人的逃跑路线，符合句意。", "支持": "语义：警察支持坏人的逃跑路线，与警察的立场矛盾。", "欢迎": "配价：「欢迎」的对象是人，不能带「路线」作宾语。", "同意": "语义：警察同意坏人逃跑，与句意相反。"}, "sentence_index": 6, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂切断了生产，工人们都回家了。", "explanation": "这里应该用〈停止〉。切断强调截断供应或联系，停止生产要用停止。"}, {"text": "他切断了这个计划，决定重新开始。", "explanation": "这里应该用〈放弃〉。切断指截开或中断联系，放弃计划要用放弃。"}, {"text": "他把窗户切断了，屋里闷得很。", "explanation": "这里应该用〈关闭〉。切断指截开或中断供应、联系，关上窗户要用关闭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大风切断着那个村子的电话线。", "corrected_sentence": "大风切断了那个村子的电话线。", "error_description": "错误：「切断着」。动作已经完成并有结果，应用「了」表示完成，「着」表示持续的状态，不能用于此处，应改为「切断了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴雨把这个小镇的供水切断的。", "corrected_sentence": "暴雨把这个小镇的供水切断了。", "error_description": "错误：「切断的」。动作已经完成，句末应用「了」，「的」不能单独作句末的谓语，应改为「切断了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
