INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "宣传是把一件事说给很多人听，让大家知道。", "primary_collocate": null, "pronunciation": "xuān chuán", "ipa": "ɕɥɛn˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "我们要宣传这个好消息。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校宣传明天的音乐会。", "target_word": "宣传", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在网上宣传新开的小店。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你帮我们宣传一下这次活动。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上宣传下周的比赛。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司用海报宣传新手机。", "target_word": "宣传", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在街上宣传着环保活动。", "target_word": "宣传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王去年宣传过这个节日。", "target_word": "宣传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得多宣传这家新开的饭馆。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店门口的人正在宣传打折的消息。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣传了", "label": "体标"}, {"form": "宣传着", "label": "体标"}, {"form": "宣传过", "label": "体标"}, {"form": "宣传片", "label": "复合"}], "register": "中性", "sense_fingerprint": "把消息、活动、店铺等告诉很多人，让大家知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6fb817-c5a5-47d1-a0ed-24e25267f898') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣传", "is_correct": true, "explanation": "宣传：把好消息告诉很多人，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能说“吃好消息”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于表面和器物，不能擦“好消息”。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是避开，与值得告诉大家的“好消息”相冲突。"}], "explanations": {"宣传": "宣传：把好消息告诉很多人，符合句意。", "吃": "搭配：“吃”用于食物，不能说“吃好消息”。", "擦": "搭配：“擦”用于表面和器物，不能擦“好消息”。", "躲": "语义：“躲”是避开，与值得告诉大家的“好消息”相冲突。"}, "sentence_index": 0, "correct_answer": "宣传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在日记里宣传了这件事。", "explanation": "这里应该用〈记录〉或〈写〉。宣传是向大众传播消息，日记是私人记录，不能用宣传。"}, {"text": "他宣传了自己的心跳。", "explanation": "这里应该用〈感受〉。宣传的对象须是消息、活动等信息，“心跳”是身体感觉，不能宣传。"}, {"text": "他宣传了一口饭。", "explanation": "这里应该用〈吃〉。宣传的对象是消息、活动等，“一口饭”只能吃，不能宣传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣传", "is_correct": true, "explanation": "宣传：向街上的人传播环保活动，符合句意。"}, {"text": "走", "is_correct": false, "explanation": "语义：“走”指行走，与“宣传”的意思不合，不能说“走环保活动”。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”指终止，与“宣传”让大家知道的意思不合。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语，且“睡着”会被理解为入睡。"}], "explanations": {"宣传": "宣传：向街上的人传播环保活动，符合句意。", "走": "语义：“走”指行走，与“宣传”的意思不合，不能说“走环保活动”。", "结束": "语义：“结束”指终止，与“宣传”让大家知道的意思不合。", "睡": "配价：“睡”是不及物动词，不能带宾语，且“睡着”会被理解为入睡。"}, "sentence_index": 6, "correct_answer": "宣传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我宣传朋友这家饭馆很好吃。", "explanation": "这里应该用〈告诉〉。宣传是面向很多人传播信息，只对一位朋友说要用〈告诉〉。"}, {"text": "我在梦里宣传了这次活动。", "explanation": "这里应该用〈梦到〉。宣传是向很多人传播消息，在梦里没有听众，不能宣传。"}, {"text": "她宣传了自己的困惑。", "explanation": "这里应该用〈倾诉〉。宣传是向大众传播信息，内心困惑要向人〈倾诉〉，不能用“宣传”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在街上宣传了着新的环保口号。", "corrected_sentence": "他们在街上宣传着新的环保口号。", "error_description": "体标重复：“了”和“着”不能同时用在同一个动词后，应只用“宣传着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把新书宣传得很好得。", "corrected_sentence": "她把新书宣传得很好。", "error_description": "多余的“得”：补语“很好”后面不能再加“得”。正确形式：“宣传得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
