INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86948, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向公众讲解、说明，使人了解并相信。", "primary_collocate": null, "pronunciation": "xuān chuán", "ipa": "ɕɥɛn˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "政府向大家宣传新的交通规定。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生宣传健康的生活方式。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校宣传节约用水的好处，让学生明白。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区每月宣传一次防火知识。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要宣传科学，不要相信谣言。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师向同学宣传环保的重要性，大家都同意了。", "target_word": "宣传", "complexity_tier": "T3", "furigana": "lǎo shī xiàng tóng xué xuān chuán huán bǎo de zhòng yào xìng, dà jiā dōu tóng yì le.", "sentence_source": "generated"}, {"text": "这个节目一直宣传着读书的好处。", "target_word": "宣传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到各个村子宣传过新的种田方法。", "target_word": "宣传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把安全知识宣传得很清楚。", "target_word": "宣传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸应该宣传正确的科学知识。", "target_word": "宣传", "complexity_tier": "T3", "furigana": "bào zhǐ yīng gāi xuān chuán zhèng què de kē xué zhī shi.", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣传了", "label": "体标"}, {"form": "宣传着", "label": "体标"}, {"form": "宣传过", "label": "体标"}, {"form": "宣传员", "label": "复合"}], "register": "中性", "sense_fingerprint": "向公众讲解道理、政策、知识，使人了解并相信", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6fb817-c5a5-47d1-a0ed-24e25267f898') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣传", "is_correct": true, "explanation": "宣传：向公众讲解规定，使人了解，符合句意。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指拆开、拆除，不能用于“交通规定”。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象是可以咬的东西，不能咬“交通规定”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“新的交通规定”作宾语。"}], "explanations": {"宣传": "宣传：向公众讲解规定，使人了解，符合句意。", "拆": "搭配：“拆”指拆开、拆除，不能用于“交通规定”。", "咬": "搭配：“咬”的对象是可以咬的东西，不能咬“交通规定”。", "笑": "配价：“笑”是不及物动词，不能带“新的交通规定”作宾语。"}, "sentence_index": 0, "correct_answer": "宣传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每天在课上宣传一瓶墨水。", "explanation": "这里应该用〈拿出〉或〈展示〉。宣传的对象是知识、政策等信息，“墨水”是实物，不能宣传。"}, {"text": "学生在考试时宣传课文。", "explanation": "这里应该用〈默写〉。宣传是向人讲解说明、使人相信，考试中写出课文不是宣传。"}, {"text": "他宣传了一块石头。", "explanation": "这里应该用〈搬〉。宣传的对象是知识、政策等，“石头”是实物，不能宣传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣传", "is_correct": true, "explanation": "宣传：向观众讲解读书的好处，符合句意。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指跌落、重击，不能用于“读书的好处”。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，与“一直宣传”的持续义相反。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语，且“睡着”会被理解为入睡。"}], "explanations": {"宣传": "宣传：向观众讲解读书的好处，符合句意。", "摔": "搭配：“摔”指跌落、重击，不能用于“读书的好处”。", "结束": "语义：“结束”表示终止，与“一直宣传”的持续义相反。", "睡": "配价：“睡”是不及物动词，不能带宾语，且“睡着”会被理解为入睡。"}, "sentence_index": 6, "correct_answer": "宣传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他宣传了一个喷嚏。", "explanation": "这里应该用〈打〉。宣传是向公众讲解说明，“喷嚏”不是可以宣传的内容。"}, {"text": "他的眼睛宣传了这个道理。", "explanation": "这里应该用〈表达〉或〈表明〉。宣传是有目的地向人讲解说明、使人相信，“眼睛”无法这样做，不能用宣传。"}, {"text": "她在心里默默宣传了这个道理。", "explanation": "这里应该用〈想〉。宣传要向公众讲解，只在心里想不是宣传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年宣传了过这种方法。", "corrected_sentence": "她去年宣传过这种方法。", "error_description": "体标重复：“了”和“过”不能同时用在同一个动词后，应只用“宣传过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生把健康知识宣传得很清楚得。", "corrected_sentence": "医生把健康知识宣传得很清楚。", "error_description": "多余的“得”：补语“很清楚”后面不能再加“得”。正确形式：“宣传得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
