INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86949, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "前任是以前做这个工作的人，现在换别人做了。", "primary_collocate": null, "pronunciation": "qián rèn", "ipa": "tɕʰjɛn˧˥ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "我的前任是一位很认真的老师。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前任经理把工作交给了我。", "target_word": "前任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的校长和前任一样爱学生。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的前任走之前，写了一本工作记录。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前任老板对员工很好，大家都想他。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去找前任了解一下这里的情况。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的前任已经换了新工作。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的前任店长在这里工作了十年。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前任司机开车很稳，大家都喜欢他。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新同事比前任做得更快。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位前任", "label": "量词"}, {"form": "前任经理", "label": "复合"}, {"form": "前任老板", "label": "复合"}], "register": "中性", "sense_fingerprint": "以前做这份工作、现在已换人的那个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前任", "is_correct": true, "explanation": "前任：指以前担任这份工作的人，与“是一位很认真的老师”相合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能“是一位很认真的老师”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能说“是一位老师”。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“位”只用于人，椅子不能用“一位老师”来形容。"}], "explanations": {"前任": "前任：指以前担任这份工作的人，与“是一位很认真的老师”相合。", "书包": "语义：书包是物品，不能“是一位很认真的老师”。", "天气": "语义：天气不是人，不能说“是一位老师”。", "椅子": "搭配：“位”只用于人，椅子不能用“一位老师”来形容。"}, "sentence_index": 0, "correct_answer": "前任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的前任同学都很优秀。", "explanation": "这里应该用〈老〉。前任指以前担任某个职务的人，同学之间没有职务交接，不能说前任。"}, {"text": "两个方案中，我选前任。", "explanation": "这里应该用〈前者〉。前任指以前担任职务的人，两者中的前一个要说前者。"}, {"text": "他明天就到任，是我的前任。", "explanation": "这里应该用〈新任〉。前任指已经离任的人，明天到任的人要说新任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前任", "is_correct": true, "explanation": "前任：以前担任这份工作的人，已经离任，所以能“换了新工作”。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能工作，更谈不上“换了新工作”。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能找工作，与“换了新工作”不相容。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：窗帘没有工作，“换工作”的说法与窗帘不搭配。"}], "explanations": {"前任": "前任：以前担任这份工作的人，已经离任，所以能“换了新工作”。", "婴儿": "语义：婴儿不能工作，更谈不上“换了新工作”。", "小狗": "语义：小狗不能找工作，与“换了新工作”不相容。", "窗帘": "搭配：窗帘没有工作，“换工作”的说法与窗帘不搭配。"}, "sentence_index": 6, "correct_answer": "前任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部剧的前任很精彩。", "explanation": "这里应该用〈前一集〉。前任指以前担任职务的人，不能指影视作品，前面播出的一集要说前一集。"}, {"text": "我在吃饭的前任，先洗了手。", "explanation": "这里应该用〈之前〉。前任指担任职务的人，表示吃饭以前要说之前。"}, {"text": "排队时，我站在他的前任。", "explanation": "这里应该用〈前面〉。表示位置在前要说前面，前任指以前担任职务的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只前任很热心。", "corrected_sentence": "这位前任很热心。", "error_description": "错误在量词：指人的“前任”要用量词“位”，“只”用于动物，不能用于人，应说“这位前任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板的那只前任把店交给了儿子。", "corrected_sentence": "老板的那位前任把店交给了儿子。", "error_description": "错误在量词：指人的“前任”要用量词“位”，“只”用于动物，不能用于人，应说“那位前任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86950, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
