INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在现任之前担任某职务的人。", "primary_collocate": null, "pronunciation": "qián rèn", "ipa": "tɕʰjɛn˧˥ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "前任总统在会上发表了讲话。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现任校长比前任校长年轻。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位市长的前任现在在大学教书。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前任主席今天也来参加会议了。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新局长请前任来介绍过去的工作。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我们学校的前任校长。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现任部长和前任部长在电视上见面了。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前任队长走了，由小王做新队长。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个职位的前任做了五年就走了。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新书记没有改变前任的决定。", "target_word": "前任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位前任", "label": "量词"}, {"form": "前任校长", "label": "复合"}, {"form": "前任主席", "label": "复合"}], "register": "中性", "sense_fingerprint": "在现任之前担任某个职务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前任", "is_correct": true, "explanation": "前任：指在现任之前担任该职务的人，与“总统”搭配，句意通顺。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是做饭的人，不能担任总统，与句意不符。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能在会上发表讲话，句子不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“总统”只用于人，桌子不能被称作总统。"}], "explanations": {"前任": "前任：指在现任之前担任该职务的人，与“总统”搭配，句意通顺。", "厨师": "语义：厨师是做饭的人，不能担任总统，与句意不符。", "猫": "语义：猫不能在会上发表讲话，句子不成立。", "桌子": "搭配：“总统”只用于人，桌子不能被称作总统。"}, "sentence_index": 0, "correct_answer": "前任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位前任校长今天刚来上任。", "explanation": "这里应该用〈现任〉。前任指已经离任的人，今天刚上任的要说现任。"}, {"text": "这台电脑是我的前任，已经用了三年。", "explanation": "这里应该用〈旧〉。前任只指人，不能指物品，电脑要说旧的或原来的。"}, {"text": "前任会议上，我们讨论了预算。", "explanation": "这里应该用〈上次〉。前任指担任职务的人，表示以前的会议要说上次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前任", "is_correct": true, "explanation": "前任：指在现任之前担任部长的人，与“现任部长”形成对照。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不担任部长，与“部长”的身份矛盾。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人，不能担任部长。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“部长”指人，椅子不能用“部长”来称呼。"}], "explanations": {"前任": "前任：指在现任之前担任部长的人，与“现任部长”形成对照。", "病人": "语义：病人不担任部长，与“部长”的身份矛盾。", "河流": "语义：河流不是人，不能担任部长。", "椅子": "搭配：“部长”指人，椅子不能用“部长”来称呼。"}, "sentence_index": 6, "correct_answer": "前任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的前任很光明，大家都很看好他。", "explanation": "这里应该用〈前途〉。前任指担任职务的人，说未来的发展要用前途。"}, {"text": "电影院里，我坐在他的前任。", "explanation": "这里应该用〈前面〉。表示位置在前要说前面，前任指先前担任职务的人。"}, {"text": "我在商店买了一个前任。", "explanation": "这里应该用〈东西〉。前任指以前担任职务的人，不能在商店里买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只前任校长已经退休了。", "corrected_sentence": "这位前任校长已经退休了。", "error_description": "错误在量词：指人的“前任校长”要用量词“位”，“只”用于动物，不能用于人，应说“这位前任校长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "主席的那只前任把印章交给了我。", "corrected_sentence": "主席的那位前任把印章交给了我。", "error_description": "错误在量词：指人的“前任”要用量词“位”，“只”用于动物，不能用于人，应说“那位前任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
