INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86951, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "属是说某个东西是谁的，或者是哪一类的。", "primary_collocate": null, "pronunciation": "shǔ", "ipa": "ʂu˨˩˦", "syllable_count": 1, "sentences": [{"text": "这块地属王先生所有，不属别人。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲸不是鱼，它属哺乳动物。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎属猫科动物。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些设备都属学校所有，不能带回家。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事属经理管，你去问他。", "target_word": "属", "complexity_tier": "T3", "furigana": "zhè jiàn shì shǔ jīng lǐ guǎn nǐ qù wèn tā", "sentence_source": "generated"}, {"text": "这间房子到底属谁所有？", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书都属图书馆所有。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西红柿属蔬菜还是水果？", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车属公司所有，不是我的。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫属国家保护动物。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "属于", "label": "复合"}, {"form": "屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说明东西归谁所有或属于哪一类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86951, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。属（shǔ）表示东西归谁所有，或属于哪一类。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是书。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，意思是树。"}, {"text": "输", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是输掉。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shǔ（第三声）声调不同，意思是熟悉或成熟。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是主人。"}], "explanations": {"属": "正确。属（shǔ）表示东西归谁所有，或属于哪一类。", "书": "shū（第一声）与 shǔ（第三声）声调不同，意思是书。", "树": "shù（第四声）与 shǔ（第三声）声调不同，意思是树。", "输": "shū（第一声）与 shǔ（第三声）声调不同，意思是输掉。", "熟": "shú（第二声）与 shǔ（第三声）声调不同，意思是熟悉或成熟。", "主": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是主人。"}, "sentence_index": null, "correct_answer": "属"}, "level_3": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。“属”表示东西归谁所有，与“这块地”“王先生”搭配。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”要带所买之物作宾语，“王先生”不能作“买”的对象，“这块地买王先生”不成立。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“地”没有感情，不能“喜欢”人，与句中的“这块地”语义冲突。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“地”没有感情，不能“讨厌”人，句子意思说不通。"}], "explanations": {"属": "正确。“属”表示东西归谁所有，与“这块地”“王先生”搭配。", "买": "配价：“买”要带所买之物作宾语，“王先生”不能作“买”的对象，“这块地买王先生”不成立。", "喜欢": "语义：“地”没有感情，不能“喜欢”人，与句中的“这块地”语义冲突。", "讨厌": "语义：“地”没有感情，不能“讨厌”人，句子意思说不通。"}, "sentence_index": 0, "correct_answer": "属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我属张，他属李。", "explanation": "这里应该用〈姓〉。“属”表示东西归谁或属于哪类，说人的姓氏要用“姓”。"}, {"text": "他属三辆车，都是新的。", "explanation": "这里应该用〈有〉。“属”表示整体归属或类别，说一个人拥有几件东西要用“有”。"}, {"text": "这只狗属小白，很听话。", "explanation": "这里应该用〈叫〉。给动物起名字用“叫”，不用“属”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86951, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。属（shǔ）表示东西归谁所有，或属于哪一类。"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是叔叔。"}, {"text": "舒", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是舒服、舒展。"}, {"text": "梳", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是梳子。"}, {"text": "煮", "is_correct": false, "explanation": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是煮。"}, {"text": "束", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，意思是捆、束缚。"}], "explanations": {"属": "正确。属（shǔ）表示东西归谁所有，或属于哪一类。", "叔": "shū（第一声）与 shǔ（第三声）声调不同，意思是叔叔。", "舒": "shū（第一声）与 shǔ（第三声）声调不同，意思是舒服、舒展。", "梳": "shū（第一声）与 shǔ（第三声）声调不同，意思是梳子。", "煮": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是煮。", "束": "shù（第四声）与 shǔ（第三声）声调不同，意思是捆、束缚。"}, "sentence_index": null, "correct_answer": "属"}, "level_3": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。“属……所有”表示这些书归图书馆所有。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿……所有”不成立，“拿”不能表示归属。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”不能表示归属，“欢迎图书馆所有”说不通。"}, {"text": "姓", "is_correct": false, "explanation": "搭配：“姓”只能接姓氏，不能说“姓图书馆所有”。"}], "explanations": {"属": "正确。“属……所有”表示这些书归图书馆所有。", "拿": "搭配：“拿……所有”不成立，“拿”不能表示归属。", "欢迎": "语义：“欢迎”不能表示归属，“欢迎图书馆所有”说不通。", "姓": "搭配：“姓”只能接姓氏，不能说“姓图书馆所有”。"}, "sentence_index": 6, "correct_answer": "属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他属医生，每天看病。", "explanation": "这里应该用〈是〉。“属”表示归属或类别，说人的身份要用“是”。"}, {"text": "这个小组属五个人。", "explanation": "这里应该用〈包括〉。“属”表示归属或类别，不能用来说明组成的人数。"}, {"text": "这块地属三分之一。", "explanation": "这里应该用〈占〉。“属”表示归属或类别，不能用来说明所占的比例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆自行车属于了我弟弟。", "corrected_sentence": "这辆自行车属于我弟弟。", "error_description": "错误：“属于”后面加了“了”。正确：“属于”表示归属，是状态动词，不能带“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件东西属不我，是别人的。", "corrected_sentence": "这件东西不属我，是别人的。", "error_description": "错误：否定词“不”放在了“属”后面。正确：否定词“不”应放在“属”前面，说“不属我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
