INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86952, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "归属；隶属于；是。", "primary_collocate": null, "pronunciation": "shǔ", "ipa": "ʂu˨˩˦", "syllable_count": 1, "sentences": [{"text": "我属马，你属什么？", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他属龙，今年二十四岁。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小岛属海南省。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院属市政府。", "target_word": "属", "complexity_tier": "T3", "furigana": "zhè jiā yī yuàn shǔ shì zhèng fǔ", "sentence_source": "generated"}, {"text": "我哥哥属虎，我属兔。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂属国家。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩都属猴，生日也差不多。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班属一年级。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小华属哪个部门？", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街属朝阳区管。", "target_word": "属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "属于", "label": "复合"}, {"form": "屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "隶属某单位地区，或生肖是某种动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86952, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。属（shǔ）在此表示生肖。"}, {"text": "舒", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是舒服、舒展。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，意思是树。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shǔ（第三声）声调不同，意思是熟悉或成熟。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是主人。"}], "explanations": {"属": "正确。属（shǔ）在此表示生肖。", "舒": "shū（第一声）与 shǔ（第三声）声调不同，意思是舒服、舒展。", "树": "shù（第四声）与 shǔ（第三声）声调不同，意思是树。", "熟": "shú（第二声）与 shǔ（第三声）声调不同，意思是熟悉或成熟。", "主": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是主人。"}, "sentence_index": null, "correct_answer": "属"}, "level_3": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。“属”用于说明生肖，“我属马”是说我的生肖是马。"}, {"text": "生", "is_correct": false, "explanation": "搭配：“生”指出生，不说“我生马”，说生肖要用“属”。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理，“我修马”与生肖无关，句子说不通。"}, {"text": "配", "is_correct": false, "explanation": "搭配：“配”指配合、搭配，“我配马”不能表示生肖。"}], "explanations": {"属": "正确。“属”用于说明生肖，“我属马”是说我的生肖是马。", "生": "搭配：“生”指出生，不说“我生马”，说生肖要用“属”。", "修": "语义：“修”是修理，“我修马”与生肖无关，句子说不通。", "配": "搭配：“配”指配合、搭配，“我配马”不能表示生肖。"}, "sentence_index": 0, "correct_answer": "属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我属王，你属李。", "explanation": "这里应该用〈姓〉。“属”表示归属或类别，说人的姓氏要用“姓”。"}, {"text": "这只猫属小花，很可爱。", "explanation": "这里应该用〈叫〉。给动物起名字用“叫”，不用“属”。"}, {"text": "这个公司属十个人。", "explanation": "这里应该用〈有〉。“属”表示隶属或类别，不能用来说明人数，说公司有多少人要用“有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86952, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。属（shǔ）在此表示生肖。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是书。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，意思是树。"}, {"text": "煮", "is_correct": false, "explanation": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是煮。"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是叔叔。"}], "explanations": {"属": "正确。属（shǔ）在此表示生肖。", "书": "shū（第一声）与 shǔ（第三声）声调不同，意思是书。", "树": "shù（第四声）与 shǔ（第三声）声调不同，意思是树。", "煮": "zhǔ 与 shǔ 声母不同（zh 与 sh），声调相同，意思是煮。", "叔": "shū（第一声）与 shǔ（第三声）声调不同，意思是叔叔。"}, "sentence_index": null, "correct_answer": "属"}, "level_3": {"options": [{"text": "属", "is_correct": true, "explanation": "正确。“属”用于说明生肖，“属猴”是说生肖是猴。"}, {"text": "嫁", "is_correct": false, "explanation": "语义：“嫁”是出嫁，只能用于人，不能与“猴”搭配。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”要接帽子、眼镜等可以戴的东西，不接动物。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”要接可以悬挂的东西，“都挂猴”说不通。"}], "explanations": {"属": "正确。“属”用于说明生肖，“属猴”是说生肖是猴。", "嫁": "语义：“嫁”是出嫁，只能用于人，不能与“猴”搭配。", "戴": "搭配：“戴”要接帽子、眼镜等可以戴的东西，不接动物。", "挂": "搭配：“挂”要接可以悬挂的东西，“都挂猴”说不通。"}, "sentence_index": 6, "correct_answer": "属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我属汽车，你属什么？", "explanation": "这里应该接〈十二生肖〉中的动物。“属”表示生肖时只能接十二生肖的动物，“汽车”不是生肖，不能这样说。"}, {"text": "这个班属二月，都是新同学。", "explanation": "这里应该用〈在〉。“属”表示隶属，后面要接单位或地区，说时间要用“在”。"}, {"text": "这个小岛属三斤。", "explanation": "这里应该用〈重〉。“属”后面要接单位或地区，说重量要用“重”，“三斤”不能接“属”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我鸡属，他属狗。", "corrected_sentence": "我属鸡，他属狗。", "error_description": "错误：“鸡”放在了“属”前面。正确：“属”要放在动物名称前面，应说“我属鸡”，不能说“我鸡属”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校属了教育局。", "corrected_sentence": "这所学校属教育局。", "error_description": "错误：“属”后面加了“了”。“属”表示隶属，是状态动词，不能带“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
