INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86954, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "规模较大、内容广泛的商品或成就展览会。", "primary_collocate": null, "pronunciation": "bó lǎn huì", "ipa": "pwo˧˥ lan˨˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "这个城市每年都举办博览会。", "target_word": "博览会", "complexity_tier": "T3", "furigana": "zhè ge chéng shì měi nián dōu jǔ bàn bó lǎn huì", "sentence_source": "generated"}, {"text": "公司带着新产品去参加博览会。", "target_word": "博览会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博览会上有很多国家的商品。", "target_word": "博览会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博览会开了三天，吸引了很多客人。", "target_word": "博览会", "complexity_tier": "T3", "furigana": "bó lǎn huì kāi le sān tiān, xī yǐn le hěn duō kè rén", "sentence_source": "generated"}, {"text": "我们明天一起去逛博览会。", "target_word": "博览会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这届博览会的主题是绿色生活。", "target_word": "博览会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博览会开幕那天，会场里人很多。", "target_word": "博览会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博览会上认识了一位客户。", "target_word": "博览会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博览会展出了很多新车。", "target_word": "博览会", "complexity_tier": "T3", "furigana": "zhè ge bó lǎn huì zhǎn chū le hěn duō xīn chē", "sentence_source": "generated"}, {"text": "博览会结束后，工人开始收拾展台。", "target_word": "博览会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "届", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "博覽會", "label": "繁体"}, {"form": "汽车博览会", "label": "复合词"}], "register": "中性", "sense_fingerprint": "大规模的商品或成就展览会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d9b7acb-06c4-4953-b400-63e6e8a36ece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "博览会", "is_correct": true, "explanation": "博览会是规模较大的展览会，每年举办符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水体，不能被“举办”，句子说的是人为组织的活动。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“举办”后面接活动、会议或展览，不说“举办空气”。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是抽象的概念，不能被“举办”，与句中的展览活动不符。"}], "explanations": {"博览会": "博览会是规模较大的展览会，每年举办符合句意。", "河流": "语义：河流是自然水体，不能被“举办”，句子说的是人为组织的活动。", "空气": "搭配：“举办”后面接活动、会议或展览，不说“举办空气”。", "历史": "语义：历史是抽象的概念，不能被“举办”，与句中的展览活动不符。"}, "sentence_index": 0, "correct_answer": "博览会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他参观了一间博览会。", "explanation": "这里应该用〈场〉。“间”用于房屋、房间，博览会是活动，应该用“场”。"}, {"text": "他参观了一只博览会。", "explanation": "这里应该用〈场〉。“只”多用于动物或成对的小物件，博览会是活动，应该用“场”。"}, {"text": "他参观了一把博览会。", "explanation": "这里应该用〈场〉。“把”用于有柄的东西，博览会是活动，应该用“场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "博览会", "is_correct": true, "explanation": "博览会有开幕仪式，会场里人很多也与之相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是活动，不会“开幕”，与会场里的人群不符。"}, {"text": "书籍", "is_correct": false, "explanation": "搭配：“开幕”用于展览、活动等，书籍不说“开幕”。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是家电，不会“开幕”，与会场的活动场景不符。"}], "explanations": {"博览会": "博览会有开幕仪式，会场里人很多也与之相符。", "天气": "语义：天气不是活动，不会“开幕”，与会场里的人群不符。", "书籍": "搭配：“开幕”用于展览、活动等，书籍不说“开幕”。", "空调": "语义：空调是家电，不会“开幕”，与会场的活动场景不符。"}, "sentence_index": 6, "correct_answer": "博览会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他参观了一辆博览会。", "explanation": "这里应该用〈场〉。“辆”用于车辆，博览会是活动，应该用“场”。"}, {"text": "他参观了一顶博览会。", "explanation": "这里应该用〈场〉。“顶”用于帽子、帐篷等，博览会应该用“场”。"}, {"text": "他参观了一件博览会。", "explanation": "这里应该用〈场〉。“件”用于衣物或事情，博览会应该用“场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去看了一只博览会。", "corrected_sentence": "我们去看了一场博览会。", "error_description": "“一只博览会”错误。博览会是活动，量词应用“场”或“届”，应写作“一场博览会”；“只”不用于活动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候去过博览会过。", "corrected_sentence": "我小时候去过博览会。", "error_description": "错误：句末多出一个「过」。「过」应紧跟动词表示经历，「去过博览会」已经完整，应删去句末的「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "后人是很久以后才出生的人。", "primary_collocate": null, "pronunciation": "hòu rén", "ipa": "xou̯⁵¹ ʐən³⁵", "syllable_count": 2, "sentences": [{"text": "古人留下的书，后人还在读。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后人从这些老画里认识了当时的生活。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是为后人修的。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天做的事，后人会看到。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年以后，后人才明白他的想法。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，要给后人留下干净的河。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后人常常拿这位诗人和别的诗人比。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些历史故事让后人知道以前发生了什么。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本日记，想让后人了解这个时代。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一千年前的城墙，后人至今还在保护。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很久以后才出生的人，泛指后来的一代代人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6db36e4c-cdd6-4cfb-9f57-3ab5220c3d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后人", "is_correct": true, "explanation": "后人：很久以后才出生的人，“留下的书，还在读”正好指这些人。"}, {"text": "祖先", "is_correct": false, "explanation": "语义：祖先已经去世，不能“还在读”古人留下的书。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“还在读”的施事须是能读书的人，“石头”不能与“读”搭配。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不会读书，句子不通。"}], "explanations": {"后人": "后人：很久以后才出生的人，“留下的书，还在读”正好指这些人。", "祖先": "语义：祖先已经去世，不能“还在读”古人留下的书。", "石头": "搭配：“还在读”的施事须是能读书的人，“石头”不能与“读”搭配。", "小鸟": "语义：小鸟不会读书，句子不通。"}, "sentence_index": 0, "correct_answer": "后人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的后人有五只。", "explanation": "这里应该用〈后代〉。〈后人〉专指人，猫的子代要说〈后代〉。"}, {"text": "后人在一百年前就修好了这座桥，很多人都来看。", "explanation": "这里应该用〈祖先〉。〈后人〉指很久以后才出生的人，不能用于一百年前已经完成的事。"}, {"text": "今天在座的后人都是我的老同学。", "explanation": "这里应该用〈同辈〉。〈后人〉指很久以后才出生的人，不能指同时代的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后人", "is_correct": true, "explanation": "后人：很久以后才出生的人，能够“拿这位诗人和别的诗人比”。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“拿……比”的主体要求是能比较的人，“花朵”不能作比较的主体。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会比较诗人，句子不通。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不能拿诗人来做比较，句子没有意义。"}], "explanations": {"后人": "后人：很久以后才出生的人，能够“拿这位诗人和别的诗人比”。", "花朵": "搭配：“拿……比”的主体要求是能比较的人，“花朵”不能作比较的主体。", "河流": "语义：河流不会比较诗人，句子不通。", "云朵": "语义：云朵不能拿诗人来做比较，句子没有意义。"}, "sentence_index": 6, "correct_answer": "后人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树的后人长得很高。", "explanation": "这里应该用〈后代〉。〈后人〉专指人，不用于树木；树木的子代要说〈后代〉。"}, {"text": "后人昨天在这里和我们一起开会。", "explanation": "这里应该用〈大家〉或〈同事〉。〈后人〉指很久以后才出生的人，不能和我们同时开会。"}, {"text": "我们的后人一千年前就修好了这座城墙。", "explanation": "时间上矛盾：〈后人〉指很久以后才出生的人，不能在一千年前修城墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些画是留给很多只后人的。", "corrected_sentence": "这些画是留给很多后人的。", "error_description": "量词错误：“后人”指人，“只”多用于动物，不能用来修饰人。“很多”后直接接名词即可。正确说法是“这些画是留给很多后人的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事，很多只后人都会记住。", "corrected_sentence": "这件事，很多后人都会记住。", "error_description": "量词错误：“后人”指人，“只”多用于动物，不能用来数人。“很多”后直接接名词即可，不必加“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
