INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86956, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指后代的人；子孙。", "primary_collocate": null, "pronunciation": "hòu rén", "ipa": "xou̯⁵¹ ʐən³⁵", "syllable_count": 2, "sentences": [{"text": "他没有后人，家里只有他一个人。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的后人住在南方。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王家的后人今天来看老房子。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是孔子的后人，家在山东。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生希望后人能记住家里的规矩。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是这位将军的后人。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片是他的后人留下的。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人大多是他的后人。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，我们家的后人别忘了祖先。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的后人现在还住着这座老房子。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某个人或某个家族的子孙后代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6db36e4c-cdd6-4cfb-9f57-3ab5220c3d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后人", "is_correct": true, "explanation": "后人：某人的子孙，“他没有后人”指他没有子孙。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是指家人的词，“家里只有他一个人”说明他没有子孙，“空气”与句意不符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：“没有太阳”与常识矛盾，句子不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：后半句说的是家里人的情况，“影子”与家人无关，“没有影子”不能解释这一点。"}], "explanations": {"后人": "后人：某人的子孙，“他没有后人”指他没有子孙。", "空气": "语义：空气不是指家人的词，“家里只有他一个人”说明他没有子孙，“空气”与句意不符。", "太阳": "语义：“没有太阳”与常识矛盾，句子不通。", "影子": "语义：后半句说的是家里人的情况，“影子”与家人无关，“没有影子”不能解释这一点。"}, "sentence_index": 0, "correct_answer": "后人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的后人有五只。", "explanation": "这里应该用〈后代〉。〈后人〉专指人，猫的子代要说〈后代〉。"}, {"text": "他是王家的一棵后人。", "explanation": "这里量词用错：“棵”用于树木，不用于人，这里应说〈位〉或〈个〉。"}, {"text": "他的后人比他更早出生。", "explanation": "这里应该用〈祖先〉。〈后人〉指子孙，应比本人晚出生；比他更早出生的应是〈祖先〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后人", "is_correct": true, "explanation": "后人：某人的子孙，“留下的”指这张照片是子孙留下的。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能“留下”照片，句子说的是人留下的东西。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会留下老照片，句子不通。"}, {"text": "钟", "is_correct": false, "explanation": "搭配：“留下”的施事应是人，“钟”不能作施事。"}], "explanations": {"后人": "后人：某人的子孙，“留下的”指这张照片是子孙留下的。", "房子": "语义：房子不能“留下”照片，句子说的是人留下的东西。", "河流": "语义：河流不会留下老照片，句子不通。", "钟": "搭配：“留下”的施事应是人，“钟”不能作施事。"}, "sentence_index": 6, "correct_answer": "后人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这群羊的后人都很健康。", "explanation": "这里应该用〈后代〉。〈后人〉专指人，羊的子代要说〈后代〉。"}, {"text": "他家有一座后人，很孝顺。", "explanation": "这里量词用错：“座”用于山、房屋等，不用于人，这里应说〈位〉或〈个〉。"}, {"text": "她的后人在她出生前就已经去世了。", "explanation": "时间上矛盾：后人应晚于本人出生，不能在她出生前去世。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的两只后人住在外地。", "corrected_sentence": "他的两个后人住在外地。", "error_description": "量词错误：“后人”指人，应用量词“个”，不能用“只”（“只”多用于动物等）。正确说法是“他的两个后人住在外地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的几只后人去年搬到北京了。", "corrected_sentence": "他的几个后人去年搬到北京了。", "error_description": "量词错误：“后人”指人，应用量词“个”，不能用“只”。“他的几只后人”是错误的，应说“他的几个后人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
