INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卡通是画出来的会动的故事，小朋友都爱看。", "primary_collocate": null, "pronunciation": "kǎ tōng", "ipa": "kʰa˨˩˦ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "弟弟每天晚上都要看卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部卡通的故事很有意思。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友最喜欢看卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢听卡通里的歌。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我陪孩子看了一部卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个卡通里有一只会说话的小狗。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完卡通，他才去做作业。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在电视前看卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候很爱看卡通，现在还记得。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡通里的小熊总是帮助别人。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "卡通片", "label": "复合"}], "register": "口语", "sense_fingerprint": "画出来的会动的故事，孩子爱看的动画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e7f192b-be0b-4077-9581-3be7d265068c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐", "is_correct": false, "explanation": "搭配：“看”不能搭配“音乐”，听音乐才说得通。"}, {"text": "卡通", "is_correct": true, "explanation": "“卡通”指动画片，“看”可以搭配，符合“每天晚上都要看”。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”与“每天晚上”时间矛盾，不能每晚都看早饭。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“看钢琴”不通，钢琴要和“弹”搭配。"}], "explanations": {"音乐": "搭配：“看”不能搭配“音乐”，听音乐才说得通。", "卡通": "“卡通”指动画片，“看”可以搭配，符合“每天晚上都要看”。", "早饭": "语义：“早饭”与“每天晚上”时间矛盾，不能每晚都看早饭。", "钢琴": "搭配：“看钢琴”不通，钢琴要和“弹”搭配。"}, "sentence_index": 0, "correct_answer": "卡通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我陪孩子踢了一会儿卡通。", "explanation": "这里应该用〈足球〉。卡通是画出来会动的故事，不是球，不能踢。"}, {"text": "我昨天看了一只卡通。", "explanation": "这里不能用“只”来数卡通。动画片要用“部”，“只”多用于动物。"}, {"text": "妈妈给孩子倒了一杯卡通。", "explanation": "这里应该用〈牛奶〉。卡通是画出来会动的故事，不是饮料，不能倒进杯子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "搭配：“看”不能搭配“饭”，吃饭才说得通。"}, {"text": "卡通", "is_correct": true, "explanation": "“卡通”指动画片，“看完”可以搭配，符合“看完……才去做作业”。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“看”不能搭配“汽油”，“看完汽油”句意不通。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：“看”不能搭配“面粉”，“看完面粉”句意不通。"}], "explanations": {"饭": "搭配：“看”不能搭配“饭”，吃饭才说得通。", "卡通": "“卡通”指动画片，“看完”可以搭配，符合“看完……才去做作业”。", "汽油": "搭配：“看”不能搭配“汽油”，“看完汽油”句意不通。", "面粉": "搭配：“看”不能搭配“面粉”，“看完面粉”句意不通。"}, "sentence_index": 6, "correct_answer": "卡通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把卡通切成了几块，放进锅里。", "explanation": "这里应该用〈土豆〉。卡通是画出来会动的故事，不是食材，不能切块下锅。"}, {"text": "孩子们喜欢骑着卡通去上学。", "explanation": "这里应该用〈自行车〉。卡通是画出来会动的故事，不是交通工具，不能骑。"}, {"text": "我买了一台卡通。", "explanation": "这里不能用“台”来数卡通。动画片要用“部”，“台”多用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天晚上我和弟弟看了一本卡通。", "corrected_sentence": "昨天晚上我和弟弟看了一部卡通。", "error_description": "量词错误：动画片要用“部”，不能用“本”（“本”用于书）。应说“看了一部卡通”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看完成卡通才去睡觉。", "corrected_sentence": "他看完卡通才去睡觉。", "error_description": "补语错误：“看完”是动补结构，“完成”不能作“看”的补语，多出的“成”使句子不通；应说“看完卡通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
