INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86958, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以夸张、简化的手法绘制的画面或动画片。", "primary_collocate": null, "pronunciation": "kǎ tōng", "ipa": "kʰa˨˩˦ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这家店的墙上画着可爱的卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用卡通风格画了一张自画像。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海报上的卡通形象很夸张。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师把照片改成了卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手机壳上印着卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种卡通的画法很简单。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请画家为新产品画一个卡通。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡通里的老虎画得很胖。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢穿印着卡通图案的衣服。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的卡通讽刺了这件事。", "target_word": "卡通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "卡通片", "label": "复合"}], "register": "口语", "sense_fingerprint": "夸张简化手法画成的图画或形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e7f192b-be0b-4077-9581-3be7d265068c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐", "is_correct": false, "explanation": "搭配：“画”不能搭配“音乐”，画的是图像。"}, {"text": "卡通", "is_correct": true, "explanation": "“卡通”指画出来的图案，“画着”可以搭配，符合“墙上画着可爱的……”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不是可以画在墙上的形象。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“画”不能搭配“歌曲”，歌曲要用“唱”或“听”。"}], "explanations": {"音乐": "搭配：“画”不能搭配“音乐”，画的是图像。", "卡通": "“卡通”指画出来的图案，“画着”可以搭配，符合“墙上画着可爱的……”。", "作业": "语义：“作业”是学习任务，不是可以画在墙上的形象。", "歌曲": "搭配：“画”不能搭配“歌曲”，歌曲要用“唱”或“听”。"}, "sentence_index": 0, "correct_answer": "卡通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我陪孩子玩了一局卡通。", "explanation": "这里应该用〈卡牌〉。卡通指画出来的画面或动画片，不是纸牌。"}, {"text": "他画了一根卡通。", "explanation": "这里不能用“根”来数卡通。画出来的图案要用“张”或“幅”，“根”多用于细长的东西。"}, {"text": "他用卡通擦了桌子。", "explanation": "这里应该用〈抹布〉。卡通指画面或动画片，不能用来擦东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "搭配：“画”不能搭配“声音”，画的是图像。"}, {"text": "卡通", "is_correct": true, "explanation": "“卡通”指画出来的图案，“画一个”可以搭配，符合“请画家为新产品画一个……”。"}, {"text": "合同", "is_correct": false, "explanation": "语义：“合同”是文件，不是可以画出来的东西。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是金额，不能被画成图案，句意不通。"}], "explanations": {"声音": "搭配：“画”不能搭配“声音”，画的是图像。", "卡通": "“卡通”指画出来的图案，“画一个”可以搭配，符合“请画家为新产品画一个……”。", "合同": "语义：“合同”是文件，不是可以画出来的东西。", "价格": "语义：“价格”是金额，不能被画成图案，句意不通。"}, "sentence_index": 6, "correct_answer": "卡通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把卡通递给收银员，刷了一下。", "explanation": "这里应该用〈银行卡〉。卡通指画面或动画片，不是刷卡用的卡片。"}, {"text": "她买了一台卡通。", "explanation": "这里不能用“台”来数卡通。画出来的图案要用“张”或“幅”，“台”多用于机器。"}, {"text": "妈妈每天给我煮一碗卡通当早饭。", "explanation": "这里应该用〈面条〉。卡通指画面或动画片，不是食物，不能煮来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上贴着一首卡通。", "corrected_sentence": "墙上贴着一张卡通。", "error_description": "量词错误：卡通是画出来的图案，应该用“张”，不能用“首”（“首”多用于诗歌、歌曲）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把卡通画了好了。", "corrected_sentence": "他把卡通画好了。", "error_description": "“了”的位置错误：“画”和“好”之间不能加“了”，“把卡通画好了”的“了”要放在补语“好”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
