INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86959, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "原子是世界上东西里最小的一种小粒子。我们看不见它。", "primary_collocate": null, "pronunciation": "yuán zǐ", "ipa": "ɥɛn˧˥ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "原子非常小，我们用眼睛看不见。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水是由很小的原子组成的。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，世界上的东西都有原子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个原子比头发还要小很多。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看不见原子，可是它真的有。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书、桌子和空气都有原子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明问老师：原子有多小？", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原子太小了，要用特别的机器才能看到。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的身体里也有很多原子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了原子是什么。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "原子核", "label": "复合"}], "register": "中性", "sense_fingerprint": "组成万物的、眼睛看不见的最小粒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原子", "is_correct": true, "explanation": "原子：组成万物、肉眼看不见的最小粒子。"}, {"text": "原则", "is_correct": false, "explanation": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。"}, {"text": "源自", "is_correct": false, "explanation": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。"}, {"text": "原址", "is_correct": false, "explanation": "原址（yuán zhǐ）声母与“原子”不同（zh 与 z），意思是原来的地址。"}, {"text": "园子", "is_correct": false, "explanation": "园子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是花园。"}], "explanations": {"原子": "原子：组成万物、肉眼看不见的最小粒子。", "原则": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。", "源自": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。", "原址": "原址（yuán zhǐ）声母与“原子”不同（zh 与 z），意思是原来的地址。", "园子": "园子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是花园。"}, "sentence_index": null, "correct_answer": "原子"}, "level_3": {"options": [{"text": "原子", "is_correct": true, "explanation": "正确：原子是肉眼看不见的最小粒子，与“非常小”“看不见”相符。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体形巨大，与“非常小”矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是肉眼能看见的东西，与“我们用眼睛看不见”矛盾。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“非常小”不用来形容抽象的语言，这样说不通。"}], "explanations": {"原子": "正确：原子是肉眼看不见的最小粒子，与“非常小”“看不见”相符。", "大象": "体貌：大象体形巨大，与“非常小”矛盾。", "手机": "语义：手机是肉眼能看见的东西，与“我们用眼睛看不见”矛盾。", "语言": "搭配：“非常小”不用来形容抽象的语言，这样说不通。"}, "sentence_index": 0, "correct_answer": "原子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上放着一朵原子。", "explanation": "这里应该用〈个〉。“朵”用于花，不能用来数原子。"}, {"text": "他手里拿着一座原子。", "explanation": "这里应该用〈个〉。“座”用于山、桥、建筑等大而固定的东西，不能用来数原子。"}, {"text": "老师拿出一条原子给我们看。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，原子不能用“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86959, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "原子", "is_correct": true, "explanation": "原子：组成万物、肉眼看不见的最小粒子。"}, {"text": "院子", "is_correct": false, "explanation": "院子（yuàn zi）第一个音节声调与“原子”不同（第四声），意思是院落。"}, {"text": "原则", "is_correct": false, "explanation": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。"}, {"text": "源自", "is_correct": false, "explanation": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。"}, {"text": "圆子", "is_correct": false, "explanation": "圆子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是一种用糯米做的食品。"}], "explanations": {"原子": "原子：组成万物、肉眼看不见的最小粒子。", "院子": "院子（yuàn zi）第一个音节声调与“原子”不同（第四声），意思是院落。", "原则": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。", "源自": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。", "圆子": "圆子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是一种用糯米做的食品。"}, "sentence_index": null, "correct_answer": "原子"}, "level_3": {"options": [{"text": "原子", "is_correct": true, "explanation": "正确：问的是肉眼看不见的最小粒子有多小。"}, {"text": "大海", "is_correct": false, "explanation": "体貌：大海浩瀚广阔，不能问它“有多小”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳非常巨大，问它“有多小”不合逻辑。"}, {"text": "银河", "is_correct": false, "explanation": "语义：银河是巨大的星系，问它“有多小”不合逻辑。"}], "explanations": {"原子": "正确：问的是肉眼看不见的最小粒子有多小。", "大海": "体貌：大海浩瀚广阔，不能问它“有多小”。", "太阳": "语义：太阳非常巨大，问它“有多小”不合逻辑。", "银河": "语义：银河是巨大的星系，问它“有多小”不合逻辑。"}, "sentence_index": 6, "correct_answer": "原子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "氧是一种很常见的原子。", "explanation": "这里应该用〈元素〉。氧是一类物质，属于元素；“原子”指单个的微粒，不用来说“一种”物质。"}, {"text": "原子是由好几个原子组成的。", "explanation": "这里应该用〈分子〉。由原子组成的是分子，原子不能由原子组成。"}, {"text": "质子是一种很小的原子。", "explanation": "这里应该用〈粒子〉。质子是原子核的组成部分，比原子更小，不是原子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每只原子都非常小。", "corrected_sentence": "每个原子都非常小。", "error_description": "“原子”的量词应用“个”。“只”多用于动物等，错误形式是“每只原子”，正确形式是“每个原子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家研究了很多原子们。", "corrected_sentence": "科学家研究了很多原子。", "error_description": "“原子”是物，不能加“们”。“们”只用于人或拟人的群体，应说“很多原子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
