INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "构成化学元素的最小微粒，由原子核和核外电子组成。", "primary_collocate": null, "pronunciation": "yuán zǐ", "ipa": "ɥɛn˧˥ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "原子由原子核和电子组成。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氢是结构最简单的原子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个水分子里有三个原子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学变化中，原子不能再分。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原子里面有电子在转动。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同元素的原子，大小和重量不同。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钠的原子比氧的重。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个原子的样子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种元素都有自己的原子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用机器看到了单个原子。", "target_word": "原子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "原子核", "label": "复合"}], "register": "中性", "sense_fingerprint": "构成化学元素的最小微粒，含原子核与电子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原子", "is_correct": true, "explanation": "原子：构成化学元素的最小微粒，由原子核和电子组成。"}, {"text": "原则", "is_correct": false, "explanation": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。"}, {"text": "源自", "is_correct": false, "explanation": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。"}, {"text": "原址", "is_correct": false, "explanation": "原址（yuán zhǐ）声母与“原子”不同（zh 与 z），意思是原来的地址。"}, {"text": "圆子", "is_correct": false, "explanation": "圆子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是一种用糯米做的食品。"}], "explanations": {"原子": "原子：构成化学元素的最小微粒，由原子核和电子组成。", "原则": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。", "源自": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。", "原址": "原址（yuán zhǐ）声母与“原子”不同（zh 与 z），意思是原来的地址。", "圆子": "圆子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是一种用糯米做的食品。"}, "sentence_index": null, "correct_answer": "原子"}, "level_3": {"options": [{"text": "原子", "is_correct": true, "explanation": "正确：原子由原子核和电子组成，与句意相符。"}, {"text": "中子", "is_correct": false, "explanation": "语义：中子是原子核的组成部分，本身并不由原子核和电子组成。"}, {"text": "细胞", "is_correct": false, "explanation": "语义：细胞由细胞核、细胞质等组成，不是由原子核和电子组成。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象是体形巨大的动物，不由原子核和电子组成。"}], "explanations": {"原子": "正确：原子由原子核和电子组成，与句意相符。", "中子": "语义：中子是原子核的组成部分，本身并不由原子核和电子组成。", "细胞": "语义：细胞由细胞核、细胞质等组成，不是由原子核和电子组成。", "大象": "体貌：大象是体形巨大的动物，不由原子核和电子组成。"}, "sentence_index": 0, "correct_answer": "原子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "实验室里有一根原子。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，原子不能用“根”来数。"}, {"text": "桌上放着一张原子。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，原子不能用“张”来数。"}, {"text": "墙上挂着一幅原子。", "explanation": "这里应该用〈个〉。“幅”用于画、字等，不能用来数原子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86960, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "原子", "is_correct": true, "explanation": "原子：构成化学元素的最小微粒，由原子核和电子组成。"}, {"text": "院子", "is_correct": false, "explanation": "院子（yuàn zi）第一个音节声调与“原子”不同（第四声），意思是院落。"}, {"text": "原则", "is_correct": false, "explanation": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。"}, {"text": "源自", "is_correct": false, "explanation": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。"}, {"text": "园子", "is_correct": false, "explanation": "园子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是花园。"}], "explanations": {"原子": "原子：构成化学元素的最小微粒，由原子核和电子组成。", "院子": "院子（yuàn zi）第一个音节声调与“原子”不同（第四声），意思是院落。", "原则": "原则（yuán zé）第二个音节声调与“原子”不同（第二声），意思是行为或言论所依据的道理。", "源自": "源自（yuán zì）第二个音节声调与“原子”不同（第四声），意思是起源于。", "园子": "园子（yuán zi）第二个音节为轻声，与“原子”声调不同，意思是花园。"}, "sentence_index": null, "correct_answer": "原子"}, "level_3": {"options": [{"text": "原子", "is_correct": true, "explanation": "正确：比较的是不同元素原子的重量，与句意相符。"}, {"text": "电子", "is_correct": false, "explanation": "语义：电子比原子轻得多，“钠的电子比氧的原子重”不符合事实。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是混合气体，不是钠的组成部分，这样比较没有意义。"}, {"text": "个子", "is_correct": false, "explanation": "搭配：“个子”指人的身高，不用于形容钠这样的物质。"}], "explanations": {"原子": "正确：比较的是不同元素原子的重量，与句意相符。", "电子": "语义：电子比原子轻得多，“钠的电子比氧的原子重”不符合事实。", "空气": "语义：空气是混合气体，不是钠的组成部分，这样比较没有意义。", "个子": "搭配：“个子”指人的身高，不用于形容钠这样的物质。"}, "sentence_index": 6, "correct_answer": "原子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁是一种很重的原子。", "explanation": "这里应该用〈元素〉。铁是一种物质，属于元素；“原子”指单个的微粒，不用来说“一种”物质。"}, {"text": "这种原子是由三个原子组成的。", "explanation": "这里应该用〈分子〉。由三个原子组成的是分子，原子不能由原子组成。"}, {"text": "中子是一种很小的原子。", "explanation": "这里应该用〈粒子〉。中子是原子核的组成部分，比原子小，不是原子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每只原子都有原子核。", "corrected_sentence": "每个原子都有原子核。", "error_description": "“原子”的量词应为“个”，“只”一般用于动物等。错误形式是“每只原子”，正确形式是“每个原子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验室里有很多原子们。", "corrected_sentence": "实验室里有很多原子。", "error_description": "“原子”是物，不能加“们”。“们”只用于人或拟人的群体，应说“很多原子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
