INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86961, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "股可以用来数一条一条的东西，也可以用来数一团一团的气味和力气。", "primary_collocate": null, "pronunciation": "gǔ", "ipa": "ku˨˩˦", "syllable_count": 1, "sentences": [{"text": "一股香味从厨房飘出来。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边吹来一股凉风。", "target_word": "股", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他身上有一股烟味。", "target_word": "股", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我突然有一股力气，把箱子搬起来了。", "target_word": "股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里流出一股清水。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上有一股臭味，大家都捂着鼻子。", "target_word": "股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟囱里冒出一股黑烟。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到他的笑，我心里升起一股暖意。", "target_word": "股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里有一股奇怪的味道。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一股水流进了小河里。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股", "label": "数量"}, {"form": "一股股", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词，数气味、力气和细流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86961, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "股", "is_correct": true, "explanation": "股 gǔ，量词，用于一团一团的气味、力气或成条的东西。"}, {"text": "姑", "is_correct": false, "explanation": "gū（第一声）与 gǔ（第三声）声调不同，意思是姑姑或姑娘。"}, {"text": "故", "is_correct": false, "explanation": "gù（第四声）与 gǔ（第三声）声调不同，意思是缘故。"}, {"text": "苦", "is_correct": false, "explanation": "kǔ 与 gǔ 声母不同（k 与 g），声调相同，意思是味道苦。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ 与 gǔ 声母不同（h 与 g），声调相同，意思是老虎。"}], "explanations": {"股": "股 gǔ，量词，用于一团一团的气味、力气或成条的东西。", "姑": "gū（第一声）与 gǔ（第三声）声调不同，意思是姑姑或姑娘。", "故": "gù（第四声）与 gǔ（第三声）声调不同，意思是缘故。", "苦": "kǔ 与 gǔ 声母不同（k 与 g），声调相同，意思是味道苦。", "虎": "hǔ 与 gǔ 声母不同（h 与 g），声调相同，意思是老虎。"}, "sentence_index": null, "correct_answer": "股"}, "level_3": {"options": [{"text": "股", "is_correct": true, "explanation": "股：量词，用于一团一团的气味，“一股香味”通顺。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不能修饰香味。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于粒状的小东西，香味不能用它来数。"}, {"text": "双", "is_correct": false, "explanation": "语义：“双”指成对的东西，香味不成对，句子不通。"}], "explanations": {"股": "股：量词，用于一团一团的气味，“一股香味”通顺。", "条": "搭配：“条”用于细长的东西，不能修饰香味。", "颗": "搭配：“颗”用于粒状的小东西，香味不能用它来数。", "双": "语义：“双”指成对的东西，香味不成对，句子不通。"}, "sentence_index": 0, "correct_answer": "股"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里突然传来一股雷声。", "explanation": "这里应该用〈阵〉。“股”用于气味、力气或成股涌出的东西，雷声这类短暂的声响要用“阵”。"}, {"text": "广场上走来一股大象，都是来看演出的。", "explanation": "这里应该用〈群〉。“股”用于气味、力气或成股涌出的东西，成群的动物要说“一群大象”，不能用“股”。"}, {"text": "村子后面有一股小山。", "explanation": "这里应该用〈座〉。“股”不用于山这类大型固定物，山要说“一座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86961, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "股", "is_correct": true, "explanation": "股 gǔ，量词，用于一团一团的气味、力气或成条的东西。"}, {"text": "固", "is_correct": false, "explanation": "gù（第四声）与 gǔ（第三声）声调不同，意思是牢固。"}, {"text": "顾", "is_correct": false, "explanation": "gù（第四声）与 gǔ（第三声）声调不同，意思是照顾。"}, {"text": "估", "is_correct": false, "explanation": "gū（第一声）与 gǔ（第三声）声调不同，意思是估计。"}, {"text": "孤", "is_correct": false, "explanation": "gū（第一声）与 gǔ（第三声）声调不同，意思是孤单。"}], "explanations": {"股": "股 gǔ，量词，用于一团一团的气味、力气或成条的东西。", "固": "gù（第四声）与 gǔ（第三声）声调不同，意思是牢固。", "顾": "gù（第四声）与 gǔ（第三声）声调不同，意思是照顾。", "估": "gū（第一声）与 gǔ（第三声）声调不同，意思是估计。", "孤": "gū（第一声）与 gǔ（第三声）声调不同，意思是孤单。"}, "sentence_index": null, "correct_answer": "股"}, "level_3": {"options": [{"text": "股", "is_correct": true, "explanation": "股：量词，用于一团一团的烟气，“一股黑烟”通顺。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的器具，烟不能用“把”来数。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋这类大型固定物，不能修饰烟。"}, {"text": "名", "is_correct": false, "explanation": "语义：“名”用于人，烟不是人，不能用“名”来数。"}], "explanations": {"股": "股：量词，用于一团一团的烟气，“一股黑烟”通顺。", "把": "搭配：“把”用于有柄的器具，烟不能用“把”来数。", "座": "搭配：“座”用于山、房屋这类大型固定物，不能修饰烟。", "名": "语义：“名”用于人，烟不是人，不能用“名”来数。"}, "sentence_index": 6, "correct_answer": "股"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上有一股裂缝，得赶紧修。", "explanation": "这里应该用〈道〉。“股”用于气味、力气或成条的东西，裂缝这类线形痕迹要用“道”。"}, {"text": "下午突然下了一股大雨。", "explanation": "这里应该用〈场〉。“股”不用于雨这类一阵一阵的天气现象，应说“一场大雨”。"}, {"text": "他在纸上写了一股诗。", "explanation": "这里应该用〈首〉。“股”用于气味、力气或成条的东西，诗要用“首”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋子里飘来股一烤肉的香味。", "corrected_sentence": "屋子里飘来一股烤肉的香味。", "error_description": "语序错误：数词「一」应放在量词「股」前面，应说「一股烤肉的香味」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
