INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86962, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于成条的东西，也用于气体、气味、力量等。", "primary_collocate": null, "pronunciation": "gǔ", "ipa": "ku˨˩˦", "syllable_count": 1, "sentences": [{"text": "一股清水从山上流下来。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门一开，一股冷气冲了进来。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这股力量让他赢了比赛。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汤里有一股鱼的味道。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一股泉水从石头里流出来。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们心里都有一股热情。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我闻到一股花香。", "target_word": "股", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把绳子分成两股。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一股风把门吹开了。", "target_word": "股", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有一股不服输的劲儿。", "target_word": "股", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股", "label": "数量"}, {"form": "一股股", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词，用于成条物、气体、气味、力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87bd48c-16e6-4375-b563-41529acc3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86962, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "股", "is_correct": true, "explanation": "股 gǔ，量词，用于成条的东西，也用于气体、气味、力量。"}, {"text": "苦", "is_correct": false, "explanation": "kǔ 与 gǔ 声母不同（k 与 g），声调相同，意思是味道苦。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ 与 gǔ 声母不同（h 与 g），声调相同，意思是老虎。"}, {"text": "估", "is_correct": false, "explanation": "gū（第一声）与 gǔ（第三声）声调不同，意思是估计。"}, {"text": "固", "is_correct": false, "explanation": "gù（第四声）与 gǔ（第三声）声调不同，意思是牢固。"}], "explanations": {"股": "股 gǔ，量词，用于成条的东西，也用于气体、气味、力量。", "苦": "kǔ 与 gǔ 声母不同（k 与 g），声调相同，意思是味道苦。", "虎": "hǔ 与 gǔ 声母不同（h 与 g），声调相同，意思是老虎。", "估": "gū（第一声）与 gǔ（第三声）声调不同，意思是估计。", "固": "gù（第四声）与 gǔ（第三声）声调不同，意思是牢固。"}, "sentence_index": null, "correct_answer": "股"}, "level_3": {"options": [{"text": "股", "is_correct": true, "explanation": "股：量词，用于成条流动的水，“一股清水”通顺。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，水不能用“本”来数。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，水不能用“张”来数。"}, {"text": "位", "is_correct": false, "explanation": "语义：“位”用于人，水不是人，句子不通。"}], "explanations": {"股": "股：量词，用于成条流动的水，“一股清水”通顺。", "本": "搭配：“本”用于书册，水不能用“本”来数。", "张": "搭配：“张”用于平面的东西，水不能用“张”来数。", "位": "语义：“位”用于人，水不是人，句子不通。"}, "sentence_index": 0, "correct_answer": "股"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋外突然传来一股巨响。", "explanation": "这里应该用〈声〉。“股”用于气味、气体、力量这类一团一团的东西，巨响要说“一声”。"}, {"text": "远处有一股高山。", "explanation": "这里应该用〈座〉。“股”不用于山这类大型固定物，山要说“一座”。"}, {"text": "他买了一股新鞋，穿上很舒服。", "explanation": "这里应该用〈双〉。“股”用于气味、力气或成条的东西，鞋要用“双”，不能说“一股鞋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86962, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "股", "is_correct": true, "explanation": "股 gǔ，量词，用于成条的东西，也用于气体、气味、力量。"}, {"text": "姑", "is_correct": false, "explanation": "gū（第一声）与 gǔ（第三声）声调不同，意思是姑姑。"}, {"text": "故", "is_correct": false, "explanation": "gù（第四声）与 gǔ（第三声）声调不同，意思是缘故。"}, {"text": "孤", "is_correct": false, "explanation": "gū（第一声）与 gǔ（第三声）声调不同，意思是孤单。"}, {"text": "顾", "is_correct": false, "explanation": "gù（第四声）与 gǔ（第三声）声调不同，意思是照顾。"}], "explanations": {"股": "股 gǔ，量词，用于成条的东西，也用于气体、气味、力量。", "姑": "gū（第一声）与 gǔ（第三声）声调不同，意思是姑姑。", "故": "gù（第四声）与 gǔ（第三声）声调不同，意思是缘故。", "孤": "gū（第一声）与 gǔ（第三声）声调不同，意思是孤单。", "顾": "gù（第四声）与 gǔ（第三声）声调不同，意思是照顾。"}, "sentence_index": null, "correct_answer": "股"}, "level_3": {"options": [{"text": "股", "is_correct": true, "explanation": "股：量词，用于气味，“一股花香”通顺。"}, {"text": "副", "is_correct": false, "explanation": "搭配：“副”用于成套的东西，花香不能用“副”来数。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于粒状的东西，花香不能用“颗”来数。"}, {"text": "名", "is_correct": false, "explanation": "语义：“名”用于人，花香不是人，句子不通。"}], "explanations": {"股": "股：量词，用于气味，“一股花香”通顺。", "副": "搭配：“副”用于成套的东西，花香不能用“副”来数。", "颗": "搭配：“颗”用于粒状的东西，花香不能用“颗”来数。", "名": "语义：“名”用于人，花香不是人，句子不通。"}, "sentence_index": 6, "correct_answer": "股"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在灯下读了一股书。", "explanation": "这里应该用〈本〉。“股”用于气味、力气或成条的东西，书要用“本”。"}, {"text": "他把一股画挂在墙上。", "explanation": "这里应该用〈幅〉。“股”用于气味、力气或成条的东西，画要用“幅”。"}, {"text": "我们唱了一股歌，大家都很开心。", "explanation": "这里应该用〈首〉。“股”不用于歌曲，歌要说“一首”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户一开，股一冷风吹了进来。", "corrected_sentence": "窗户一开，一股冷风吹了进来。", "error_description": "语序错误：数词「一」应放在量词「股」前面，应说「一股冷风」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房里飘出一股一把烤面包的香气。", "corrected_sentence": "厨房里飘出一股烤面包的香气。", "error_description": "量词错误：「香气」前重复了两个量词「一股」和「一把」，只应保留「一股」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51211d4f-3c43-40e9-a7e5-e8ed9e0a47f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
