INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86963, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和解是吵架的两个人不再生气，重新和好。", "primary_collocate": null, "pronunciation": "hé jiě", "ipa": "xɤ˧˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两个孩子吵架后，今天又和解了。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐和妹妹昨天吵了架，今天已经和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和他和解，所以买了一份礼物。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们生气了很久，最后还是和解了。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌打了一架，老师让他们互相和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个好朋友为小事吵架，一个星期后和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向我说了对不起，我们终于和解了。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩多年不说话，现在终于和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈希望你们两个早点和解，别再生气。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架以后，她主动给我打电话，我们和解了。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和解了", "label": "体标"}, {"form": "和解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "吵架的人不再生气，重新和好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和解", "is_correct": true, "explanation": "正确答案。「吵架后，今天又和解了」表示吵架后重新和好，与句意相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」指成年人缔结婚姻，与两个孩子吵架后的情形不相配。"}, {"text": "分手", "is_correct": false, "explanation": "搭配：「分手」多用于恋人或合作伙伴之间，不用于孩子吵架后的情形。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：「毕业」指完成学业，与吵架后的情形无关，句子不通。"}], "explanations": {"和解": "正确答案。「吵架后，今天又和解了」表示吵架后重新和好，与句意相符。", "结婚": "语义：「结婚」指成年人缔结婚姻，与两个孩子吵架后的情形不相配。", "分手": "搭配：「分手」多用于恋人或合作伙伴之间，不用于孩子吵架后的情形。", "毕业": "语义：「毕业」指完成学业，与吵架后的情形无关，句子不通。"}, "sentence_index": 0, "correct_answer": "和解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题拖了很久，最后终于和解了。", "explanation": "这里应该用〈解决〉。和解指双方消除矛盾、重归于好，主语应是人或团体；问题要用解决。"}, {"text": "这道题我终于和解了。", "explanation": "这里应该用〈解出〉。和解指双方消除矛盾，不指解答题目；把题目做出来要用解出。"}, {"text": "打了五年，战争终于和解了。", "explanation": "这里应该用〈结束〉。和解的主体须是双方（人或团体），战争是事件，不能和解；战争结束要用结束。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和解", "is_correct": true, "explanation": "正确答案。前文「说了对不起」，后文「终于和解了」表示重归于好，前后连贯。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：「终于」接在「说了对不起」之后，表示和好；「吵架」与之相反，句子不通。"}, {"text": "分开", "is_correct": false, "explanation": "语义：「分开」表示离开、分离，与说了对不起后的和好情形相反。"}, {"text": "关心", "is_correct": false, "explanation": "配价：「关心」需要带宾语（关心某人），句末没有宾语，且语义不通。"}], "explanations": {"和解": "正确答案。前文「说了对不起」，后文「终于和解了」表示重归于好，前后连贯。", "吵架": "语义：「终于」接在「说了对不起」之后，表示和好；「吵架」与之相反，句子不通。", "分开": "语义：「分开」表示离开、分离，与说了对不起后的和好情形相反。", "关心": "配价：「关心」需要带宾语（关心某人），句末没有宾语，且语义不通。"}, "sentence_index": 6, "correct_answer": "和解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病终于和解了。", "explanation": "这里应该用〈痊愈〉。和解指双方消除矛盾，不指身体恢复健康；病好了要用痊愈。"}, {"text": "比赛中，他在最后一分钟和解了。", "explanation": "这里应该用〈获胜〉。和解指双方消除矛盾、重归于好，不用于比赛的胜负。"}, {"text": "绳子打成了结，最后终于和解了。", "explanation": "这里应该用〈解开〉。和解指双方消除矛盾，不指解开绳结；解开绳结要用解开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天和解他了。", "corrected_sentence": "我昨天和他和解了。", "error_description": "错误：「和解」是不及物动词，不能直接带人作宾语。正确说法是「和他和解」，用介词「和」引出对方。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很和解了。", "corrected_sentence": "他们终于和解了。", "error_description": "错误：「和解」是动词，不能被程度副词「很」修饰。正确说法是「终于和解」，用时间副词表示事情最终发生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
