INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86964, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方消除矛盾，停止争执，重归于好。", "primary_collocate": null, "pronunciation": "hé jiě", "ipa": "xɤ˧˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "经过老师的劝说，双方停止争吵，握手和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和工人经过谈判，终于和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家邻居为了院子争了很久，现在已经和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家结束了冲突，决定和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院希望双方能够和解，不再争执。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和员工谈了三次，才互相和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年的矛盾消除了，两家人和解了。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友劝他们放下矛盾，早日和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队长握了握手，当场和解。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方都愿意让步，所以很快和解了。", "target_word": "和解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和解了", "label": "体标"}, {"form": "和解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "双方消除矛盾、停止争执并重归于好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和解", "is_correct": true, "explanation": "正确答案。双方停止争吵、握手，即是消除矛盾、重归于好，与句意吻合。"}, {"text": "投降", "is_correct": false, "explanation": "语义：「投降」指一方向另一方屈服，与双方停止争吵后握手言和的情形不符。"}, {"text": "争论", "is_correct": false, "explanation": "语义：「争论」与前句「停止争吵」相矛盾，句意不通。"}, {"text": "报复", "is_correct": false, "explanation": "语义：「报复」是对对方的伤害作出回击，与停止争吵、握手的结果正好相反。"}], "explanations": {"和解": "正确答案。双方停止争吵、握手，即是消除矛盾、重归于好，与句意吻合。", "投降": "语义：「投降」指一方向另一方屈服，与双方停止争吵后握手言和的情形不符。", "争论": "语义：「争论」与前句「停止争吵」相矛盾，句意不通。", "报复": "语义：「报复」是对对方的伤害作出回击，与停止争吵、握手的结果正好相反。"}, "sentence_index": 0, "correct_answer": "和解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的伤口终于和解了。", "explanation": "这里应该用〈愈合〉。和解指双方消除矛盾，不指伤口长好；伤口长好要用愈合。"}, {"text": "这场雨下了一整天，傍晚终于和解了。", "explanation": "这里应该用〈停〉。和解的主体须是双方，雨不能和解；雨停要用停。"}, {"text": "战火终于和解了。", "explanation": "这里应该用〈停止〉。和解的主体须是双方（人或团体），不能用于战火这类事物；战火要用停止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和解", "is_correct": true, "explanation": "正确答案。前文「矛盾消除了」，后文「和解了」表示重归于好，前后一致。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：「矛盾消除了」之后，「争吵」与之矛盾，句意不通。"}, {"text": "解释", "is_correct": false, "explanation": "配价：「解释」需要带说明的内容作宾语，「两家人解释了」句末缺少宾语。"}, {"text": "开战", "is_correct": false, "explanation": "语义：「开战」表示双方交战，与矛盾消除后的和好情形相反，句意不通。"}], "explanations": {"和解": "正确答案。前文「矛盾消除了」，后文「和解了」表示重归于好，前后一致。", "争吵": "语义：「矛盾消除了」之后，「争吵」与之矛盾，句意不通。", "解释": "配价：「解释」需要带说明的内容作宾语，「两家人解释了」句末缺少宾语。", "开战": "语义：「开战」表示双方交战，与矛盾消除后的和好情形相反，句意不通。"}, "sentence_index": 6, "correct_answer": "和解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的旋律终于和解了。", "explanation": "这里应该用〈和谐〉。和解指双方消除矛盾，不指声音或旋律协调；旋律协调要用和谐。"}, {"text": "他在比赛中和解了。", "explanation": "这里应该用〈获胜〉。和解指双方消除矛盾，不用于比赛的胜负。"}, {"text": "这座城市的交通终于和解了。", "explanation": "这里应该用〈畅通〉。和解指双方消除矛盾，不指交通顺畅；道路通行顺利要用畅通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家人终于被和解了。", "corrected_sentence": "两家人终于和解了。", "error_description": "错误：「和解」表示双方自愿消除矛盾，不能加「被」表示被动。正确说法是「两家人终于和解了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个朋友很和解了。", "corrected_sentence": "两个朋友最终和解了。", "error_description": "错误：「和解」不能被程度副词「很」修饰。应改用「最终」等表示结果的副词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
