INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86965, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "是以是“所以”的意思，说因为这样才那样。", "primary_collocate": null, "pronunciation": "shì yǐ", "ipa": "ʂʅ˥˩ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "她不喜欢吵，是以住在山里。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水很干净，是以鱼特别多。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身体不好，是以很少出远门。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲得清楚，是以同学们都听懂了。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱便宜，是以买的人很多。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们早就准备好了，是以一点也不急。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪小，是以大家都照顾他。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思，是以我看了两遍。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上风大，是以我带着一件厚衣服。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李常常迟到，是以经理不高兴。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "是以：相当于所以，因为这样才那样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86965, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "是以", "is_correct": true, "explanation": "正确答案。是以，连词，表示因果，意为“因此、所以”。"}, {"text": "释义", "is_correct": false, "explanation": "shì yì 与 shì yǐ 第二音节声调不同（第四声与第三声），意思是对词语意义的解释。"}, {"text": "事宜", "is_correct": false, "explanation": "shì yí 与 shì yǐ 第二音节声调不同（第二声与第三声），意思是有关事情的安排或事务。"}, {"text": "石椅", "is_correct": false, "explanation": "shí yǐ 与 shì yǐ 第一音节声调不同（第二声与第四声），意思是石头做的椅子。"}], "explanations": {"是以": "正确答案。是以，连词，表示因果，意为“因此、所以”。", "释义": "shì yì 与 shì yǐ 第二音节声调不同（第四声与第三声），意思是对词语意义的解释。", "事宜": "shì yí 与 shì yǐ 第二音节声调不同（第二声与第三声），意思是有关事情的安排或事务。", "石椅": "shí yǐ 与 shì yǐ 第一音节声调不同（第二声与第四声），意思是石头做的椅子。"}, "sentence_index": null, "correct_answer": "是以"}, "level_3": {"options": [{"text": "是以", "is_correct": true, "explanation": "正确答案。是以，连词，表示因果，此处说明她不喜欢吵，所以住在山里。"}, {"text": "以免", "is_correct": false, "explanation": "语义：“以免”表示为了避免某种情况，后文应是要避免的事，与“住在山里”的因果关系不符。"}, {"text": "不但", "is_correct": false, "explanation": "配价：“不但”要与“而且”“还”呼应表示递进，这里后文没有对应词，句子不通。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”后面要用“也”“还”呼应表示假设让步，这里前后不构成让步关系。"}], "explanations": {"是以": "正确答案。是以，连词，表示因果，此处说明她不喜欢吵，所以住在山里。", "以免": "语义：“以免”表示为了避免某种情况，后文应是要避免的事，与“住在山里”的因果关系不符。", "不但": "配价：“不但”要与“而且”“还”呼应表示递进，这里后文没有对应词，句子不通。", "即使": "搭配：“即使”后面要用“也”“还”呼应表示假设让步，这里前后不构成让步关系。"}, "sentence_index": 0, "correct_answer": "是以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先吃饭，是以写作业。", "explanation": "这里应该用〈然后〉。是以表示因果，前后应是结果关系；这里只是先后顺序，要用〈然后〉。"}, {"text": "他爱吃辣，是以也爱吃甜。", "explanation": "这里应该用〈而且〉。是以表示因果，爱吃辣不会导致爱吃甜，两者只是并列递进，应说“他爱吃辣，而且也爱吃甜”。"}, {"text": "这不是他的错，是以我的错。", "explanation": "这里应该用〈而是〉。是以表示因果，不能用于否定之后的更正对比；“不是……而是……”要用〈而是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是以", "is_correct": true, "explanation": "正确答案。是以，连词，表示因果，此处说明他年纪小，所以大家都照顾他。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”“却”等呼应表示让步，这里没有对应词，前后关系也不成立。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示如果不这样就会怎样，后文要接不好的结果，与“大家都照顾他”不符。"}, {"text": "而是", "is_correct": false, "explanation": "配价：“而是”前面必须有“不是”“不”等否定词，这里前文没有否定，不能使用。"}], "explanations": {"是以": "正确答案。是以，连词，表示因果，此处说明他年纪小，所以大家都照顾他。", "虽然": "搭配：“虽然”要与“但是”“却”等呼应表示让步，这里没有对应词，前后关系也不成立。", "否则": "语义：“否则”表示如果不这样就会怎样，后文要接不好的结果，与“大家都照顾他”不符。", "而是": "配价：“而是”前面必须有“不是”“不”等否定词，这里前文没有否定，不能使用。"}, "sentence_index": 6, "correct_answer": "是以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "与其在这里等，是以现在走。", "explanation": "这里应该用〈不如〉。是以表示因果，不能表示比较后的选择；“与其……不如……”要用〈不如〉。"}, {"text": "他会做饭，是以还会修车。", "explanation": "这里应该用〈此外〉。是以表示因果，不能用来补充并列的新信息；做饭与修车之间没有因果关系。"}, {"text": "是以天气如何，我们都出发。", "explanation": "这里应该用〈不论〉。是以只能连接已发生的原因和结果，不能引出“天气如何”这样的任意条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他工作很忙，是以所以很少回家。", "corrected_sentence": "他工作很忙，是以很少回家。", "error_description": "“是以”与“所以”都表示因果，不能同时使用，应删去“所以”。正确说法是“他工作很忙，是以很少回家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她嗓子不好，因为是以很少唱歌。", "corrected_sentence": "她嗓子不好，是以很少唱歌。", "error_description": "“是以”和“因为”都表示因果，不能同时使用，应删去“因为”。正确说法是“她嗓子不好，是以很少唱歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
