INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86966, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，因此；所以。", "primary_collocate": null, "pronunciation": "shì yǐ", "ipa": "ʂʅ˥˩ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "他工作认真，是以大家都信任他。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，是以我没有出门。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店东西好，是以客人很多。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天练习，是以进步很快。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，是以我们到得很晚。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读书很多，是以懂得不少。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下大雨，是以比赛不办了。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王帮过我，是以我很感谢他。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离家近，是以他走路上学。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很努力，是以考试成绩很好。", "target_word": "是以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "是以：连词，表示因果，因此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86966, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "是以", "is_correct": true, "explanation": "正确答案。是以，连词，表示因果，意为“因此、所以”。"}, {"text": "释义", "is_correct": false, "explanation": "shì yì 与 shì yǐ 第二音节声调不同（第四声与第三声），意思是对词语意义的解释。"}, {"text": "事宜", "is_correct": false, "explanation": "shì yí 与 shì yǐ 第二音节声调不同（第二声与第三声），意思是有关事情的安排或事务。"}, {"text": "石椅", "is_correct": false, "explanation": "shí yǐ 与 shì yǐ 第一音节声调不同（第二声与第四声），意思是石头做的椅子。"}], "explanations": {"是以": "正确答案。是以，连词，表示因果，意为“因此、所以”。", "释义": "shì yì 与 shì yǐ 第二音节声调不同（第四声与第三声），意思是对词语意义的解释。", "事宜": "shì yí 与 shì yǐ 第二音节声调不同（第二声与第三声），意思是有关事情的安排或事务。", "石椅": "shí yǐ 与 shì yǐ 第一音节声调不同（第二声与第四声），意思是石头做的椅子。"}, "sentence_index": null, "correct_answer": "是以"}, "level_3": {"options": [{"text": "是以", "is_correct": true, "explanation": "正确答案。是以，连词，前句说明原因，后句说明结果，此处表示因此大家信任他。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示如果不这样就会怎样，后文要接不好的结果，与“大家都信任他”的正面结果相冲突。"}, {"text": "除非", "is_correct": false, "explanation": "语义：“除非”引出唯一的条件，不能引出结果；“他工作认真，除非大家都信任他”前后关系不通。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”后面要用“也”“还”等呼应表示假设让步，这里前后不构成让步关系，句子不完整。"}], "explanations": {"是以": "正确答案。是以，连词，前句说明原因，后句说明结果，此处表示因此大家信任他。", "否则": "语义：“否则”表示如果不这样就会怎样，后文要接不好的结果，与“大家都信任他”的正面结果相冲突。", "除非": "语义：“除非”引出唯一的条件，不能引出结果；“他工作认真，除非大家都信任他”前后关系不通。", "即使": "搭配：“即使”后面要用“也”“还”等呼应表示假设让步，这里前后不构成让步关系，句子不完整。"}, "sentence_index": 0, "correct_answer": "是以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先洗澡，是以吃饭。", "explanation": "这里应该用〈然后〉。是以表示因果，前后应是结果关系；这里只是先后顺序，要用〈然后〉。"}, {"text": "他会唱歌，是以会跳舞。", "explanation": "这里应该用〈也〉。是以表示因果，不能表示并列关系；唱歌与跳舞之间没有因果联系，应用〈也〉表示并列。"}, {"text": "我们可以坐车，是以走路。", "explanation": "这里应该用〈或者〉。是以表示因果，不能表示二选一的选择关系；“可以坐车，或者走路”要用〈或者〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是以", "is_correct": true, "explanation": "正确答案。是以，连词，表示因果，此处说明因为下大雨，所以比赛不办了。"}, {"text": "以免", "is_correct": false, "explanation": "语义：“以免”前面应是为避免后文情况而采取的行为；这里下大雨并非为了避免比赛取消，前后关系不通。"}, {"text": "而是", "is_correct": false, "explanation": "配价：“而是”前面必须有“不是”“不”等否定词，这里前文没有否定，不能使用。"}, {"text": "不但", "is_correct": false, "explanation": "配价：“不但”后面要用“而且”“还”呼应表示递进，这里没有对应词，语义也不通。"}], "explanations": {"是以": "正确答案。是以，连词，表示因果，此处说明因为下大雨，所以比赛不办了。", "以免": "语义：“以免”前面应是为避免后文情况而采取的行为；这里下大雨并非为了避免比赛取消，前后关系不通。", "而是": "配价：“而是”前面必须有“不是”“不”等否定词，这里前文没有否定，不能使用。", "不但": "配价：“不但”后面要用“而且”“还”呼应表示递进，这里没有对应词，语义也不通。"}, "sentence_index": 6, "correct_answer": "是以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "快点走，是以要迟到了。", "explanation": "这里应该用〈否则〉。是以表示因果，不能表示“不然”的假设后果；“快点走，否则要迟到了”要用〈否则〉。"}, {"text": "他会做饭，是以还会修车。", "explanation": "这里应该用〈此外〉。是以表示因果，不能用来补充并列的新信息；做饭与修车之间没有因果关系。"}, {"text": "与其再等下去，是以现在出发。", "explanation": "这里应该用〈不如〉。是以表示因果，不能表示比较后的选择；“与其……不如……”要用〈不如〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气很好，因为是以我们去公园了。", "corrected_sentence": "天气很好，是以我们去公园了。", "error_description": "“是以”和“因为”都表示因果，不能同时使用，应删去“因为”。正确说法是“天气很好，是以我们去公园了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最近常熬夜，是以所以身体越来越差。", "corrected_sentence": "他最近常熬夜，是以身体越来越差。", "error_description": "“是以”与“所以”都是表示因果的连词，不能同时使用。应删去“所以”，写作“他最近常熬夜，是以身体越来越差”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86967, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86967, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86967, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "要是的意思是\"如果\"。说\"要是\"的时候，后面的事情还没有发生，是一种假设。", "primary_collocate": null, "pronunciation": "yào shi", "ipa": "jaʊ˥˩ ʂɨ", "syllable_count": 2, "sentences": [{"text": "要是明天下雨，我们会在家看书。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是我有一百万，我想去世界各地旅行。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是你累了，可以先回家休息。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是我会飞，我会飞到海边看日出。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是见到她，请告诉她我在等她。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是今天不堵车，我们能准时到。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要是知道这件事，一定会很高兴。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要是你，会给他打个电话。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是明天天气好，我们去公园玩吧。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是你有时间，可以来我家吃饭。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语假设连词，设想尚未发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要是", "is_correct": true, "explanation": "正确答案。口语假设连词，读 yào shi，第二个音节为轻声。"}, {"text": "要事", "is_correct": false, "explanation": "shì（第四声）与 shi（轻声）声调不同，要事的意思是重要的事情。"}, {"text": "药师", "is_correct": false, "explanation": "shī（第一声）与 shi（轻声）声调不同，药师的意思是药剂师。"}, {"text": "要使", "is_correct": false, "explanation": "shǐ（第三声）与 shi（轻声）声调不同，要使是表示致使的动词短语，意思是让。"}], "explanations": {"要是": "正确答案。口语假设连词，读 yào shi，第二个音节为轻声。", "要事": "shì（第四声）与 shi（轻声）声调不同，要事的意思是重要的事情。", "药师": "shī（第一声）与 shi（轻声）声调不同，药师的意思是药剂师。", "要使": "shǐ（第三声）与 shi（轻声）声调不同，要使是表示致使的动词短语，意思是让。"}, "sentence_index": null, "correct_answer": "要是"}, "level_3": {"options": [{"text": "要是", "is_correct": true, "explanation": "正确答案。「要是」引出尚未发生的假设条件，与「会在家看书」呼应。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：「而且」要承接前文的并列或递进内容，句首没有前文，句子不通。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，句首没有前文可转折，「但是明天下雨」与后句没有对立关系。"}, {"text": "然而", "is_correct": false, "explanation": "语域：「然而」是书面语，与这句口语化的假设句不协调。"}], "explanations": {"要是": "正确答案。「要是」引出尚未发生的假设条件，与「会在家看书」呼应。", "而且": "搭配：「而且」要承接前文的并列或递进内容，句首没有前文，句子不通。", "但是": "语义：「但是」表示转折，句首没有前文可转折，「但是明天下雨」与后句没有对立关系。", "然而": "语域：「然而」是书面语，与这句口语化的假设句不协调。"}, "sentence_index": 0, "correct_answer": "要是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "要是你帮忙，我就迟到了。", "explanation": "这里应该用〈要不是〉。「要是你帮忙，我就迟到了」把帮忙说成迟到的条件，而〈要不是〉表示若没有某人的帮助才会如此。"}, {"text": "我正在看书，要是他进来了。", "explanation": "这里应该用〈忽然〉。要是表示假设，不用来叙述正在进行的事中突然发生的事；叙述已发生的事要用忽然。"}, {"text": "要是他迟到了，所以错过了火车。", "explanation": "这里应该用〈因为〉。要是表示假设，「所以」引出的是已经发生的结果；说明已经发生的原因要用因为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要是", "is_correct": true, "explanation": "正确答案。「要是」引出假设条件，与「一定会很高兴」呼应，句意通顺。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：「虽然」要与「却」「但」等词呼应，句中没有这类词，且与「一定会很高兴」的推断不相容。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：「况且」用于补充前面已说明的理由，句首没有前文可补充，句子不通。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示时间先后，不表示假设；「然后他知道这件事」无法作为条件。"}], "explanations": {"要是": "正确答案。「要是」引出假设条件，与「一定会很高兴」呼应，句意通顺。", "虽然": "搭配：「虽然」要与「却」「但」等词呼应，句中没有这类词，且与「一定会很高兴」的推断不相容。", "况且": "搭配：「况且」用于补充前面已说明的理由，句首没有前文可补充，句子不通。", "然后": "语义：「然后」表示时间先后，不表示假设；「然后他知道这件事」无法作为条件。"}, "sentence_index": 6, "correct_answer": "要是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "要是天气好，比赛取消了。", "explanation": "这里应该用〈由于〉。要是表示假设，「天气好」只是假设；已经发生的原因要用由于。"}, {"text": "我不知道要是他同意。", "explanation": "这里应该用〈是否〉。要是只引出假设条件，不表示「是不是」的疑问。"}, {"text": "要是天气好不好，我们都要去。", "explanation": "这里应该用〈不管〉。要是表示假设，不能表示无论怎样都……的无条件关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天要是不下雨，要是我们就去公园。", "corrected_sentence": "明天要是不下雨，我们就去公园。", "error_description": "错误：多出一个“要是”；“要是我们就去公园”重复了假设词。正确：“明天要是不下雨，我们就去公园”，假设条件只需引出一次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "要是我有时间，所以我来。", "corrected_sentence": "要是我有时间，我就来。", "error_description": "错误：“要是……所以……”；正确：“要是……就……”。“要是”表示假设，后面要用“就”呼应，“所以”只用于因果关系。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86968, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86968, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86968, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示假设，相当于\"如果\"，后面常有\"就\"\"那么\"等与之呼应。", "primary_collocate": null, "pronunciation": "yào shi", "ipa": "jaʊ˥˩ ʂɨ", "syllable_count": 2, "sentences": [{"text": "要是你不想去，那么我一个人去。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是路上有事，请给我打电话。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是他不同意，那么我们换个办法。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是天黑了，你不要一个人出门。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是我们早点出发，那么能赶上火车。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是饿了，冰箱里有面包。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是你喜欢这本书，我送给你。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是明年有机会，我想再来中国。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是他迟到了，我们先开始吧。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是你把钥匙忘在家里，那么只好请人开门。", "target_word": "要是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表假设的连词，后文常用那么等呼应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86968, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要是", "is_correct": true, "explanation": "正确答案。口语假设连词，读 yào shi，第二个音节为轻声。"}, {"text": "要事", "is_correct": false, "explanation": "shì（第四声）与 shi（轻声）声调不同，要事的意思是重要的事情。"}, {"text": "药师", "is_correct": false, "explanation": "shī（第一声）与 shi（轻声）声调不同，药师的意思是药剂师。"}, {"text": "要使", "is_correct": false, "explanation": "shǐ（第三声）与 shi（轻声）声调不同，要使是表示致使的动词短语，意思是让。"}], "explanations": {"要是": "正确答案。口语假设连词，读 yào shi，第二个音节为轻声。", "要事": "shì（第四声）与 shi（轻声）声调不同，要事的意思是重要的事情。", "药师": "shī（第一声）与 shi（轻声）声调不同，药师的意思是药剂师。", "要使": "shǐ（第三声）与 shi（轻声）声调不同，要使是表示致使的动词短语，意思是让。"}, "sentence_index": null, "correct_answer": "要是"}, "level_3": {"options": [{"text": "要是", "is_correct": true, "explanation": "正确答案。「要是」引出假设条件，与后文「那么」呼应。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：「尽管」要与「还是」「仍然」呼应，句中的「那么」不能与之搭配，句子不通。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示时间先后，不表示假设，与「那么」的条件关系不符。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：「而且」要承接前文的并列或递进内容，句首没有前文，句子不通。"}], "explanations": {"要是": "正确答案。「要是」引出假设条件，与后文「那么」呼应。", "尽管": "搭配：「尽管」要与「还是」「仍然」呼应，句中的「那么」不能与之搭配，句子不通。", "然后": "语义：「然后」表示时间先后，不表示假设，与「那么」的条件关系不符。", "而且": "搭配：「而且」要承接前文的并列或递进内容，句首没有前文，句子不通。"}, "sentence_index": 0, "correct_answer": "要是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "要是他生病了，所以我替他去。", "explanation": "这里应该用〈因为〉。要是表示假设，「所以」引出的是已经发生的结果；说明已经发生的原因要用因为。"}, {"text": "我不知道要是他同意不同意。", "explanation": "这里应该用〈是否〉。要是只引出假设条件，不表示「是不是」的疑问。"}, {"text": "我正在做饭，要是他回来了。", "explanation": "这里应该用〈忽然〉。要是表示假设，不用来叙述正在进行的事中突然发生的事；叙述已发生的事要用忽然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要是", "is_correct": true, "explanation": "正确答案。「要是」引出假设条件，句意通顺。"}, {"text": "不过", "is_correct": false, "explanation": "语义：「不过」表示转折，句首没有前文可转折，与「我送给你」的意思不协调。"}, {"text": "而", "is_correct": false, "explanation": "搭配：「而」用来连接前后两个部分，句首没有前文可连接，「而你喜欢这本书」句子不通。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：「况且」用于补充前文的理由，句首没有前文，句子不通。"}], "explanations": {"要是": "正确答案。「要是」引出假设条件，句意通顺。", "不过": "语义：「不过」表示转折，句首没有前文可转折，与「我送给你」的意思不协调。", "而": "搭配：「而」用来连接前后两个部分，句首没有前文可连接，「而你喜欢这本书」句子不通。", "况且": "搭配：「况且」用于补充前文的理由，句首没有前文，句子不通。"}, "sentence_index": 6, "correct_answer": "要是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "要是他帮忙，我早就迟到了。", "explanation": "这里应该用〈要不是〉。要是表示假设，「要是他帮忙，我早就迟到了」把他的帮忙说成迟到的原因；表示「若没有他的帮助」要用要不是。"}, {"text": "要是他去不去，我们都很高兴。", "explanation": "这里应该用〈不管〉。要是只引出假设条件，不表示无论怎样都……的无条件关系；无论去不去要用不管。"}, {"text": "要是他生病了，所以我们取消了比赛。", "explanation": "这里应该用〈由于〉。要是表示假设，后面的「所以」引出的是已经发生的结果；说明已经确定的原因要用由于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他要是不来，要是我们就先走。", "corrected_sentence": "他要是不来，我们就先走。", "error_description": "错误：多出一个“要是”；“要是我们就先走”重复了假设词。正确：“他要是不来，我们就先走”，假设条件只需引出一次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "要是他有空，所以我陪你去。", "corrected_sentence": "要是他有空，那么我陪你去。", "error_description": "错误：“要是……所以……”；正确：“要是……那么……”。“要是”表示假设，后文要用“那么”或“就”呼应，“所以”只用于因果关系。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
