INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86969, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "咱是我们，也包括正在听你说话的那个人。", "primary_collocate": null, "pronunciation": "zán", "ipa": "tsan³⁵", "syllable_count": 1, "sentences": [{"text": "咱一起去公园玩儿吧。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班了，咱去吃点儿东西。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，咱的孩子都长大了。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱说好了，明天八点见面。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别急，咱有的是时间。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是你不忙，咱就一起走。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天咱听老师的，好好练习。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书咱都看过，很有意思。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱要早点儿出发，不然赶不上车。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱的球队赢了，大家都很高兴。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咱们", "label": "复合"}], "register": "口语", "sense_fingerprint": "口语里的“我们”，包括听话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86969, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "咱", "is_correct": true, "explanation": "咱（zán）：口语代词，指包括听话人在内的我们。"}, {"text": "赞", "is_correct": false, "explanation": "赞（zàn）与“咱”声调不同（第四声），意思是称赞。"}, {"text": "残", "is_correct": false, "explanation": "残（cán）与“咱”声母不同（c 与 z），意思是残缺。"}, {"text": "攒", "is_correct": false, "explanation": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。"}, {"text": "簪", "is_correct": false, "explanation": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}], "explanations": {"咱": "咱（zán）：口语代词，指包括听话人在内的我们。", "赞": "赞（zàn）与“咱”声调不同（第四声），意思是称赞。", "残": "残（cán）与“咱”声母不同（c 与 z），意思是残缺。", "攒": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。", "簪": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}, "sentence_index": null, "correct_answer": "咱"}, "level_3": {"options": [{"text": "咱", "is_correct": true, "explanation": "正确：“咱”包括说话人和听话人，与“一起去公园玩儿吧”的邀请相符。"}, {"text": "什么", "is_correct": false, "explanation": "语法：“什么”是疑问代词，不能作“一起去公园玩儿吧”的主语。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物或动物，不能用来邀请人一起去。"}, {"text": "这儿", "is_correct": false, "explanation": "语义：“这儿”指地方，不能作“一起去”的主语。"}], "explanations": {"咱": "正确：“咱”包括说话人和听话人，与“一起去公园玩儿吧”的邀请相符。", "什么": "语法：“什么”是疑问代词，不能作“一起去公园玩儿吧”的主语。", "它": "语义：“它”指事物或动物，不能用来邀请人一起去。", "这儿": "语义：“这儿”指地方，不能作“一起去”的主语。"}, "sentence_index": 0, "correct_answer": "咱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "咱三个说好了，你别去。", "explanation": "这里应该用〈我们〉。“咱”包括听话人，这句又要求听话人别去，应该用“我们”。"}, {"text": "咱都同意了，你不用同意。", "explanation": "这里应该用〈他们〉。“咱”包括听话人，这句又说听话人不用同意，应该用“他们”。"}, {"text": "咱几个说好了，你别跟着。", "explanation": "这里应该用〈他们〉。“咱”包括听话人，这句又让听话人别跟着，应该用“他们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86969, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "咱", "is_correct": true, "explanation": "咱（zán）：口语代词，指包括听话人在内的我们。"}, {"text": "暂", "is_correct": false, "explanation": "暂（zàn）与“咱”声调不同（第四声），意思是暂时。"}, {"text": "蚕", "is_correct": false, "explanation": "蚕（cán）与“咱”声母不同（c 与 z），意思是吐丝的虫子。"}, {"text": "攒", "is_correct": false, "explanation": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。"}, {"text": "簪", "is_correct": false, "explanation": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}], "explanations": {"咱": "咱（zán）：口语代词，指包括听话人在内的我们。", "暂": "暂（zàn）与“咱”声调不同（第四声），意思是暂时。", "蚕": "蚕（cán）与“咱”声母不同（c 与 z），意思是吐丝的虫子。", "攒": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。", "簪": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}, "sentence_index": null, "correct_answer": "咱"}, "level_3": {"options": [{"text": "咱", "is_correct": true, "explanation": "正确：“咱”包括说话人和听话人，劝大家听老师的，好好练习。"}, {"text": "什么", "is_correct": false, "explanation": "语法：“什么”是疑问代词，不能作“听老师的”的主语。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指事物，不指能听老师话的人。"}, {"text": "多少", "is_correct": false, "explanation": "语法：“多少”问数量，不能作“听老师的”的主语。"}], "explanations": {"咱": "正确：“咱”包括说话人和听话人，劝大家听老师的，好好练习。", "什么": "语法：“什么”是疑问代词，不能作“听老师的”的主语。", "它们": "语义：“它们”指事物，不指能听老师话的人。", "多少": "语法：“多少”问数量，不能作“听老师的”的主语。"}, "sentence_index": 6, "correct_answer": "咱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "咱俩去吧，你不用去。", "explanation": "这里应该用〈他俩〉。“咱俩”包括听话人，这句又让听话人不去，应该用“他俩”。"}, {"text": "咱俩去签字，你在家等着吧。", "explanation": "这里应该用〈我俩〉。“咱俩”包括听话人，这句又让听话人在家等，应该用“我俩”。"}, {"text": "咱几个去看电影，你别跟来。", "explanation": "这里应该用〈我们〉。“咱”包括听话人，这句又不让听话人跟来，应该用“我们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "们咱学校的食堂很大。", "corrected_sentence": "咱们学校的食堂很大。", "error_description": "“咱们”是固定的词序，“们”不能放在“咱”前面，应说“咱们学校”，不说“们咱学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咱的们都很努力，一起加油。", "corrected_sentence": "咱们都很努力，一起加油。", "error_description": "“咱们”是一个不能拆开的词，“的”不能插在“咱”和“们”之间，应说“咱们都很努力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
